#--------------------------------------------------------------------------------------------------------------------------
# Authority 초기화 (updated 20220519)
#--------------------------------------------------------------------------------------------------------------------------
def initiate_authority_for_superuser(request):
    qs_user = User.objects.filter(is_superuser=True)
    q_authority = Authority.objects.all().last()
    if q_authority is None:
        q_authority = Authority.objects.create()
        for AUTH_FIELD in LIST_AUTH_FIELD:
            for q_user in qs_user:
                if q_user.is_superuser:
                    data = {
                        f'{AUTH_FIELD}':[q_user.member.id],
                    }
                    Authority.objects.filter(id=q_authority.id).update(**data)
    q_authority.refresh_from_db()
    if request.user.is_superuser == True:
        create_or_update_superuser_member_and_profile(request)
        create_or_update_default_mysettings(request.user)
        q_mysettings_hr = HR_My_Settings.objects.filter(owner=request.user).last()
        data = {
            'authority': q_authority,
        }
        HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return q_authority


#--------------------------------------------------------------------------------------------------------------------------
# HR Default Settings 실행 (updated 20230127)
#--------------------------------------------------------------------------------------------------------------------------
def create_or_update_default_hr_settings(request):
    q_hr_default_settings = HR_Default_Settings.objects.last()
    if q_hr_default_settings is None:
        default_user_password = 'qhfhshdl'
        default_time_start_standard = datetime.time(9, 0)
        default_time_start_early = datetime.time(8, 30)
        default_time_end_standard = datetime.time(18, 0)
        default_time_end_lately = datetime.time(19, 0)
        data = {
            'default_user_password': default_user_password,
            'default_time_start_standard': default_time_start_standard,
            'default_time_start_early': default_time_start_early,
            'default_time_end_standard': default_time_end_standard,
            'default_time_end_lately': default_time_end_lately,
        }
        q_hr_default_settings = HR_Default_Settings.objects.create(**data)
    return q_hr_default_settings

