#--------------------------------------------------------------------------------------------------------------------------
# Group 리스트/등록 메인
#--------------------------------------------------------------------------------------------------------------------------
def hrLayoutRegisterGroupFunction(request):
    qs_group = Group.objects.filter(check_discard=False).order_by('group_name')
    qs_company = Company.objects.filter(check_discard=False).order_by('company_name')

    qs_c2g = Company2Group.objects.filter(check_discard=False).order_by('group')
    dict_c2g_selected = hrLayoutDesignDictGeneratorC2G(qs_c2g)

    form = HrLayoutRegisterGroupForm()
    ############################################
    if request.method == 'GET':
        context = {
            'qs_group':qs_group,
            'dict_c2g': dict_c2g_selected,
            'form':form,
        }
        return context
    ############################################
    if request.method == 'POST':
        print(request.POST)

        if request.POST.get('button-register-group-individual') == 'true':
            form = HrLayoutRegisterGroupForm(request.POST)
            if form.is_valid():
                form.save()
            return True

        # Group 파일로 등록하기
        if request.POST.get('button-register-group-file') == 'true':
            uploaded_file = request.FILES['group-upload']
            df = pd.read_excel(uploaded_file, sheet_name=0, header=0, index_col=False, keep_default_na=True)
            for index, column in df.iterrows():
                group_name = column[1]
                group_name = group_name.strip()
                group_name = group_name.replace(" ", "")
                comment = column[3]
                check_is_voronoigroup = column[4]
                check_is_iacuc_member = column[5]
                check_discard = column[6]
                data = {
                    'group_name': group_name,
                    'comment': comment,
                    'check_is_voronoigroup': check_is_voronoigroup,
                    'check_is_iacuc_member': check_is_iacuc_member,
                    'check_discard': check_discard,
                }
                q_group_selected = Group.objects.filter(Q(check_discard=False) & Q(group_name=group_name)).last()
                if q_group_selected is None:
                    Group.objects.create(**data)
                    messages.success(request, f"Hi! {request.user}, 새로운 {group_name} Group를 등록였습니다!")
                else:
                    Group.objects.filter(id=q_group_selected.id).update(**data)
                    messages.success(request, f"Hi! {request.user}, {group_name} Group를 업데이트 하였습니다!")

#--------------------------------------------------------------------------------------------------------------------------
# Group 업데이트/삭제 메인
#--------------------------------------------------------------------------------------------------------------------------
def hrLayoutUpdateGroupFunction(request, pk):
    # pk is q_group.id
    q_group = Group.objects.get(id=pk)
    form = HrLayoutRegisterGroupForm(instance=q_group)
    if request.method == 'GET':
        context = {
            'q_group':q_group,
            'form':form,
        }
        return context
    if request.method == 'POST':

        #--------------------------------------------------------------------------------------------------------------------------
        # Group 등록하기
        #--------------------------------------------------------------------------------------------------------------------------
        if request.POST.get('button-hr-layout-group-control-group-register') is not None:
            form = HrLayoutRegisterGroupForm(request.POST, instance=q_group)
            if form.is_valid():
                form.save()
            return q_group.id

        #--------------------------------------------------------------------------------------------------------------------------
        # Group 삭제하기
        #--------------------------------------------------------------------------------------------------------------------------
        if request.POST.get('button-hr-layout-group-control-group-delete') is not None:
            q_group_id_str = request.POST.get('button-hr-layout-group-control-group-delete')
            q_group_id = int(q_group_id_str)
            q_group = Group.objects.get(id=q_group_id)
            data = {
                'check_discard': True,
            }
            Group.objects.filter(id=q_group.id).update(**data)
            messages.warning(request, f"Hi! {request.user.profile.name_korean}님, 선택한 {q_group.group_name} Group을 삭제하였습니다!")
            return 'delete'




