    for q_m2t in qs_m2t:
        list_team_id_membered.append(q_m2t.team.id)
    qs_team__empty = Team.objects.filter(~Q(id__in=list_team_id_membered) & Q(check_discard=False))
    dict_m2t_selected = hrLayoutDesignDictGeneratorM2T(qs_m2t)

    # print('dict_m2t_selected', dict_m2t_selected)
    form = HrLayoutRegisterTeamForm()
    ############################################
