#--------------------------------------------------------------------------------------------------------------------------
# 등록 멤버 리스트 Ordering
#--------------------------------------------------------------------------------------------------------------------------
def ordering_list_member_by_button(request, q_mysettings_hr):
    selected_field_ordering = request.POST.get('button-list-member-ordering')
    check_display_order_field_ascending = q_mysettings_hr.check_display_order_field_ascending
    if check_display_order_field_ascending == False :
        check_display_order_field_ascending = True
    else:
        check_display_order_field_ascending = False
    data = {
        'selected_field_ordering': selected_field_ordering,
        'check_display_order_field_ascending': check_display_order_field_ascending,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)


#--------------------------------------------------------------------------------------------------------------------------
# 등록 멤버 키워드 검색하기
#--------------------------------------------------------------------------------------------------------------------------
def search_registered_member_by_keyword(request, q_mysettings_hr, location):
    check_subsearch = request.POST.get('check-subsearch-member-by-keyword')
    if check_subsearch == 'on':
        check_subsearch = True
    else:
        check_subsearch = False
    input_keyword = request.POST.get('input-text-search-member')
    list_input_keyword_collection = get_cleaned_list_word(input_keyword)
    # print('list_input_keyword_collection', list_input_keyword_collection)

    if len(list_input_keyword_collection) > 0:
        list_profile_id_searched_new = []
        if location == 'member_register':
            list_profile_id_searched = q_mysettings_hr.list_profile_id_searched
        elif location == 'member_resign':
            list_profile_id_searched = q_mysettings_hr.list_resign_profile_id_searched
        if list_profile_id_searched is None:
            list_profile_id_searched = []
        for input_keyword in list_input_keyword_collection:
            if check_subsearch == True:
                if location == 'member_register':
                    qs_profile_searched = Profile.objects.filter(Q(check_resign=False) & Q(id__in=list_profile_id_searched) & (Q(name_korean__icontains=input_keyword) | Q(first_name__icontains=input_keyword) | Q(last_name__icontains=input_keyword) | Q(phone_office__icontains=input_keyword) | Q(phone_mobile__icontains=input_keyword) | Q(email__icontains=input_keyword)))
                elif location == 'member_resign':
                    qs_profile_searched = Profile.objects.filter(Q(check_resign=True) & Q(id__in=list_profile_id_searched) & (Q(name_korean__icontains=input_keyword) | Q(first_name__icontains=input_keyword) | Q(last_name__icontains=input_keyword) | Q(phone_office__icontains=input_keyword) | Q(phone_mobile__icontains=input_keyword) | Q(email__icontains=input_keyword)))
            else:
                if location == 'member_register':
                    qs_profile_searched = Profile.objects.filter(Q(check_resign=False) &Q(name_korean__icontains=input_keyword) | Q(first_name__icontains=input_keyword) | Q(last_name__icontains=input_keyword) | Q(phone_office__icontains=input_keyword) | Q(phone_mobile__icontains=input_keyword) | Q(email__icontains=input_keyword))
                elif location == 'member_resign':
                    qs_profile_searched = Profile.objects.filter(Q(check_resign=True) & Q(name_korean__icontains=input_keyword) | Q(first_name__icontains=input_keyword) | Q(last_name__icontains=input_keyword) | Q(phone_office__icontains=input_keyword) | Q(phone_mobile__icontains=input_keyword) | Q(email__icontains=input_keyword))
            if len(qs_profile_searched) > 0:
                for q_profile_searched in qs_profile_searched:
                    if q_profile_searched.id not in list_profile_id_searched_new:
                        list_profile_id_searched_new.append(q_profile_searched.id)
        # print('list_profile_id_searched_new', list_profile_id_searched_new)
        if len(list_profile_id_searched_new) > 0:
            if location == 'member_register':
                data = {
                    'list_input_keyword': list_input_keyword_collection,
                    'list_profile_id_searched': list_profile_id_searched_new,
                    'check_subsearch': check_subsearch,
                }
            elif location == 'member_resign':
                data = {
                    'list_input_keyword': list_input_keyword_collection,
                    'list_resign_profile_id_searched': list_profile_id_searched_new,
                    'check_subsearch': check_subsearch,
                }
            HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
        else:
            messages.warning(request, f'입력한 키워드로 매칭되는 멤버가 없습니다.')
            return False
    else:
        if location == 'member_register':
            data = {
                'list_input_keyword': list_input_keyword_collection,
                'list_profile_id_searched': None,
                'check_subsearch': check_subsearch,
            }
        elif location == 'member_resign':
            data = {
                'list_input_keyword': list_input_keyword_collection,
                'list_resign_profile_id_searched': None,
                'check_subsearch': check_subsearch,
            }
        HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
        return False
    return True


