#--------------------------------------------------------------------------------------------------------------------------
# 수동으로 멤버 업데이트 하기
#--------------------------------------------------------------------------------------------------------------------------
def update_member_information_by_form(request, q_mysettings_home, pk):
    q_mysettings_hr = q_mysettings_home.mysettings_hr
    q_profile = Profile.objects.get(id=pk)
    print('q_profile *********************************', q_profile.name_korean)
    form = HrLayoutRegisterMemberForm(request.POST, instance=q_profile)
    if form.is_valid():
        form.save()
    # Options
    input_date_of_birth = request.POST.get('date_of_birth')
    input_date_joined = request.POST.get('date_joined')
    input_date_left = request.POST.get('date_left')
    if input_date_of_birth is not None and input_date_of_birth != '':
        date_of_birth = datetime.datetime.strptime(input_date_of_birth, '%Y-%m-%d').date()
    else:
        date_of_birth = q_profile.date_of_birth
    if input_date_joined is not None and input_date_joined != '':
        date_joined = datetime.datetime.strptime(input_date_joined, '%Y-%m-%d').date()
    else:
        date_joined = q_profile.date_joined
    if input_date_left is not None and input_date_left != '':
        date_left = datetime.datetime.strptime(input_date_left, '%Y-%m-%d').date()
    else:
        date_left = q_profile.date_left
    phone_office = request.POST.get('phone_office')
    if phone_office == '':
        phone_office = None
    address = request.POST.get('address')
    if address == '':
        address = None
    introduction = request.POST.get('introduction')
    if introduction == '':
        introduction = None
    # Data 수집
    data = {
        'date_of_birth': date_of_birth,
        'date_joined': date_joined,
        'date_left': date_left,
        'phone_office': phone_office,
        'address': address,
        'introduction': introduction,
    }
    # Comment 입력시 Data에 Dict_Comment 추가하기
    comment = request.POST.get('textarea-comment-member-register')
    comment = comment.strip()
    if comment !='':
        dict_comment = q_profile.dict_comment
        if dict_comment is None:
            dict_comment = {}
        q_member = request.user.member
        dict_comment[q_member.id] = comment
        data['dict_comment'] = dict_comment
    # Profile Update
    Profile.objects.filter(id=q_profile.id).update(**data)
    return True



