# Member, Profile 생성/업데이트
#--------------------------------------------------------------------------------------------------------------------------
def create_user_related_member(q_user, first_name, last_name, email, name_korean, phone_mobile):
    # Member 생성/업데이트 하기
    q_member = Member.objects.filter(user=q_user).last()
    if q_member is None:
        data = {
            'user':q_user,
            'member_name': name_korean,
        }
        q_member = Member.objects.create(**data)
    else:
        data = {
            'member_name': name_korean,
            'check_discard': False,
        }
        Member.objects.filter(id=q_member.id).update(**data)
        q_member.refresh_from_db()
    return q_member


#--------------------------------------------------------------------------------------------------------------------------
# Profile 생성/업데이트
#--------------------------------------------------------------------------------------------------------------------------
def create_user_related_profile(q_user, q_member, first_name, last_name, email, name_korean, phone_mobile, phone_office, date_joined, date_of_birth):
    # Profile 생성/업데이트 하기
    q_profile = Profile.objects.filter(Q(user=q_user)).last()
    if date_joined is None:
        date_joined = q_profile.date_joined
    if date_of_birth is None:
        date_of_birth = q_profile.date_of_birth
    print('q_profile', q_profile)
    if q_profile is None:
        print('신규생성')
        data = {
            'user': q_user,
            'member': q_member,
            'first_name': first_name,
            'last_name': last_name,
            'name_korean': name_korean,
            'email': email,
            'phone_mobile': phone_mobile,
            'phone_office': phone_office,
            'date_joined': date_joined,
            'date_of_birth': date_of_birth,
        }
        q_profile = Profile.objects.create(**data)
    else:
        print('업데이트')
        data = {
            'first_name': first_name,
            'last_name': last_name,
            'name_korean': name_korean,
            'phone_mobile': phone_mobile,
            'phone_office': phone_office,
            'date_joined': date_joined,
            'date_of_birth': date_of_birth,
            'check_discard': False,
        }
        # q_profile_left = Profile.objects.filter(Q(user=q_user) & Q(check_resign=True) & Q(check_discard=True)).last()
        # if q_profile_left is not None:
        #     print('재입사 업데이트')
        #     # 퇴사자가 재입사한 경우:
        #     update_member_information_comeback(q_profile_left)
        Profile.objects.filter(id=q_profile.id).update(**data)
        q_profile.refresh_from_db()
    return q_profile


#--------------------------------------------------------------------------------------------------------------------------
# User 생성/업데이트 함수
#--------------------------------------------------------------------------------------------------------------------------
def create_or_update_users_function(username, default_password, first_name, last_name, email, name_korean, phone_mobile, phone_office, date_joined, date_of_birth):
    #--------------------------------------------------------------------------------------------------------------------------
    # 사용자정보 생성/업데이트
    # list_member_created = []
    # list_member_updated = []
    q_user = User.objects.filter(username=email).last()
    if q_user is None:
        # 사용자 생성
        data = {
            'first_name': first_name,
            'last_name': last_name,
            'email': email,
            'username': username,
        }
        q_user = User.objects.create(**data)
        q_user.set_password(default_password)
        q_user.save()
        print(f"---------------Register New User: {first_name}{last_name}------------------ ")
    else:
        # 사용자 업데이트
        data = {
            'first_name': first_name,
            'last_name': last_name,
        }
        User.objects.filter(id=q_user.id).update(**data)
        q_user.refresh_from_db()
        print(f"---------------Update Current User: {first_name}{last_name}------------------ ")
    #--------------------------------------------------------------------------------------------------------------------------
    # Member / Profile 생성/업데이트
    q_member = create_user_related_member(q_user, first_name, last_name, email, name_korean, phone_mobile)
    q_profile = create_user_related_profile(q_user, q_member, first_name, last_name, email, name_korean, phone_mobile, phone_office, date_joined, date_of_birth)
    #--------------------------------------------------------------------------------------------------------------------------
    # Profile 연관 테이블 생성
    create_or_update_profile_related_tables(q_user)
    #--------------------------------------------------------------------------------------------------------------------------
    # 기본 Mysettings 쿼리 생성
    create_or_update_default_mysettings(q_user)
    return q_user, q_member, q_profile


