#--------------------------------------------------------------------------------------------------------------------------
# 파일 업로드를 통한 프로파일 정보 생성/업데이트
#--------------------------------------------------------------------------------------------------------------------------
def hr_layout_control_create_or_update_member_profile_by_file_upload(request, q_mysettings_hr):
    q_hr_default_settings = HR_Default_Settings.objects.last()
    if q_hr_default_settings is None:
        q_hr_default_settings = create_or_update_default_hr_settings(request)
    default_password = q_hr_default_settings.default_user_password
    uploaded_file = request.FILES['file-upload-hrlayout-for-profile-only']
    df = pd.read_excel(uploaded_file, sheet_name=0, header=0, index_col=False, keep_default_na=True)
    df = df.where(pd.notnull(df), None)
    df = df.astype(object).replace(np.nan, None)
    df = df.astype(object).replace('', None)
    df = df.replace(np.nan, '', regex=True)

    # file index = No(0), Group(1), Company(2), Division(3), Team(4), Member(5), First_Name(6), Last_Name(7), Username(8), Email(9), Date_Joined(10), Date_of_Birth(11), Phone_Office(12), Phone_Mobile(13), Check_Team_Leader(14), Team_Leader(15), Division_Leader(16), Company_Leader(17)
    #################################################################################################
    # 유저-멤버-프로파일 및 사용자 업무관리 관련 기본 쿼리 생성
    for index, column in df.iterrows():
        name_korean = column[5]
        first_name = column[6]
        if first_name is not None:
            first_name = str(first_name)
            first_name = first_name.strip()
            first_name = first_name.replace(" ", "")
            first_name = first_name.capitalize()
        last_name = column[7]
        if last_name is not None:
            last_name = str(last_name)
            last_name = last_name.strip()
            last_name = last_name.capitalize()
        username = column[8]
        email = column[9]
        date_joined = column[10]

        if date_joined is not None and date_joined != '':
            date_joined_str = str(date_joined)
            if ' ' in date_joined_str:
                date_joined_str = date_joined_str.split(' ')[0]
            date_joined = datetime.datetime.strptime(date_joined_str, '%Y-%m-%d').date()
        else:
            date_joined = None
        date_of_birth = column[11]
        if date_of_birth is not None and date_of_birth != '':
            date_of_birth_str = str(date_of_birth)
            if ' ' in date_of_birth_str:
                date_of_birth_str = date_of_birth_str.split(' ')[0]
            date_of_birth = datetime.datetime.strptime(date_of_birth_str, '%Y-%m-%d').date()
        else:
            date_of_birth = None
        phone_office = column[12]
        phone_mobile = column[13]
        create_or_update_users_function(username, default_password, first_name, last_name, email, name_korean, phone_mobile, phone_office, date_joined, date_of_birth)
    return True


