def hr_layout_register_member_function(request):
    # My Settings 불러오기
    where_am_i = 'hr'
    location = 'member_register'
    q_authority = Authority.objects.filter(check_discard=False).last()
    q_mysettings_home = get_mysettings_home(request)
    q_mysettings_hr = get_xxx_my_settings(request, q_mysettings_home, where_am_i)
    ordering_field = q_mysettings_hr.selected_field_ordering
    check_display_order_field_ascending = q_mysettings_hr.check_display_order_field_ascending
    if check_display_order_field_ascending == True:
        ordering_field = f'{ordering_field}'
    else:
        ordering_field = f'-{ordering_field}'
    list_profile_id_searched = q_mysettings_hr.list_profile_id_searched
    if list_profile_id_searched is not None and len(list_profile_id_searched) > 0:
        qs_profile_searched = Profile.objects.filter(Q(id__in=list_profile_id_searched) & Q(check_discard=False)).order_by(ordering_field)
    else:
        qs_profile_searched = None
    qs_profile_all = Profile.objects.filter(Q(check_discard=False) & Q(check_resign=False)).order_by(ordering_field)
    qs_profile_discard = Profile.objects.filter(check_discard=True).order_by(ordering_field)
    q_hr_default_settings = create_or_update_default_hr_settings(request)
    # 추후 사용않는 form 삭제
    form = HrLayoutRegisterMemberForm()
    form_date = Member_Register_Date_Form()
    u_form = UserReigsterForm()
