#--------------------------------------------------------------------------------------------------------------------------
# 멤버영구학제 모달창 활성화
#--------------------------------------------------------------------------------------------------------------------------
def hr_layout_member_delete_permanently_warning_activate(request, q_mysettings_hr, pk):
    data = {
        'activate_modal_warning_delete_member_permanently': True,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True


#--------------------------------------------------------------------------------------------------------------------------
# 멤버 정보 삭제 (discard all (not delete))
#--------------------------------------------------------------------------------------------------------------------------
def hr_layout_member_delete_permanently(request, q_mysettings_hr, pk):
    if request.POST.get('checkbox-hr-layout-delete-member-permanently-confirm') != 'on':
        messages.warning(request, f'"내용을 이해했습니다" 란에 체크하지 않았습니다.')
        return False
    q_profile_id_str = request.POST.get('button-hr-layout-member-delete-permanently')
    q_profile_id = int(q_profile_id_str)
    q_profile = Profile.objects.get(id=q_profile_id)
    q_hrlayout_highest = get_my_highest_q_hrlayout_among_many(q_profile)
    messages.warning(request, f'{q_profile.name_korean}님의 {q_profile.email} 계정을 영구히 삭제하였습니다.')
    #--------------------------------------------------------------------------------------------------------------------------
    data = {
        'check_discard': True,
        'check_resign': True,
    }
    Profile.objects.filter(id=q_profile.id).update(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    qs_hrlayout = HR_Layout.objects.filter(member__user=q_profile.user)
    if qs_hrlayout is not None and len(qs_hrlayout) > 0:
        for q_hrlayout in qs_hrlayout:
            data = {
                'check_discard': False
            }
            HR_Layout.objects.filter(id=q_hrlayout.id).update(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    q_member = Member.objects.filter(user=q_profile.user).last()
    data = {
        'check_discard': False
    }
    Member.objects.filter(id=q_member.id).update(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    qs_m2t = Member2Team.objects.filter(member=q_member)
    if qs_m2t is not None and len(qs_m2t) > 0:
        for q_m2t in qs_m2t:
            data = {
                'check_discard': True,
            }
            Member2Team.objects.filter(id=q_m2t.id).update(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    qs_m2d = Member2Division.objects.filter(member=q_member)
    if qs_m2d is not None and len(qs_m2d) > 0:
        for q_m2d in qs_m2d:
            data = {
                'check_discard': True,
            }
            Member2Division.objects.filter(id=q_m2d.id).update(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    qs_m2c = Member2Company.objects.filter(member=q_member)
    if qs_m2c is not None and len(qs_m2c) > 0:
        for q_m2c in qs_m2c:
            data = {
                'check_discard': True,
            }
            Member2Company.objects.filter(id=q_m2c.id).update(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    data = {
        'hrlayout': q_hrlayout_highest, # 전임자 권한
        'shift_type': MEMBER_SHIFT_TYPE[0][0], # ('RESIGN', '퇴사에 따른 변경'),
        'member_predecessor' : None, # 전임자 멤버
        'member_successor': None, # 후임자 멤버
        'check_member_successor_exist': False,
    }
    q_hrlayout_management = HR_Layout_Member_Management.objects.create(**data)
    #--------------------------------------------------------------------------------------------------------------------------

    data = {
        'activate_modal_warning_delete_member_permanently': False,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return 'delete'

#--------------------------------------------------------------------------------------------------------------------------
# 멤버영구삭제 취소하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_layout_member_delete_permanently_cancel(request, q_mysettings_hr, pk):
    q_profile = Profile.objects.get(id=pk)
    data = {
        'activate_modal_warning_delete_member_permanently': False,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    messages.success(request, f'{q_profile.name_korean}님의 {q_profile.email} 계정정보 영구삭제를 취소하였습니다.')
    return True



