def hr_layout_update_member_function(request, pk):
    # pk is q_profile.id
    where_am_i = 'hr'
    q_mysettings_home = get_mysettings_home(request)
    q_mysettings_hr = get_xxx_my_settings(request, q_mysettings_home, where_am_i)
    #--------------------------------------------------------------------------------------------------------------------------
    # Queryset
    q_profile = Profile.objects.get(id=pk)
    if q_profile.email is None:
        data = {
            'email': request.user.email,
        }
        Profile.objects.filter(id=q_profile.id).update(**data)
    qs_member = Member.objects.filter(Q(check_discard=False) & Q(user__profile__check_discard=False))
    q_authority = Authority.objects.filter(check_discard=False).last()
    #--------------------------------------------------------------------------------------------------------------------------
    # form
    form = HrLayoutRegisterMemberForm(instance=q_profile)
    form_date = Profile_Update_Date_Form()
    form_text = Hr_Layout_Register_Member_Intro_Form(instance=q_profile)

    def registered_date_of_birth():
        if q_profile is not None:
            date_of_birth = q_profile.date_of_birth
            return date_of_birth
        else:
            return None
    def registered_date_joined():
        if q_profile is not None:
            date_joined = q_profile.date_joined
            return date_joined
        else:
            return None
    def registered_date_left():
        if q_profile is not None:
            date_left = q_profile.date_left
            return date_left
        else:
            return None

    form_hr_profile_register_date_of_birth = HR_Profile_Date_of_Birth_Register_Form(initial={'date_of_birth':registered_date_of_birth})
    form_hr_profile_register_date_joined = HR_Profile_Date_Joined_Register_Form(initial={'date_joined':registered_date_joined})
    form_hr_profile_register_date_left = HR_Profile_Date_Left_Register_Form(initial={'date_left':registered_date_left})

    ######################################################################################################
    if request.method == 'GET':
        context = {
            'COMMENT_HR': COMMENT_HR,
            # Queryset
            'q_mysettings_hr': q_mysettings_hr,
            'q_profile':q_profile,
            'q_authority': q_authority,
            # Form
            'form': form,
            'form_date': form_date,
            'form_text': form_text,
            'qs_member': qs_member,

            'form_hr_profile_register_date_of_birth': form_hr_profile_register_date_of_birth,
            'form_hr_profile_register_date_joined': form_hr_profile_register_date_joined,
            'form_hr_profile_register_date_left': form_hr_profile_register_date_left,
        }
        return context
    ######################################################################################################
    if request.method == 'POST':
        print('request. post', request.POST)

        # 멤버 정보 업데이트
        if request.POST.get('button-update-member-info') == 'true':
            return update_member_information_by_form(request, q_mysettings_home, pk)


        # 멤버영구학제 모달창 활성화
        if request.POST.get('button-hr-layout-member-delete-permanently-warning-activate') is not None:
            return hr_layout_member_delete_permanently_warning_activate(request, q_mysettings_hr, pk)

        # 멤버 영구 삭제
        if request.POST.get('button-hr-layout-member-delete-permanently') is not None:
            return hr_layout_member_delete_permanently(request, q_mysettings_hr, pk)

        # 멤버영구삭제 취소하기
        if request.POST.get('button-hr-layout-member-delete-permanently-cancel') is not None:
            return hr_layout_member_delete_permanently_cancel(request, q_mysettings_hr, pk)



        return True



