#--------------------------------------------------------------------------------------------------------------------------
# Step 1. 퇴사자 포지션 선택
#--------------------------------------------------------------------------------------------------------------------------
def select_resign_member_hrlayout(request, q_mysettings_hr, q_profile):
    q_hrlayout_id_str = request.POST.get('radio-resign-member-hrlayout-id')
    if q_hrlayout_id_str is None or q_hrlayout_id_str == '':
        messages.warning(request, f'선택된 조직도의 포지션 정보가 없습니다. 관리자에게 문의하세요.')
        return False
    q_hrlayout_id = int(q_hrlayout_id_str)
    q_hrlayout = HR_Layout.objects.get(id=q_hrlayout_id)
    if q_profile.member == q_hrlayout.member:
        data = {
            'hrlayout': q_hrlayout,
            'resign_step': 2
        }
        HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
        return True
    else:
        messages.warning(request, f'선택된 포지션은 {q_profile.member.member_name} 님의 포지션이 아닙니다.')
        return False


#--------------------------------------------------------------------------------------------------------------------------
# Step 1.  퇴사자 포지션 선택 취소
#--------------------------------------------------------------------------------------------------------------------------
def reset_select_resign_member_hrlayout(request, q_mysettings_hr, q_profile):
    q_hrlayout = q_mysettings_hr.hrlayout
    if q_profile.member == q_hrlayout.member:
        data = {
            'hrlayout': None,
            'resign_step': 1,
        }
        HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
        messages.warning(request, f'포지선 선택을 취소하였습니다.')
        return True
    else:
        messages.warning(request, f'선택된 포지션은 {q_profile.member.member_name} 님의 포지션이 아닙니다.')
        return False


#--------------------------------------------------------------------------------------------------------------------------
# Step 2. 퇴사자 후임자 검색 (옵션)
#--------------------------------------------------------------------------------------------------------------------------
def search_successor_member_to_replace_resign_member(request, q_mysettings_hr, q_profile):
    q_hrlayout_management = q_mysettings_hr.hrlayout_management
    keyword_str = request.POST.get('text-search-successor-member-name')
    if keyword_str is None or keyword_str == '':
        messages.warning(request, f'검색어 입력이 올바르지 않습니다.')
        return False
    print('keyword_str', keyword_str)
    qs_member = Member.objects.filter(Q(check_discard=False) & Q(member_name__icontains=keyword_str))
    list_resign_successor_searched_member_id = []
    if qs_member is not None and len(qs_member) > 0:
        for q_member in qs_member:
            list_resign_successor_searched_member_id.append(q_member.id)
    else:
        messages.warning(request, f'검색된 멤버가 없습니다.')
    if len(list_resign_successor_searched_member_id) == 0:
        list_resign_successor_searched_member_id = None
    data = {
        'list_resign_successor_searched_member_id': list_resign_successor_searched_member_id,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True


#--------------------------------------------------------------------------------------------------------------------------
# Step 3. 멤버 현재 포지션 정보 획득
#--------------------------------------------------------------------------------------------------------------------------
def get_member_hr_position_information(request, q_mysettings_hr):
    q_hrlayout = q_mysettings_hr.hrlayout
    q_member = q_hrlayout.member
    q_team = q_hrlayout.team
    q_division = q_hrlayout.division
    q_company = q_hrlayout.company
    check_team_leader = q_hrlayout.check_team_leader
    check_division_leader = q_hrlayout.check_division_leader
    check_company_leader = q_hrlayout.check_company_leader
    list_m2t_id = []
    list_m2d_id = []
    list_m2c_id = []
    list_t2d_id = []
    list_d2c_id = []
    list_c2g_id = []

    qs_m2t = Member2Team.objects.filter(Q(check_discard=False) & Q(team=q_team) & Q(member=q_member))
    print('qs_m2t', qs_m2t)
    if qs_m2t is not None and len(qs_m2t) > 0:
        for q_m2t in qs_m2t:
            if q_m2t.id not in list_m2t_id:
                list_m2t_id.append(q_m2t.id)

    qs_m2d = Member2Division.objects.filter(Q(check_discard=False) & Q(division=q_division) & Q(member=q_member))
    print('qs_m2d', qs_m2d)
    if qs_m2d is not None and len(qs_m2d) > 0:
        for q_m2d in qs_m2d:
            qs_d2c = Division2Company.objects.filter(Q(check_discard=False) & Q(member2division=q_m2d))
            if qs_d2c is not None and len(qs_d2c) > 0:
                for q_d2c in qs_d2c:
                    qs_c2g = Company2Group.objects.filter(Q(check_discard=False) & Q(division2company=q_d2c))
                    if qs_c2g is not None and len(qs_c2g) > 0:
                        for q_c2g in qs_c2g:
                            if q_c2g.id not in list_c2g_id:
                                list_c2g_id.append(q_c2g.id)
                    if q_d2c.id not in list_d2c_id:
                        list_d2c_id.append(q_d2c.id)
            if q_m2d.id not in list_m2d_id:
                list_m2d_id.append(q_m2d.id)

    qs_m2c = Member2Company.objects.filter(Q(check_discard=False) & Q(company=q_company) & Q(member=q_member))
    print('qs_m2c', qs_m2c)
    if qs_m2c is not None and len(qs_m2c) > 0:
        for q_m2c in qs_m2c:
            qs_c2g = Company2Group.objects.filter(Q(check_discard=False) & Q(member2company=q_m2c))
            if qs_c2g is not None and len(qs_c2g) > 0:
                for q_c2g in qs_c2g:
                    if q_c2g.id not in list_c2g_id:
                        list_c2g_id.append(q_c2g.id)
            if q_m2c.id not in list_m2c_id:
                list_m2c_id.append(q_m2c.id)

    if qs_m2t is not None and len(qs_m2t) > 0:
        for q_m2t in qs_m2t:
            print('q_m2t', q_m2t)
            qs_t2d = Team2Division.objects.filter(Q(check_discard=False) & Q(member2team=q_m2t))
            if qs_t2d is not None and len(qs_t2d) > 0:
                for q_t2d in qs_t2d:
                    print('q_t2d', q_t2d)
                    qs_d2c = Division2Company.objects.filter(Q(check_discard=False) & Q(team2division=q_t2d))
                    if qs_d2c is not None and len(qs_d2c) > 0:
                        for q_d2c in qs_d2c:
                            print('q_d2c', q_d2c)
                            qs_c2g = Company2Group.objects.filter(Q(check_discard=False) & Q(division2company=q_d2c))
                            if qs_c2g is not None and len(qs_c2g) > 0:
                                for q_c2g in qs_c2g:
                                    print('q_c2g', q_c2g)
                                    if q_c2g.id not in list_c2g_id:
                                        list_c2g_id.append(q_c2g.id)
                            if q_d2c.id not in list_d2c_id:
                                list_d2c_id.append(q_d2c.id)
                    if q_t2d.id not in list_t2d_id:
                        list_t2d_id.append(q_t2d.id)

    qs_t2d = Team2Division.objects.filter(id__in=list_t2d_id)
    qs_d2c = Division2Company.objects.filter(id__in=list_d2c_id)
    qs_c2g = Company2Group.objects.filter(id__in=list_c2g_id)
    return list_m2t_id, list_m2d_id, list_m2c_id, list_t2d_id, list_d2c_id, list_c2g_id, qs_m2t, qs_m2d, qs_m2c, qs_t2d, qs_d2c, qs_c2g



#--------------------------------------------------------------------------------------------------------------------------
# Step 2. 후임자 검색결과 중 선택하기
#
# 후임자 유/무 무관하게 HR_Layout_Member_Management 쿼리 생성
# 전임자 포지션 정보 저장 및 권한 백업 생성
#--------------------------------------------------------------------------------------------------------------------------
def select_successor_member_id_to_replace_resign_member(request, q_mysettings_hr, q_profile):
    q_user = q_profile.user
    q_member_predecessor = q_profile.user.member
    q_hrlayout = q_mysettings_hr.hrlayout
    radio_successor_check_str = request.POST.get('radio-resign-position-successor-check') # 후임자 유무 선택
    print('radio_successor_check_str', radio_successor_check_str)
    radio_selected_member_id_str = request.POST.get('radio-select-member-as-a-successor-member-id') # 검색한 멤버 중 선택한 후임자 id
    print('radio_selected_member_id_str', radio_selected_member_id_str)
    #--------------------------------------------------------------------------------------------------------------------------
    # 퇴사자 포지션과 동일한 포지션의 권한 변경 백업 내용 확인 및 삭제
    if q_hrlayout.check_division_leader == False and q_hrlayout.check_company_leader == False:
        qs_hrlayout_management_old = HR_Layout_Member_Management.objects.filter(Q(check_discard=False) & Q(hrlayout_predecessor_backup__member=q_hrlayout.member) & Q(hrlayout_predecessor_backup__team=q_hrlayout.team))
    else:
        if q_hrlayout.check_division_leader == True:
            qs_hrlayout_management_old = HR_Layout_Member_Management.objects.filter(Q(check_discard=False) & Q(hrlayout_predecessor_backup__member=q_hrlayout.member) & Q(hrlayout_predecessor_backup__division=q_hrlayout.division))
        elif q_hrlayout.check_company_leader == True:
            qs_hrlayout_management_old = HR_Layout_Member_Management.objects.filter(Q(check_discard=False) & Q(hrlayout_predecessor_backup__member=q_hrlayout.member) & Q(hrlayout_predecessor_backup__company=q_hrlayout.company))
        else:
            qs_hrlayout_management_old = None
    if qs_hrlayout_management_old is not None and len(qs_hrlayout_management_old) > 0:
        for q_hrlayout_management_old in qs_hrlayout_management_old:
            data = {
                'check_discard': True,
            }
            HR_Layout_Member_Management.objects.filter(id=q_hrlayout_management_old.id).update(**data)
            messages.success(request, f'중복되는 퇴사처리된 포지션 정보를 삭제하였습니다.')
    #--------------------------------------------------------------------------------------------------------------------------
    # q_hrlayout_management 생성
    if radio_selected_member_id_str is None or radio_selected_member_id_str == '':
        # 선택한 후임자 없음
        if radio_successor_check_str == 'false':
            # check 후임자 없음, 선택된 후임자 없음. ==> 후임자 없는 상태로 다음단계 진행
            check_member_successor_exist = False
            q_member_successor = None
            messages.success(request, f'후임자 없음으로 선택하였습니다.')
        else:
            q_member_successor = None
            # check 후임자 있음, 선택된 후임자 없음. ==> 오류. 후임자를 선택하세요
            messages.warning(request, f'후임자를 다시 선택하세요')
            return False
    else:
        # 선택한 후임자 있음
        if radio_successor_check_str == 'false':
            # check 후임자 없음, 선택된 후임자 있음. ==> 후임자 선택한 상태로 다음단계 진행
            check_member_successor_exist = True
        else:
            # check 후임자 있음, 선택된 후임자 있음. ==> 후임자 선택한 상태로 다음단계 진행
            check_member_successor_exist = True
        selected_member_id = int(radio_selected_member_id_str)
        q_member_successor = Member.objects.get(id=selected_member_id)
        messages.success(request, f'{q_member_successor.member_name}님을 후임자로 선택하였습니다.')
    data = {
        'hrlayout': q_hrlayout, # 전임자 권한
        'shift_type': MEMBER_SHIFT_TYPE[0][0], # ('RESIGN', '퇴사에 따른 변경'),
        'member_predecessor' : q_hrlayout.member, # 전임자 멤버
        'member_successor': q_member_successor, # 후임자 멤버
        'check_member_successor_exist': check_member_successor_exist,
    }
    q_hrlayout_management = HR_Layout_Member_Management.objects.create(**data)
    print('전임자', q_member_predecessor)
    print('후임자', q_member_successor)
    # Mysettings 상태 업데이트
    data = {
        'hrlayout_management': q_hrlayout_management,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    q_mysettings_hr.refresh_from_db()
    #--------------------------------------------------------------------------------------------------------------------------
    # 전임자 권한 백업하기
    # hrlayout == 전임자 권한
    print( '********************** 전임자 오리지널', q_hrlayout.id, q_hrlayout.member)
    q_hrlayout.pk = None
    q_hrlayout.save()  # <== 저장하는 순간 q_hrlayout은 신규 복제한 hrlayout 이다.
    q_hrlayout_predecessor_backup = q_hrlayout
    data = {
        'check_backup': True,
        'check_discard': True,
    }
    HR_Layout.objects.filter(id=q_hrlayout_predecessor_backup.id).update(**data)
    q_hrlayout_predecessor_backup.refresh_from_db()
    data = {
        'hrlayout_predecessor_backup': q_hrlayout_predecessor_backup,
    }
    HR_Layout_Member_Management.objects.filter(id=q_hrlayout_management.id).update(**data)
    q_hrlayout_management.refresh_from_db()
    data = {
        'hrlayout': q_hrlayout_predecessor_backup,
    }
    HR_My_Settings.objects.filter(id=q_hrlayout_management.id).update(**data)
    q_mysettings_hr.refresh_from_db()
    print( '********************** 전임자 백업', q_hrlayout_predecessor_backup.id, q_hrlayout_predecessor_backup.member)
    #--------------------------------------------------------------------------------------------------------------------------
    # 전임자 포지션 백업하기
    return_value = get_member_hr_position_information(request, q_mysettings_hr)
    data = {
        'list_m2t_id': return_value[0],
        'list_m2d_id': return_value[1],
        'list_m2c_id': return_value[2],
        'list_t2d_id': return_value[3],
        'list_d2c_id': return_value[4],
        'list_c2g_id': return_value[5],
    }
    HR_Layout_Member_Management.objects.filter(id=q_hrlayout_management.id).update(**data)
    q_hrlayout_management.refresh_from_db()
    #--------------------------------------------------------------------------------------------------------------------------
    data = {
        'hrlayout_management': q_hrlayout_management,
        'resign_step': 3,
        'list_resign_successor_searched_member_id': None,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    return True


#--------------------------------------------------------------------------------------------------------------------------
# Step 2. 후임자 선택 취소하기
#--------------------------------------------------------------------------------------------------------------------------
def reset_select_successor_member_id_to_replace_resign_member(request, q_mysettings_hr, q_profile):
    q_hrlayout_management = q_mysettings_hr.hrlayout_management
    data = {
        'check_discard': True,
    }
    HR_Layout_Member_Management.objects.filter(id=q_hrlayout_management.id).update(**data)
    data = {
        'hrlayout_management': None,
        'resign_step': 2,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    messages.warning(request, f'후임자 선택을 취소하였습니다.')
    return True


#--------------------------------------------------------------------------------------------------------------------------
# Step 3. 추가 정보 기입하기, 권한 이양/삭제 하기
#
# 퇴사일 저장
# 코멘트 저장
# 후임자 있을 경우
#     - 후임자에게 전임자의 Position(m2t/m2d/m2c) 넘겨주기
#     - 후임자에게 전임자의 권한(hrlayout) 넘겨주기
# 후임자 없는 경우
#     - 전임자 Position / 권한 삭제
#--------------------------------------------------------------------------------------------------------------------------
def save_resign_member_hrlayout(request, q_mysettings_hr, q_profile):
    q_member = q_profile.member
    q_user = q_profile.user
    q_hrlayout = q_mysettings_hr.hrlayout
    q_hrlayout_management = q_mysettings_hr.hrlayout_management
    q_hrlayout_predecessor_backup = q_hrlayout_management.hrlayout_predecessor_backup
    q_team_replaced = q_hrlayout_predecessor_backup.team
    q_division_replaced = q_hrlayout_predecessor_backup.division
    q_company_replaced = q_hrlayout_predecessor_backup.company
    list_m2t_id = q_hrlayout_management.list_m2t_id
    list_m2d_id = q_hrlayout_management.list_m2d_id
    list_m2c_id = q_hrlayout_management.list_m2c_id
    list_t2d_id = q_hrlayout_management.list_t2d_id
    list_d2c_id = q_hrlayout_management.list_d2c_id
    list_c2g_id = q_hrlayout_management.list_c2g_id
    #--------------------------------------------------------------------------------------------------------------------------
    # 사용자 입력값 확보
    date_shift = request.POST.get('date_shift')
    comment_str = request.POST.get('text-comment-resign-member')
    if comment_str is None or comment_str == '':
        comment_str = None
    #--------------------------------------------------------------------------------------------------------------------------
    # 후임자 있는 경우: 권한 이양, 조직도 포지션 멤버 교체
    # 후임자 없는 경우: 권한 삭제, 조직도 포지션 삭제
    #--------------------------------------------------------------------------------------------------------------------------
    if q_hrlayout_management.check_member_successor_exist == True:
        # 후임자 있는 경우, 전임자 권한 후임자로 대체하기
        print('# 후임자 있는 경우, 전임자 권한 후임자로 대체하기')
        q_hrlayout_predecessor = q_hrlayout_management.hrlayout # 전임자 상태의 권한 쿼리
        # print( '********************** 전임자 ==> 후임자', q_hrlayout_predecessor.id, q_hrlayout_predecessor.member)
        q_member_predecessor = q_hrlayout_management.member_predecessor
        q_member_successor = q_hrlayout_management.member_successor
        q_team_leader = q_hrlayout_predecessor.team_leader
        q_division_leader = q_hrlayout_predecessor.division_leader
        q_company_leader = q_hrlayout_predecessor.company_leader
        if q_member_predecessor == q_hrlayout_predecessor.team_leader:  # 전임자가 팀 리더이면 팀리더 까지 이양
            q_team_leader = q_member_successor
        if q_member_predecessor == q_hrlayout_predecessor.division_leader: # 전임자가 부서 리더이면 부서 리더 까지 이양
            q_division_leader = q_member_successor
        if q_member_predecessor == q_hrlayout_predecessor.company_leader: # 전임자가 부서 리더이면 부서 리더 까지 이양
            q_company_leader = q_member_successor
        data = {
            'member': q_member_successor,
            'team_leader': q_team_leader,
            'division_leader': q_division_leader,
            'company_leader': q_company_leader,
        }
        HR_Layout.objects.filter(id=q_hrlayout_predecessor.id).update(**data)
        q_hrlayout_predecessor.refresh_from_db()
        # print( '********************** 전임자 ==> 후임자', q_hrlayout_predecessor.id, q_hrlayout_predecessor.member)
        #--------------------------------------------------------------------------------------------------------------------------
        # 후임자 있는 경우, 전임자 포지션 후임자로 대체하기
        # 멤버로 엮인 포지션으로 검색하면 모두 한 번에 대체됨. 권한쿼리로 찾아서 매칭되는 포지션면 대체되어야 함.
        # 백업된 전임자의 권한 쿼리에서 포지션 찾기
        if list_m2t_id is not None and len(list_m2t_id) > 0:
            qs_m2t = Member2Team.objects.filter(id__in=list_m2t_id)
            data = {'member': q_member_successor}
            if qs_m2t is not None and len(qs_m2t) > 0:
                for q_m2t in qs_m2t:
                    if q_m2t.team == q_team_replaced:  # 백업된 전임자의 권한과 일치한 팀 포지션 물려받기
                        Member2Team.objects.filter(id=q_m2t.id).update(**data)
        if list_m2d_id is not None and len(list_m2d_id) > 0:
            qs_m2d = Member2Division.objects.filter(id__in=list_m2d_id)
            data = {'member': q_member_successor}
            if qs_m2d is not None and len(qs_m2d) > 0:
                for q_m2d in qs_m2d:
                    if q_m2d.division == q_division_replaced: # 백업된 전임자의 권한과 일치한 부서 포지션 물려받기
                        Member2Division.objects.filter(id=q_m2d.id).update(**data)
        if list_m2c_id is not None and len(list_m2c_id) > 0:
            qs_m2c = Member2Company.objects.filter(id__in=list_m2c_id)
            data = {'member': q_member_successor}
            if qs_m2c is not None and len(qs_m2c) > 0:
                for q_m2c in qs_m2c:
                    if q_m2c.company == q_company_replaced: # 백업된 전임자의 권한과 일치한 회사 포지션 물려받기
                        Member2Company.objects.filter(id=q_m2c.id).update(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    else:
        q_member_predecessor = None
        # 후임자 없는 경우, 전임자 권한 삭제하기
        print('# 후임자 없는 경우, 전임자 권한 삭제하기')
        # 멤버로 검색되는 모든 포지션을 삭제하면 복수의 다른 포지션까지 삭제되기 때문에 삭제하는 권한에 연결된 포지션만 삭제하여야 함.
        q_hrlayout_predecessor = q_hrlayout_management.hrlayout # 전임자 상태의 권한 쿼리
        data = {
            'check_discard': True,
        }
        HR_Layout.objects.filter(id=q_hrlayout_predecessor.id).update(**data)
        q_hrlayout_predecessor.refresh_from_db()
        # 후임자 없는 경우, 전임자 포지션 삭제하기
        data = {'check_discard': True}
        #-------------------------------------------------
        # m2t 포지션 삭제하기
        if list_m2t_id is not None and len(list_m2t_id) > 0:
            qs_m2t = Member2Team.objects.filter(id__in=list_m2t_id)
            if qs_m2t is not None and len(qs_m2t) > 0:
                for q_m2t in qs_m2t:
                    if q_m2t.team == q_team_replaced:  # 백업된 전임자의 권한과 일치한 팀 포지션 삭제하기
                        Member2Team.objects.filter(id=q_m2t.id).update(**data)
                        print("m2t 포지션 삭제하기", q_m2t, q_m2t.id)
                        #-------------------------------------------------
                        # t2d 포지션 삭제하기
                        if list_t2d_id is not None and len(list_t2d_id) > 0:
                            qs_t2d = Team2Division.objects.filter(id__in=list_t2d_id)
                            if qs_t2d is not None and len(qs_t2d) > 0:
                                for q_t2d in qs_t2d:
                                    if q_t2d.member2team == q_m2t:  # 백업된 전임자의 권한과 일치한 팀2부서 포지션 삭제하기
                                        Team2Division.objects.filter(id=q_t2d.id).update(**data)
                                        print("t2d 포지션 삭제하기", q_t2d)
                                        #-------------------------------------------------
                                        # d2c 포지션 삭제하기
                                        if list_d2c_id is not None and len(list_d2c_id) > 0:
                                            qs_d2c = Division2Company.objects.filter(id__in=list_d2c_id)
                                            if qs_d2c is not None and len(qs_d2c) > 0:
                                                for q_d2c in qs_d2c:
                                                    if q_d2c.team2division == q_t2d:  # 백업된 전임자의 권한과 일치한 부서2회사 포지션 삭제하기
                                                        Division2Company.objects.filter(id=q_d2c.id).update(**data)
                                                        print("d2c 포지션 삭제하기", q_d2c)
                                                        #-------------------------------------------------
                                                        # c2g 포지션 삭제하기
                                                        if list_c2g_id is not None and len(list_c2g_id) > 0:
                                                            qs_c2g = Company2Group.objects.filter(id__in=list_c2g_id)
                                                            if qs_c2g is not None and len(qs_c2g) > 0:
                                                                for q_c2g in qs_c2g:
                                                                    if q_c2g.division2company == q_d2c:  # 백업된 전임자의 권한과 일치한 회사2그룹 포지션 삭제하기
                                                                        Company2Group.objects.filter(id=q_c2g.id).update(**data)
                                                                        print("c2g 포지션 삭제하기", q_c2g)
        if list_m2d_id is not None and len(list_m2d_id) > 0:
            qs_m2d = Member2Division.objects.filter(id__in=list_m2d_id)
            if qs_m2d is not None and len(qs_m2d) > 0:
                for q_m2d in qs_m2d:
                    if q_m2d.division == q_division_replaced: # 백업된 전임자의 권한과 일치한 부서 포지션 삭제하기
                        Member2Division.objects.filter(id=q_m2d.id).update(**data)
                        print("m2d 포지션 삭제하기", q_m2d)
        if list_m2c_id is not None and len(list_m2c_id) > 0:
            qs_m2c = Member2Company.objects.filter(id__in=list_m2c_id)
            if qs_m2c is not None and len(qs_m2c) > 0:
                for q_m2c in qs_m2c:
                    if q_m2c.company == q_company_replaced: # 백업된 전임자의 권한과 일치한 회사 포지션 삭제하기
                        Member2Company.objects.filter(id=q_m2c.id).update(**data)
                        print("m2c 포지션 삭제하기", q_m2c)
    #--------------------------------------------------------------------------------------------------------------------------
    print('# hrlayout_management 상태 업데이트')
    data = {
        'date_shift': date_shift,
        'comment': comment_str,
        'check_completed': True,
    }
    HR_Layout_Member_Management.objects.filter(id=q_hrlayout_management.id).update(**data)
    data = {
        'resign_step': 1,
        'hrlayout': None,
        'hrlayout_management': None,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    print('# 퇴사자 보직 관련 모두 이양/삭제 완료한 경우.')
    print('# 전임자 member / Profile 인사정보 삭제  (퇴사시키기)')
    qs_hrlayout = HR_Layout.objects.filter(Q(check_discard=False) & Q(member=q_member) & Q(check_backup=False))  # 백업본이 아닌 권한이양 해야하는 모든 보직
    print('qs_hrlayout', qs_hrlayout)
    if len(qs_hrlayout) == 0:  # 퇴사자 보직 관련 모두 이양/삭제 완료한 경우.
        print('# 퇴사자 보직 관련 모두 이양/삭제 완료한 경우.')
        data = {
            'check_resign': True,
            'check_discard': True,
        }
        Profile.objects.filter(id=q_profile.id).update(**data)
        data = {
            'check_discard': True,
        }
        q_career = Career.objects.filter(Q(check_discard=False) & Q(user=q_user)).last()
        if q_career is not None:
            Career.objects.filter(id=q_career.id).update(**data)
        q_education = Education.objects.filter(Q(check_discard=False) & Q(user=q_user)).last()
        if q_education is not None:
            Education.objects.filter(id=q_education.id).update(**data)
        q_educationinternal = EducationInternalTreatment.objects.filter(Q(check_discard=False) & Q(user=q_user)).last()
        if q_educationinternal is not None:
            EducationInternalTreatment.objects.filter(id=q_educationinternal.id).update(**data)
        #--------------------------------------------------------------------------------------------------------
        if q_member_predecessor is not None:
            # Member 쿼리 Discard
            data = {
                'check_discard': True,
            }
            Member.objects.filter(id=q_member_predecessor.id).update(**data)
            # Member ID 제거 from Authority Table
            q_authority = Authority.objects.last()
            if q_authority is None:
                messages.warning(request, f'권한 테이블이 없습니다. 관리자에게 문의하세요.')
                return False
            list_member_id_reset = [q_member_predecessor.id]
            for AUTH_FIELD in LIST_AUTH_FIELD:
                # Field object(JSONField) 를 List로 변환
                list_auth_xxx = getattr(q_authority, AUTH_FIELD)
                if list_auth_xxx is not None and len(list_auth_xxx) > 0:
                    # 선택된 멤버 ID만 리스트에서 제거
                    list_auth_xxx = [x for x in list_auth_xxx if x not in list_member_id_reset]
                    # 제거된 리스트 다시 해당 필드에 저장
                    data = {
                        f'{AUTH_FIELD}': list_auth_xxx,
                    }
                    Authority.objects.filter(id=q_authority.id).update(**data)
        messages.success(request, f'해당 퇴사요청자의 모든 보직이 퇴사처리 되었습니다.')
        data = {
            'profile': None,
        }
        HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    else:
        print('# 퇴사자 보직 아직 남아있는 경우.')
        messages.warning(request, f'해당 퇴사요청자의 처리해야 하는 보직이 아직 남아있습니다.')
        pass
    #--------------------------------------------------------------------------------------------------------------------------
    return True



