def hr_layout_delete_member_function(request, pk):
    # pk is q_profile.id
    where_am_i = 'hr'
    q_mysettings_home = get_mysettings_home(request)
    q_mysettings_hr = get_xxx_my_settings(request, q_mysettings_home, where_am_i)
    q_profile = Profile.objects.get(id=pk)
    q_member = q_profile.user.member
    qs_member_all = Member.objects.filter(check_discard=False)
    qs_hrlayout = HR_Layout.objects.filter(Q(check_discard=False) & Q(member=q_member))
    qs_hrlayout_discard = HR_Layout.objects.filter(Q(check_discard=True)  & Q(member=q_member))
    qs_hrlayout_management_resign = HR_Layout_Member_Management.objects.filter(Q(check_discard=False) & Q(member_predecessor=q_member) & Q(shift_type=MEMBER_SHIFT_TYPE[0][0]) & Q(check_completed=True)) #  ('RESIGN', '퇴사에 따른 변경'),
    print('qs_hrlayout_management_resign', qs_hrlayout_management_resign)
    #--------------------------------------------------------------------------------------------------------------------------
    # Form
    form_date_shift = HR_Member_Date_Shift_Form()
    #--------------------------------------------------------------------------------------------------------------------------
    q_hrlayout_selected = q_mysettings_hr.hrlayout
    q_hrlayout_management_selected = q_mysettings_hr.hrlayout_management
    if q_hrlayout_selected is not None:
        if q_hrlayout_selected.member != q_profile.member:
            data = {
                'hrlayout': None,
                'hrlayout_management': None,
            }
            HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
            q_mysettings_hr.refresh_from_db()
    else:
        data = {
            'hrlayout_management': None,
        }
        HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
        q_mysettings_hr.refresh_from_db()


    #--------------------------------------------------------------------------------------------------------------------------
    if q_hrlayout_management_selected is not None:
        print('hrlayout', q_hrlayout_management_selected.hrlayout.id, q_hrlayout_management_selected.hrlayout.member)
        print('hrlayout_predecessor_backup', q_hrlayout_management_selected.hrlayout_predecessor_backup.id, q_hrlayout_management_selected.hrlayout_predecessor_backup.member)
    #--------------------------------------------------------------------------------------------------------------------------

    print('qs_hrlayout', qs_hrlayout)
    ######################################################################################################
    if request.method == 'GET':
        context = {
            'MEMBER_SHIFT_TYPE': MEMBER_SHIFT_TYPE,
            'COMMENT_HR': COMMENT_HR,
            'q_mysettings_hr': q_mysettings_hr,
            'q_profile':q_profile,
            'qs_hrlayout': qs_hrlayout,
            'qs_hrlayout_discard': qs_hrlayout_discard,
            'qs_member_all': qs_member_all,
            'qs_hrlayout_management_resign': qs_hrlayout_management_resign,
            'form_date_shift': form_date_shift,
        }
        return context
    ######################################################################################################
    if request.method == 'POST':
        print('request. post', request.POST)

        #--------------------------------------------------------------------------------------------------------------------------
        # 퇴사자 포지션 선택
        #--------------------------------------------------------------------------------------------------------------------------
        if request.POST.get('button-resign-member-hrlayout-select') == 'true':
            select_resign_member_hrlayout(request, q_mysettings_hr, q_profile)

        #--------------------------------------------------------------------------------------------------------------------------
        # 퇴사자 포지션 선택 취소
        #--------------------------------------------------------------------------------------------------------------------------
        if request.POST.get('button-resign-member-hrlayout-select-reset') == 'true':
            reset_select_resign_member_hrlayout(request, q_mysettings_hr, q_profile)

        #--------------------------------------------------------------------------------------------------------------------------
        # 퇴사자 후임자 검색
        #--------------------------------------------------------------------------------------------------------------------------
        if request.POST.get('button-search-successor-member-name') is not None:
            search_successor_member_to_replace_resign_member(request, q_mysettings_hr, q_profile)

        #--------------------------------------------------------------------------------------------------------------------------
        # 후임자 검색결과 중 선택하기
        #--------------------------------------------------------------------------------------------------------------------------
        if request.POST.get('button-successor-member-id-select') == 'true':
            select_successor_member_id_to_replace_resign_member(request, q_mysettings_hr, q_profile)

        #--------------------------------------------------------------------------------------------------------------------------
        # 후임자 선택 취소하기
        #--------------------------------------------------------------------------------------------------------------------------
        if request.POST.get('button-successor-member-id-select-reset') == 'true':
            reset_select_successor_member_id_to_replace_resign_member(request, q_mysettings_hr, q_profile)

        #--------------------------------------------------------------------------------------------------------------------------
        # 퇴사자 포지션 변경내용 저장하기
        #--------------------------------------------------------------------------------------------------------------------------
        if request.POST.get('button-successor-member-comment-confirm') == 'true':
            save_resign_member_hrlayout(request, q_mysettings_hr, q_profile)

        return False



