def hr_layout_list_resign_function(request):
    # pk is q_profile.id
    where_am_i = 'hr'
    location = 'member_resign'
    q_mysettings_home = get_mysettings_home(request)
    q_mysettings_hr = get_xxx_my_settings(request, q_mysettings_home, where_am_i)
    #--------------------------------------------------------------------------------------------------------------------------
    ordering_field = q_mysettings_hr.selected_field_ordering
    check_display_order_field_ascending = q_mysettings_hr.check_display_order_field_ascending
    if check_display_order_field_ascending == True:
        ordering_field = f'{ordering_field}'
    else:
        ordering_field = f'-{ordering_field}'
    list_resign_profile_id_searched = q_mysettings_hr.list_resign_profile_id_searched
    if list_resign_profile_id_searched is not None and len(list_resign_profile_id_searched) > 0:
        qs_profile_searched = Profile.objects.filter(id__in=list_resign_profile_id_searched).order_by(ordering_field)
    else:
        qs_profile_searched = None
    #--------------------------------------------------------------------------------------------------------------------------
    qs_profile_resign = Profile.objects.filter(Q(check_discard=True) & Q(check_resign=True)).order_by(ordering_field)
    # Sorting
    ordering_field = q_mysettings_hr.selected_field_ordering
    check_display_order_field_ascending = q_mysettings_hr.check_display_order_field_ascending
    if check_display_order_field_ascending == True:
        ordering_field = f'{ordering_field}'
    else:
        ordering_field = f'-{ordering_field}'
    qs_profile_resign = qs_profile_resign.order_by(ordering_field)

    # list_profile_id_searched = q_mysettings_hr.list_profile_id_searched
    # if list_profile_id_searched is not None and len(list_profile_id_searched) > 0:
    #     qs_profile_searched = Profile.objects.filter(Q(id__in=list_profile_id_searched) & Q(check_discard=False))
    # else:
    #     qs_profile_searched = None


    qs_hrlayout_management = HR_Layout_Member_Management.objects.filter(check_discard=False)
    if q_mysettings_hr.profile_resign is not None:
        qs_hrlayout_management_resign = HR_Layout_Member_Management.objects.filter(Q(check_discard=False) & Q(hrlayout_predecessor_backup__member=q_mysettings_hr.profile_resign.member))
    else:
        qs_hrlayout_management_resign = None
    #--------------------------------------------------------------------------------------------------------------------------
    print('qs_profile_resign', qs_profile_resign)
    print('qs_hrlayout_management_resign', qs_hrlayout_management_resign)
    ######################################################################################################
    if request.method == 'GET':
        context = {
            'MEMBER_REGISTER_FIELD': MEMBER_REGISTER_FIELD,
            'q_mysettings_hr': q_mysettings_hr,
            'qs_profile_searched': qs_profile_searched,
            'qs_profile_resign': qs_profile_resign,
            'qs_hrlayout_management': qs_hrlayout_management,
            'qs_hrlayout_management_resign': qs_hrlayout_management_resign,
        }
        return context
    ######################################################################################################
    if request.method == 'POST':
        print('request. post', request.POST)

        # 등록 멤버 리스트 Ordering
        if request.POST.get('button-list-member-ordering') is not None:
            ordering_list_member_by_button(request, q_mysettings_hr)

         # 등록 멤버 키워드 검색하기
        if request.POST.get('button-search-member-by-keyowrd') is not None:
            search_registered_member_by_keyword(request, q_mysettings_hr, location)

        # 등록 멤버 키워드 리셋하기
        if request.POST.get('button-reset-member-by-keyowrd') is not None:
            reset_registered_member_by_keyword(request, q_mysettings_hr, location)

        # 멤버 선택하기
        if request.POST.get('button-selected-resign-member-further-task') is not None:
            select_resign_memeber_from_list(request, q_mysettings_hr)

        return False
















