def hrLayoutDesignDictGeneratorM2T(qs_m2t):
    if len(qs_m2t) > 0:
        # 부서별 선택된 팀 Dict 만들기
        list_dict_m2t_selected = []
        list_dict_member_dup_check = []
        for q_m2t in qs_m2t:
            # 더미가 아닌 경우에 한해 중복제거한 팀만 모음
            if q_m2t.team is not None:
                k_q_team = q_m2t.team
                v_q_member = q_m2t.member
                if v_q_member not in list_dict_member_dup_check:
                    list_dict_member_dup_check.append(v_q_member)
                    list_dict_m2t_selected.append({k_q_team:v_q_member})
        # {k_q_division, [v_q_m2t_1, v_q_m2t_2, v_q_m2t_3 ... 서로다른팀]} 형태를 만들어야 한다.,
        dict_m2t_selected = {}
        for k, v in [(key, d[key]) for d in list_dict_m2t_selected for key in d]:
            if k not in dict_m2t_selected:
                dict_m2t_selected[k] = [v]
            else:
                dict_m2t_selected[k].append(v)
    else:
        dict_m2t_selected = None
    return dict_m2t_selected


