def reset_hr_layout(request, q_mysettings_hr):
    qs_m2t = Member2Team.objects.all()
    qs_m2t.delete()
    qs_t2d = Team2Division.objects.all()
    qs_t2d.delete()
    qs_m2d = Member2Division.objects.all()
    qs_m2d.delete()
    qs_d2c = Division2Company.objects.all()
    qs_d2c.delete()
    qs_m2c = Member2Company.objects.all()
    qs_m2c.delete()
    qs_c2g = Company2Group.objects.all()
    qs_c2g.delete()
    qs_m2g = Member2Group.objects.all()
    qs_m2g.delete()
    print("##################################################################  성공적으로 조직도를 삭제하였습니다.")
    return True


#--------------------------------------------------------------------------------------------------------------------------
# File 업로드를 통한 전체 HR조직도 생성
# m2t, t2d, d2c, c2g, m2d, m2c, m2g 생성하기
#--------------------------------------------------------------------------------------------------------------------------
def create_hr_layout(request, uploaded_file):
    q_hr_default_settings = HR_Default_Settings.objects.last()
    if q_hr_default_settings is None:
        q_hr_default_settings = create_or_update_default_hr_settings(request)
    df = pd.read_excel(uploaded_file, sheet_name=0, header=0, index_col=False, keep_default_na=True)
    df = df.where(pd.notnull(df), None)
    df = df.astype(object).replace(np.nan, None)
    df = df.astype(object).replace('', None)
    df = df.replace(np.nan, '', regex=True)

        # # collect Team, Division, Company, Group names
    list_team_names = []
    list_division_names = []
    list_company_names = []
    list_group_names = []

    # file index = No(0), Group(1), Company(2), Division(3), Team(4), Member(5), First_Name(6), Last_Name(7), Username(8), Email(9), Date_Joined(10), Date_of_Birth(11), Phone_Office(12), Phone_Mobile(13), Check_Team_Leader(14), Team_Leader(15), Division_Leader(16), Company_Leader(17)
    #################################################################################################
    print('# Step1, create_or_update User / Member / Profile / Vacation / Career / Education / EducationInternalTreatment table')
    # 유저-멤버-프로파일 및 사용자 업무관리 관련 기본 쿼리 생성
    for index, column in df.iterrows():
        group_name = column[1]
        company_name = column[2]
        division_name = column[3]
        team_name = column[4]
        name_korean = column[5]
        first_name = column[6]
        if first_name is not None:
            first_name = str(first_name)
            first_name = first_name.strip()
            first_name = first_name.replace(" ", "")
            first_name = first_name.capitalize()
        last_name = column[7]
        if last_name is not None:
            last_name = str(last_name)
            last_name = last_name.strip()
            last_name = last_name.capitalize()
        username = column[8]
        email = column[9]
        date_joined = column[10]
        print('date_joined', date_joined)
        if date_joined is not None and date_joined != '':
            date_joined_str = str(date_joined)
            if ' ' in date_joined_str:
                date_joined_str = date_joined_str.split(' ')[0]
            date_joined = datetime.datetime.strptime(date_joined_str, '%Y-%m-%d').date()
        else:
            date_joined = None
        date_of_birth = column[11]
        if date_of_birth is not None and date_of_birth != '':
            date_of_birth_str = str(date_of_birth)
            if ' ' in date_of_birth_str:
                date_of_birth_str = date_of_birth_str.split(' ')[0]
            date_of_birth = datetime.datetime.strptime(date_of_birth_str, '%Y-%m-%d').date()
        else:
            date_of_birth = None


        phone_office = column[12]
        phone_mobile = column[13]

        check_team_leader = column[14]
        team_leader_name = column[15]
        division_leader_name = column[16]
        company_leader_name = column[17]

        # datetime_joined = column[16]
        # date_joined = datetime_joined.date()
        # datetime_of_birth = column[17]
        # date_of_birth = datetime_of_birth.date()
        default_password = q_hr_default_settings.default_user_password
        #-------------------------------------------------------------------------------------------------------------------
        # Profile 쿼리 생성
        create_or_update_users_function(username, default_password, first_name, last_name, email, name_korean, phone_mobile, phone_office, date_joined, date_of_birth)
        #-------------------------------------------------------------------------------------------------------------------
        # Team, Division, Company, Group list 확보
        if team_name not in list_team_names:
            list_team_names.append(team_name)
        if division_name not in list_division_names:
            list_division_names.append(division_name)
        if company_name not in list_company_names:
            list_company_names.append(company_name)
        if group_name not in list_group_names:
            list_group_names.append(group_name)
    print('list_team_names', list_team_names)
    print('list_division_names', list_division_names)
    print('list_company_names', list_company_names)
    print('list_group_names', list_group_names)

    #################################################################################################
    # 조직 기본 유닛 생성 : Team, Division, Company, Group
    print('# Step2-2, create Team, Division, Company, Group tables //////////////////////////////////')
    for v_team_name in list_team_names:
        if v_team_name == 'Division_Leader' or v_team_name == 'Company_Leader' or v_team_name == 'Group_Leader' :
            pass
        else:
            q_team_selected = Team.objects.filter(Q(check_discard=False) & Q(team_name=v_team_name)).last()
            if q_team_selected is None:
                data = {
                    'team_name': v_team_name,
                }
                Team.objects.create(**data)
                messages.success(request, f'{v_team_name} Team을 생성하였습니다.')
    for v_division_name in list_division_names:
        if v_division_name == 'Division_Leader' or v_division_name == 'Company_Leader' or v_division_name == 'Group_Leader':
            pass
        else:
            q_division_selected = Division.objects.filter(Q(check_discard=False) & Q(division_name=v_division_name)).last()
            if q_division_selected is None:
                data = {
                    'division_name': v_division_name,
                }
                Division.objects.create(**data)
                messages.success(request, f'{v_division_name} Division을 생성하였습니다.')
    for v_company_name in list_company_names:
        if v_company_name == 'Division_Leader' or v_company_name == 'Company_Leader' or v_company_name == 'Group_Leader':
            pass
        else:
            q_company_selected = Company.objects.filter(Q(check_discard=False) & Q(company_name=v_company_name)).last()
            if q_company_selected is None:
                data = {
                    'company_name': v_company_name,
                }
                Company.objects.create(**data)
                messages.success(request, f'{v_company_name} Company를 생성하였습니다.')
    for v_group_name in list_group_names:
        q_group_selected = Group.objects.filter(Q(check_discard=False) & Q(check_is_voronoigroup=True) & Q(group_name=v_group_name)).last()
        if q_group_selected is None:
            data = {
                'group_name': v_group_name,
                'check_is_voronoigroup': True,
            }
            Group.objects.create(**data)
            messages.success(request, f'{v_group_name} Group을 생성하였습니다.')

    #################################################################################################
    # 조직도 생성 : m2t, t2d, d2c, c2g, m2d, m2c, m2g 생성
    list_total_count = []
    for index, column in df.iterrows():
        group_name = column[1]
        company_name = column[2]
        division_name = column[3]
        team_name = column[4]
        member_name = column[5]
        check_team_leader = column[14]

        print('check_team_leader', check_team_leader, type(check_team_leader))
        # team_leader_name = column[13]
        # division_leader_name = column[14]
        # company_leader_name = column[15]

        # create m2t query
        if check_team_leader == 1:
            print('Team Leader !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!')
            check_team_leader = True
        else:
            check_team_leader = False

        q_member_selected = Member.objects.filter(Q(check_discard=False) & Q(member_name=member_name)).last()
        q_team_selected = Team.objects.filter(Q(check_discard=False) & Q(team_name=team_name)).last()
        if q_team_selected is not None:
            q_m2t_selected = Member2Team.objects.filter(Q(team=q_team_selected) & Q(member=q_member_selected)).last()
            print('q_m2t_selected', q_m2t_selected, )
            data = {
                'member': q_member_selected,
                'team': q_team_selected,
                'check_team_leader': check_team_leader,
            }
            if q_m2t_selected is None:
                Member2Team.objects.create(**data)
                list_total_count.append(True)
            else:
                Member2Team.objects.filter(id=q_m2t_selected.id).update(**data)
    #-------------------------------------------------------------------------------------------------------------------
    print('# Step3-2-1, create t2d, table ///////////////////////////////////////////////////////')
    for index, column in df.iterrows():
        group_name = column[1]
        company_name = column[2]
        division_name = column[3]
        team_name = column[4]
        member_name = column[5]

        # create t2d query
        q_member_selected = Member.objects.filter(Q(check_discard=False) & Q(member_name=member_name)).last()
        q_team_selected = Team.objects.filter(Q(check_discard=False) & Q(team_name=team_name)).last()
        q_division_selected = Division.objects.filter(Q(check_discard=False) & Q(division_name=division_name)).last()
        if q_team_selected is not None:
            q_m2t_selected = Member2Team.objects.filter(Q(team=q_team_selected) & Q(member=q_member_selected)).last()
            q_t2d_selected = Team2Division.objects.filter(Q(check_discard=False) & Q(division=q_division_selected) & Q(member2team=q_m2t_selected)).last()
            data = {
                'division': q_division_selected,
                'member2team': q_m2t_selected,
            }
            if q_t2d_selected is None:
                Team2Division.objects.create(**data)
                list_total_count.append(True)
            else:
                Team2Division.objects.filter(id=q_t2d_selected.id).update(**data)
    #-------------------------------------------------------------------------------------------------------------------
    print('# Step3-3-1, create d2c, table ////////////////////////////////////////////////////////')
    for index, column in df.iterrows():
        group_name = column[1]
        company_name = column[2]
        division_name = column[3]
        team_name = column[4]
        member_name = column[5]

        # create d2c query
        q_member_selected = Member.objects.filter(Q(check_discard=False) & Q(member_name=member_name)).last()
        q_team_selected = Team.objects.filter(Q(check_discard=False) & Q(team_name=team_name)).last()
        if q_team_selected is not None:
            q_division_selected = Division.objects.filter(Q(check_discard=False) & Q(division_name=division_name)).last()
            if q_division_selected is not None:
                q_company_selected = Company.objects.filter(Q(check_discard=False) & Q(company_name=company_name)).last()
                if q_company_selected is not None:
                    q_m2t_selected = Member2Team.objects.filter(Q(team=q_team_selected) & Q(member=q_member_selected)).last()
                    q_t2d_selected = Team2Division.objects.filter(Q(check_discard=False) & Q(division=q_division_selected) & Q(member2team=q_m2t_selected)).last()
                    q_d2c_selected = Division2Company.objects.filter(Q(check_discard=False) & Q(company=q_company_selected) & Q(team2division=q_t2d_selected)).last()
                    data = {
                        'company': q_company_selected,
                        'team2division': q_t2d_selected,
                    }
                    if q_d2c_selected is None:
                        Division2Company.objects.create(**data)
                        list_total_count.append(True)
                    else:
                        Division2Company.objects.filter(id=q_d2c_selected.id).update(**data)
    #-------------------------------------------------------------------------------------------------------------------
    print('# Step3-4, create c2g table //////////////////////////////////////////////////////////////')
    for index, column in df.iterrows():
        group_name = column[1]
        company_name = column[2]
        division_name = column[3]
        team_name = column[4]
        member_name = column[5]

        # create c2g query
        q_member_selected = Member.objects.filter(Q(check_discard=False) & Q(member_name=member_name)).last()
        q_team_selected = Team.objects.filter(Q(check_discard=False) & Q(team_name=team_name)).last()
        if q_team_selected is not None:
            q_division_selected = Division.objects.filter(Q(check_discard=False) & Q(division_name=division_name)).last()
            if q_division_selected is not None:
                q_company_selected = Company.objects.filter(Q(check_discard=False) & Q(company_name=company_name)).last() # d2c로 모든걸 사용하게 되면 삭제
                if q_company_selected is not None:
                    q_m2t_selected = Member2Team.objects.filter(Q(team=q_team_selected) & Q(member=q_member_selected)).last()
                    q_t2d_selected = Team2Division.objects.filter(Q(check_discard=False) & Q(division=q_division_selected) & Q(member2team=q_m2t_selected)).last()
                    q_group_selected = Group.objects.filter(Q(check_discard=False) & Q(group_name=group_name)).last()
                    q_d2c_selected = Division2Company.objects.filter(Q(check_discard=False) & Q(company=q_company_selected) & Q(team2division=q_t2d_selected)).last()
                    if q_group_selected is not None:
                        q_c2g_selected = Company2Group.objects.filter(Q(check_discard=False) & Q(group=q_group_selected) & Q(division2company=q_d2c_selected)).last()
                        if q_c2g_selected is None:
                            data = {
                                'group': q_group_selected,
                                'division2company': q_d2c_selected,
                                'company': q_company_selected  # d2c로 모든걸 사용하게 되면 삭제
                            }
                            Company2Group.objects.create(**data)
                            list_total_count.append(True)
    #-------------------------------------------------------------------------------------------------------------------
    print('# Step3-2-2, create m2d, table ///////////////////////////////////////////////////////')
    for index, column in df.iterrows():
        group_name = column[1]
        company_name = column[2]
        division_name = column[3]
        team_name = column[4]
        member_name = column[5]

        # create m2d query
        if team_name == 'Division_Leader':
            q_member_selected = Member.objects.filter(Q(check_discard=False) & Q(member_name=member_name)).last()
            q_division_selected = Division.objects.filter(Q(check_discard=False) & Q(division_name=division_name)).last()
            if q_division_selected is not None:
                q_m2d__selected = Member2Division.objects.filter(Q(check_discard=False) & Q(member=q_member_selected) & Q(division=q_division_selected)).last()
                data = {
                    'member': q_member_selected,
                    'division': q_division_selected,
                    'check_division_leader': True
                }
                if q_m2d__selected is None:
                    Member2Division.objects.create(**data)
                    list_total_count.append(True)
                else:
                    Member2Division.objects.filter(id=q_m2d__selected.id).update(**data)

        # create m2c query
        if division_name == 'Company_Leader':
            q_member_selected = Member.objects.filter(Q(check_discard=False) & Q(member_name=member_name)).last()
            if q_company_selected is not None:
                q_company_selected = Company.objects.filter(Q(check_discard=False) & Q(company_name=company_name)).last()
                q_m2c__selected = Member2Company.objects.filter(Q(check_discard=False) & Q(member=q_member_selected) & Q(company=q_company_selected)).last()
                data = {
                    'member': q_member_selected,
                    'company': q_company_selected,
                    'check_company_leader': True
                }
                if q_m2c__selected is None:
                    Member2Company.objects.create(**data)
                    list_total_count.append(True)
                else:
                    Member2Company.objects.filter(id=q_m2c__selected.id).update(**data)
    #-------------------------------------------------------------------------------------------------------------------
    print('총 생성 쿼리 개수', list_total_count.count(True))
    return True


