def create_hr_layout_by_file_upload(request, q_mysettings_hr):
    type_table_import = request.POST.get('radio-import-hr-layout-type')
    uploaded_file = request.FILES['inputfile']
    # q_group__voronoi = Group.objects.filter(Q(check_discard=False) & Q(check_is_voronoigroup=True)).last()
