    #     }
    #     Group.objects.create(**data)
    # 모두 생성 조건인 경우(현재 이것만 가능)
    if type_table_import == 'all':
        #--------------------------------------------------------------------------------------------------------------------------
        # 기존 조직도 Reset
        reset_hr_layout(request, q_mysettings_hr)
        messages.success(request, f'성공적으로 조직도를 삭제하였습니다.')
        #--------------------------------------------------------------------------------------------------------------------------
        # 조직도 생성
        create_hr_layout(request, uploaded_file)
        messages.success(request, '인사 조직도 File을 DB에 업로드 하였습니다.')
        #--------------------------------------------------------------------------------------------------------------------------
        # 조직도 DB 업데이트
        create_authority_table(request, q_mysettings_hr)
        messages.success(request, '인사 조직도를 사용자별 DB에 저장하였습니다.')
        # # 접속권한 초기화
        # initiate_Authority_Table(request)
        # messages.success(request, '권한 Table을 DB에 생성하였습니다.')
    return True



