def hr_layout_design_home_function(request):
    ls_today = datetime.date.today()
    where_am_i = 'hr'
    q_mysettings_home = get_mysettings_home(request)
    q_mysettings_hr = get_xxx_my_settings(request, q_mysettings_home, where_am_i)

    # 디자인한 조직도, 팀장/부서장/회사장 선택하기
    # Prerequisites
    qs_member = Member.objects.filter(check_discard=False).order_by('member_name')
    qs_team = Team.objects.filter(check_discard=False).order_by('team_name')
    qs_division = Division.objects.filter(check_discard=False).order_by('division_name')
    qs_company = Company.objects.filter(check_discard=False).order_by('company_name')
    qs_group = Group.objects.filter(check_discard=False).order_by('group_name')

    qs_m2t = Member2Team.objects.filter(Q(check_discard=False) & Q(member__check_discard=False)).order_by('member')
    qs_t2d = Team2Division.objects.filter(Q(check_discard=False) & Q(member2team__check_discard=False)).order_by('member2team')
    qs_m2d = Member2Division.objects.filter(Q(check_discard=False) & Q(member__check_discard=False)).order_by('division')
    qs_d2c = Division2Company.objects.filter(Q(check_discard=False) & Q(team2division__check_discard=False)).order_by('team2division')
    qs_m2c = Member2Company.objects.filter(Q(check_discard=False) & Q(member__check_discard=False)).order_by('member')
    qs_c2g = Company2Group.objects.filter(Q(check_discard=False) & Q(company__check_discard=False)).order_by('group')

    dict_m_in_t = hrLayoutDesignDictGeneratorMinT_QS(qs_team, qs_m2t)
    dict_m_in_d = hrLayoutDesignDictGeneratorMinD_QS(qs_division, qs_m2d)
    dict_t_in_d = hrLayoutDesignDictGeneratorTinD_QS(qs_division, qs_t2d)
    dict_m_in_c = hrLayoutDesignDictGeneratorMinC_QS(qs_company, qs_m2c)
    dict_d_in_c = hrLayoutDesignDictGeneratorDinC_QS(qs_company, qs_d2c)
    dict_c_in_g = hrLayoutDesignDictGeneratorCinG_QS(qs_group, qs_c2g)

    # pprint.pprint(dict_m_in_d)
    dict_m2t_q_list = hrLayoutDesignDictGeneratorM2T(qs_m2t)
    dict_t2d_q_list = hrLayoutDesignDictGeneratorT2D(qs_t2d)
    dict_m2d_q_list = hrLayoutDesignDictGeneratorM2D(qs_m2d)
    dict_d2c_q_list = hrLayoutDesignDictGeneratorD2C(qs_d2c)
