def hrLayoutDesignT2DStep1Function(request):
    qs_team_all = Team.objects.filter(check_discard=False).order_by('team_name')
    qs_division = Division.objects.filter(check_discard=False).order_by('division_name')
    qs_t2d = Team2Division.objects.filter(check_discard=False).order_by('member2team')
    qs_m2t = Member2Team.objects.filter(check_discard=False).order_by('member')
    qs_m2d = Member2Division.objects.filter(check_discard=False).order_by('member')
    q_tslog = TeamSearchLog.objects.last()
    form = HrTeamSearchLogForm()
    qs_team = hrLayoutDesignDuplicationCheckTeamQuery(qs_t2d, q_tslog)
    # Division별로 Member 쿼리 Dict타입으로 모으기
    dict_m2d_selected = hrLayoutDesignDictGeneratorM2D(qs_m2d)
    # Division별로 Team 쿼리 Dict타입으로 모으기
    dict_t2d_selected = hrLayoutDesignDictGeneratorT2D(qs_t2d)

    if request.method == 'GET':
        context = {
            'dict_m2d_selected':dict_m2d_selected,
            'dict_t2d_selected': dict_t2d_selected,
            'form': form,
            'qs_team': qs_team,
            'qs_division': qs_division,
            'qs_t2d': qs_t2d,
            'qs_m2t':qs_m2t,
            'qs_m2d':qs_m2d,
        }
        return context
    if request.method == 'POST':

        button_division_select = request.POST.get('name-division-select')
        button_division_leader_select = request.POST.get('name-division-leader-select')
        button_division_member_deselect = request.POST.get('name-division-member-deselect')
        list_v_q_m2d_deselected_id = request.POST.getlist('member-deselected')
        list_v_q_t2d_deselected_id = request.POST.getlist('division-deselected')
        q_division_id = request.POST.get('division-selected')

        # 부서 선택하기
        if q_division_id is not None:
            q_division = Division.objects.get(id=q_division_id)
            # 선택한 부서를 활성화하기위한 더미 t2d 쿼리 생성하기
            if button_division_select == "value-division-select" :
                if q_division_id is not None:
                    data = {
                        'division': q_division,
                    }
                    Team2Division.objects.create(**data)

            # 부서 리더 선택하기
            if button_division_leader_select == 'value-division-leader-select':
                # 해당 부서 멤버 리더 리셋하기
                q_division_selected = Division.objects.get(id=q_division_id)
                qs_m2d__leader_reset = Member2Division.objects.filter(division=q_division_selected)
                data = {
                    'check_division_leader': False,
                }
                for q_m2d__leader_reset in qs_m2d__leader_reset:
                    Member2Division.objects.filter(id=q_m2d__leader_reset.id).update(**data)
                # 해당 부서 멤버 리더 세팅하기
                if len(list_v_q_m2d_deselected_id) > 0:
                    qs_m2d__leader_select = Member2Division.objects.filter(id__in=list_v_q_m2d_deselected_id)
                    data = {
                        'check_division_leader': True,
                    }
                    for q_m2d__leader_select in qs_m2d__leader_select:
                        print(q_m2d__leader_select)
                        Member2Division.objects.filter(id=q_m2d__leader_select.id).update(**data)


            # 팀/멤버 선택 해제
            if button_division_member_deselect == 'value-division-member-deselect':
                # 선택해제한 t2d 쿼리값 지우기,
                if len(list_v_q_t2d_deselected_id) > 0:
                    for v_q_t2d_deselected_id in list_v_q_t2d_deselected_id:
                        q_t2d__deselected = Team2Division.objects.get(id=v_q_t2d_deselected_id)
                        q_division__deselected = q_t2d__deselected.division
                        q_member2team__deselected = q_t2d__deselected.member2team
                        # 동일팀으로 등록된 m2t 쿼리 찾기
                        q_team__deselected = q_member2team__deselected.team
                        qs_m2t__deselected_all = Member2Team.objects.filter(team=q_team__deselected)
                        # 동일팀-동일부서로 등록된 모든 t2d 쿼리 삭제
                        for q_m2t__deselected_all in qs_m2t__deselected_all:
                            q_division__deselcted = q_t2d__deselected.division
                            qs_t2d__deselected = Team2Division.objects.filter(Q(member2team=q_m2t__deselected_all) & Q(division=q_division__deselected))
                            # 삭제 메세지 표시 데이터 획득용
                            for q_t2d__deselected in qs_t2d__deselected:
                                q_division__deselected = q_t2d__deselected.division
                                q_team__deselected = q_t2d__deselected.member2team
                                messages.success(request, f"Hi! {request.user}, 선택한 {q_division__deselected.division_name} 부서에 {q_team__deselected.team.team_name} 팀의 {q_team__deselected.member.member_name} 멤버를 삭제하였습니다.")
                            qs_t2d__deselected.delete()

                # 선택해제한 m2d 쿼리값 지우기
                if len(list_v_q_m2d_deselected_id) > 0:
                    for v_q_m2d_deselected_id in list_v_q_m2d_deselected_id:
                        q_m2d__deselected = Member2Division.objects.get(id=v_q_m2d_deselected_id)
                        q_m2d__deselected.delete()

            q_t2d__last = Team2Division.objects.last()
            return q_t2d__last.id
        else:
            messages.warning(request, f"Hi! {request.user}, 부서 선택을 먼저 하세요!")
            return False


def hrLayoutDesignT2DStep2Function(request, pk):
    print('# pk is q_t2d.id', pk)

    q_t2d__last = Team2Division.objects.get(id=pk)
    print('q_t2d__last', q_t2d__last)
    q_division = q_t2d__last.division
    print('q_division', q_division)
    qs_division = Division.objects.filter(check_discard=False).order_by('division_name')
    qs_t2d = Team2Division.objects.filter(check_discard=False).order_by('member2team')
    qs_m2t = Member2Team.objects.filter(check_discard=False).order_by('member')
    qs_m2d = Member2Division.objects.filter(check_discard=False).order_by('member')
    qs_team_all = Team.objects.filter(check_discard=False)
    q_tslog = TeamSearchLog.objects.last()


    # Division별로 Member 쿼리 Dict타입으로 모으기
    dict_m2d_selected = hrLayoutDesignDictGeneratorM2D(qs_m2d)
    # Division별로 Team 쿼리 Dict타입으로 모으기
    dict_t2d_selected = hrLayoutDesignDictGeneratorT2D(qs_t2d)
    form = HrTeamSearchLogForm(instance=q_tslog)
    # 조건별 선택 가능 팀 리스트에 뿌릴 팀 쿼리 계산
    # 최초 검색은 쿼리가 없다.
    qs_team = hrLayoutDesignDuplicationCheckTeamQuery(qs_t2d, q_tslog)
    ##############################################################
    if request.method == 'GET':
        context = {
            'dict_m2d_selected':dict_m2d_selected,
            'dict_t2d_selected':dict_t2d_selected,
            'form':form,
            'q_t2d': q_t2d__last,
            'qs_t2d':qs_t2d,
            'qs_division': qs_division,
            'qs_team': qs_team,
            'qs_team_all':qs_team_all,
            'qs_m2t': qs_m2t,
        }
        return context
    ##############################################################
    if request.method == 'POST':
        print('request.POST', request.POST)

        if request.POST.get('button-reset') == 'true':
            TeamSearchLog.objects.create()
            return False

        if request.POST.get('button-select') == 'true':
            # 선택한 팀들을 t2d 쿼리 생성하기, q_team_id값을 리스트로 받는다.
            list_q_team_selected_id_str = request.POST.getlist('team-selected')
            #print('list_q_team_selected_id_str', list_q_team_selected_id_str)

            if len(list_q_team_selected_id_str) > 0:
                list_q_team_selected_id = list(map(int, list_q_team_selected_id_str))

                # 선택된 팀을 포함하는 m2t 쿼리들을 모은다.
                for q_team_selected_id in list_q_team_selected_id:
                    q_team_selected = Team.objects.get(id=q_team_selected_id)
                    if q_team_selected is not None:
                        qs_m2t__selected = Member2Team.objects.filter(team=q_team_selected)

                        if len(qs_m2t__selected) > 0:
                            # m2t 쿼리들을 해당 t2d 쿼리 생성에 사용한다.
                            for q_m2t_selected in qs_m2t__selected:
                                data = {
                                    'member2team': q_m2t_selected,
                                    'division': q_division,
                                }
                                Team2Division.objects.create(**data)

                                messages.success(request, f"Hi! {request.user}, 선택한 {q_division.division_name} 부서에 {q_m2t_selected.team.team_name} 팀의 {q_m2t_selected.member.member_name} 멤버를 등록하였습니다.")
                                # 더미 t2d 쿼리 지우기 (하나이상의 팀을 선택하여 팀을 생성하는 경우)
                                qs_t2d__member2team_null = Team2Division.objects.filter(member2team__isnull=True)
                                if qs_t2d__member2team_null is not None:
                                    qs_t2d__member2team_null.delete()
                        else:
                            messages.warning(request, f"Hi! { request.user.profile.name_korean }, 선택한 팀에 소속된 멤버가 없습니다. 팀에 멤버를 등록하세요.ㅣ")
                            return False
                    else:
                        messages.warning(request, f"Hi! { request.user.profile.name_korean }, 선택한 팀에 소속된 멤버가 없습니다. 팀에 멤버를 등록하세요.ㅣ")
                        return False



                q_t2d__last = Team2Division.objects.last()

                # 팀 리스트 검색 쿼리/설정 저장
                form = HrTeamSearchLogForm(request.POST, instance=q_tslog)
                if form.is_valid():
                    form.save()
                # 팀 리스트 표시 모드 변경 체크
                q_tslog__last = TeamSearchLog.objects.last()
                search_keyword = request.POST.get('search_keyword').replace(" ", "")
                if search_keyword is not None:
                    qs_team = Team.objects.filter(Q(team_name__icontains=search_keyword))
                    list_team_id_searched = []
                    for q_team in qs_team:
                        list_team_id_searched.append(q_team.id)
                    data = {
                        'list_team_id_searched':list_team_id_searched,
                    }
                    TeamSearchLog.objects.filter(id=q_tslog__last.id).update(**data)
                return q_t2d__last.id
            else:
                return False



