def hrLayoutDesignM2DStep1Function(request):
    qs_division = Division.objects.filter(check_discard=False).order_by('division_name')
    qs_t2d = Team2Division.objects.filter(check_discard=False).order_by('member2team')
    qs_m2d = Member2Division.objects.filter(check_discard=False).order_by('member')
    q_tslog = TeamSearchLog.objects.last()
    qs_m2t = Member2Team.objects.filter(check_discard=False).order_by('member')
    q_mslog = MemberSearchLog.objects.last()
    # 팀에 이미 등록된 멤버 중복 제거하기
    qs_member = hrLayoutDesignDuplicationCheckMemberQuery()
    # Division별로 Team 쿼리 Dict타입으로 모으기
    dict_t2d_selected = hrLayoutDesignDictGeneratorT2D(qs_t2d)
    # Division별로 Member 쿼리 Dict타입으로 모으기
    dict_m2d_selected = hrLayoutDesignDictGeneratorM2D(qs_m2d)
    # 멤버 검색 입력 Form
    form = HrMemberSearchLogForm(instance=q_mslog)
    # 최초 검색은 쿼리가 없다.
    if request.method == 'GET':
        context = {
            'dict_m2d_selected':dict_m2d_selected,
            'dict_t2d_selected':dict_t2d_selected,
            'qs_member':qs_member,
            'form':form,
            'qs_division': qs_division,
        }
        return context
    if request.method == 'POST':
        button_division_select = request.POST.get('name-division-select')
        button_division_leader_select = request.POST.get('name-division-leader-select')
        button_division_member_deselect = request.POST.get('name-division-member-deselect')
        q_division_id = request.POST.get('division-selected')

        list_v_q_t2d_deselected_id = request.POST.getlist('division-deselected')
        list_v_q_m2d_deselected_id = request.POST.getlist('member-deselected')

        # 부서 선택하기
        if q_division_id is not None:
            q_division = Division.objects.get(id=q_division_id)
            # 선택한 부서를 활성화하기위한 더미 t2d 쿼리 생성하기
            if button_division_select == "value-division-select" :
                if q_division_id is not None:
                    data = {
                        'division': q_division,
                    }
                    Member2Division.objects.create(**data)

            # 부서 리더 선택하기
            if button_division_leader_select == 'value-division-leader-select':
                # 해당 부서 멤버 리더 리셋하기
                q_division_selected = Division.objects.get(id=q_division_id)
                qs_m2d__leader_reset = Member2Division.objects.filter(division=q_division_selected)
                data = {
                    'check_division_leader': False,
                }
                for q_m2d__leader_reset in qs_m2d__leader_reset:
                    Member2Division.objects.filter(id=q_m2d__leader_reset.id).update(**data)
                # 해당 부서 멤버 리더 세팅하기
                if len(list_v_q_m2d_deselected_id) > 0:
                    qs_m2d__leader_select = Member2Division.objects.filter(id__in=list_v_q_m2d_deselected_id)
                    data = {
                        'check_division_leader': True,
                    }
                    for q_m2d__leader_select in qs_m2d__leader_select:
                        print(q_m2d__leader_select)
                        Member2Division.objects.filter(id=q_m2d__leader_select.id).update(**data)


            # 팀/멤버 선택 해제
            # 선택해제한 t2d 쿼리값 지우기
            if button_division_member_deselect == 'value-division-member-deselect':
                if len(list_v_q_t2d_deselected_id) > 0:
                    for v_q_t2d_deselected_id in list_v_q_t2d_deselected_id:
                        q_t2d__deselected = Team2Division.objects.get(id=v_q_t2d_deselected_id)
                        q_member2team__deselected = q_t2d__deselected.member2team
                        q_member2team__team_deselected = q_member2team__deselected.team
                        qs_m2t__deselected = Member2Team.objects.filter(team=q_member2team__team_deselected)

                        for q_m2t__deselected in qs_m2t__deselected:
                            q_division__deselcted = q_t2d__deselected.division
                            qs_t2d__deselected = Team2Division.objects.filter(Q(member2team=q_m2t__deselected) & Q(division=q_division__deselcted))
                            qs_t2d__deselected.delete()
                            for q_t2d__deselected in qs_t2d__deselected:
                                q_division__deselected = q_t2d__deselected.division
                                q_team__deselected = q_t2d__deselected.member2team
                                messages.success(request, f"Hi! {request.user}, 선택한 {q_division__deselected.division.division_name} 부서에 {q_team__deselected.team.team_name} 팀을 삭제하였습니다.")


                # 선택해제한 m2d 쿼리값 지우기
                if len(list_v_q_m2d_deselected_id) > 0:
                    for v_q_m2d_deselected_id in list_v_q_m2d_deselected_id:
                        q_m2d__deselected = Member2Division.objects.get(id=v_q_m2d_deselected_id)
                        q_m2d__deselected.delete()
                        messages.success(request, f"Hi! {request.user}, 선택한 {q_m2d__deselected.division.division_name} 부서에 {q_m2d__deselected.member.member_name} 멤버를 삭제하였습니다.")

            q_m2d__last = Member2Division.objects.last()
            return q_m2d__last.id
        else:
            messages.warning(request, f"Hi! {request.user}, 부서 선택을 먼저 하세요!")
            return False


def hrLayoutDesignM2DStep2Function(request, pk):
    # pk is q_m2d.id
    print('pk', pk)
    q_m2d__last = Member2Division.objects.get(id=pk)
    q_division = q_m2d__last.division
    qs_division = Division.objects.filter(check_discard=False).order_by('division_name')
    qs_t2d = Team2Division.objects.filter(check_discard=False).order_by('member2team')
    qs_team_all = Team.objects.filter(check_discard=False)
    q_tslog = TeamSearchLog.objects.last()
    qs_m2t = Member2Team.objects.filter(check_discard=False).order_by('member')
    qs_m2d = Member2Division.objects.filter(check_discard=False)
    q_mslog = MemberSearchLog.objects.last()
    # 멤버 중복 제거하기(검색불일치, 팀/부서/회사 등록된 멤버)
    qs_member = hrLayoutDesignDuplicationCheckMemberQuery()
    dict_t2d_selected = hrLayoutDesignDictGeneratorT2D(qs_t2d)
    dict_m2d_selected = hrLayoutDesignDictGeneratorM2D(qs_m2d)
    form = HrMemberSearchLogForm(instance=q_mslog)
    # 조건별 선택 가능 팀 리스트에 뿌릴 팀 쿼리 계산
    # 최초 검색은 쿼리가 없다.
    if request.method == 'GET':
        context = {
            'dict_m2d_selected':dict_m2d_selected,
            'dict_t2d_selected':dict_t2d_selected,
            'form':form,
            'qs_t2d':qs_t2d,
            'qs_division': qs_division,
            'q_division': q_division,
            'qs_member':qs_member,
            'qs_m2t': qs_m2t,
            'qs_m2d':qs_m2d,
            'q_m2d':q_m2d__last,
        }
        return context
    if request.method == 'POST':
        reset = request.POST.get('reset')
        if reset == 'true':
            MemberSearchLog.objects.create()
        else:
            # Reset이 아닌 경우
            # 선택한 멤버들을 m2t 쿼리 생성하기
            list_q_member_selected_id = request.POST.getlist('member-selected')

            # 동일부서에 멤버의 중복은 제거함(생성하지 않아야 함.)
            for q_member_id in list_q_member_selected_id:
                q_member = Member.objects.get(id=q_member_id)
                qs_m2d__member_division = Member2Division.objects.filter(Q(member=q_member) & Q(division=q_division))
                if len(qs_m2d__member_division) == 0:
                    data = {
                        'member': q_member,
                        'division': q_division,
                    }
                    Member2Division.objects.create(**data)
                    messages.success(request, f"Hi! {request.user}, 선택한 {q_division.division_name} 부서에 {q_member.member_name} 멤버를 등록하였습니다.")
                    # 더미 m2t 쿼리 지우기 (조건은 Select 버튼으로 m2t쿼리를 생성하나? , 그냥 검색하기 위해 select 버튼을 누른거면 지우면 안됨.)
                    # 멤버 한 명 이상 선택한 경우 + 성공적으로 m2d쿼리를 생성한 경우만 더미 지우기
                    if len(list_q_member_selected_id) > 0:
                        if len(qs_m2d) > 1:
                            qs_m2d__member_null = Member2Division.objects.filter(member__isnull=True)
                            if qs_m2d__member_null is not None:
                                qs_m2d__member_null.delete()
                else:
                    messages.warning(request, f"선택한 {q_member.member_Name} 멤버는 이미 해당 부서에 등록되어 있습니다. 동일 부서에 중복 등록할 수 없습니다!")
            q_m2d__last = Member2Division.objects.last()

            # 팀 선택 쿼리값을 step2로 넘기기 위한 더미 쿼리 지우기
            # 멤버 리스트 검색 쿼리/설정 저장
            form = HrMemberSearchLogForm(request.POST, instance=q_mslog)
            if form.is_valid():
                form.save()
            # 멤버 리스트 표시 모드 변경 체크
            q_mslog__last = MemberSearchLog.objects.last()
            search_keyword = request.POST.get('search_keyword').replace(" ", "")
            if search_keyword is not None:
                qs_member = Member.objects.filter(Q(member_name__icontains=search_keyword))
                list_member_id_searched = []
                for q_member in qs_member:
                    list_member_id_searched.append(q_member.id)
                data = {
                    'list_member_id_searched':list_member_id_searched,
                }
                MemberSearchLog.objects.filter(id=q_mslog__last.id).update(**data)
        return q_m2d__last.id



