def hrLayoutDesignD2CStep1Function(request):
    qs_division_all = Division.objects.filter(check_discard=False).order_by('division_name')
    qs_company = Company.objects.filter(check_discard=False).order_by('company_name')
    qs_d2c = Division2Company.objects.filter(check_discard=False).order_by('team2division')
    qs_t2d = Team2Division.objects.filter(check_discard=False).order_by('member2team')
    qs_m2t = Member2Team.objects.filter(check_discard=False).order_by('member')
    qs_m2c = Member2Company.objects.filter(check_discard=False).order_by('member')
    q_dslog = DivisionSearchLog.objects.last()

    form = HrDivisionSearchLogForm()
    dict_t2d_selected = hrLayoutDesignDictGeneratorT2D(qs_t2d)
    dict_d2c_selected = hrLayoutDesignDictGeneratorD2C(qs_d2c)
    dict_m2c_selected = hrLayoutDesignDictGeneratorM2C(qs_m2c)
    qs_division = hrLayoutDesignDuplicationCheckDivisionQuery(qs_d2c, q_dslog)

    if request.method == 'GET':
        context = {
            'dict_m2c_selected': dict_m2c_selected,
            'dict_t2d_selected': dict_t2d_selected,
            'dict_d2c_selected': dict_d2c_selected,
            'form': form,
            'qs_company': qs_company,
            'qs_division': qs_division,
            'qs_d2c': qs_d2c,
            'qs_t2d':qs_t2d,
            'qs_m2t':qs_m2t,
        }
        return context
    if request.method == 'POST':
        # 선택한 부서를 활성화하기위한 더미 d2c 쿼리 생성하기
        q_company_id = request.POST.get('company-selected')
        if q_company_id is not None:
            q_company = Company.objects.get(id=q_company_id)
            button_company_select = request.POST.get('name-company-select')
            button_company_leader_select = request.POST.get('name-company-leader-select')
            button_company_member_deselect = request.POST.get('name-company-member-deselect')
            list_v_q_d2c_deselected_id = request.POST.getlist('division-deselected')
            list_v_q_m2c_deselected_id = request.POST.getlist('member-deselected')

            # 회사 선택하기
            # 선택한 회사를 활성화하기위한 더미 d2c 쿼리 생성하기
            if button_company_select == "value-company-select" :
                data = {
                    'company': q_company,
                }
                Division2Company.objects.create(**data)
            else:
                pass
            # 회사 리더 선택하기
            if button_company_leader_select == 'value-company-leader-select':
                # 해당 회사 리더 리셋하기
                q_company_selected = Company.objects.get(id=q_company_id)
                qs_m2c__leader_reset = Member2Company.objects.filter(company=q_company_selected)
                data = {
                    'check_company_leader': False,
                }
                for q_m2c__leader_reset in qs_m2c__leader_reset:
                    Member2Company.objects.filter(id=q_m2c__leader_reset.id).update(**data)
                # 해당 회사 리더 세팅하기
                if len(list_v_q_m2c_deselected_id) > 0:
                    qs_m2c__leader_select = Member2Company.objects.filter(id__in=list_v_q_m2c_deselected_id)
                    data = {
                        'check_company_leader': True,
                    }
                    for q_m2c__leader_select in qs_m2c__leader_select:
                        Member2Company.objects.filter(id=q_m2c__leader_select.id).update(**data)

            # 부서/멤버 선택해제
            if button_company_member_deselect == 'value-company-member-deselect':

                # 선택해제한 d2c 쿼리값 지우기
                if len(list_v_q_d2c_deselected_id) > 0:
                    print('list_v_q_d2c_deselected_id', list_v_q_d2c_deselected_id)
                    for v_q_d2c_deselected_id in list_v_q_d2c_deselected_id:
                        q_d2c__deselected = Division2Company.objects.get(id=v_q_d2c_deselected_id)
                        q_company__deselected = q_d2c__deselected.company
                        q_m2d__deselected_d2c = q_d2c__deselected.member2division
                        q_t2d__deselected_d2c = q_d2c__deselected.team2division
                        # 해당 회사에 상응하는 D2C쿼리가 다 지워졌지만 M2C쿼리가 남은 경우 M2C 쿼리도 모두 삭제
                        # 해당 부서의 D2C 쿼리가 다 삭제되었는지 확인 (동일 division의 모든 t2d 쿼리 확인)
                        if q_t2d__deselected_d2c is None:
                            qs_d2c__deselected_member = Division2Company.objects.filter(Q(member2division__isnull=False) & Q(company=q_company__deselected))
                            qs_d2c__deselected_member.delete()
                        else:
                            q_division__deselected = q_t2d__deselected_d2c.division
                            qs_t2d__deselected_all = Team2Division.objects.filter(division=q_division__deselected)
                            # 동일부서-동일회사로 등록된 모든 d2c쿼리 삭제
                            for q_t2d__deselected_all in qs_t2d__deselected_all:
                                qs_d2c__deselcted_t2d = Division2Company.objects.filter(Q(team2division=q_t2d__deselected_all) & Q (company=q_company__deselected))
                                qs_d2c__deselcted_t2d.delete()

                # 선택해제한 m2c 쿼리값 지우기
                if len(list_v_q_m2c_deselected_id) > 0:
                    print('list_v_q_m2c_deselected_id', len(list_v_q_m2c_deselected_id))
                    for v_q_m2c_deselected_id in list_v_q_m2c_deselected_id:
                        q_m2c__deselected = Member2Company.objects.get(id=v_q_m2c_deselected_id)
                        q_member__deselected_m2c = q_m2c__deselected.member
                        q_company__deselected = q_m2c__deselected.company
                        # 동일 회사에 중복된 멤버 쿼리까지 모두 삭제하기 위함.
                        qs_m2c__deselected = Member2Company.objects.filter(Q(member=q_member__deselected_m2c) & Q(company=q_company__deselected))
                        qs_m2c__deselected.delete()

            q_d2c__last = Division2Company.objects.last()
            return q_d2c__last.id
        else:
            messages.warning(request, f"Hi! {request.user}, 회사 선택을 먼저 하세요!")
            return False


def hrLayoutDesignD2CStep2Function(request, pk):
    # 검색을 하였는데, Company에 등록한 division이 아직 없는 경우는 pk값으로 검색되는 q_d2c__last값이 없다.
    # 보통은 등록하기 전에 더미값을 하나 가지고 있다. (회사 선택하고 나면 자동 생성되는)
    # 더미를 미리 지우지 마라., 하나 이상 회사에 부서를 등록하기 전까지는 더미를 지우면 안된다.
    # pk is q_d2c.id
    q_d2c__last = Division2Company.objects.get(id=pk)
    q_company = q_d2c__last.company
    qs_division_all = Division.objects.filter(check_discard=False).order_by('division_name')
    qs_company = Company.objects.filter(check_discard=False).order_by('company_name')
    qs_t2d = Team2Division.objects.filter(check_discard=False).order_by('division')
    qs_d2c = Division2Company.objects.filter(check_discard=False).order_by('company')
    qs_m2c = Member2Company.objects.filter(check_discard=False).order_by('member')
    qs_division_all = Division.objects.filter(check_discard=False)
    q_dslog = DivisionSearchLog.objects.last()

    dict_t2d_selected = hrLayoutDesignDictGeneratorT2D(qs_t2d)
    dict_d2c_selected = hrLayoutDesignDictGeneratorD2C(qs_d2c)
    dict_m2c_selected = hrLayoutDesignDictGeneratorM2C(qs_m2c)
    form = HrDivisionSearchLogForm(instance=q_dslog)
    # 조건별 선택 가능 팀 리스트에 뿌릴 팀 쿼리 계산
    # 최초 검색은 쿼리가 없다.
    qs_division = hrLayoutDesignDuplicationCheckDivisionQuery(qs_d2c, q_dslog)
    ############################################################
    if request.method == 'GET':
        context = {
            'dict_m2c_selected':dict_m2c_selected,
            'dict_t2d_selected':dict_t2d_selected,
            'dict_d2c_selected':dict_d2c_selected,
            'form':form,
            'q_d2c': q_d2c__last,
            'qs_d2c':qs_d2c,
            'qs_t2d': qs_t2d,
            'qs_division': qs_division,
            'qs_division_all':qs_division_all,
            'qs_company': qs_company,
            'q_company':q_company,
        }
        return context
    ############################################################
    if request.method == 'POST':
        print('request.POST', request.POST)

        if request.POST.get('button-reset') == 'true':
            DivisionSearchLog.objects.create()

        if request.POST.get('button-select') == 'true':
            # 선택한 부서들을 d2c 쿼리 생성하기, 선택한 q_division id값을 리스트로 받는다.
            list_q_division_selected_id_str = request.POST.getlist('division-selected')

            if len(list_q_division_selected_id_str) > 0:
                list_q_division_selected_id = list(map(int, list_q_division_selected_id_str))

                # 선택된 부서를 포함하는 d2c 쿼리들을 모은다.
                for q_division_selected_id in list_q_division_selected_id:
                    q_division_selected = Division.objects.get(id=int(q_division_selected_id))
                    qs_t2d__selected = Team2Division.objects.filter(division=q_division_selected)
                    qs_m2d__selected = Member2Division.objects.filter(division=q_division_selected)


                    if len(qs_t2d__selected) > 0:
                        # t2d 쿼리들을 해당 d2c 쿼리 생성에 사용한다.
                        for q_t2d_selected in qs_t2d__selected:
                            # 동일 회사에 동일 부서 중복 생성 방지 체크
                            qs_t2d__dup_check = Division2Company.objects.filter(Q(check_discard=False) & Q(team2division=q_t2d_selected) & Q(company=q_company))
                            if len(qs_t2d__dup_check) == 0:
                                data = {
                                    'team2division': q_t2d_selected,
                                    'company': q_company,
                                }
                                Division2Company.objects.create(**data)
                    else:
                        messages.warning(request, f"Hi! { request.user.profile.name_korean }, 선택한 부서에 소속된 팀이 없습니다. 부서에 팀을 등록하세요.ㅣ")
                        return False

                    if len(qs_m2d__selected) > 0:
                        # m2d 쿼리들을 해당 d2c 쿼리 생성에 사용한다.
                        for q_m2d__selected in qs_m2d__selected:
                            qs_m2d__dup_check = Division2Company.objects.filter(Q(check_discard=False) & Q(member2division=q_m2d__selected) & Q(company=q_company))
                            if len(qs_m2d__dup_check) == 0:
                                data = {
                                    'member2division': q_m2d__selected,
                                    'company': q_company,
                                }
                                Division2Company.objects.create(**data)
                    else:
                        messages.warning(request, f"Hi! { request.user.profile.name_korean }, 선택한 부서에 소속된 멤버가 없습니다. 부서에 멤버를 등록하세요.ㅣ")
                        return False

                # 더미 d2c 쿼리 지우기 (하나 이상의 부서를 선택하여 d2c쿼리를 생성하는 경우)
                if len(qs_d2c) > 1 :
                    qs_d2c__dummy = Division2Company.objects.filter(Q(check_discard=False) & Q(team2division__isnull=True) & Q(member2division__isnull=True))
                    if qs_d2c__dummy is not None:
                        qs_d2c__dummy.delete()


            q_d2c__last = Division2Company.objects.last()

            # 팀 리스트 검색 쿼리/설정 저장
            form = HrDivisionSearchLogForm(request.POST, instance=q_dslog)
            if form.is_valid():
                form.save()
            # 팀 리스트 표시 모드 변경 체크
            search_keyword = request.POST.get('search_keyword').replace(" ", "")
            if search_keyword is not None:
                q_dslog__last = DivisionSearchLog.objects.last()
                qs_division = Division.objects.filter(Q(division_name__icontains=search_keyword))
                list_division_id_searched = []
                for q_division in qs_division:
                    list_division_id_searched.append(q_division.id)
                data = {
                    'list_division_id_searched':list_division_id_searched,
                }
                DivisionSearchLog.objects.filter(id=q_dslog__last.id).update(**data)
        return q_d2c__last.id


