def reset_c2g_company_list():
    q_cslog = CompanySearchLog.objects.last()
    print('q_cslog', q_cslog)
    # 모든 회사 id 리스트
    list_company_id_all = []
    qs_company = Company.objects.filter(check_discard=False)
    for q_company in qs_company:
        if q_company.id not in list_company_id_all:
            list_company_id_all.append(q_company.id)

    # 등록된 회사 id 리스트 찾기(더미가 아닌 모든 c2g 쿼리 이용)
    qs_c2g = Company2Group.objects.filter(company__isnull=False)
    # 쿼리에서 회사 id 리스트화(그룹에 등록된 회사 리스트화)
    list_company_id_registered_in_group = []
    if qs_c2g is not None:
        for q_c2g in qs_c2g:
            if q_c2g.company.id not in list_company_id_registered_in_group:
                list_company_id_registered_in_group.append(q_c2g.company.id)


    # 모든회사 id - 등록된 회사 id (차집합) 을 통한 등록안된 회사 id 찾기
    list_company_id_not_registered_in_group = []
    if len(list_company_id_all) > 0:
        for company_id in list_company_id_all :
            if company_id not in list_company_id_registered_in_group:
                list_company_id_not_registered_in_group.append(company_id)

    # Search company id DB 업데이트, 최초 등록시 생성, 이후 업데이트
    data={
        'list_company_id_searched': list_company_id_not_registered_in_group
    }
    qs_cslog = CompanySearchLog.objects.filter(check_discard=False)
    if len(qs_cslog) == 0:
        CompanySearchLog.objects.create(**data)
    else:
        CompanySearchLog.objects.filter(id=q_cslog.id).update(**data)


def hrLayoutDesignC2GStep1Function(request):
    qs_c2g = Company2Group.objects.filter(check_discard=False)
    qs_group = Group.objects.filter(check_discard=False)
    qs_m2c = Member2Company.objects.filter(check_discard=False)
    q_cslog = CompanySearchLog.objects.last()
    dict_m2c_selected = hrLayoutDesignDictGeneratorM2C(qs_m2c)
    dict_c2g_selected = hrLayoutDesignDictGeneratorC2G(qs_c2g)
    qs_company = hrLayoutDesignDuplicationCheckCompanyQuery(qs_c2g, q_cslog)

    form = HrCompanySearchLogForm(instance=q_cslog)

    ###################################################
    if request.method == "GET":
        context={
            'qs_company': qs_company,
            'qs_c2g': qs_c2g,
            'qs_group': qs_group,
            'dict_m2c_selected':dict_m2c_selected,
            'dict_c2g_selected':dict_c2g_selected,
            'form':form,
        }
        return context
    ###################################################
    if request.method == "POST":
        # 선택한 그룹을 활성화하기위한 더미 c2g 쿼리 생성하기
        button_group_select = request.POST.get('button-group-select')
        if button_group_select == 'true':
            q_group_id = request.POST.get('group-selected-id')
            if q_group_id is not None:
                q_group = Group.objects.get(id=int(q_group_id))
                # 선택한 그룹를 활성화하기위한 더미 c2g 쿼리 생성하기
                data = {
                    'group': q_group,
                }
                Company2Group.objects.create(**data)
                # 마지막 c2g 쿼리 찾기
                q_c2g__last = Company2Group.objects.last()
                return q_c2g__last.id
            else:
                messages.warning(request, f"Hi! {request.user}, 그룹 선택을 먼저 하세요!")
                return False
        else:
            messages.warning(request, f"Hi! {request.user}, 그룹 선택을 먼저 하세요!")
            return False
        # 회사/ 선택해제
        button_group_deselect = request.POST.get('button-company-deselect')
        if button_group_deselect == 'true':
            list_v_q_c2g_deselected_id = request.POST.getlist('company-deselected-id')
            # 선택해제한 c2g 쿼리값 지우기
            if len(list_v_q_c2g_deselected_id) > 0:
                list_v_q_c2g_deselected_id_int = list(map(int, list_v_q_c2g_deselected_id))
                for v_q_c2g_deselected_id_int in list_v_q_c2g_deselected_id_int:
                    q_c2g__deselected = Company2Group.objects.get(id=v_q_c2g_deselected_id_int)
                    q_group__deselected = q_c2g__deselected.group
                    q_company__deselected_c2g = q_c2g__deselected.company
                    # 해당 회사의 C2G 쿼리가 다 삭제되었는지 확인 (동일 company의 모든 company 쿼리 확인)
                    if q_company__deselected_c2g is None:
                        qs_c2g__deselected_member = Company2Group.objects.filter(Q(company__isnull=False) & Q(group=q_group__deselected))
                        qs_c2g__deselected_member.delete()
                # 마지막 c2g 쿼리 찾기
                q_c2g__last = Company2Group.objects.last()
                return q_c2g__last.id
            else:
                messages.warning(request, f"Hi! {request.user}, 회사를 하나 이상 선택하세요!")
                return False
        else:
            messages.warning(request, f"Hi! {request.user}, 그룹 선택을 먼저 하세요!")
            return False


def hrLayoutDesignC2GStep2Function(request, pk):
    # pk is q_c2g__last.id
    qs_c2g = Company2Group.objects.filter(check_discard=False)
    q_c2g = Company2Group.objects.get(id=pk)
    q_group = q_c2g.group
    qs_group = Group.objects.filter(check_discard=False)
    qs_m2c = Member2Company.objects.filter(check_discard=False)
    q_cslog = CompanySearchLog.objects.last()
    dict_m2c_selected = hrLayoutDesignDictGeneratorM2C(qs_m2c)
    dict_c2g_selected = hrLayoutDesignDictGeneratorC2G(qs_c2g)

    qs_company = hrLayoutDesignDuplicationCheckCompanyQuery(qs_c2g, q_cslog)
    form = HrCompanySearchLogForm(instance=q_cslog)

    ###################################################
    if request.method == "GET":
        context={
            'qs_company': qs_company,
            'qs_c2g': qs_c2g,
            'q_c2g':q_c2g,
            'qs_group': qs_group,
            'dict_m2c_selected':dict_m2c_selected,
            'dict_c2g_selected':dict_c2g_selected,
            'form':form,
        }
        return context
    ###################################################
    if request.method == "POST":
        print(request.POST)
        # 선택한 그룹을 활성화하기위한 더미 c2g 쿼리 생성하기
        button_group_select = request.POST.get('button-group-select')
        if button_group_select == 'true':

            q_group_id = request.POST.get('group-selected-id')
            if q_group_id is not None:
                q_group_selected = Group.objects.get(id=int(q_group_id))
                # 선택한 그룹를 활성화하기위한 더미 c2g 쿼리 생성하기
                data = {
                    'group': q_group_selected,
                }
                Company2Group.objects.create(**data)
                # 마지막 c2g 쿼리 찾기
                q_c2g__last = Company2Group.objects.last()
                return q_c2g__last.id
            else:
                messages.warning(request, f"Hi! {request.user}, 그룹 선택을 먼저 하세요!")
                return False

        # 회사 선택해제
        button_group_deselect = request.POST.get('button-company-deselect')
        if button_group_deselect == 'true':
            list_v_q_c2g_deselected_id = request.POST.getlist('company-deselected-id')
            # 선택해제한 c2g 쿼리값 지우기
            if len(list_v_q_c2g_deselected_id) > 0:
                list_v_q_c2g_deselected_id_int = list(map(int, list_v_q_c2g_deselected_id))
                for v_q_c2g_deselected_id_int in list_v_q_c2g_deselected_id_int:
                    q_c2g__deselected = Company2Group.objects.get(id=v_q_c2g_deselected_id_int)
                    q_group__deselected = q_c2g__deselected.group
                    q_company__deselected = q_c2g__deselected.company
                    # 선택된 그룹의 선택해제를 위해 선택한 회사와 동일한 쿼리는 모두 찾아서 삭제
                    if q_company__deselected is not None:
                        qs_c2g__deselected_member = Company2Group.objects.filter(Q(company=q_company__deselected) & Q(group=q_group__deselected))
                        qs_c2g__deselected_member.delete()
                    # 회사 선택하기 리스트 리셋
                    reset_c2g_company_list()
                # 마지막 c2g 쿼리 찾기
                q_c2g__last = Company2Group.objects.last()
                return q_c2g__last.id
            else:
                messages.warning(request, f"Hi! {request.user}, 회사를 하나 이상 선택하세요!")
                q_c2g__last = Company2Group.objects.last()
                return q_c2g__last.id


        # 회사 선택 및 그룹에 저장(C2G 쿼리 생성)
        button_select = request.POST.get('button-select')
        if button_select == 'true':
            # 선택한 회사 아이디값이 들어왔는 경우
            list_company_selected_id = request.POST.getlist('company-selected-id')
            if len(list_company_selected_id) > 0:
                list_company_selected_id_int = list(map(int, list_company_selected_id))
                qs_company__selected = Company.objects.filter(id__in=list_company_selected_id_int)
                for q_company_selected in qs_company__selected :
                    data = {
                        'company': q_company_selected,
                        'group': q_group
                    }
                    Company2Group.objects.create(**data)
                    # 마지막 c2g 쿼리 찾기
                q_c2g__last = Company2Group.objects.last()
                # 회사 선택하기 리스트 리셋
                reset_c2g_company_list()
                return q_c2g__last.id

            # 회사 검색 키워드값이 들어온 경우
            # 회사 리스트 검색 쿼리/설정 저장
            search_keyword = request.POST.get('search_keyword')
            list_search_keyword = re.sub("[^\w]", " ",  search_keyword).split()
            if len(list_search_keyword) > 0:
                check_company_search_duplication = request.POST.get('check_company_search_duplication')
                if check_company_search_duplication == 'on':
                    check_company_search_duplication = True
                else:
                    check_company_search_duplication = False
                list_company_id_searched = []
                for search_keyword in list_search_keyword:
                    qs_company = Company.objects.filter(Q(company_name__icontains=search_keyword))
                    for q_company in qs_company:
                        if q_company.id not in list_company_id_searched:
                            list_company_id_searched.append(q_company.id)
                data = {
                    'check_company_search_duplication':check_company_search_duplication,
                    'list_search_keyword': list_search_keyword,
                    'list_company_id_searched':list_company_id_searched,
                }
                CompanySearchLog.objects.create(**data)
                # 마지막 c2g 쿼리 찾기
                q_c2g__last = Company2Group.objects.last()
                return q_c2g__last.id
            # 둘 다 아닌 경우
            else:
                messages.warning(request, f"Hi! {request.user}, 회사를 하나 이상 선택 혹은 검색 키워드값을 입력하세요!")
                q_c2g__last = Company2Group.objects.last()
                return q_c2g__last.id

        button_reset = request.POST.get('button-reset')
        if button_reset == 'true':
            reset_c2g_company_list()
            q_c2g__last = Company2Group.objects.last()
            return q_c2g__last.id




