#--------------------------------------------------------------------------------------------------------------------------
# 기본 공통함수
#--------------------------------------------------------------------------------------------------------------------------

# 대쉬보드 테이블 페이지 넘기기
def page_next_authpanel(request, q_mysettings_home):
    # q_profile__last = Profile.objects.filter(Q(check_discard=False) & Q(user=request.user)).last()
    q_mysettings_hr = q_mysettings_home.mysettings_hr
    page_number_auth_panel = q_mysettings_hr.page_number_auth_panel
    if page_number_auth_panel == 4:
        page_number_auth_panel = 1
    else:
        page_number_auth_panel = page_number_auth_panel + 1
    data = {
        'page_number_auth_panel': page_number_auth_panel
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True


