# 키워드로 멤버 검색하기
def search_authority_member_by_keyword(request, q_mysettings_home):
    q_mysettings_hr = q_mysettings_home.mysettings_hr

    # q_authority = q_mysettings_hr.authority
    radio_search_type_str = request.POST.get('radio-search-type')
    input_text_str = request.POST.get('input-search-authpanel-byname')
    # print('input_text_str', input_text_str)
    if input_text_str != "":
        list_member_hr_id_searched = []

        if radio_search_type_str == 'member':
            qs_hrlayout_searched = HR_Layout.objects.filter(Q(check_discard=False) & Q(member__member_name__icontains=input_text_str))
            if len(qs_hrlayout_searched) == 0:
                data = {
                    'check_searched': False,
                    'list_member_hr_id_searched': None,
                    'check_member_searched_selected': False,
                }
                HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
                messages.warning(request, f'검색된 내용이 없습니다.')
                return False
            for q_hrlayout_searched in qs_hrlayout_searched:
                list_member_hr_id_searched.append(q_hrlayout_searched.id)
                messages.success(request, f'{len(list_member_hr_id_searched)} 명이 검색되었습니다.')

        elif radio_search_type_str == 'team':
            qs_hrlayout_searched = HR_Layout.objects.filter(Q(check_discard=False) & Q(team__team_name__icontains=input_text_str))
            if len(qs_hrlayout_searched) == 0:
                data = {
                    'check_searched': False,
                    'list_member_hr_id_searched': None,
                    'check_member_searched_selected': False,
                }
                HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
                messages.warning(request, f'검색된 내용이 없습니다.')
                return False
            else:
                for q_hrlayout_searched in qs_hrlayout_searched:
                    list_member_hr_id_searched.append(q_hrlayout_searched.id)
                messages.success(request, f'{len(list_member_hr_id_searched)} 명이 검색되었습니다.')


        elif radio_search_type_str == 'division':
            qs_hrlayout_searched = HR_Layout.objects.filter(Q(check_discard=False) & Q(division__division_name__iexact=input_text_str))
            if len(qs_hrlayout_searched) == 0:
                data = {
                    'check_searched': False,
                    'list_member_hr_id_searched': None,
                    'check_member_searched_selected': False,
                }
                HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
                messages.warning(request, f'검색된 내용이 없습니다.')
                return False
            else:
                for q_hrlayout_searched in qs_hrlayout_searched:
                    list_member_hr_id_searched.append(q_hrlayout_searched.id)
                messages.success(request, f'{len(list_member_hr_id_searched)} 명이 검색되었습니다.')

        data = {
            'check_searched': True,
            'list_member_hr_id_searched': list_member_hr_id_searched,
            'check_member_searched_selected': False,
        }
        HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    else:
        messages.warning(request, f'검색어를 입력하지 않았습니다.')
        return False




