def create_authority_table(request, q_mysettings_hr):
    qs_hrlayout = HR_Layout.objects.filter(check_discard=False)
    # 새로 조직도 저장 #######################################
    q_group__voronoi = Group.objects.filter(Q(check_discard=False) & Q(check_is_voronoigroup=True)).last()
    list_member_hrlayout = []
    if q_group__voronoi is not None:
        #-------------------------------------------------------------------------------------------------------------------
        # 팀원 / 팀장 획득
        qs_m2t = Member2Team.objects.filter(check_discard=False)
        # print('qs_m2t', len(qs_m2t))
        if qs_m2t is not None and len(qs_m2t) > 0:
            for q_m2t in qs_m2t:
                q_group = q_group__voronoi
                q_company = None
                q_division = None
                q_team = None
                q_member = None
                q_team_leader = None
                q_division_leader = None
                q_company_leader = None
                check_team_leader = False
                check_division_leader = False
                check_company_leader = False
                #--------------------------------------------------------------------------------------------
                # 멤버 찾기
                q_member = q_m2t.member
                # print('q_member', q_member.member_name)
                #--------------------------------------------------------------------------------------------
                # 팀 찾기
                q_team = q_m2t.team
                # print('q_team', q_team.team_name)
