# Authority Table 업데이트 (updated 20220518)
#--------------------------------------------------------------------------------------------------------------------------
def update_authority_dashboard_panel(request, q_mysettings_home):
    q_mysettings_hr = q_mysettings_home.mysettings_hr
    page_number_auth_panel = q_mysettings_hr.page_number_auth_panel
    list_member_hr_id_searched  = q_mysettings_hr.list_member_hr_id_searched
    # print('list_member_hr_id_searched', list_member_hr_id_searched)
    if list_member_hr_id_searched is None:
        list_member_hr_id_searched = []
    qs_hr_member_searched = HR_Layout.objects.filter(id__in=list_member_hr_id_searched)
    list_member_id_searched = []
    for q_hr_member_searched in qs_hr_member_searched:
        if q_hr_member_searched.member.id not in list_member_id_searched:
            list_member_id_searched.append(q_hr_member_searched.member.id)
    # print('list_member_id_searched', list_member_id_searched)
    q_authority = Authority.objects.filter(check_discard=False).last()
    if q_authority is None:
        q_authority = initiate_Authority_Table(request)
        data = {
            'authority': q_authority,
        }
        HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)

    # 공통 ################################################################################################
    # Check list 받아서 Authority 테이블 업데이트
    def get_list_auto_level_adjusted_member_id(q_authority, AUTH_FIELD, list_checkbox_auth_p_id_str, list_checkbox_auth_r_id_str, list_checkbox_auth_v_id_str, list_checkbox_auth_d_id_str):
        # 리스트에서 empty item('') 제거
        list_checkbox_auth_p_id_str = [x for x in list_checkbox_auth_p_id_str if len(x.strip()) > 0]
        list_checkbox_auth_r_id_str = [x for x in list_checkbox_auth_r_id_str if len(x.strip()) > 0]
        list_checkbox_auth_v_id_str = [x for x in list_checkbox_auth_v_id_str if len(x.strip()) > 0]
        list_checkbox_auth_d_id_str = [x for x in list_checkbox_auth_d_id_str if len(x.strip()) > 0]
        # 하위 레벨 리스트에 상위레벨 추가자 넣기
        if len(list_checkbox_auth_d_id_str) > 0 :
            for auth_d_id_str in list_checkbox_auth_d_id_str:
                list_checkbox_auth_v_id_str.append(auth_d_id_str)
                list_checkbox_auth_r_id_str.append(auth_d_id_str)
                list_checkbox_auth_p_id_str.append(auth_d_id_str)
        if len(list_checkbox_auth_v_id_str) > 0 :
            for auth_d_id_str in list_checkbox_auth_v_id_str:
                list_checkbox_auth_r_id_str.append(auth_d_id_str)
                list_checkbox_auth_p_id_str.append(auth_d_id_str)
        if len(list_checkbox_auth_r_id_str) > 0 :
            for auth_d_id_str in list_checkbox_auth_r_id_str:
                list_checkbox_auth_p_id_str.append(auth_d_id_str)
        # 중복 제거
        list_checkbox_auth_p_id_str = list(set(list_checkbox_auth_p_id_str))
        list_checkbox_auth_r_id_str = list(set(list_checkbox_auth_r_id_str))
        list_checkbox_auth_v_id_str = list(set(list_checkbox_auth_v_id_str))
        list_checkbox_auth_d_id_str = list(set(list_checkbox_auth_d_id_str))
        # 체크박스로 들어온 멤버리스트 id Int로 변환 (empty list도 변환됨)
        list_checkbox_auth_p_id = list(map(int, list_checkbox_auth_p_id_str))
        list_checkbox_auth_r_id = list(map(int, list_checkbox_auth_r_id_str))
        list_checkbox_auth_v_id = list(map(int, list_checkbox_auth_v_id_str))
        list_checkbox_auth_d_id = list(map(int, list_checkbox_auth_d_id_str))

        # 선택한 field 기존 등록된 멤버 리스트 확보
        list_auth_field_group_name = [ f'auth_{AUTH_FIELD}', f'auth_{AUTH_FIELD}_register', f'auth_{AUTH_FIELD}_validation', f'auth_{AUTH_FIELD}_design']
        # list_auth_field_member_id = []
        i = 0
        for auth_field_group_name in list_auth_field_group_name:
            # 각 필드 기존 멤버들 ID 리스트 확보
            list_auth_xxx_member_id = getattr(q_authority, auth_field_group_name)
            # 기존 멤버들 리스트에서 현재 페이지 멤버 리스트 삭제
            if list_auth_xxx_member_id is not None and len(list_auth_xxx_member_id) > 0:
                for member_id_searched in list_member_id_searched:
                    if member_id_searched in list_auth_xxx_member_id:
                        list_auth_xxx_member_id.remove(member_id_searched)
            else:
                list_auth_xxx_member_id = []
            # 현재 페이지 새 멤버 리스트 추가
            if i == 0:
                for xxx_member_id in list_auth_xxx_member_id:
                    if xxx_member_id not in list_checkbox_auth_p_id:
                        list_checkbox_auth_p_id.append(xxx_member_id)
            elif i == 1:
                for xxx_member_id in list_auth_xxx_member_id:
                    if xxx_member_id not in list_checkbox_auth_r_id:
                        list_checkbox_auth_r_id.append(xxx_member_id)
            elif i == 2:
                for xxx_member_id in list_auth_xxx_member_id:
                    if xxx_member_id not in list_checkbox_auth_v_id:
                        list_checkbox_auth_v_id.append(xxx_member_id)
            elif i == 3:
                for xxx_member_id in list_auth_xxx_member_id:
                    if xxx_member_id not in list_checkbox_auth_d_id:
                        list_checkbox_auth_d_id.append(xxx_member_id)
            else:
                pass
            i = i + 1
        return list_checkbox_auth_p_id, list_checkbox_auth_r_id, list_checkbox_auth_v_id, list_checkbox_auth_d_id
    # -------------------------------------------------------------------------------------

    # page별 authority part
    if page_number_auth_panel == 1:
        list_auth_section_test = ['member', 'todo', 'chatgpt', 'competitor', 'program', 'tpp', 'target', 'tracking']
    elif page_number_auth_panel == 2:
        list_auth_section_test = ['aieln', 'aigeneration', 'pdf2smiles', 'rxnfinder', 'compound', 'project', 'structure', 'kpviewer', 'patentability', 'sar', 'inventory', 'controlcompound', 'compoundsynthesis', 'compoundscreening']
    elif page_number_auth_panel == 3:
        list_auth_section_test = ['biostudy', 'bioeln', 'dashboard', 'dashboardpk', 'exceldownload', 'tumormanager', 'iacuc', 'protocol', 'screeninginvitro', 'screeninginvivo']
    elif page_number_auth_panel == 4:
        list_auth_section_test = ['bd', 'bdqna', 'finance', 'hr', 'ip', 'material', 'purchasing']
    else:
        list_auth_section_test = []

    # 신규 변경내용 업데이트
    for AUTH_FIELD in list_auth_section_test:
        # 현재 페이지에서 해당 필드의 최종 선택된 멤버 리스트 받아오기
        list_checkbox_auth_p_id_str = request.POST.getlist(f'checkbox-auth-{AUTH_FIELD}-id')
        list_checkbox_auth_r_id_str = request.POST.getlist(f'checkbox-auth-{AUTH_FIELD}-register-id')
        list_checkbox_auth_v_id_str = request.POST.getlist(f'checkbox-auth-{AUTH_FIELD}-validation-id')
        list_checkbox_auth_d_id_str = request.POST.getlist(f'checkbox-auth-{AUTH_FIELD}-design-id')
        return_value = get_list_auto_level_adjusted_member_id(q_authority, AUTH_FIELD, list_checkbox_auth_p_id_str, list_checkbox_auth_r_id_str, list_checkbox_auth_v_id_str, list_checkbox_auth_d_id_str)
        # 리스트 저장하기
        data = {
            f'auth_{AUTH_FIELD}': return_value[0],
            f'auth_{AUTH_FIELD}_register': return_value[1],
            f'auth_{AUTH_FIELD}_validation': return_value[2],
            f'auth_{AUTH_FIELD}_design': return_value[3],
        }
        Authority.objects.filter(id=q_authority.id).update(**data)
    return True


#--------------------------------------------------------------------------------------------------------------------------
# 선텍한 멤버 Authority 리셋하기 (선택한 멤버의 모든 Auth 필드에서 선텍 삭제)
#--------------------------------------------------------------------------------------------------------------------------
def reset_selected_member_authority(request, q_mysettings_home):
    q_mysettings_hr = q_mysettings_home.mysettings_hr
    q_authority = q_authority = Authority.objects.filter(Q(check_discard=False)).last()

    # 선텍된 멤버 리스트 확보
    list_member_id_selected_str = request.POST.getlist('checkbox-auth-member-hrlayout-select-id')
    if list_member_id_selected_str != "":
        list_member_id_selected = list(map(int, list_member_id_selected_str))

    # list_member_hrlayout_id_str = request.POST.getlist('checkbox-auth-member-hrlayout-select-id')
    # if len(list_member_hrlayout_id_str) > 0 :
    #     # 멤버 ID를 Int로 전환
    #     list_member_hrlayout_id = list(map(int, list_member_hrlayout_id_str))
    #     qs_hrlayout = HR_Layout.objects.filter(id__in=list_member_hrlayout_id)
    #     list_member_id_selected = []
    #     if qs_hrlayout is not None and len(qs_hrlayout) > 0:
    #         for q_hrlayout in qs_hrlayout:
    #             if q_hrlayout.member.id not in list_member_id_selected:
    #                 list_member_id_selected.append(q_hrlayout.member.id)

    if len(list_member_id_selected) > 0 :
        # 멤버 ID를 Int로 전환
        list_member_id_reset = list(map(int, list_member_id_selected))
        list_auth_member = q_authority.auth_member
        for AUTH_FIELD in LIST_AUTH_FIELD:
            # Field object(JSONField) 를 List로 변환
            list_auth_xxx = getattr(q_authority, AUTH_FIELD)
            if list_auth_xxx is not None and len(list_auth_xxx) > 0:
                # 선택된 멤버 ID만 리스트에서 제거
                list_auth_xxx = [x for x in list_auth_xxx if x not in list_member_id_reset]
                # 제거된 리스트 다시 해당 필드에 저장
                data = {
                    f'{AUTH_FIELD}': list_auth_xxx,
                }
                Authority.objects.filter(id=q_authority.id).update(**data)
    return True


#--------------------------------------------------------------------------------------------------------------------------
# 모든 멤버 Authority 리셋하기
#--------------------------------------------------------------------------------------------------------------------------
def reset_all_member_authority(request, q_mysettings_home):
    q_mysettings_hr = q_mysettings_home.mysettings_hr
    list_member_hr_id_searched = q_mysettings_hr.list_member_hr_id_searched
    q_authority = Authority.objects.filter(check_discard=False).last()
    qs_member = Member.objects.filter(check_discard=False).order_by('member_name')
    # list를 비우기
    for AUTH_FIELD in LIST_AUTH_FIELD:
        data = {
            f'{AUTH_FIELD}': [],
        }
        Authority.objects.filter(id=q_authority.id).update(**data)
    # 특정 field 값 채우기
    list_member_all_id = []
    for q_member in qs_member:
        list_member_all_id.append(q_member.id)
    data = {
        'auth_member': list_member_all_id,
    }
    Authority.objects.filter(id=q_authority.id).update(**data)
    q_authority.refresh_from_db()
    data = {
        'list_member_hr_id_searched': list_member_hr_id_searched,
        'list_member_id_all_part': [],
        'list_member_id_searched': [],
        'check_member_searched_selected': False,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return q_authority


