def hr_authority_home_function(request):
    pk = request.user.id
    # My Settings 불러오기
    q_authority = initiate_authority_for_superuser(request)
    q_authority = Authority.objects.filter(check_discard=False).last()
    where_am_i = 'hr'
    q_mysettings_home = get_mysettings_home(request)
