# Mail 발송
def hr_document_issued_mailing_service_for_approval_process(request, q_hr_document_issued):
    print('************************* Mail 발송 시작 ****************************')
    return True
    #--------------------------------------------------------------------------------------------------------------------------
    # 기본정보 수집
    q_profile = q_hr_document_issued.owner.profile
    q_document_format = q_hr_document_issued.document_format
    q_hrapproval = q_hr_document_issued.hrapproval

    status_document_approval_process = q_hrapproval.status_document_approval_process
    list_dict_document_approver = q_hrapproval.list_dict_document_approver
    list_dict_document_takeover = q_hrapproval.list_dict_document_takeover
    list_dict_document_referrer = q_hrapproval.list_dict_document_referrer
    list_dict_document_receiver = q_hrapproval.list_dict_document_receiver

    #--------------------------------------------------------------------------------------------------------------------------
    # 보내야 하는 메일주소 확보
    #--------------------------------------------------------------------------------------------------------------------------
    # 정보 획득
    mailing_data_owner = {
        'email': q_profile.email,
        # 'email': 'hsk2@voronoi.io',
        'name': q_profile.name_korean,
        'position': q_profile.position,
    }

    list_mailing_data = []
    # list_mailing_data_approver = []
    # list_mailing_data_takeover = []
    # list_mailing_data_referrer = []
    # list_mailing_data_receiver = []
    if status_document_approval_process == 'UNDER_APPROVAL':
        # 수정중, 다음 승인권자에게 메일 보냄
        approver_id_last = 1
        for dict_document in list_dict_document_approver:
            # 다음 승인권자 찾기
            if 'validation' in dict_document:
                approver_id = dict_document['id']
                if approver_id_last < approver_id:
                    approver_id_last = approver_id + 1
        for dict_document in list_dict_document_approver:
            if dict_document['id'] == approver_id_last:
                # 다음 승인권자만 리스트에 넣기
                data = {
                'email': dict_document['email'],
                'name': dict_document['name'],
                'position': dict_document['position'],
            }
                list_mailing_data.append(data)
    if status_document_approval_process == 'REQ_MODIFICATION':
        # 수정요청, 문서작성자에게 메일보냄
        list_mailing_data.append(mailing_data_owner)
        pass
    if status_document_approval_process == 'DONE_MODIFICATION':
        # 수정완료, 현재 승인권자에게 메일보냄
        approver_id_last = 1
        for dict_document in list_dict_document_approver:
            # 현재 승인권자 찾기
            if 'validation' in dict_document:
                approver_id = dict_document['id']
                if approver_id_last < approver_id:
                    approver_id_last = approver_id
        for dict_document in list_dict_document_approver:
            if dict_document['id'] == approver_id_last:
                # 다음 승인권자만 리스트에 넣기
                data = {
                'email': dict_document['email'],
                'name': dict_document['name'],
                'position': dict_document['position'],
            }
                list_mailing_data.append(data)
    if status_document_approval_process == 'APPROVED':
        # 승인완료, 문서작성자, 업무인수자, 참조자, 수신처 메일보냄
        list_mailing_data.append(mailing_data_owner)
        if list_dict_document_takeover is not None and len(list_dict_document_takeover) > 0:
            for dict_document in list_dict_document_takeover:
                data = {
                    'email': dict_document['email'],
                    'name': dict_document['name'],
                    'position': dict_document['position'],
                }
                list_mailing_data.append(data)
        if list_dict_document_referrer is not None and len(list_dict_document_referrer) > 0:
            for dict_document in list_dict_document_referrer:
                data = {
                    'email': dict_document['email'],
                    'name': dict_document['name'],
                    'position': dict_document['position'],
                }
                list_mailing_data.append(data)
        if list_dict_document_receiver is not None and len(list_dict_document_receiver) > 0:
            for dict_document in list_dict_document_receiver:
                data = {
                    'email': dict_document['email'],
                    'name': dict_document['name'],
                    'position': dict_document['position'],
                }
                list_mailing_data.append(data)
    if status_document_approval_process == 'REJECTED':
        # 승인거절, 문서작성자에게 메일보냄
        list_mailing_data.append(mailing_data_owner)
    if status_document_approval_process == 'CANCEL':
        # 승인취소, 기승인한 승인권자에게 메일보냄
        approver_id_last = 1
        for dict_document in list_dict_document_approver:
            # 마지막 승인관련 Action을 취한 승인권자 찾기
            if 'validation' in dict_document:
                approver_id = dict_document['id']
                if approver_id_last < approver_id:
                    approver_id_last = approver_id
        for dict_document in list_dict_document_approver:
            if dict_document['id'] <= approver_id_last:
                # 마지막 승인관련 Action을 취한 승인권자 이전 승인권자 모두 메일 보냄
                data = {
                    'email': dict_document['email'],
                    'name': dict_document['name'],
                    'position': dict_document['position'],
                }
                list_mailing_data.append(data)
    #--------------------------------------------------------------------------------------------------------------------------
    # 최종 발송메일 주소 획득
