#--------------------------------------------------------------------------------------------------------------------------
# HR_Layout 정보로 인사정보 Dictionay 값으로 찾아주기
#--------------------------------------------------------------------------------------------------------------------------
def hr_get_selected_member_hr_information_dictionary_format(q_hrlayout):
    q_profile = q_hrlayout.member.user.profile
    position_str = get_my_position_title_and_update_to_q_hrlayout(q_hrlayout)
    email_str = q_profile.email
    data = {
        'name': q_hrlayout.member.user.profile.name_korean,
        'position': position_str,
        'email': email_str,
        'hrlayout_id': q_hrlayout.id,
        'profile_id': q_profile.id,
    }
    return data


#--------------------------------------------------------------------------------------------------------------------------
# 검색한 멤버 인사정보 List Dictionay 값으로 찾아주기
#--------------------------------------------------------------------------------------------------------------------------
def hr_get_searched_member_hr_information_list_dictionary_format(keyword):
    qs_hrlayout = HR_Layout.objects.filter(Q(check_discard=False) & (Q(member__user__profile__name_korean__icontains=keyword) | Q(team__team_name__icontains=keyword))).order_by('team__team_name', 'member__user__profile__name_korean')
    #--------------------------------------------------------------------------------------------------------------------------
    list_searched_dict_document_xxx = []
    if qs_hrlayout is not None and len(qs_hrlayout) > 0:
        for q_hrlayout in qs_hrlayout:
            data = hr_get_selected_member_hr_information_dictionary_format(q_hrlayout)
            list_searched_dict_document_xxx.append(data)
    return list_searched_dict_document_xxx




#--------------------------------------------------------------------------------------------------------------------------
# 본인 직책의 Position 명명하기
#--------------------------------------------------------------------------------------------------------------------------
def get_my_position_title_and_update_to_q_hrlayout(q_hrlayout):
    if q_hrlayout is not None:
        if q_hrlayout.company is not None:
            company_name_str = q_hrlayout.company.company_name
        else:
            company_name_str = None
        if q_hrlayout.division is not None:
            division_name_str = q_hrlayout.division.division_name
        else:
            division_name_str = None
        if q_hrlayout.team is not None:
            team_name_str = q_hrlayout.team.team_name
        else:
            team_name_str = None

        if q_hrlayout.check_company_leader == True:
            # 회사장인 경우
            check_position_title = f'{company_name_str}_리더'
        else:
            if q_hrlayout.check_division_leader == True:
                # 부서장인 경우
                check_position_title = f'{company_name_str}_{division_name_str}_리더'
            else:
                if q_hrlayout.check_team_leader == True:
                    # 팀장인 경우
                    check_position_title = f'{company_name_str}_{division_name_str}_{team_name_str}_리더'
                else:
                    # 팀원인 경우
                    check_position_title = f'{company_name_str}_{division_name_str}_{team_name_str}_멤버'

        data = {
            'position': check_position_title,
        }
        HR_Layout.objects.filter(id=q_hrlayout.id).update(**data)
        return check_position_title
    else:
        return None


#--------------------------------------------------------------------------------------------------------------------------
# 나의 포지션에서 팀장 찾기
#--------------------------------------------------------------------------------------------------------------------------
def get_my_team_leader_hr_layout(q_hrlayout):
    check_status_finding_leader = False
    if q_hrlayout.company_leader == False:
        if q_hrlayout.division_leader == False:
            if q_hrlayout.team_leader == False:
                check_status_finding_leader = True
    if check_status_finding_leader is True:
        q_hrlayout_my_team_leader = HR_Layout.objects.filter(Q(check_discard=False) & Q(team=q_hrlayout.team) & Q(check_team_leader=True)).last()
        return q_hrlayout_my_team_leader
    else:
        return None


#--------------------------------------------------------------------------------------------------------------------------
# 나의 포지션에서 부서장 찾기
#--------------------------------------------------------------------------------------------------------------------------
def get_my_division_leader_hr_layout(q_hrlayout):
    check_status_finding_leader = False
    if q_hrlayout.company_leader == False:
        if q_hrlayout.division_leader == False:
            check_status_finding_leader = True
    if check_status_finding_leader is True:
        q_hrlayout_my_division_leader = HR_Layout.objects.filter(Q(check_discard=False) & Q(division=q_hrlayout.division) & Q(check_team_leader=True)).last()
        return q_hrlayout_my_division_leader
    else:
        return None


#--------------------------------------------------------------------------------------------------------------------------
# 나의 포지션에서 회사장 찾기
#--------------------------------------------------------------------------------------------------------------------------
def get_my_company_leader_hr_layout(q_hrlayout):
    check_status_finding_leader = False
    if q_hrlayout.company_leader == False:
        check_status_finding_leader = True
    if check_status_finding_leader is True:
        q_hrlayout_my_company_leader = HR_Layout.objects.filter(Q(check_discard=False) & Q(company=q_hrlayout.company) & Q(check_team_leader=True)).last()
        return q_hrlayout_my_company_leader
    else:
        return None


#--------------------------------------------------------------------------------------------------------------------------
# 본인의 가장 높은 직책의 q_hrlayout 찾기
#--------------------------------------------------------------------------------------------------------------------------
def get_my_highest_q_hrlayout_among_many(q_profile):
    # print('#--------------------------------------------------------------------------------------------------------------------------', q_profile.name_korean)
    q_user = q_profile.user
    check_company_leader = False
    check_division_leader = False
    check_team_leader = False
    q_hrlayout_highest = None
    dict_selected_hrlayout = {}
    qs_hrlayout = HR_Layout.objects.filter(Q(check_discard=False) & Q(member__user=q_user))
    if qs_hrlayout is not None and len(qs_hrlayout) > 0:
        for q_hrlayout in qs_hrlayout:
            if q_hrlayout.check_company_leader == False and q_hrlayout.check_division_leader == False and q_hrlayout.check_team_leader == False:
                dict_selected_hrlayout['team_member'] = q_hrlayout
            else:
                if q_hrlayout.check_company_leader == True:
                    check_company_leader = True
                    dict_selected_hrlayout['company_leader'] = q_hrlayout
                if q_hrlayout.check_division_leader == True:
                    check_division_leader = True
                    dict_selected_hrlayout['division_leader'] = q_hrlayout
                if q_hrlayout.check_team_leader == True:
                    check_team_leader = True
                    dict_selected_hrlayout['team_leader'] = q_hrlayout
    # print('check_company_leader', check_company_leader)
    # print('check_division_leader', check_division_leader)
    # print('check_team_leader', check_team_leader)
    if qs_hrlayout is not None and len(qs_hrlayout) > 0:
        if check_company_leader == False and check_division_leader == False and check_team_leader == False:
            q_hrlayout_highest = dict_selected_hrlayout['team_member']
        else:
            if check_company_leader == True:
                q_hrlayout_highest = dict_selected_hrlayout['company_leader']
            else:
                if check_division_leader == True:
                    q_hrlayout_highest = dict_selected_hrlayout['division_leader']
                else:
                    q_hrlayout_highest = dict_selected_hrlayout['team_leader']
    return q_hrlayout_highest












