#--------------------------------------------------------------------------------------------------------------------------
# 문서양식 등록 모달창 띄우기
#--------------------------------------------------------------------------------------------------------------------------
def hr_document_format_modal_view_to_register_new_document_format_open(request, q_mysettings_hr):
    # 문서양식 등록 리셋
    hr_document_format_close_modal_view_and_reset_register_infor(request, q_mysettings_hr)
    data = {
        'document_format': None,
        'check_activate_document_format_register_modal_view': True,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True


#--------------------------------------------------------------------------------------------------------------------------
# 문서양식 등록 리셋 및 모달창 닫기
#--------------------------------------------------------------------------------------------------------------------------
def hr_document_format_close_modal_view_and_reset_register_infor(request, q_mysettings_hr):
    data = {
        'check_activate_document_format_register_modal_view': False,
        'document_format_title': None,
        'document_format_description': None,
        'list_dict_document_approver': None,
        'list_dict_document_takeover': None,
        'list_dict_document_referrer': None,
        'list_dict_document_receiver': None,
        'list_dict_document_approver_searched': None,
        'list_dict_document_takeover_searched': None,
        'list_dict_document_referrer_searched': None,
        'list_dict_document_receiver_searched': None,
        'list_dict_document_approver_recommended': None,
        'list_dict_document_takeover_recommended': None,
        'list_dict_document_referrer_recommended': None,
        'list_dict_document_receiver_recommended': None,
        }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True


#--------------------------------------------------------------------------------------------------------------------------
# 문서양식 등록 확인하기(등록하기/업데이트하기)
#--------------------------------------------------------------------------------------------------------------------------
def hr_document_format_confirm_register_new_document_format_and_close_modal_view(request, q_mysettings_hr):
    q_hr_document_format = q_mysettings_hr.document_format
    if q_hr_document_format is None:
        # 등록하기
        qs_hr_document_format = HR_Document_Format.objects.all()
        if qs_hr_document_format is not None and len(qs_hr_document_format) > 0:
            if len(qs_hr_document_format) >= 9:
                code_str = f'00{str(len(qs_hr_document_format) + 1)}'
            elif len(qs_hr_document_format) >= 99:
                code_str = f'0{str(len(qs_hr_document_format) + 1)}'
            else:
                code_str = f'{str(len(qs_hr_document_format) + 1)}'
        else:
            code_str = '001'
    data = {
        'title': q_mysettings_hr.document_format_title,
        'description': q_mysettings_hr.document_format_description,
        'list_dict_document_referrer': q_mysettings_hr.list_dict_document_referrer,
        'list_dict_document_receiver': q_mysettings_hr.list_dict_document_receiver,
    }
    if q_hr_document_format is None:
        data['owner'] = request.user
        data['code'] = code_str
        q_hr_document_format = HR_Document_Format.objects.create(**data)
        messages.success(request, f'문서양식을 신규로 생성하였습니다.')
    else:
        HR_Document_Format.objects.filter(id=q_hr_document_format.id).update(**data)
        q_hr_document_format.refresh_from_db()
        messages.success(request, f'문서양식을 업데이트 하였습니다.')
    data= {
        'document_format': q_hr_document_format,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    #문서양식 등록 리셋 및 모달창 닫기
    hr_document_format_close_modal_view_and_reset_register_infor(request, q_mysettings_hr)
    return True


#--------------------------------------------------------------------------------------------------------------------------
# 문서양식 업데이트 모달창 띄우기
#--------------------------------------------------------------------------------------------------------------------------
def hr_document_format_modal_view_to_update_selected_document_format_open(request, q_mysettings_hr):
    q_hr_document_format_id_str = request.POST.get('button-hr-document-format-update-document-format-modal-view-open')
    if q_hr_document_format_id_str is None or q_hr_document_format_id_str == '':
        return False
    q_hr_document_format_id = int(q_hr_document_format_id_str)
    q_hr_document_format = HR_Document_Format.objects.get(id=q_hr_document_format_id)
    # 선택한 문서포맷 쿼리로부터 정보를 획득하기
    if q_hr_document_format is not None:
        document_format_title = q_hr_document_format.title
        if document_format_title is None:
            document_format_title = ''
        document_format_description = q_hr_document_format.description
        if document_format_description is None:
            document_format_description = ''
        list_dict_document_referrer = q_hr_document_format.list_dict_document_referrer
        if list_dict_document_referrer is None:
            list_dict_document_referrer = []
        list_dict_document_referrer_searched = []
        list_dict_document_receiver = q_hr_document_format.list_dict_document_receiver
        if list_dict_document_receiver is None:
            list_dict_document_receiver = []
        list_dict_document_receiver_searched = []
    # 획득한 문서포맷 정보를 Mysettings 임시정보란에 저장하기(Modal창에 refreshdata() 함수로 정보전달을 위해)
    data = {
        'document_format': q_hr_document_format,
        'check_activate_document_format_register_modal_view': True,
        'document_format_title': document_format_title,
        'document_format_description': document_format_description,
        'list_dict_document_referrer': list_dict_document_referrer,
        'list_dict_document_referrer_searched': list_dict_document_referrer_searched,
        'list_dict_document_receiver': list_dict_document_receiver,
        'list_dict_document_receiver_searched': list_dict_document_receiver_searched,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    # return 'hr-document-format-update'
    return True



#--------------------------------------------------------------------------------------------------------------------------
# 문서양식 활성화/비활성화
#--------------------------------------------------------------------------------------------------------------------------
def hr_document_format_activate_or_inactivate_selected_document_format(request, q_mysettings_hr):
    q_hr_document_format_id_str = request.POST.get('button-hr-document-format-update-document-format-activate')
    if q_hr_document_format_id_str is None or q_hr_document_format_id_str == '':
        return False
    q_hr_document_format_id = int(q_hr_document_format_id_str)
    q_hr_document_format = HR_Document_Format.objects.get(id=q_hr_document_format_id)
    check_activate = q_hr_document_format.check_activate
    if check_activate == True:
        check_activate = False
    else:
        check_activate = True
    data = {
        'check_activate': check_activate
    }
    HR_Document_Format.objects.filter(id=q_hr_document_format.id).update(**data)
    return True





