def hr_document_control_function(request):
    ls_today = datetime.date.today()
    ls_year = datetime.datetime.now().year
    ls_next_year = int(ls_year) + 1
    where_am_i = 'hr'
    q_authority = Authority.objects.filter(check_discard=False).last()
    q_mysettings_home = get_mysettings_home(request)
    q_mysettings_hr = get_xxx_my_settings(request, q_mysettings_home, where_am_i)
    # Queryset
    # 등록 문서 포맷 관리
    qs_hr_document_format = HR_Document_Format.objects.filter(Q(check_discard=False)).order_by('code')
    # 승인된 문서 관리
    qs_document_issued_approved = HR_Document_Issued.objects.filter(Q(check_discard=False) & Q(hrapproval__status_document_approval_process='APPROVED')).order_by('-id')[:200]
    print('qs_document_issued_approved', qs_document_issued_approved)
    # 승인된 + 수정요청된 문서 관리
    qs_document_issued_requested = HR_Document_Issued.objects.filter(Q(check_discard=False) & Q(hrapproval__status_document_approval_process='APPROVED') & Q(hrrequest__status_document_request_to='REQUESTED_TO_HR')).order_by('-id')[:200]

    for ITEM in LIST_HR_DOCUMENT_FORMAT_TYPE:
        title = ITEM[1]
        q_hr_document_format_selected = HR_Document_Format.objects.filter(Q(check_discard=False) & Q(title=title)).last()
        if q_hr_document_format_selected is None:
            qs_hr_document_format = HR_Document_Format.objects.filter(Q(check_discard=False)).order_by('code')
            if qs_hr_document_format is not None and len(qs_hr_document_format) > 0:
                if len(qs_hr_document_format) >= 9:
                    code_str = str(len(qs_hr_document_format) + 1)
                else:
                    code_str = f'0{str(len(qs_hr_document_format) + 1)}'
            else:
                    code_str = '01'
            q_admin = User.objects.filter(is_superuser=True).last()
            data = {
                'owner': q_admin,
                'title': ITEM[1],
                'code': code_str,
                'type_format': ITEM[0],
            }
            HR_Document_Format.objects.create(**data)
        else:
            pass

    #################################################
    if request.method == 'GET':
        context = {
            'NATIONAL_EVENT_TYPES': NATIONAL_EVENT_TYPES,
            'VORONOI_EVENT_TYPES': VORONOI_EVENT_TYPES,
            'LIST_HR_DOCUMENT_CONTROL_TYPE': LIST_HR_DOCUMENT_CONTROL_TYPE,
            'LIST_DOCUMENT_CONTROL_TABLE_COLUMN_INDEX': LIST_DOCUMENT_CONTROL_TABLE_COLUMN_INDEX,
            'LIST_MY_DOCUMENT_HISTORY_TABLE_COLUMN_INDEX': LIST_MY_DOCUMENT_HISTORY_TABLE_COLUMN_INDEX,
            'LIST_VACATION_TYPES': LIST_VACATION_TYPES,
            'LIST_VACATION_REGULAR_TYPES': LIST_VACATION_REGULAR_TYPES,
            'LIST_TYPE_WORKINGTIME': LIST_TYPE_WORKINGTIME,
            'LIST_TYPE_WORKINGTIME_FIELD': LIST_TYPE_WORKINGTIME_FIELD,
            'STATUS_MY_VACATION_CONTROL': STATUS_MY_VACATION_CONTROL,
            'STATUS_HR_DOCUMENT_APPROVAL_PROCESS': STATUS_HR_DOCUMENT_APPROVAL_PROCESS,
            'STATUS_MY_XXX_DOCUMENT_PLAN_REQUEST_TO': STATUS_MY_XXX_DOCUMENT_PLAN_REQUEST_TO,

            'ls_today': ls_today,
            'ls_year': ls_year,
            'ls_next_year': ls_next_year,
            'q_mysettings_hr': q_mysettings_hr,

            'qs_hr_document_format': qs_hr_document_format,
            'qs_document_issued_approved': qs_document_issued_approved,
            'qs_document_issued_requested': qs_document_issued_requested,
        }
        return context
    #################################################
    if request.method == 'POST':
        print('request.POST', request.POST)


        # HR Document Submenu 스위칭
        if request.POST.get('button-hr-document-control-type-switch') is not None:
            hr_document_control_switch_menu(request, q_mysettings_hr)

        # 화면 Full width 스위칭
        if request.POST.get('button-hr-document-control-statistics-table-display-size-switch') == 'true':
            check_fullwidth = q_mysettings_hr.check_display_size_document_format_table_fullwidth
            if check_fullwidth == True:
                check_fullwidth = False
            else:
                check_fullwidth = True
            data = {'check_display_size_document_format_table_fullwidth' : check_fullwidth,}
            HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
            return True

        #--------------------------------------------------------------------------------------------------------------------------

        # 문서양식 등록 모달창 띄우기
        if request.POST.get('button-hr-document-control-register-new-document-modal-view-open') == 'true':
            hr_document_format_modal_view_to_register_new_document_format_open(request, q_mysettings_hr)

        # 문서양식 등록 모달창 닫기
        if request.POST.get('button-hr-document-control-register-new-document-modal-view-close') == 'true':
            hr_document_format_close_modal_view_and_reset_register_infor(request, q_mysettings_hr)

        # 문서양식 등록 확인하기(등록하기)
        if request.POST.get('button-hr-document-format-register-confirm') == 'true':
            hr_document_format_confirm_register_new_document_format_and_close_modal_view(request, q_mysettings_hr)

        # 문서양식 업데이트 모달창 띄우기
        if request.POST.get('button-hr-document-format-update-document-format-modal-view-open') is not None:
            return hr_document_format_modal_view_to_update_selected_document_format_open(request, q_mysettings_hr)

        # 문서양식 활성화/비활성화
        if request.POST.get('button-hr-document-format-update-document-format-activate') is not None:
            hr_document_format_activate_or_inactivate_selected_document_format(request, q_mysettings_hr)




        #--------------------------------------------------------------------------------------------------------------------------
        # 승인된 문서 수정요청 응답
        #--------------------------------------------------------------------------------------------------------------------------

        # 승인문서 수정요청 응답 모달창 열기
        if request.POST.get('button-hr-document-history-document-modification-communication-with-hr-modal-view-open') is not None:
            hr_xxx_document_modification_communication_modal_open(request, q_mysettings_hr)

        # 승인문서 수정요청 응답 모달창 닫기
        if request.POST.get('button-hr-document-history-document-modification-communication-with-hr-modal-view-close') is not None:
            hr_xxx_document_modification_communication_modal_close(request, q_mysettings_hr)


        # 수정요청 커뮤니케이션 모달창 확정하기
        if request.POST.get('button-hr-document-history-document-modification-communication-with-hr-modal-view-confirm') == 'true':
            hr_xxx_document_history_document_modification_communication_modal_view_confirm(request, q_mysettings_hr)






        return False

















