#--------------------------------------------------------------------------------------------------------------------------
# 입력한 날이 주말 여부 체크 함수
#--------------------------------------------------------------------------------------------------------------------------
def my_check_date_weekend(input_date):
    # input_date : datetime.date() 오브젝트  /  datetime.datetime.today()
    # 주말체크
    list_day_of_week = [5, 6]
    day_of_week = input_date.weekday()
    if day_of_week not in list_day_of_week:
        check_weekend = False
    else:
        check_weekend = True
    return check_weekend


#--------------------------------------------------------------------------------------------------------------------------
# 입력한 날이 휴일 여부 체크 함수
#--------------------------------------------------------------------------------------------------------------------------
def check_date_holiday_member(input_date):
    qs_event_national = HR_Calendar_Event.objects.filter(Q(check_discard=False) & Q(check_voronoi_event=False) & Q(date_event=input_date) & Q(check_holiday=True)).order_by('date_event')
    qs_event_voronoi = HR_Calendar_Event.objects.filter(Q(check_discard=False) & Q(check_voronoi_event=True) & Q(date_event=input_date) & Q(check_holiday=True)).order_by('date_event')
    if qs_event_national is None or len(qs_event_national) == 0:
        check_event_national = False
    else:
        check_event_national = True
    if qs_event_voronoi is None or len(qs_event_voronoi) == 0:
        check_event_voronoi = False
    else:
        check_event_voronoi = True
    if check_event_national == False and check_event_voronoi == False:
        check_holiday = False
    else:
        check_holiday = True
    return check_holiday


#--------------------------------------------------------------------------------------------------------------------------
# 입력한 날이 휴가 여부 체크 함수
#--------------------------------------------------------------------------------------------------------------------------
def check_date_vacation_member(q_user, input_date):
    qs_vacation_plan = Vacation_Plan.objects.filter(Q(owner=q_user) & Q(check_discard=False) & Q(check_valid=True) & Q(datetime_start__lte=input_date) & Q(datetime_end__gte=input_date))
    if qs_vacation_plan is None or len(qs_vacation_plan) == 0:
        check_vacation = False
    else:
        check_vacation = True
    return check_vacation


#--------------------------------------------------------------------------------------------------------------------------
# 선택한 날짜 근무일 상태 확인
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_get_status_working_day(request, input_date):
    q_user = request.user
    check_weekend = my_check_date_weekend(input_date)
    check_holiday = check_date_holiday_member(input_date)
    check_vacation = check_date_vacation_member(q_user, input_date)
    if check_weekend == False and check_holiday == False:
        status_working_day = STATUS_WORKING_DAY[0][0]  # ('WK_DAY_NORMAL', '정상근무일'),  # 0
    else:
        status_working_day = STATUS_WORKING_DAY[1][0]  # ('WK_DAY_HOLYDAY', '주말/국공휴일/회사휴일'),  # 1
    return status_working_day



#--------------------------------------------------------------------------------------------------------------------------
# 선택한 날의 근무일 상태 체크
#--------------------------------------------------------------------------------------------------------------------------
def get_status_working_day_by_selected_day(date_selected_day):
    # status_working_day 찾기
    selected_year = date_selected_day.year
    q_calendar_control = HR_Calendar_Control.objects.filter(Q(check_discard=False) & Q(year_calendar=selected_year)).last()
    # qs_calendar_event_holiday = HR_Calendar_Event.objects.filter(Q(check_discard=False) & Q(calendar_control=q_calendar_control) & Q(type_event_national=NATIONAL_EVENT_TYPES[0][0]))
    qs_calendar_event_holiday = HR_Calendar_Event.objects.filter(Q(check_discard=False) & Q(calendar_control=q_calendar_control) & Q(check_holiday=True))
    list_national_holidays = []
    if qs_calendar_event_holiday is not None and len(qs_calendar_event_holiday) > 0:
        for q_calendar_event_holiday in qs_calendar_event_holiday:
            if q_calendar_event_holiday.date_event not in list_national_holidays:
                list_national_holidays.append(q_calendar_event_holiday.date_event)
    if date_selected_day in list_national_holidays:
        # 국공휴일 / 회사휴일인 경우
        status_working_day = 'WK_DAY_HOLYDAY'  # STATUS_WORKING_DAY[1][0]  # ('WK_DAY_HOLYDAY', '주말/국공휴일/회사휴일'),  # 1
    else:
        if hr_check_date_weekend(date_selected_day) == True:
            # 주말인 경우
            status_working_day = 'WK_DAY_HOLYDAY'  # STATUS_WORKING_DAY[1][0]  # ('WK_DAY_HOLYDAY', '주말/국공휴일/회사휴일'),  # 1
        else:
            # 정상근무일인 경우
            status_working_day = 'WK_DAY_NORMAL'  # STATUS_WORKING_DAY[0][0]  # ('WK_DAY_NORMAL', '정상근무일'),  # 0
    return status_working_day




#--------------------------------------------------------------------------------------------------------------------------
# 순근무시간/총근무시간 계산  Ver. 2023-04-01
#
# delta_time_net_working : 식사시간 제외한 넷 델타근무시간
# time_net_working  : 식사시간 제외한 넷 근무시간
# delta_time_total_working  : 식사시간 포함한 총 델타근무시간
# time_total_working  : 식사시간 포함한 총 근무시간
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_get_net_working_time(datetime_start, datetime_end):
    # print('**************************************************************************************************근무일 ', datetime_start.year, datetime_start.month, datetime_start.day)
    # print('datetime_start', datetime_start,)
    # print('datetime_end', datetime_end)
    if datetime_start != None and datetime_end != None:
        # print('출퇴근 시간 정보 있음, 계산시작!!')
        time_start = datetime.time(datetime_start.hour, datetime_start.minute)
        time_end = datetime.time(datetime_end.hour, datetime_end.minute)

        q_hr_default_settings = HR_Default_Settings.objects.last()
        check_default_baseline_lunchtime_start = q_hr_default_settings.check_default_baseline_lunchtime_start
        check_default_baseline_lunchtime_end = q_hr_default_settings.check_default_baseline_lunchtime_end
        check_default_baseline_dinnertime_start = q_hr_default_settings.check_default_baseline_dinnertime_start
        check_default_baseline_dinnertime_end = q_hr_default_settings.check_default_baseline_dinnertime_end
        default_baseline_lunchtime_start = q_hr_default_settings.default_baseline_lunchtime_start # 점심식사 한것으로 간주하는 근무시작시간 기준선
        default_baseline_lunchtime_end = q_hr_default_settings.default_baseline_lunchtime_end # 점심식사 한것으로 간주하는 근무종료시간 기준선
        default_baseline_dinnertime_start = q_hr_default_settings.default_baseline_dinnertime_start # 저녁식사 한것으로 간주하는 근무시작시간 기준선
        default_baseline_dinnertime_end = q_hr_default_settings.default_baseline_dinnertime_end # 저녁식사 한것으로 간주하는 근무종료시간 기준선

        #--------------------------------------------------------------------------------------------------------------------------
        # 순근무시간 계산 (델타시간형식)
        if datetime.date(datetime_start.year, datetime_start.month, datetime_start.day) == datetime.date(datetime_end.year, datetime_end.month, datetime_end.day):
            print('# 퇴근일 == 출근일인 퇴근상태 확인')
            if datetime_end > datetime_start:
                delta_time_net_working = datetime_end - datetime_start
                delta_time_total_working = delta_time_net_working
            else:
                delta_time_net_working = None
                delta_time_total_working = None
        else:
            print('# 퇴근일 != 출근일인 퇴근상태')
            if datetime_end.minute >= datetime_start.minute:
                # print('1')
                delta_time_hour = 24 + int(datetime_end.hour) - int(datetime_start.hour)
                delta_time_minute = int(datetime_end.minute) - int(datetime_start.minute)
            else:
                # print('2')
                delta_time_hour = 24 + int(datetime_end.hour) - int(datetime_start.hour) - 1
                delta_time_minute = 60 + int(datetime_end.minute) - int(datetime_start.minute)
            # print('delta_time_hour', delta_time_hour, 'delta_time_minute', delta_time_minute)

            # datetime.time 간 크기비교는 가능, 빼기(Delta time)는 불가능, 때문에 datetime.datetime 형식으로 빼야 한다.
            if datetime.datetime(1,1,1, delta_time_hour, delta_time_minute) > datetime.datetime(1,1,1,0,0):
                delta_time_net_working = datetime.datetime(1,1,1, delta_time_hour, delta_time_minute) - datetime.datetime(1,1,1,0,0)
            else:
                delta_time_net_working = None
            delta_time_total_working = delta_time_net_working
        print('delta_time_total_working 1', delta_time_total_working)
        print('delta_time_net_working 1', delta_time_net_working)
        #--------------------------------------------------------------------------------------------------------------------------
        # 식사시간 차감
        if datetime.date(datetime_start.year, datetime_start.month, datetime_start.day) == datetime.date(datetime_end.year, datetime_end.month, datetime_end.day):
            # print('# 퇴근일 == 출근일인 퇴근상태 확인')
            if time_start < default_baseline_lunchtime_start:
                # 점심식사 전에 출근했으면
                if time_end > default_baseline_lunchtime_end :
                    # 점심 식사 뒤에 퇴근했으면  print('# 점심시간 지난경우')
                    if time_end > default_baseline_dinnertime_end:
                        # print('# 저녁식사시간 후에 퇴근한 경우 경우 점심식사 + 저녁식사 2시간 제외')
                        delta_time_net_working = delta_time_net_working - datetime.timedelta(hours=2)
                    else:
                        # print('# 아닌경우 점심식사 시간 1시간 제외')
                        delta_time_net_working = delta_time_net_working - datetime.timedelta(hours=1)
                else:
                    # 점심식사 전에 퇴근한경우
                    pass
            else:
                # 점심식사 시작 후 출근한 경우
                pass
        else:
            # print('# 퇴근일 != 출근일인 퇴근상태, 다음날 새벽 퇴근인 경우')
            if time_start < default_baseline_lunchtime_start:
                # print('# 점심식사 + 저녁식사 시간 2시간 제외')
                delta_time_net_working = delta_time_net_working - datetime.timedelta(hours=2)
            else:
                if time_start < default_baseline_dinnertime_start:
                    # print('# 저녁식사 시간 1시간 제외')
                    delta_time_net_working = delta_time_net_working - datetime.timedelta(hours=1)
                else:
                    # print('# 식사시간 제외 없음(식사 안했다고 가정)')
                    pass
        print('delta_time_total_working 2', delta_time_total_working)
        print('delta_time_net_working 2', delta_time_net_working)
        #--------------------------------------------------------------------------------------------------------------------------
        # 델타 순근무시간을 datetime.time 형식으로 변경
        if delta_time_net_working is not None:
            # print('delta_time_net_working', delta_time_net_working)
            delta_time_net_working_str = str(delta_time_net_working)
            time_net_working_hour = int(delta_time_net_working_str.split(':')[0])
            time_net_working_minute = int(delta_time_net_working_str.split(':')[1])
            time_net_working = datetime.time(time_net_working_hour, time_net_working_minute)
        else:
            time_net_working = None
        if delta_time_total_working is not None:
            delta_time_total_working_str = str(delta_time_total_working)
            time_total_working_hour = int(delta_time_total_working_str.split(':')[0])
            time_total_working_minute = int(delta_time_total_working_str.split(':')[1])
            time_total_working = datetime.time(time_total_working_hour, time_total_working_minute)
        else:
            time_total_working = None
    else:
        # 출퇴근 시간 정보 누락으로 순근무시간 계산 불가
        delta_time_net_working = None
        time_net_working = None
        delta_time_total_working = None
        time_total_working  = None
    #--------------------------------------------------------------------------------------------------------------------------
    # print('delta_time_net_working, time_net_working, delta_time_total_working, time_total_working', delta_time_net_working, time_net_working, delta_time_total_working, time_total_working)
    return delta_time_net_working, time_net_working, delta_time_total_working, time_total_working


#--------------------------------------------------------------------------------------------------------------------------
# 출근 상태 확인 Ver.2023-04-03
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_get_status_workingtime_start(datetime_start, q_wkt_control, default_time_start_standard):
    q_hr_default_settings = HR_Default_Settings.objects.last()
    # default_time_start_standard = q_hr_default_settings.default_time_start_standard
    default_time_end_standard = q_hr_default_settings.default_time_end_standard
    default_time_start_early = q_hr_default_settings.default_time_start_early
    default_time_end_lately = q_hr_default_settings.default_time_end_lately
    default_datebaseline_time = q_hr_default_settings.default_datebaseline_time
    #--------------------------------------------------------------------------------------------------------------------------
    date_start = datetime.date(datetime_start.year, datetime_start.month, datetime_start.day)
    time_start = datetime.time(datetime_start.hour, datetime_start.minute)
    from hr.functions import get_status_working_day_by_selected_day
    status_working_day = get_status_working_day_by_selected_day(date_start)
    #--------------------------------------------------------------------------------------------------------------------------
    if status_working_day == 'WK_DAY_NORMAL': #  STATUS_WORKING_DAY[0][0] ('WK_DAY_NORMAL', '정상근무일'),  # 0
        # 평일 정상 출근
        if time_start <= default_time_start_standard:
            if time_start < default_time_start_early:
                status_wkt_start = 'WWD_TIME_EARLY'  # STATUS_WORKING_TIME_START[0][0] # ('WWD_TIME_EARLY', '조기출근'),  # 0
            else:
                status_wkt_start = 'WKD_TIME_NORMAL'  # STATUS_WORKING_TIME_START[1][0] # ('WKD_TIME_NORMAL', '정상출근'),  # 1
        else:
            status_wkt_start = 'WKD_TIME_LATE'  # STATUS_WORKING_TIME_START[2][0]  # ('WKD_TIME_LATE', '지각'),  # 2
    else:
        # 근무일 외 출근
        status_wkt_start = 'WKD_TIME_EXTRA'  # STATUS_WORKING_TIME_START[4][0]  # ('WKD_TIME_EXTRA', '근무일 외 출근'),  # 4
    return status_wkt_start


#--------------------------------------------------------------------------------------------------------------------------
# 퇴근 상태 확인 Ver.2023-04-03
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_get_status_workingtime_end(datetime_end, q_wkt_control, default_time_end_standard):
    q_hr_default_settings = HR_Default_Settings.objects.last()
    default_time_start_standard = q_hr_default_settings.default_time_start_standard
    # default_time_end_standard = q_hr_default_settings.default_time_end_standard
    default_time_start_early = q_hr_default_settings.default_time_start_early
    default_time_end_lately = q_hr_default_settings.default_time_end_lately
    default_datebaseline_time = q_hr_default_settings.default_datebaseline_time
    #--------------------------------------------------------------------------------------------------------------------------
    day_1 = datetime.timedelta(days=1)
    date_end = datetime.date(datetime_end.year, datetime_end.month, datetime_end.day)
    time_end = datetime.time(datetime_end.hour, datetime_end.minute)
    if time_end < default_datebaseline_time:
        selected_date = date_end - day_1
    else:
        selected_date = date_end
    from hr.functions import get_status_working_day_by_selected_day
    status_working_day = get_status_working_day_by_selected_day(selected_date)
    #--------------------------------------------------------------------------------------------------------------------------
    if time_end < default_datebaseline_time:
        # 현재시간이 날짜기준선 이전이면 하루 전날 출근(다음날 새벽 퇴근인 경우.)
        # 퇴근일 != 출근일인 퇴근상태
        if status_working_day == 'WK_DAY_NORMAL':  # STATUS_WORKING_DAY[0][0] ('WK_DAY_NORMAL', '정상근무일'),  # 0
            # 정상근무일인 경우
            status_wkt_end = 'WKD_TIME_LATE'  # STATUS_WORKING_TIME_END[2][0] # ('WKD_TIME_LATE', '연장근로'),  # 2
        else:
            # 휴일인 경우
            status_wkt_end = 'WKD_TIME_EXTRA'  # STATUS_WORKING_TIME_END[4][0]  # ('WKD_TIME_EXTRA', '근무일 외 퇴근'),  # 4
    else:
        # 퇴근일 == 출근일인 퇴근상태 확인
        if status_working_day == 'WK_DAY_NORMAL':  # STATUS_WORKING_DAY[0][0] ('WK_DAY_NORMAL', '정상근무일'),  # 0
            # 정상근무일인 경우
            if time_end >= default_time_end_standard:
                if time_end > default_time_end_lately:
                    status_wkt_end = 'WKD_TIME_LATE'  # STATUS_WORKING_TIME_END[2][0] # ('WKD_TIME_LATE', '연장근로'),  # 2
                else:
                    status_wkt_end = 'WKD_TIME_NORMAL'  # STATUS_WORKING_TIME_END[1][0] # ('WKD_TIME_NORMAL', '정상퇴근'),  # 1
            else:
                status_wkt_end = 'WKD_TIME_EARLY'  # STATUS_WORKING_TIME_END[0][0]  # ('WKD_TIME_EARLY', '조기퇴근'),  # 0
        else:
            # 휴일인 경우
            status_wkt_end = 'WKD_TIME_EXTRA'  # STATUS_WORKING_TIME_END[4][0]  # ('WKD_TIME_EXTRA', '근무일 외 퇴근'),  # 4
    return status_wkt_end




