#--------------------------------------------------------------------------------------------------------------------------
# HR 멤버 발행출퇴근 현황  Keyword 로 필터링하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_control_filter_form_keyword(request, q_mysettings_hr):
    print('# HR 멤버 발행출퇴근 현황  Keyword 로 필터링하기')
    ls_today = datetime.date.today()
    keyword_str = request.POST.get('text-hr-workingtime-control-member-search-keyword')
    from nlp.functions import get_list_cleaned_word_function
    list_input_word = get_list_cleaned_word_function(keyword_str)

    # 출근 체크 리스트에서 제외하는 멤버 리스트 프로필 ID
    q_hr_doc_min_settigns = HR_Document_Minor_Settings.objects.last()
    list_profile_id_wkt_issued_check_excepter = q_hr_doc_min_settigns.list_profile_id_wkt_issued_check_excepter

    date_selected_workingtime = q_mysettings_hr.date_selected_workingtime
    if date_selected_workingtime is None:
        ls_today = datetime.date.today()
        data = {
            'date_selected_workingtime': ls_today,
        }
        HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
        q_mysettings_hr.refresh_from_db()
        date_selected_workingtime = ls_today

    list_wkt_issued_id_searched = []
    if len(list_input_word) == 0:
        qs_wkt_issued = Workingtime_Issued.objects.filter(Q(check_discard=False) & ~Q(owner__profile__id__in=list_profile_id_wkt_issued_check_excepter) & Q(date_of_work=date_selected_workingtime))
        if qs_wkt_issued is not None and len(qs_wkt_issued) > 0:
            for q_wkt_issued in qs_wkt_issued:
                if q_wkt_issued.id not in list_wkt_issued_id_searched:
                    list_wkt_issued_id_searched.append(q_wkt_issued.id)
    else:
        for keyword_str in list_input_word:
            qs_wkt_issued = Workingtime_Issued.objects.filter(Q(check_discard=False) & ~Q(owner__profile__id__in=list_profile_id_wkt_issued_check_excepter) & Q(date_of_work=date_selected_workingtime) & (Q(owner__profile__name_korean__icontains=keyword_str) | Q(workingtime_control__hrlayout__division__division_name__icontains=keyword_str) | Q(workingtime_control__hrlayout__team__team_name__icontains=keyword_str)))
            if qs_wkt_issued is not None and len(qs_wkt_issued) > 0:
                for q_wkt_issued in qs_wkt_issued:
                    if q_wkt_issued.id not in list_wkt_issued_id_searched:
                        list_wkt_issued_id_searched.append(q_wkt_issued.id)

    data = {
        'list_workingtime_issued_id_searched': list_wkt_issued_id_searched,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True


