def hr_workingtime_control_search_workingtime_by_filtering_condition(request, q_mysettings_hr):
    hr_workingtime_control_select_form_workingday(request, q_mysettings_hr)
    hr_workingtime_control_select_form_workingtime_start(request, q_mysettings_hr)
    hr_workingtime_control_select_form_workingtime_end(request, q_mysettings_hr)
    hr_workingtime_control_filter_form_keyword(request, q_mysettings_hr)
    return True


#--------------------------------------------------------------------------------------------------------------------------
# Workingtime Control 쿼리 생성 or 업데이트
# 매달 생성함.
#--------------------------------------------------------------------------------------------------------------------------
def create_or_update_hr_workingtime_control(q_profile, fiscal_year, fiscal_month):
    q_hrlayout = get_my_highest_q_hrlayout_among_many(q_profile)
    q_wkt_control = Workingtime_Control.objects.filter(Q(owner=q_profile.user) & Q(fiscal_year=fiscal_year) & Q(fiscal_month=fiscal_month)).last()
    #--------------------------------------------------------------------------------------------------------------------------
    # 직전 control 쿼리 정보 상속받기
    if fiscal_month == 1:
        fiscal_month_prev = 12
        fiscal_year_prev = fiscal_year - 1
    else:
        fiscal_month_prev = fiscal_month - 1
        fiscal_year_prev = fiscal_year
    q_wkt_control_prev = Workingtime_Control.objects.filter(Q(owner=q_profile.user) & Q(fiscal_year=fiscal_year_prev) & Q(fiscal_month=fiscal_month_prev)).last()
    if q_wkt_control_prev is not None:
        # 출퇴근시간 개인맞춤 세팅 상속받기
        check_default_datetime_start_activated = q_wkt_control_prev.check_default_datetime_start_activated
        check_default_datetime_end_activated = q_wkt_control_prev.check_default_datetime_end_activated
        default_time_start_standard = q_wkt_control_prev.default_time_start_standard
        default_time_end_standard = q_wkt_control_prev.default_time_end_standard
        check_default_datetime_personalization_activated = q_wkt_control_prev.check_default_datetime_personalization_activated
        list_dict_default_wkt_standard_personalized = q_wkt_control_prev.list_dict_default_wkt_standard_personalized
    else:
        check_default_datetime_start_activated = False
        check_default_datetime_end_activated = False
        default_time_start_standard = None
        default_time_end_standard = None
        check_default_datetime_personalization_activated = False
        list_dict_default_wkt_standard_personalized = None
    #--------------------------------------------------------------------------------------------------------------------------
    if q_wkt_control is None:
        data = {
            'owner': q_profile.user,
            'hrlayout': q_hrlayout,
            'fiscal_year': fiscal_year,
            'fiscal_month': fiscal_month,
            'check_default_datetime_start_activated': check_default_datetime_start_activated,
            'check_default_datetime_end_activated': check_default_datetime_end_activated,
            'default_time_start_standard': default_time_start_standard,
            'default_time_end_standard': default_time_end_standard,
            'check_default_datetime_personalization_activated': check_default_datetime_personalization_activated,
            'list_dict_default_wkt_standard_personalized': list_dict_default_wkt_standard_personalized,
        }
        q_wkt_control = Workingtime_Control.objects.create(**data)
    else:
        data = {
            'hrlayout': q_hrlayout,
        }
        Workingtime_Control.objects.filter(id=q_wkt_control.id).update(**data)
        q_wkt_control.refresh_from_db()
    return q_wkt_control


#--------------------------------------------------------------------------------------------------------------------------
# Workingtime 멤버 Workingtime Control Refresh
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_control_refresh_workingtime_today_search(request, q_mysettings_hr):
    ls_today = datetime.date.today()
    ls_year = ls_today.year
    ls_month = ls_today.month
    if q_mysettings_hr.date_selected_workingtime is not None:
        selected_year = q_mysettings_hr.date_selected_workingtime.year
        selected_month = q_mysettings_hr.date_selected_workingtime.month
    else:
        selected_year = ls_year
        selected_month = ls_month
    qs_profile = Profile.objects.filter(Q(check_discard=False) & Q(check_resign=False))
    if qs_profile is None or len(qs_profile) == 0:
        for q_profile in qs_profile:
            create_or_update_hr_workingtime_control(q_profile, selected_year, selected_month)
    return True


