#--------------------------------------------------------------------------------------------------------------------------
# Workingtime 쿼리 삭제하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_control_workingtime_issue_delete(request, q_mysettings_hr):
    q_wkt_issued_id_str = request.POST.get('button-hr-workingtime-control-workingtime-issued-delete')
    if q_wkt_issued_id_str is None or q_wkt_issued_id_str == '':
        return False
    q_wkt_issued_id = int(q_wkt_issued_id_str)
    q_wkt_issued = Workingtime_Issued.objects.get(id=q_wkt_issued_id)
    data = {
        'check_discard': True,
    }
    Workingtime_Issued.objects.filter(id=q_wkt_issued.id).update(**data)
    if q_mysettings_hr.workingtime_issued == q_wkt_issued:
        data = {
            'workingtime_issued': None,
        }
        HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
        q_mysettings_hr.refresh_from_db()
    messages.warning(request, f'선택된 {q_wkt_issued.owner.profile.name_korean}님의 출퇴근쿼리를 삭제하였습니다.')
    return True


#--------------------------------------------------------------------------------------------------------------------------
# 선택한 멤버로 다른 작업 하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_control_select_member_workingtime(request, q_mysettings_hr):
    list_q_wkt_id_str = request.POST.getlist('checkbox-hr-workingtime-select-member')
    if list_q_wkt_id_str is None or list_q_wkt_id_str == '':
        return False
    if 'all' in list_q_wkt_id_str:
        date_selected_workingtime = q_mysettings_hr.date_selected_workingtime
        if date_selected_workingtime is None:
            ls_today = datetime.date.today()
            date_selected_workingtime = ls_today
        qs_wkt_selected_day = Workingtime_Issued.objects.filter(Q(check_discard=False) & Q(date_of_work=date_selected_workingtime))
        if qs_wkt_selected_day is not None and len(qs_wkt_selected_day) > 0:
            list_q_wkt_id = []
            for q_wkt_selected_day in qs_wkt_selected_day:
                if q_wkt_selected_day.id not in list_q_wkt_id:
                    list_q_wkt_id.append(q_wkt_selected_day.id)
    else:
        list_q_wkt_id = list(map(int, list_q_wkt_id_str))
    print('list_q_wkt_id', list_q_wkt_id)
    data = {
        'list_workingtime_issued_id_selected': list_q_wkt_id,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    messages.success(request, f'{len(list_q_wkt_id)}명이 선택되었습니다.')
    return True


