#--------------------------------------------------------------------------------------------------------------------------
# WKT 세팅근무시간 수정내용 확정하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_control_confirm_selected_member_workingtime_modification_default(request, q_mysettings_hr):
    print('# WKT 세팅근무시간 수정내용 확정하기')
    ls_today = datetime.date.today()
    ls_year = ls_today.year
    ls_month = ls_today.month
    q_wkt_id_str = request.POST.get('button-hr-workingtime-control-confirm-modification-workingtime-default')
    if q_wkt_id_str is None or q_wkt_id_str == '':
        return False
    q_wkt_id = int(q_wkt_id_str)
    q_workingtime_issued = Workingtime_Issued.objects.get(id=q_wkt_id)
    if q_workingtime_issued is not None:
        q_owner = q_workingtime_issued.owner
        q_profile = q_owner.profile
        if q_workingtime_issued.date_of_work is not None:
            selected_year = q_workingtime_issued.date_of_work.year
            selected_month = q_workingtime_issued.date_of_work.month
        else:
            selected_year = ls_year
            selected_month = ls_month
        q_workingtime_control = create_or_update_hr_workingtime_control(q_profile, selected_year, selected_month)
        if q_workingtime_issued.workingtime_control is None:
            data = {
                'workingtime_control': q_workingtime_control,
            }
            Workingtime_Issued.objects.filter(id=q_workingtime_issued.id).update(**data)
            q_workingtime_issued.refresh_from_db()
        else:
            q_workingtime_control = q_workingtime_issued.workingtime_control
    else:
        return False
    print('q_workingtime_control //////////////: ', q_workingtime_control.owner)
    check_default_datetime_start_activated_str = request.POST.get('select-hr-workingday-control-form-workingtime-start-default')
    if check_default_datetime_start_activated_str == 'true':
        check_default_datetime_start_activated = True
    else:
        check_default_datetime_start_activated = False

    check_default_datetime_end_activated_str = request.POST.get('select-hr-workingday-control-form-workingtime-end-default')
    if check_default_datetime_end_activated_str == 'true':
        check_default_datetime_end_activated = True
    else:
        check_default_datetime_end_activated = False

    default_datetime_start_str = request.POST.get('input-time-hr-workingtime-control-modification-start-default')
    if default_datetime_start_str is not None and default_datetime_start_str != '':
        default_datetime_start_hour_int = int(default_datetime_start_str.split(':')[0])
        default_datetime_start_minute_int = int(default_datetime_start_str.split(':')[1])
        default_time_start_standard = datetime.time(default_datetime_start_hour_int, default_datetime_start_minute_int)
    else:
        default_time_start_standard = q_workingtime_control.default_time_start_standard

    default_datetime_end_str = request.POST.get('input-time-hr-workingtime-control-modification-end-default')
    print('default_datetime_end_str', default_datetime_end_str)
    if default_datetime_end_str is not None and default_datetime_end_str != '':
        default_datetime_end_hour_int = int(default_datetime_end_str.split(':')[0])
        default_datetime_end_minute_int = int(default_datetime_end_str.split(':')[1])
        default_time_end_standard = datetime.time(default_datetime_end_hour_int, default_datetime_end_minute_int)
    else:
        default_time_end_standard = q_workingtime_control.default_time_end_standard

    data = {
        'check_default_datetime_start_activated': check_default_datetime_start_activated,
        'check_default_datetime_end_activated': check_default_datetime_end_activated,
        'default_time_start_standard': default_time_start_standard,
        'default_time_end_standard': default_time_end_standard,
    }
    print('data //////////////: ', data)
    Workingtime_Control.objects.filter(id=q_workingtime_control.id).update(**data)
    return True


