#--------------------------------------------------------------------------------------------------------------------------
# 출퇴근 정보 내용없는 중복 제거하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_control_selected_member_monthly_wkt_issued_modal_view_remove_dup(request, q_mysettings_hr):
    q_workingtime_issued = q_mysettings_hr.workingtime_issued
    ls_today = datetime.date.today()
    day_x = datetime.timedelta(days=60)
    day_1 = datetime.timedelta(days=1)
    ls_day_x_ago = ls_today - day_x
    qs_profile = Profile.objects.filter(Q(check_discard=False) & Q(check_resign=False))
    if qs_profile is not None and len(qs_profile) > 0:
        for q_profile in qs_profile:
            q_user = q_profile.user
            print('q_user', q_user)
            # if q_workingtime_issued is not None:
            #     q_user = q_workingtime_issued.owner
            day_i = ls_today
            qs = Workingtime_Issued.objects.filter(Q(check_discard=False) & Q(owner=q_user) & Q(status_wkt_start='WKD_TIME_UNKNOWN') & Q(status_wkt_end='WKD_TIME_UNKNOWN') & Q(datetime_start__isnull=True) & Q(datetime_end__isnull=True))
            if qs is not None and len(qs) > 1:
                print('qs number', len(qs))
                while day_i > ls_day_x_ago:
                    print('day_i', day_i)
                    qs_known = Workingtime_Issued.objects.filter(Q(date_of_work=day_i) & Q(check_discard=False) & Q(owner=q_user) & ~Q(status_wkt_start='WKD_TIME_UNKNOWN') & ~Q(status_wkt_end='WKD_TIME_UNKNOWN'))
                    if qs_known is not None and len(qs_known) > 0:
                        # print('# 명명된 출퇴근 쿼리가 1개 이상 있으면 Unknown 쿼리 모두 삭제')
                        qs = Workingtime_Issued.objects.filter(Q(date_of_work=day_i) & Q(check_discard=False) & Q(owner=q_user) & Q(status_wkt_start='WKD_TIME_UNKNOWN') & Q(status_wkt_end='WKD_TIME_UNKNOWN') & Q(datetime_start__isnull=True) & Q(datetime_end__isnull=True))
                        if qs is not None and len(qs) > 0:
                            print('명명된 출퇴근 쿼리가 1개 이상 있으면 Unknown 쿼리 모두 삭제 - 삭제할 쿼리 있음')
                            i = 0
                            for q in qs:
                                data = {
                                    'check_discard': True,
                                }
                                Workingtime_Issued.objects.filter(id=q.id).update(**data)
                                i = i + 1
                            messages.success(request, f'{q_user.profile.name_korean}님의 {str(day_i)}일자에 중복된 {len(qs)}개의 출퇴근 쿼리를 삭제하였습니다.')
                        else:
                            # print('삭제할 쿼리 없음')
                            pass
                    else:
                        # print('# 명명된 출퇴근 쿼리가 없으면 Unknown 쿼리 1개 남겨놓고 삭제')
                        qs = Workingtime_Issued.objects.filter(Q(date_of_work=day_i) & Q(check_discard=False) & Q(owner=q_user) & Q(status_wkt_start='WKD_TIME_UNKNOWN') & Q(status_wkt_end='WKD_TIME_UNKNOWN') & Q(datetime_start__isnull=True) & Q(datetime_end__isnull=True))
                        if qs is not None and len(qs) > 1:
                            print('명명된 출퇴근 쿼리(qs_known)가 없으면 Unknown 쿼리 2개 이상이면, Unknown 쿼리 1개 남겨놓고 삭제 - 삭제할 쿼리 있음')
                            i = 0
                            for q in qs:
                                if i == 0:
                                    pass
                                else:
                                    data = {
                                        'check_discard': True,
                                    }
                                    Workingtime_Issued.objects.filter(id=q.id).update(**data)
                                i = i + 1
                            messages.success(request, f'{q_user.profile.name_korean}님의 {str(day_i)}일자에 중복된 {len(qs) - 1 }개의 출퇴근 쿼리를 삭제하였습니다.')
                        else:
                            # print('삭제할 쿼리 없음')
                            pass
                    day_i = day_i - day_1
            else:
                print('no dup.')
                messages.success(request, f'{q_user.profile.name_korean}님의 중복된 출퇴근 쿼리가 없습니다.')
                pass
    return True







