#--------------------------------------------------------------------------------------------------------------------------
# Keyword Search
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_control_search_workingtime_analytics_table(request, q_mysettings_hr):
    print('# Keyword Search')
    keyword_str = request.POST.get('text-hr-workingtime-control-search-analytics-keyword')
    print('keyword_str', keyword_str)
    from nlp.functions import get_list_cleaned_word_function
    list_input_word = get_list_cleaned_word_function(keyword_str)

    # 출근 체크 리스트에서 제외하는 멤버 리스트 프로필 ID
    q_hr_doc_min_settigns = HR_Document_Minor_Settings.objects.last()
    list_profile_id_wkt_issued_check_excepter = q_hr_doc_min_settigns.list_profile_id_wkt_issued_check_excepter

    date_selected_workingtime_control = q_mysettings_hr.date_selected_workingtime_control
    if date_selected_workingtime_control is None:
        ls_today = datetime.date.today()
        selected_year = ls_today.year
        selected_month = ls_today.month
        date_selected_workingtime_control = datetime.date(selected_year, selected_month, 1)
        data = {
            'date_selected_workingtime_control': date_selected_workingtime_control
        }
        HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
        q_mysettings_hr.refresh_from_db()
    selected_year = date_selected_workingtime_control.year
    selected_month = date_selected_workingtime_control.month

    list_wkt_control_id_searched = []
    if len(list_input_word) == 0:
        qs_wkt_control = Workingtime_Control.objects.filter(Q(check_discard=False) & ~Q(owner__profile__id__in=list_profile_id_wkt_issued_check_excepter) & Q(fiscal_year=selected_year) & Q(fiscal_month=selected_month))
        if qs_wkt_control is not None and len(qs_wkt_control) > 0:
            for q_wkt_control in qs_wkt_control:
                if q_wkt_control.id not in list_wkt_control_id_searched:
                    list_wkt_control_id_searched.append(q_wkt_control.id)
    else:
        for keyword_str in list_input_word:
            qs_wkt_control = Workingtime_Control.objects.filter(Q(check_discard=False) & ~Q(owner__profile__id__in=list_profile_id_wkt_issued_check_excepter) & Q(fiscal_year=selected_year) & Q(fiscal_month=selected_month) & (Q(owner__profile__name_korean__icontains=keyword_str) | Q(hrlayout__division__division_name__icontains=keyword_str) | Q(hrlayout__team__team_name__icontains=keyword_str)))
            if qs_wkt_control is not None and len(qs_wkt_control) > 0:
                for q_wkt_control in qs_wkt_control:
                    if q_wkt_control.id not in list_wkt_control_id_searched:
                        list_wkt_control_id_searched.append(q_wkt_control.id)
    data = {
        'list_wkt_control_id_searched': list_wkt_control_id_searched,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True


