#--------------------------------------------------------------------------------------------------------------------------
# 발행근무시간들로 분석하기 함수 v.2023.4.24.

# 평일
# 회사출근횟수 / 출장외근횟수 / 재택근무횟수 ==> 새로은 카테고리로 뺀다. (근무위치)
# 평일 출근누락, 평일 퇴근누락 합쳐서 평일 출퇴근 누락(오류) 횟수 하나로 제일 마지막에 넣는다.

# 휴일
# 휴일 출퇴근 횟수 / 휴일 총 근무시간 / 휴일 평균 근무시간 / 휴일 출퇴근 오류 횟수(휴일 출근오류, 휴일 퇴근오류 합친다.)
#--------------------------------------------------------------------------------------------------------------------------
def get_dict_data_for_wkt_issued_analytics(qs_workingtime_issued):
    # 평일
    list_q_wkt_issued_business_all_monthly = []  # 월간 평일 출근 횟수(외근후 출근, 반차/반반차후 출근, 외근, 재택 포함,  휴가 불포함)
    list_q_wkt_issued_business_onsite_monthly = []  # 월간 평일 회사 바로출근 횟수(외근후 출근, 반차/반반차후 출근 불포함)
    list_q_wkt_issued_business_outside_monthly = []  # 평일 외근/출장 근무 개수
    list_q_wkt_issued_business_home_monthly = []  # 평일 재택 근무 개수
    list_q_wkt_issued_business_vacation_monthly = []  # 평일 휴가 개수
    list_q_wkt_issued_business_etc_monthly = []  # 평일 기타 개수
    #--------------------------------------------------------------------------------------------------------------------------
    list_q_wkt_issued_business_valid_checkin_checkout_monthly = [] # 월간 평일 출퇴근 기록 있는 근무
    list_q_wkt_issued_business_valid_checkin_monthly = [] # 월간 평일 onsite 출근 기록 있는 근무일수(출근도장만 찍혔으면 무조건(외근후출근, 반차/반반차후 출근 모두 포함))
    list_q_wkt_issued_business_valid_checkout_monthly = [] # 월간 평일 onsite 퇴근 기록 있는 근무일수(퇴근도장만 찍혔으면 무조건(외근후바로퇴근, 퇴근후 바로 반차/반반차 모두 포함))

    list_q_wkt_issued_business_valid_checkin_checkout_on_site_monthly = [] # 월간 평일 onsite 출퇴근 기록 있는 근무일수(회사로 바로 출근, 회사에서 바로 퇴근)
    list_q_wkt_issued_business_valid_checkin_on_site_monthly = [] # 월간 평일 onsite 출근 기록 있는 근무일수(회사로 바로 출근)
    list_q_wkt_issued_business_valid_checkout_on_site_monthly = [] # 월간 평일 onsite 퇴근 기록 있는 근무일수(회사에서 바로 퇴근)
    #--------------------------------------------------------------------------------------------------------------------------
    list_q_wkt_issued_business_checkin_standard_monthly = []  # 월간 평일 정상출근
    list_q_wkt_issued_business_checkin_late_monthly = []  # 월간 평일 지각
    list_q_wkt_issued_business_checkin_unknown_monthly = []  # 월간 평일 출근누락
    list_q_wkt_issued_business_checkin_late_standard_monthly = []  # 월간 평일 늦은 정상 출근(휴가후출근/외근후출근)
    #--------------------------------------------------------------------------------------------------------------------------
    list_q_wkt_issued_business_checkout_standard_monthly = []  # 월간 평일 정상퇴근
    list_q_wkt_issued_business_checkout_late_monthly = []  # 월간 평일 연장근로
    list_q_wkt_issued_business_checkout_unknown_monthly = []  # 월간 평일 퇴근누락
    list_q_wkt_issued_business_checkout_early_standard_monthly = []  # 월간 평일 이른 정상 퇴근(퇴근후휴가/외근후바로퇴근)
    #--------------------------------------------------------------------------------------------------------------------------
    # 휴일
    list_q_wkt_issued_holiday_all_monthly = []  # 휴일 모든 출퇴근관련 정보
    list_q_wkt_issued_holiday_valid_checkin_checkout_monthly = [] # 월간 휴일 출퇴근 시간 기록 있는 근무정보
    list_q_wkt_issued_holiday_checkin_standard_monthly = []  # 휴일 정상 출근
    list_q_wkt_issued_holiday_checkin_unknown_monthly = []  # 휴일 출근 누락
    list_q_wkt_issued_holiday_checkout_standard_monthly = []  # 휴일 정상 퇴근
    list_q_wkt_issued_holiday_checkout_unknown_monthly = []  # 휴일 퇴근 누락

    if qs_workingtime_issued is not None and len(qs_workingtime_issued) > 0:
        for q_wkt_issued_monthly in qs_workingtime_issued:
            # print('q_wkt_issued_monthly', q_wkt_issued_monthly.id, q_wkt_issued_monthly.owner.profile.name_korean)
            # 근무일별 분류(평일/휴일)
            if q_wkt_issued_monthly.status_working_day == 'WK_DAY_NORMAL':  # 정상근무일(평일)
                if q_wkt_issued_monthly not in list_q_wkt_issued_business_all_monthly:
                    list_q_wkt_issued_business_all_monthly.append(q_wkt_issued_monthly)
                    #--------------------------------------------------------------------------------------------------------------------------
                    # 월간 평일 onsite 출근 and 퇴근 기록 있는 근무(출근도장만 찍혔으면 무조건(외근후출근, 반차/반반차후 출근 모두 포함))
                    if q_wkt_issued_monthly.datetime_start is not None and q_wkt_issued_monthly.datetime_end is not None:
                        list_q_wkt_issued_business_valid_checkin_checkout_monthly.append(q_wkt_issued_monthly)
                    # 월간 평일 onsite 출근 기록 있는 근무(출근도장만 찍혔으면 무조건(외근후출근, 반차/반반차후 출근 모두 포함))
                    if q_wkt_issued_monthly.datetime_start is not None:
                        list_q_wkt_issued_business_valid_checkin_monthly.append(q_wkt_issued_monthly)
                    # 월간 평일 onsite 퇴근 기록 있는 근무(퇴근도장만 찍혔으면 무조건(외근후바로퇴근, 퇴근후 바로 반차/반반차 모두 포함))
                    if q_wkt_issued_monthly.datetime_end is not None:
                        list_q_wkt_issued_business_valid_checkout_monthly.append(q_wkt_issued_monthly)
                    #--------------------------------------------------------------------------------------------------------------------------
                    # 월간 평일 onsite 출퇴근 기록 있는 근무일수(회사로 바로 출근, 회사에서 바로 퇴근)
                    if q_wkt_issued_monthly.status_wkt_start == 'WKD_TIME_EARLY' or q_wkt_issued_monthly.status_wkt_start == 'WKD_TIME_NORMAL' or q_wkt_issued_monthly.status_wkt_start == 'WKD_TIME_LATE':
                        if q_wkt_issued_monthly.status_wkt_end == 'WKD_TIME_EARLY' or q_wkt_issued_monthly.status_wkt_end == 'WKD_TIME_NORMAL' or q_wkt_issued_monthly.status_wkt_end == 'WKD_TIME_LATE':
                            list_q_wkt_issued_business_valid_checkin_checkout_on_site_monthly.append(q_wkt_issued_monthly)
                    # 월간 평일 onsite 출근 기록 있는 근무일수(회사로 바로 출근)
                    if q_wkt_issued_monthly.status_wkt_start == 'WKD_TIME_EARLY' or q_wkt_issued_monthly.status_wkt_start == 'WKD_TIME_NORMAL' or q_wkt_issued_monthly.status_wkt_start == 'WKD_TIME_LATE':
                        list_q_wkt_issued_business_valid_checkin_on_site_monthly.append(q_wkt_issued_monthly)
                    # 월간 평일 onsite 퇴근 기록 있는 근무일수(회사에서 바로 퇴근)
                    if q_wkt_issued_monthly.status_wkt_end == 'WKD_TIME_EARLY' or q_wkt_issued_monthly.status_wkt_end == 'WKD_TIME_NORMAL' or q_wkt_issued_monthly.status_wkt_end == 'WKD_TIME_LATE':
                        list_q_wkt_issued_business_valid_checkout_on_site_monthly.append(q_wkt_issued_monthly)
                    #--------------------------------------------------------------------------------------------------------------------------


                    # 근무형태별 분류(회사출근/외근출장/재택근무/휴가/기타)
                    if q_wkt_issued_monthly.status_working_type_location == 'ON-SITE':  # 회사출근
                        if q_wkt_issued_monthly not in list_q_wkt_issued_business_onsite_monthly:
                            list_q_wkt_issued_business_onsite_monthly.append(q_wkt_issued_monthly)
                    elif q_wkt_issued_monthly.status_working_type_location == 'OUTSIDE':  # 외근/출장
                        if q_wkt_issued_monthly not in list_q_wkt_issued_business_outside_monthly:
                            list_q_wkt_issued_business_outside_monthly.append(q_wkt_issued_monthly)
                    elif q_wkt_issued_monthly.status_working_type_location == 'HOME':  # 재택근무
                        if q_wkt_issued_monthly not in list_q_wkt_issued_business_home_monthly:
                            list_q_wkt_issued_business_home_monthly.append(q_wkt_issued_monthly)
                    elif q_wkt_issued_monthly.status_working_type_location == 'VACATION':  # 휴가
                        if q_wkt_issued_monthly not in list_q_wkt_issued_business_vacation_monthly:
                            list_q_wkt_issued_business_vacation_monthly.append(q_wkt_issued_monthly)
                    elif q_wkt_issued_monthly.status_working_type_location == 'UNKNOWN':  # 기타
                        if q_wkt_issued_monthly not in list_q_wkt_issued_business_etc_monthly:
                            list_q_wkt_issued_business_etc_monthly.append(q_wkt_issued_monthly)

                    # 평일 출근상태 분류(정상출근/지각/출근미상)
                    if q_wkt_issued_monthly.status_wkt_start == 'WKD_TIME_EARLY' or q_wkt_issued_monthly.status_wkt_start == 'WKD_TIME_NORMAL':  # 정상출근,  # 조기출근 ==> 정상출근으로 간주
                        if q_wkt_issued_monthly not in list_q_wkt_issued_business_checkin_standard_monthly:
                            list_q_wkt_issued_business_checkin_standard_monthly.append(q_wkt_issued_monthly)
                    elif q_wkt_issued_monthly.status_wkt_start == 'WKD_TIME_LATE':  # 지각
                        if q_wkt_issued_monthly not in list_q_wkt_issued_business_checkin_late_monthly:
                            list_q_wkt_issued_business_checkin_late_monthly.append(q_wkt_issued_monthly)
                    elif q_wkt_issued_monthly.status_wkt_start == 'WKD_TIME_UNKNOWN':  # 출근미상
                        if q_wkt_issued_monthly not in list_q_wkt_issued_business_checkin_unknown_monthly:
                            list_q_wkt_issued_business_checkin_unknown_monthly.append(q_wkt_issued_monthly)
                    elif q_wkt_issued_monthly.status_wkt_start == 'WKD_TIME_VACATION_AND_WORK' or q_wkt_issued_monthly.status_wkt_start == 'WKD_TIME_OFF_SITE_AND_ON_SITE':  # 반차/반반차 후 출근 or 외근 후 출근
                        if q_wkt_issued_monthly not in list_q_wkt_issued_business_checkin_late_standard_monthly:
                            list_q_wkt_issued_business_checkin_late_standard_monthly.append(q_wkt_issued_monthly)

                    # 평일 퇴근상태 분류(정상퇴근/연장근로/퇴근미상)
                    if q_wkt_issued_monthly.status_wkt_end == 'WKD_TIME_EARLY' or q_wkt_issued_monthly.status_wkt_end == 'WKD_TIME_NORMAL':  # 정상퇴근,  # 조기퇴근 ==> 정상퇴근으로 간주
                        if q_wkt_issued_monthly not in list_q_wkt_issued_business_checkout_standard_monthly:
                            list_q_wkt_issued_business_checkout_standard_monthly.append(q_wkt_issued_monthly)
                    elif q_wkt_issued_monthly.status_wkt_end == 'WKD_TIME_LATE':  # 연장근로
                        if q_wkt_issued_monthly not in list_q_wkt_issued_business_checkout_late_monthly:
                            list_q_wkt_issued_business_checkout_late_monthly.append(q_wkt_issued_monthly)
                    elif q_wkt_issued_monthly.status_wkt_end == 'WKD_TIME_UNKNOWN':  # 퇴근미상
                        if q_wkt_issued_monthly not in list_q_wkt_issued_business_checkout_unknown_monthly:
                            list_q_wkt_issued_business_checkout_unknown_monthly.append(q_wkt_issued_monthly)
                    elif q_wkt_issued_monthly.status_wkt_end == 'WKD_TIME_VACATION_AND_WORK' or q_wkt_issued_monthly.status_wkt_end == 'WKD_TIME_OFF_SITE_AND_ON_SITE':  # 반차/반반차 퇴근 or 외근후 바로퇴근
                        if q_wkt_issued_monthly not in list_q_wkt_issued_business_checkout_early_standard_monthly:
                            list_q_wkt_issued_business_checkout_early_standard_monthly.append(q_wkt_issued_monthly)

            else:  # 휴일
                if q_wkt_issued_monthly not in list_q_wkt_issued_holiday_all_monthly:
                    # 휴일 출퇴근기록 모두 수집
                    list_q_wkt_issued_holiday_all_monthly.append(q_wkt_issued_monthly)

                    # 휴일 출퇴근 시간 기록 있는 날 분류
                    if q_wkt_issued_monthly.datetime_start is not None and q_wkt_issued_monthly.datetime_end is not None:
                        list_q_wkt_issued_holiday_valid_checkin_checkout_monthly.append(q_wkt_issued_monthly)

                    # 휴일 출퇴근은 누락이 아니면 모두 정상근무시간으로 적용(지각/연장근로 없음)
                    # 휴일 출근상태(정상출근/출근미상)
                    if q_wkt_issued_monthly.status_wkt_start == 'WKD_TIME_UNKNOWN' or q_wkt_issued_monthly.status_wkt_start is None:  # 출근미상
                        if q_wkt_issued_monthly not in list_q_wkt_issued_holiday_checkin_unknown_monthly:
                            list_q_wkt_issued_holiday_checkin_unknown_monthly.append(q_wkt_issued_monthly)
                    else: # 정상출근
                        if q_wkt_issued_monthly not in list_q_wkt_issued_holiday_checkin_standard_monthly:
                            list_q_wkt_issued_holiday_checkin_standard_monthly.append(q_wkt_issued_monthly)
                    # 휴일 퇴근상태(정상퇴근/퇴근미상)
                    if q_wkt_issued_monthly.status_wkt_start == 'WKD_TIME_UNKNOWN' or q_wkt_issued_monthly.status_wkt_start is None:  # 퇴근미상
                        if q_wkt_issued_monthly not in list_q_wkt_issued_holiday_checkout_unknown_monthly:
                            list_q_wkt_issued_holiday_checkout_unknown_monthly.append(q_wkt_issued_monthly)
                    else: # 정상퇴근
                        if q_wkt_issued_monthly not in list_q_wkt_issued_holiday_checkout_standard_monthly:
                            list_q_wkt_issued_holiday_checkout_standard_monthly.append(q_wkt_issued_monthly)

    #--------------------------------------------------------------------------------------------------------------------------
    # 멤버별 q_wkt_control로 분류된 Wkt Issued 내용으로 Workingtime Control 내용 계산하기
    #--------------------------------------------------------------------------------------------------------------------------
    # 횟수 계산

    #--------------------------------------------------------------------------------------------------------------------------
    # 평일 + 휴일
    #--------------------------------------------------------------------------------------------------------------------------
    # 월간 휴일+평일 근무 횟수
    num_workingdays_all_checkin_monthly = len(list_q_wkt_issued_business_all_monthly) + len(list_q_wkt_issued_holiday_all_monthly)

    #--------------------------------------------------------------------------------------------------------------------------
    # 평일
    #--------------------------------------------------------------------------------------------------------------------------

    # 평일 출근 장소  :  0 = 1 + 2 + 3
        # 0 월간 평일 출근 횟수(외근후 출근, 반차/반반차후 출근, 외근, 재택 포함,  휴가 불포함)
        # 1 월간 평일 회사 바로출근 횟수(외근후 출근, 반차/반반차후 출근 불포함)
        # 2 월간 평일 출장/외근 횟수
        # 3 월간 평일 자택근무 횟수

    # 0 : 평일 모든 출근  = 월간 평일 회사출근 횟수 + 월간 평일 출장/외근 횟수 + 월간 평일 자택근무 횟수
    num_workingdays_business_checkin_all_monthly = len(list_q_wkt_issued_business_all_monthly)
    # 1 : 월간 평일 회사출근 횟수
    num_workingdays_business_checkin_onsite_monthly = len(list_q_wkt_issued_business_onsite_monthly)
    # 2 : 월간 평일 출장/외근 횟수
    num_workingdays_business_checkin_outside_monthly = len(list_q_wkt_issued_business_outside_monthly)
    # 3 : 월간 평일 자택근무 횟수
    num_workingdays_business_checkin_home_monthly = len(list_q_wkt_issued_business_home_monthly)
    #--------------------------------------------------------------------------------------------------------------------------

    # 월간 평일 출퇴근 정보 있는 횟수
    num_workingdays_business_valid_checkin_checkout_onsite_monthly = len(list_q_wkt_issued_business_valid_checkin_checkout_monthly)


    # 평일 출근 상태
    # 월간 평일 정상 출근 횟수
    num_workingdays_business_checkin_standard_monthly = len(list_q_wkt_issued_business_checkin_standard_monthly)
    # 월간 평일 지각 횟수
    num_workingdays_business_checkin_late_monthly = len(list_q_wkt_issued_business_checkin_late_monthly)
    # 월간 평일 출근 누락 횟수
    num_workingdays_business_checkin_unknown_monthly = len(list_q_wkt_issued_business_checkin_unknown_monthly)

    # 평일 퇴근 상태
    # 월간 평일 정상 퇴근 횟수
    num_workingdays_business_checkout_standard_monthly = len(list_q_wkt_issued_business_checkout_standard_monthly)
    # 월간 평일 연장근로 횟수
    num_workingdays_business_checkout_late_monthly = len(list_q_wkt_issued_business_checkout_late_monthly)
    # 월간 평일 퇴근 누락 횟수
    num_workingdays_business_checkout_unknown_monthly = len(list_q_wkt_issued_business_checkout_unknown_monthly)

    num_workingdays_business_checkin_checkout_unknown_monthly = num_workingdays_business_checkin_unknown_monthly + num_workingdays_business_checkout_unknown_monthly
    #--------------------------------------------------------------------------------------------------------------------------
    # 휴일
    # 월간 휴일 출퇴근 정보 있는 횟수
    num_workingdays_holiday_valid_checkin_checkout_onsite_monthly = len(list_q_wkt_issued_holiday_valid_checkin_checkout_monthly)
    # 월간 휴일 출근 횟수
    num_workingdays_holiday_checkin_all_monthly = len(list_q_wkt_issued_holiday_all_monthly)
    # 월간 휴일 정상출근 횟수
    num_workingdays_holiday_checkin_standard_monthly = len(list_q_wkt_issued_holiday_checkin_standard_monthly)
    # 월간 휴일 누락출근 횟수
    num_workingdays_holiday_checkin_unknown_monthly = len(list_q_wkt_issued_holiday_checkin_unknown_monthly)
    # 월간 휴일 정상퇴근 횟수
    num_workingdays_holiday_checkout_standard_monthly = len(list_q_wkt_issued_holiday_checkout_standard_monthly)
    # 월간 휴일 누락퇴근 횟수
    num_workingdays_holiday_checkout_unknown_monthly = len(list_q_wkt_issued_holiday_checkout_unknown_monthly)

    num_workingdays_holiday_checkin_checkout_unknown_monthly = num_workingdays_holiday_checkin_unknown_monthly + num_workingdays_holiday_checkout_unknown_monthly
    #--------------------------------------------------------------------------------------------------------------------------
    # 델타 시간 계산
    # datetime.time - datetime.time  계산은 안됨
    # datetime.datetime - datetime.datetime으로 만들어서 계산하고 다시 time만 빼내야 함.

    #--------------------------------------------------------------------------------------------------------------------------
    # HR이 설정한 출퇴근 시간 기준값
    q_hr_default_settings = HR_Default_Settings.objects.last()
    default_time_start_standard = q_hr_default_settings.default_time_start_standard  # 출근기준
    default_time_end_standard = q_hr_default_settings.default_time_end_standard  # 퇴근기준
    default_time_start_early = q_hr_default_settings.default_time_start_early
    default_time_end_lately = q_hr_default_settings.default_time_end_lately  # 연장근로 기준
    default_datebaseline_time = q_hr_default_settings.default_datebaseline_time  # 날짜변경 기준
    #--------------------------------------------------------------------------------------------------------------------------
    # 총 시간 계산
    #--------------------------------------------------------------------------------------------------------------------------
    # 월간 평일 순/총 근무시간 합
    datetime_wkt_all_monthly_total = datetime.datetime(1, 1, 1, 0, 0)
    datetime_wkt_all_monthly_net = datetime.datetime(1, 1, 1, 0, 0)
    datetime_wkt_all_monthly_total_on_site = datetime.datetime(1, 1, 1, 0, 0) # 월간 평일+휴일 총 근무시간(외근/자택근무 제외)
    datetime_wkt_all_monthly_net_on_site = datetime.datetime(1, 1, 1, 0, 0) # 월간 평일+휴일 넷 근무시간(외근/자택근무 제외)

    datetime_wkt_business_monthly_total = datetime.datetime(1, 1, 1, 0, 0)
    datetime_wkt_business_monthly_net = datetime.datetime(1, 1, 1, 0, 0)
    datetime_wkt_business_monthly_total_on_site = datetime.datetime(1, 1, 1, 0, 0)
    datetime_wkt_business_monthly_net_on_site = datetime.datetime(1, 1, 1, 0, 0)

    if len(list_q_wkt_issued_business_valid_checkin_checkout_monthly) > 0: # 평일 출퇴근 기록 있는 날 분류
        for q_wkt_issued in list_q_wkt_issued_business_valid_checkin_checkout_monthly:
            status_wkt_start = q_wkt_issued.status_wkt_start
            status_wkt_end = q_wkt_issued.status_wkt_end
            date_of_work = q_wkt_issued.date_of_work
            # 자택근무시 or 외근시 or 외근 후 출근시 9시 출근으로 간주
            if status_wkt_start == 'WKD_TIME_OFF_SITE_AND_ON_SITE' or status_wkt_start == 'WKD_TIME_OFF_SITE':
                datetime_start = datetime.datetime(date_of_work.year, date_of_work.month, date_of_work.day, 9, 0)
            else:
                datetime_start = q_wkt_issued.datetime_start
            # 자택근무시 or 외근시 or 외근 후 현장에서 바로퇴근시 18시 퇴근으로 간주
            if status_wkt_end == 'WKD_TIME_OFF_SITE_AND_ON_SITE' or status_wkt_end == 'WKD_TIME_OFF_SITE':
                datetime_end = datetime.datetime(date_of_work.year, date_of_work.month, date_of_work.day, 18, 0)
            else:
                datetime_end = q_wkt_issued.datetime_end
            # 시간 더하기
            if datetime_end > datetime_start:
                return_value = hr_workingtime_get_net_working_time(datetime_start, datetime_end)
