def hr_workingtime_control_calculate_workingtime_analytics_graph_row(request, q_mysettings_hr):
    print('# Normal Distribution Calculation')
    # 기본 WKT Control 계산하기
    hr_workingtime_control_calculate_workingtime_analytics_table_row(request, q_mysettings_hr)
    # 상대평가 계산하기
