#--------------------------------------------------------------------------------------------------------------------------
# Workingtime Analytics Data Calculation Switch 하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_control_switch_workingtime_analytics_table_row(request, q_mysettings_hr):
    check_activate_analytics_table_graph = q_mysettings_hr.check_activate_analytics_table_graph
    if check_activate_analytics_table_graph == True:
        check_activate_analytics_table_graph = False
    else:
        check_activate_analytics_table_graph = True
    data = {
        'check_activate_analytics_table_graph': check_activate_analytics_table_graph,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)


    #--------------------------------------------------------------------------------------------------------------------------
    # 임시 삭제
    ls_today = datetime.date.today()
    day_x = datetime.timedelta(days=60)
    day_1 = datetime.timedelta(days=1)
    ls_day_x_ago = ls_today - day_x
    day_i = ls_today

    while day_i > ls_day_x_ago:
        datetime_end_good = datetime.datetime(day_i.year, day_i.month, day_i.day, 18, 00)
        qs_wkt_end_good = Workingtime_Issued.objects.filter(Q(date_of_work=day_i) & Q(check_discard=False) & Q(datetime_end=datetime_end_good))
        if qs_wkt_end_good is not None and len(qs_wkt_end_good) > 0:
            for q_wkt_end_good in qs_wkt_end_good:
                data = {
                   'status_wkt_end': 'WKD_TIME_NORMAL',
                }
                Workingtime_Issued.objects.filter(id=q_wkt_end_good.id).update(**data)
        day_i = day_i - day_1


    return True




#--------------------------------------------------------------------------------------------------------------------------
# 앞뒤로 한달씩 날짜 이동하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_control_calendar_select_date_prev_month_or_next_month(request, q_mysettings_hr):
    ls_today = datetime.date.today()
    ls_year = ls_today.year
    ls_month = ls_today.month
    ls_this_month = datetime.date(ls_year, ls_month, 1)
    #--------------------------------------------------------------------------------------------------------------------------
    # 선택한 달 및 앞뒤 한달씩 Datetime 생성하기
    date_selected_workingtime_control = q_mysettings_hr.date_selected_workingtime_control
    if date_selected_workingtime_control is None:
        ls_today = datetime.date.today()
        selected_year = ls_today.year
        selected_month = ls_today.month
        date_selected_workingtime_control = datetime.date(selected_year, selected_month, 1)
        data = {
            'date_selected_workingtime_control': date_selected_workingtime_control
        }
        HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
        q_mysettings_hr.refresh_from_db()
    selected_year = date_selected_workingtime_control.year
    selected_month = date_selected_workingtime_control.month
    if selected_month == 12:
        selected_year_next = selected_year + 1
        selected_month_next = 1
        selected_year_prev = selected_year
        selected_month_prev = selected_month - 1
    elif selected_month == 1:
        selected_year_next = selected_year
        selected_month_next = selected_month + 1
        selected_year_prev = selected_year - 1
        selected_month_prev = 12
    else:
        selected_year_next = selected_year
        selected_month_next = selected_month + 1
        selected_year_prev = selected_year
        selected_month_prev = selected_month - 1
    selected_calendar_date_str = request.POST.get('button-hr-workingtime-control-calendar-select-date')
    if selected_calendar_date_str == 'prev_month':
        date_selected_workingtime_control = datetime.date(selected_year_prev, selected_month_prev, 1)
    elif selected_calendar_date_str == 'next_month':
        date_selected_workingtime_control = datetime.date(selected_year_next, selected_month_next, 1)
    elif selected_calendar_date_str == 'selected_month':
        date_selected_workingtime_control = date_selected_workingtime_control
    elif selected_calendar_date_str == 'reset':
        date_selected_workingtime_control = ls_this_month
    else:
        pass
    #--------------------------------------------------------------------------------------------------------------------------
    # Mysettings 설정 저장하기
    data = {
        'date_selected_workingtime_control': date_selected_workingtime_control,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    q_mysettings_hr.refresh_from_db()
    return True




