#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_control_select_calendar_date_workingtime_control(request, q_mysettings_hr):
    specific_date_str = request.POST.get('input-hr-workingtime-control-calendar-select-date-workingtime-control')
    if specific_date_str is None or specific_date_str == '':
        return False
    list_specific_date_str = specific_date_str.split('-')
    specific_date = datetime.date(int(list_specific_date_str[0]), int(list_specific_date_str[1]), 1)
    data = {
        'date_selected_workingtime_control': specific_date,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    q_mysettings_hr.refresh_from_db()
    return True


#--------------------------------------------------------------------------------------------------------------------------
# Analytics Table Column type 숨기기/보이기
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_control_workingtime_analytics_select_table_column_type(request, q_mysettings_hr):
    wkt_index_type_str = request.POST.get('button-hr-workingtime-control-select-workingtime-analytics-table-column-type')
    list_selected_field_name_for_wkt_analytics_type = q_mysettings_hr.list_selected_field_name_for_wkt_analytics_type
    if wkt_index_type_str in list_selected_field_name_for_wkt_analytics_type:
        list_selected_field_name_for_wkt_analytics_type.remove(wkt_index_type_str)
    else:
        list_selected_field_name_for_wkt_analytics_type.append(wkt_index_type_str)
    data = {
        'list_selected_field_name_for_wkt_analytics_type': list_selected_field_name_for_wkt_analytics_type,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True


#--------------------------------------------------------------------------------------------------------------------------
# Workingtime Analytics Table Column index 명으로 Sorting 하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_control_workingtime_analytics_select_table_column_index_for_sorting(request, q_mysettings_hr):
    selected_field_str = request.POST.get('button-hr-workingtime-control-select-workingtime-analytics-table-column-index')
    selected_field_name_for_wkt_analytics_sorting = q_mysettings_hr.selected_field_name_for_wkt_analytics_sorting
    check_selected_field_name_for_wkt_analytics_sorting_descend = q_mysettings_hr.check_selected_field_name_for_wkt_analytics_sorting_descend
    if selected_field_str is not None and selected_field_str != '':
        if selected_field_name_for_wkt_analytics_sorting is not None:
            if selected_field_name_for_wkt_analytics_sorting == selected_field_str:
                if check_selected_field_name_for_wkt_analytics_sorting_descend == False:
                    selected_field_str = f'-{selected_field_str}'
        data = {
            'selected_field_name_for_wkt_analytics_sorting': selected_field_str,
        }
        HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
        q_mysettings_hr.refresh_from_db()
    return True


#--------------------------------------------------------------------------------------------------------------------------
# 팀이름 선택하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_control_seelct_workingtime_analytics_table_row_team(request, q_mysettings_hr):
    ls_today = datetime.date.today()
    q_wkt_control_id_str = request.POST.get('button-hr-workingtime-control-select-workingtime-analytics-table-row-team')
    if q_wkt_control_id_str is None or q_wkt_control_id_str == '':
        return False
    q_wkt_control_id = int(q_wkt_control_id_str)
    q_wkt_control = Workingtime_Control.objects.get(id=q_wkt_control_id)
    q_team = q_wkt_control.hrlayout.team
    qs_hr_layout = HR_Layout.objects.filter(Q(check_discard=False) & Q(team=q_team))
    if qs_hr_layout is not None and len(qs_hr_layout) > 0:
        list_wkt_control_id_selected = []
        date_selected_workingtime_control = q_mysettings_hr.date_selected_workingtime_control
        if date_selected_workingtime_control is None:
            selected_year = ls_today.year
            selected_month = ls_today.month
            date_selected_workingtime_control = datetime.date(selected_year, selected_month, 1)
            data = {
                'date_selected_workingtime_control': date_selected_workingtime_control
            }
            HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
            q_mysettings_hr.refresh_from_db()
        selected_year = date_selected_workingtime_control.year
        selected_month = date_selected_workingtime_control.month
        for q_hr_layout in qs_hr_layout:
            q_wkt_control_selected = Workingtime_Control.objects.filter(Q(check_discard=False) & Q(hrlayout=q_hr_layout) & Q(fiscal_year=selected_year) & Q(fiscal_month=selected_month)).last()
            if q_wkt_control_selected is not None and q_wkt_control_selected.id not in list_wkt_control_id_selected:
                list_wkt_control_id_selected.append(q_wkt_control_selected.id)
    else:
        list_wkt_control_id_selected = None
    data = {
        'list_wkt_control_id_selected': list_wkt_control_id_selected,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    q_mysettings_hr.refresh_from_db()
    return True



#--------------------------------------------------------------------------------------------------------------------------
# 부서이름 선택하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_control_select_workingtime_analytics_table_row_division(request, q_mysettings_hr):

    q_wkt_control_id_str = request.POST.get('button-hr-workingtime-control-select-workingtime-analytics-table-row-division')
    if q_wkt_control_id_str is None or q_wkt_control_id_str == '':
        return False
    q_wkt_control_id = int(q_wkt_control_id_str)
    q_wkt_control = Workingtime_Control.objects.get(id=q_wkt_control_id)
    q_division = q_wkt_control.hrlayout.division
    qs_hr_layout = HR_Layout.objects.filter(Q(check_discard=False) & Q(division=q_division))
    if qs_hr_layout is not None and len(qs_hr_layout) > 0:
        list_wkt_control_id_selected = []
        date_selected_workingtime_control = q_mysettings_hr.date_selected_workingtime_control
        if date_selected_workingtime_control is None:
            ls_today = datetime.date.today()
            selected_year = ls_today.year
            selected_month = ls_today.month
            date_selected_workingtime_control = datetime.date(selected_year, selected_month, 1)
            data = {
                'date_selected_workingtime_control': date_selected_workingtime_control
            }
            HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
            q_mysettings_hr.refresh_from_db()
        selected_year = date_selected_workingtime_control.year
        selected_month = date_selected_workingtime_control.month
        for q_hr_layout in qs_hr_layout:
            q_wkt_control_selected = Workingtime_Control.objects.filter(Q(check_discard=False) & Q(hrlayout=q_hr_layout) & Q(fiscal_year=selected_year) & Q(fiscal_month=selected_month)).last()
            if q_wkt_control_selected is not None and q_wkt_control_selected.id not in list_wkt_control_id_selected:
                list_wkt_control_id_selected.append(q_wkt_control_selected.id)
    else:
        list_wkt_control_id_selected = None
    data = {
        'list_wkt_control_id_selected': list_wkt_control_id_selected,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    q_mysettings_hr.refresh_from_db()
    return True


