#--------------------------------------------------------------------------------------------------------------------------
# 멤버 출퇴근 분석 파일 다운로드 ver. 2023-04-24
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_control_analytics_table_file_download(request, q_mysettings_hr, qs_wkt_control):
    # q_hr_dms = HR_Document_Minor_Settings.objects.last()
    # if q_hr_dms is not None:
    #     list_profile_id_wkt_issued_check_excepter = q_hr_dms.list_profile_id_wkt_issued_check_excepter
    # if list_profile_id_wkt_issued_check_excepter is None:
    #     list_profile_id_wkt_issued_check_excepter = []
    date_selected_workingtime_control = q_mysettings_hr.date_selected_workingtime_control
    if date_selected_workingtime_control is None:
        selected_year = ls_today.year
        selected_month = ls_today.month
        date_selected_workingtime_control = datetime.date(selected_year, selected_month, 1)
        data = {
            'date_selected_workingtime_control': date_selected_workingtime_control
        }
        HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
        q_mysettings_hr.refresh_from_db()
    list_member_workingtime_control_field = []
    if qs_wkt_control is None or len(qs_wkt_control) == 0:
        False
    for q_wkt_control in qs_wkt_control:
        q_profile = q_wkt_control.owner.profile
        if q_profile is not None:
            name_korean = q_profile.name_korean
        else:
            name_korean = None
        q_hrlayout = q_wkt_control.hrlayout
        if q_hrlayout is not None:
            q_division = q_hrlayout.division
            if q_division is not None:
                division_name = q_wkt_control.hrlayout.division.division_name
            else:
                division_name = None
            q_team = q_hrlayout.team
            if q_team is not None:
                team_name = q_wkt_control.hrlayout.team.team_name
            else:
                team_name = None
        else:
            division_name = None
            team_name = None

        # 월간 평일+휴일 총 근무횟수
        num_workingdays_all_checkin_monthly = q_wkt_control.num_workingdays_all_checkin_monthly
