def hr_workingtime_issued_search_member_personalized_basic_info(request):
    inputTextName_str = str(request.GET.get('inputTextName'))
    if inputTextName_str is None or inputTextName_str == '':
        return None
    qs_hrlayout = HR_Layout.objects.filter(Q(check_discard=False) & (Q(member__user__profile__name_korean__icontains=inputTextName_str) | Q(team__team_name__icontains=inputTextName_str))).order_by('team__team_name', 'member__user__profile__name_korean')
    # print('qs_hrlayout', qs_hrlayout)
    #--------------------------------------------------------------------------------------------------------------------------
    list_dict_personalized_searched = []
    if qs_hrlayout is not None and len(qs_hrlayout) > 0:
        for q_hrlayout in qs_hrlayout:
            position_str = get_my_position_title_and_update_to_q_hrlayout(q_hrlayout)
            q_profile = q_hrlayout.member.user.profile
            data = {
                'name': q_profile.name_korean,
                'position': position_str,
                'email': q_profile.email,
                'phone_mobile': q_profile.phone_mobile,
                'hrlayout_id': q_hrlayout.id,
                'profile_id': q_profile.id,
            }
            list_dict_personalized_searched.append(data)
    # print('list_dict_personalized_searched', list_dict_personalized_searched)
    return list_dict_personalized_searched


#--------------------------------------------------------------------------------------------------------------------------
# 개인 맞춤형 출퇴근시간 기본값 리스트 생성
#--------------------------------------------------------------------------------------------------------------------------
def get_list_dict_default_wkt_standard_personalized(q_profile):
    print('# 개인 맞춤형 출퇴근시간 기본값 리스트 생성')
    ls_today = datetime.date.today()
    q_workingtime_control = Workingtime_Control.objects.filter(Q(check_discard=False) & Q(owner=q_profile.user) & Q(fiscal_year=ls_today.year) & Q(fiscal_month=ls_today.month)).last()
    #--------------------------------------------------------------------------------------------------------------------------
    list_dict_default_wkt_standard_personalized = [] # [{'start_hour': 9, 'start_minute': 30, 'end_hour': 18, 'end_minute': 30}], [화요일] [수요일]...}
    q_hds = HR_Default_Settings.objects.last()
    # print('q_hds', q_hds)
    if q_hds is None:
        return False
    default_time_start_standard = q_hds.default_time_start_standard
    default_time_end_standard = q_hds.default_time_end_standard
    if q_workingtime_control is not None:
        if q_workingtime_control.check_default_datetime_start_activated == True:
            default_time_start_standard = q_workingtime_control.default_time_start_standard
        if q_workingtime_control.check_default_datetime_end_activated == True:
            default_time_end_standard = q_workingtime_control.default_time_end_standard
    # print('default_time_start_standard', default_time_start_standard)
    # print('default_time_end_standard', default_time_end_standard)
    i = 0
    while i < 5:
        start_hour = 0 if default_time_start_standard.hour is None or default_time_start_standard.hour == '' else default_time_start_standard.hour
        start_minute = 0 if default_time_start_standard.minute is None or default_time_start_standard.minute == '' else default_time_start_standard.minute
        end_hour = 0 if default_time_end_standard.hour is None or default_time_end_standard.hour == '' else default_time_end_standard.hour
        end_minute = 0 if default_time_end_standard.minute is None or default_time_end_standard.minute == '' else default_time_end_standard.minute
        data = {
            'start_hour':start_hour,
            'start_minute':start_minute,
            'end_hour':end_hour,
            'end_minute': end_minute,
            'date_start': str(ls_today), # 시작 날짜, 끝 날짜 기록
            'date_end': 'none', # 시작 날짜, 끝 날짜 기록
        }
        list_dict_default_wkt_standard_personalized.append(data)
        i = i + 1
    # print('list_dict_default_wkt_standard_personalized /////////////////////// ', list_dict_default_wkt_standard_personalized)
    return list_dict_default_wkt_standard_personalized


#--------------------------------------------------------------------------------------------------------------------------
# 모달창에서 선택한 멤버 개인맞춤형 리스트에 추가하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_issued_register_selected_member_personalized(request, q_mysettings_hr):
    print('# 모달창에서 선택한 멤버 개인맞춤형 리스트에 추가하기', request)

    q_hr_dms = HR_Document_Minor_Settings.objects.last()
    if q_hr_dms is None:
        data = {}
        q_hr_dms = HR_Document_Minor_Settings.objects.create(**data)
    list_dict_wkt_issued_check_personalized = q_hr_dms.list_dict_wkt_issued_check_personalized
    if list_dict_wkt_issued_check_personalized is None:
        list_dict_wkt_issued_check_personalized = []
    #--------------------------------------------------------------------------------------------------------------------------
    q_hrlayout_id_str = str(request.POST.get('buttonSelectNameExcepter'))
    if q_hrlayout_id_str is None or q_hrlayout_id_str == '':
        return False
    q_hrlayout_id_int = int(q_hrlayout_id_str)
    q_hrlayout = HR_Layout.objects.get(id=q_hrlayout_id_int)
    q_profile = q_hrlayout.member.user.profile
    list_dict_default_wkt_standard_personalized = get_list_dict_default_wkt_standard_personalized(q_profile)
    #--------------------------------------------------------------------------------------------------------------------------
    # 이미 등록되어 있으면 제외
    if len(list_dict_wkt_issued_check_personalized) > 0:
        for dict_personalized in list_dict_wkt_issued_check_personalized:
            if dict_personalized['hrlayout_id'] == q_hrlayout.id:
                return False
    #--------------------------------------------------------------------------------------------------------------------------
    position_str = get_my_position_title_and_update_to_q_hrlayout(q_hrlayout)

    print('q_profile.email,', q_profile.email)
    data = {
        'name': q_profile.name_korean,
        'position': position_str,
        'email': q_profile.email,
        'phone_mobile': q_profile.phone_mobile,
        'hrlayout_id': q_hrlayout.id,
        'profile_id': q_profile.id,
        'list_dict_default_wkt_standard_personalized': list_dict_default_wkt_standard_personalized,
    }
    list_dict_wkt_issued_check_personalized.append(data)
    data = {
        'list_dict_wkt_issued_check_personalized': list_dict_wkt_issued_check_personalized,  # 개인맞춤형 출퇴근 등록자의 세부내용 리스트
    }
    HR_Document_Minor_Settings.objects.filter(id=q_hr_dms.id).update(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    # 개인맞춤형 멤버 출퇴근 컨트롤 세팅 True로 업데이트
    ls_now = datetime.datetime.now()
    fiscal_year = ls_now.year
    fiscal_month = ls_now.month

    #--------------------------------------------------------------------------------------------------------------------------
    q_workingtime_control = Workingtime_Control.objects.filter(Q(owner=q_profile.user) & Q(check_discard=False) & Q(fiscal_year=fiscal_year) & Q(fiscal_month=fiscal_month)).last()
    if q_workingtime_control is None:
        q_workingtime_control = create_or_update_hr_workingtime_control(q_profile, fiscal_year, fiscal_month)
    data = {
        'check_default_datetime_personalization_activated': True,
        'list_dict_default_wkt_standard_personalized': list_dict_default_wkt_standard_personalized,
    }
    Workingtime_Control.objects.filter(id=q_workingtime_control.id).update(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    return True


#--------------------------------------------------------------------------------------------------------------------------
# 모달창에서 선택한 멤버 개인맞춤형 리스트에서 삭제하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_issued_delete_selected_member_personalized(request, q_mysettings_hr):
    ls_today = datetime.date.today()
    q_hr_dms = HR_Document_Minor_Settings.objects.last()
    if q_hr_dms is None:
        data = {}
        q_hr_dms = HR_Document_Minor_Settings.objects.create(**data)
    list_dict_wkt_issued_check_personalized = q_hr_dms.list_dict_wkt_issued_check_personalized
    if list_dict_wkt_issued_check_personalized is None:
        list_dict_wkt_issued_check_personalized = []
    #--------------------------------------------------------------------------------------------------------------------------
    q_hrlayout_id_str = str(request.POST.get('buttonDeleteNameExcepter'))
    if q_hrlayout_id_str is None or q_hrlayout_id_str == '':
        return False
    q_hrlayout_id_int = int(q_hrlayout_id_str)
    q_hrlayout = HR_Layout.objects.get(id=q_hrlayout_id_int)
    q_profile = q_hrlayout.member.user.profile
    # print('q_hrlayout', q_hrlayout)
    #--------------------------------------------------------------------------------------------------------------------------
    # 기 등록되어 있으면 리스트에서 삭제
    if len(list_dict_wkt_issued_check_personalized) > 0:
        for dict_excepter in list_dict_wkt_issued_check_personalized:
            if dict_excepter['hrlayout_id'] == q_hrlayout.id:
                list_dict_wkt_issued_check_personalized.remove(dict_excepter)
    #--------------------------------------------------------------------------------------------------------------------------
    data = {
        'list_dict_wkt_issued_check_personalized': list_dict_wkt_issued_check_personalized,
    }
    HR_Document_Minor_Settings.objects.filter(id=q_hr_dms.id).update(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    # 제외자 리스트에서 제거시 자동 개인맞춤별출퇴근 등록 해제
    ls_now = datetime.datetime.now()
    fiscal_year = ls_now.year
    fiscal_month = ls_now.month
    q_workingtime_control = Workingtime_Control.objects.filter(Q(owner=q_profile.user) & Q(check_discard=False) & Q(fiscal_year=fiscal_year) & Q(fiscal_month=fiscal_month)).last()
    if q_workingtime_control is None:
        q_workingtime_control = create_or_update_hr_workingtime_control(q_profile, fiscal_year, fiscal_month)
    # 시작 날짜, 끝 날짜 기록
    list_dict_default_wkt_standard_personalized = q_workingtime_control.list_dict_default_wkt_standard_personalized
    for dict_default_wkt in list_dict_default_wkt_standard_personalized:
        dict_default_wkt['date_end'] = str(ls_today)
    data = {
        'check_default_datetime_personalization_activated': False,
        'list_dict_default_wkt_standard_personalized': list_dict_default_wkt_standard_personalized,
    }
    Workingtime_Control.objects.filter(id=q_workingtime_control.id).update(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    return True







