# 인사팀 커뮤니케이션  - 발행 출퇴근 수정하기 (사용자 요청에 의해)
###########################################################################################################################

#--------------------------------------------------------------------------------------------------------------------------
# 발행한 출퇴근 선택하기/선택취소하기
# == 수정하기 창 활성화 (Workingtime_issued 쿼리 선택시 자동으로 관련 창이 활성화)
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_control_activate_selected_member_workingtime_modification_view(request, q_mysettings_hr):
    q_wkt_id_str = request.POST.get('button-hr-workingtime-control-workingtime-issued-modify-activate')
    if q_wkt_id_str is None or q_wkt_id_str == '':
        return False
    q_wkt_id = int(q_wkt_id_str)
    q_workingtime_issued = Workingtime_Issued.objects.get(id=q_wkt_id)
    if q_mysettings_hr.workingtime_issued == q_workingtime_issued:
        if q_workingtime_issued.dict_modified_draft_for_workingtime_issued_from_hr is not None:
            data = {
                'dict_modified_draft_for_workingtime_issued_from_hr': None
            }
            Workingtime_Issued.objects.filter(id=q_workingtime_issued.id).update(**data)
            messages.warning(request, f'작성된 임시 출퇴근 수정내용이 삭제되었습니다.')
        q_workingtime_issued = None

    data = {
        'workingtime_issued': q_workingtime_issued,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True


#--------------------------------------------------------------------------------------------------------------------------
# 발행한 출퇴근 수정요청에 대한 인사팀 Talk 등록하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_issued_control_confirm_response_trouble_view(request, q_mysettings_hr):
    q_workingtime_issued_id_str = request.POST.get('button-hr-workingtime-control-workingtime-issued-response-confirm')
    if q_workingtime_issued_id_str is None or q_workingtime_issued_id_str == '':
        messages.warning(request, f'선택한 발행된 휴가 정보가 없습니다. 관리자에게 문의하세요.')
        return False
    q_workingtime_issued_id = int(q_workingtime_issued_id_str)
    q_workingtime_issued = Workingtime_Issued.objects.get(id=q_workingtime_issued_id)
    #--------------------------------------------------------------------------------------------------------------------------
    response_contents_str = request.POST.get('text-hr-workingtime-control-workingtime-issued-response-contents')
    if response_contents_str is None or response_contents_str == '':
        messages.warning(request, f'응답내용을 입력하지 않았습니다.')
        return False
    #--------------------------------------------------------------------------------------------------------------------------
    dict_request_for_my_issued_wkt_trouble = q_workingtime_issued.dict_request_for_my_issued_wkt_trouble
    if dict_request_for_my_issued_wkt_trouble is None:
        dict_request_for_my_issued_wkt_trouble = {}
    num_conversation = len(dict_request_for_my_issued_wkt_trouble)
    k_member_name = f'({num_conversation + 1}){q_mysettings_hr.owner.profile.name_korean}'
    dict_request_for_my_issued_wkt_trouble[k_member_name] = response_contents_str
    data = {
        'dict_request_for_my_issued_wkt_trouble': dict_request_for_my_issued_wkt_trouble,
    }
    Workingtime_Issued.objects.filter(id=q_workingtime_issued.id).update(**data)
    messages.success(request, f'발행된 휴가 Trouble에 대한 답변을 등록하였습니다. Update를 눌러 문제해결 요청에 대한 대응조치를 완료하세요')
    return True


#--------------------------------------------------------------------------------------------------------------------------
# 발행한 출퇴근 인사팀에서 마지막에 등록한 Talk 지우기
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_issued_control_confirm_response_trouble_delete_comment(request, q_mysettings_hr):
    q_workingtime_issued_id_str = request.POST.get('button-hr-workingtime-control-workingtime-issued-response-delete-last-comment')
    if q_workingtime_issued_id_str is None or q_workingtime_issued_id_str == '':
        messages.warning(request, f'선택한 발행된 휴가 정보가 없습니다. 관리자에게 문의하세요.')
        return False
    q_workingtime_issued_id = int(q_workingtime_issued_id_str)
    q_workingtime_issued = Workingtime_Issued.objects.get(id=q_workingtime_issued_id)
    #--------------------------------------------------------------------------------------------------------------------------
    dict_request_for_my_issued_wkt_trouble = q_workingtime_issued.dict_request_for_my_issued_wkt_trouble
    dict_request_for_my_issued_wkt_trouble.popitem()
    data = {
        'dict_request_for_my_issued_wkt_trouble': dict_request_for_my_issued_wkt_trouble,
    }
    # if len(dict_request_for_my_issued_wkt_trouble) == 0:
    #     data['check_report_trouble_submitted'] = False
    Workingtime_Issued.objects.filter(id=q_workingtime_issued.id).update(**data)
    return True







#--------------------------------------------------------------------------------------------------------------------------
# 발행한 출퇴근 수정내용 임시저장하기 (Draft 생성)
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_control_save_draft_workingtime_issued_modification_by_hr(request, q_mysettings_hr):
    ls_today = datetime.date.today()
    q_hr_default_settings = HR_Default_Settings.objects.last()
    default_datebaseline_time = q_hr_default_settings.default_datebaseline_time
    q_wkt_id_str = request.POST.get('button-hr-workingtime-control-workingtime-issued-modify-update')
    if q_wkt_id_str is None or q_wkt_id_str == '':
        return False
    q_wkt_id = int(q_wkt_id_str)
    q_workingtime_issued = Workingtime_Issued.objects.get(id=q_wkt_id)
    #--------------------------------------------------------------------------------------------------------------------------
    date_of_work_str = request.POST.get('input-date-hr-workingtime-control-modification-date-of-work')
    if date_of_work_str is not None and date_of_work_str != '':
        date_of_work = datetime.date(int(date_of_work_str.split('-')[0]), int(date_of_work_str.split('-')[1]), int(date_of_work_str.split('-')[2]))
        date_of_work_str = str(date_of_work)
    else:
        date_of_work = str(q_workingtime_issued.date_of_work)
    day_1 = datetime.timedelta(days=1)
    date_of_work_next = date_of_work + day_1
    datetime_start = None
    datetime_end = None
    #--------------------------------------------------------------------------------------------------------------------------
    wkt_start_time_str = request.POST.get('input-time-hr-workingtime-control-modification-start')
    # print('wkt_start_time_str', wkt_start_time_str)
    if wkt_start_time_str is not None and wkt_start_time_str != '':
        wkt_start_time_hour_int = int(wkt_start_time_str.split(':')[0])
        wkt_start_time_minute_int = int(wkt_start_time_str.split(':')[1])
        datetime_start = datetime.datetime(date_of_work.year, date_of_work.month, date_of_work.day, wkt_start_time_hour_int, wkt_start_time_minute_int)
        datetime_start_str = str(datetime_start)
        time_start = datetime.time(wkt_start_time_hour_int, wkt_start_time_minute_int)
        time_start_str = str(time_start)
    else:
        datetime_start_str = str(q_workingtime_issued.datetime_start)
        time_start_str = 'None'
    #--------------------------------------------------------------------------------------------------------------------------
    wkt_end_time_str = request.POST.get('input-time-hr-workingtime-control-modification-end')
    print('wkt_end_time_str', wkt_end_time_str)
    if wkt_end_time_str is not None and wkt_end_time_str != '':
        wkt_end_time_hour_int = int(wkt_end_time_str.split(':')[0])
        wkt_end_time_minute_int = int(wkt_end_time_str.split(':')[1])
        if default_datebaseline_time.hour > wkt_end_time_hour_int:
            datetime_end = datetime.datetime(date_of_work_next.year, date_of_work_next.month, date_of_work_next.day, wkt_end_time_hour_int, wkt_end_time_minute_int)
        else:
            datetime_end = datetime.datetime(date_of_work.year, date_of_work.month, date_of_work.day, wkt_end_time_hour_int, wkt_end_time_minute_int)
        datetime_end_str = str(datetime_end)
        time_end = datetime.time(wkt_end_time_hour_int, wkt_end_time_minute_int)
        time_end_str = str(time_end)
    else:
        datetime_end_str = str(q_workingtime_issued.datetime_end)
        time_end_str = 'None'
    #--------------------------------------------------------------------------------------------------------------------------
    # 상태 정보가 없는 경우 오늘이면 None, 과거이면 출근미상/퇴근미상으로 등록
    status_wkt_start_str = request.POST.get('select-hr-workingday-control-form-workingtime-start')
    if time_start_str == 'None' or status_wkt_start_str == 'None':
        if date_of_work == ls_today:
            time_start_str = 'None'
            status_wkt_start_str = 'None'
        else:
            time_start_str = 'None'
            status_wkt_start_str = STATUS_WORKING_TIME_START[3][0]

    status_wkt_end_str = request.POST.get('select-hr-workingday-control-form-workingtime-end')
    # print('status_wkt_end_str  1', status_wkt_end_str, type(status_wkt_end_str))
    if time_end_str == 'None' or status_wkt_end_str == 'None':
        if date_of_work == ls_today:
            time_end_str = 'None'
            status_wkt_end_str = 'None'
        else:
            time_end_str = 'None'
            status_wkt_end_str = STATUS_WORKING_TIME_END[3][0]
    # print('datetime_end_str', datetime_end_str, type(datetime_end_str))
    # print('status_wkt_end_str  2', status_wkt_end_str, type(status_wkt_end_str))
    #--------------------------------------------------------------------------------------------------------------------------
    # 델타 시간 계산
    if datetime_start != None and datetime_end != None:
        return_value = hr_workingtime_get_net_working_time(datetime_start, datetime_end)
        time_net_working_str = str(return_value[1])
        time_total_working_str = str(return_value[3])

    else:
        time_net_working_str = 'None'
        time_total_working_str = 'None'
    #--------------------------------------------------------------------------------------------------------------------------
    status_working_type_location_str = request.POST.get('select-hr-workingday-control-form-workingtime-location')
    #--------------------------------------------------------------------------------------------------------------------------
    draft_data = {
        'date_of_work': date_of_work_str,
        'datetime_start': datetime_start_str,
        'datetime_end': datetime_end_str,
        'time_start': time_start_str,
        'time_end': time_end_str,
        'status_wkt_start': status_wkt_start_str,
        'status_wkt_end': status_wkt_end_str,
        'time_net_working': time_net_working_str,
        'time_total_working': time_total_working_str,
        'status_working_type_location': status_working_type_location_str,
    }
    # print('draft_data', draft_data)
    data = {
        'status_workingtime_issued_requested_to_hr': STATUS_MY_WORKINGTIME_ISSUED_REQUEST_TO_HR[2][0],  # ('MODIFIED', '인사팀이 정정 내용 기입 완료, 내용확인'), # 2
        'dict_modified_draft_for_workingtime_issued_from_hr': draft_data,
    }
    Workingtime_Issued.objects.filter(id=q_workingtime_issued.id).update(**data)
    messages.success(request, f'선택한 출퇴근 수정내용을 임시 저장하였습니다. 수정내용에 대하여 문제 없을 경우 Confirm하여 수정요청자에게 전달하세요.')
    # HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True


#--------------------------------------------------------------------------------------------------------------------------
# 발행한 출퇴근 수정안 요청자에게 보내기
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_control_response_modification_draft_to_requestor(request, q_mysettings_hr):
    q_wkt_id_str = request.POST.get('button-hr-workingtime-control-response-modification-draft-to-requestor')
    if q_wkt_id_str is None or q_wkt_id_str == '':
        return False
    q_wkt_id = int(q_wkt_id_str)
    q_workingtime_issued = Workingtime_Issued.objects.get(id=q_wkt_id)
    #--------------------------------------------------------------------------------------------------------------------------
    response_contents_str = '*** 인사팀이 요청내용에 대하여 수정하였습니다. ***'
    dict_request_for_my_issued_wkt_trouble = q_workingtime_issued.dict_request_for_my_issued_wkt_trouble
    if dict_request_for_my_issued_wkt_trouble is None:
        dict_request_for_my_issued_wkt_trouble = {}
    num_conversation = len(dict_request_for_my_issued_wkt_trouble)
