#--------------------------------------------------------------------------------------------------------------------------
# 발행된 출퇴근 인사팀이 수정 완료하기 - Workingtime_Issued 내용 저장
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_issued_control_close_request_trouble_view(request, q_mysettings_hr):
    q_workingtime_issued_id_str = request.POST.get('button-hr-workingtime-control-workingtime-issued-request-close')
    if q_workingtime_issued_id_str is None or q_workingtime_issued_id_str == '':
        messages.warning(request, f'선택한 멤버의 출퇴근 정보가 없습니다. 관리자에게 문의하세요.')
        return False
    q_workingtime_issued_id = int(q_workingtime_issued_id_str)
    q_workingtime_issued = Workingtime_Issued.objects.get(id=q_workingtime_issued_id)
    #--------------------------------------------------------------------------------------------------------------------------
    # Draft 내용으로 정보 업데이트
    dict_draft = q_workingtime_issued.dict_modified_draft_for_workingtime_issued_from_hr
    # print('dict_draft', dict_draft)
    list_date_of_work_str = dict_draft['date_of_work'].split('-')
    date_of_work_year = int(list_date_of_work_str[0])
    date_of_work_month = int(list_date_of_work_str[1])
    date_of_work_day = int(list_date_of_work_str[2])
    # print('list_date_of_work_str', list_date_of_work_str)
    # print('list_date_of_work_str int ', int(list_date_of_work_str[0]), type(int(list_date_of_work_str[0])))
    date_of_work = datetime.date(date_of_work_year, date_of_work_month, date_of_work_day)
    #--------------------------------------------------------------------------------------------------------------------------
    status_wkt_start_str = dict_draft['status_wkt_start']
    status_wkt_end_str = dict_draft['status_wkt_end']

    # print('dict_draft datetime_start', dict_draft['datetime_start'], type(dict_draft['datetime_start']))
    if dict_draft['datetime_start'] is not None and dict_draft['datetime_start'] != 'None':
        # print('1')
        datetime_date_str = dict_draft['datetime_start'].split(' ')[0]
        datetime_time_str = dict_draft['datetime_start'].split(' ')[1]
        datetime_start = datetime.datetime( int(datetime_date_str.split('-')[0]), int(datetime_date_str.split('-')[1]), int(datetime_date_str.split('-')[2]), int(datetime_time_str.split(':')[0]), int(datetime_time_str.split(':')[1]))
    else:
        # print('2')
        datetime_start = None
        status_wkt_start_str = None

    # print('dict_draft datetime_end', dict_draft['datetime_end'], type(dict_draft['datetime_end']) )
    if dict_draft['datetime_end'] is not None and dict_draft['datetime_end'] != 'None':
        # print('3')
        datetime_date_str = dict_draft['datetime_end'].split(' ')[0]
        datetime_time_str = dict_draft['datetime_end'].split(' ')[1]
        datetime_end = datetime.datetime( int(datetime_date_str.split('-')[0]), int(datetime_date_str.split('-')[1]), int(datetime_date_str.split('-')[2]), int(datetime_time_str.split(':')[0]), int(datetime_time_str.split(':')[1]))
    else:
        # print('4')
        datetime_end = None
        status_wkt_end_str = None

    #--------------------------------------------------------------------------------------------------------------------------
    if datetime_start is not None and datetime_end is not None:
        time_net_working_hour = int(dict_draft['time_net_working'].split(':')[0])
        time_net_working_minute = int(dict_draft['time_net_working'].split(':')[1])
        time_net_working = datetime.time(time_net_working_hour, time_net_working_minute)
        time_total_working_hour = int(dict_draft['time_total_working'].split(':')[0])
        time_total_working_minute = int(dict_draft['time_total_working'].split(':')[1])
        time_total_working = datetime.time(time_total_working_hour, time_total_working_minute)
    else:
        time_net_working = None
        time_total_working = None
    #--------------------------------------------------------------------------------------------------------------------------
    status_working_type_location_str = dict_draft['status_working_type_location']
    #--------------------------------------------------------------------------------------------------------------------------
    data = {
        'date_of_work': date_of_work,
        'datetime_start': datetime_start,
        'datetime_end': datetime_end,
        'status_wkt_start': status_wkt_start_str,
        'status_wkt_end': status_wkt_end_str,
        'time_net_working': time_net_working,
        'time_total_working': time_total_working,
        'status_working_type_location': status_working_type_location_str,
    }
    Workingtime_Issued.objects.filter(id=q_workingtime_issued.id).update(**data)
    q_workingtime_issued.refresh_from_db()
    #--------------------------------------------------------------------------------------------------------------------------
    response_contents_str = f'*** 출퇴근 정보 수정요청이 종료되었습니다. ***'
    dict_request_for_my_issued_wkt_trouble = q_workingtime_issued.dict_request_for_my_issued_wkt_trouble
    if dict_request_for_my_issued_wkt_trouble is None:
        dict_request_for_my_issued_wkt_trouble = {}
    num_conversation = len(dict_request_for_my_issued_wkt_trouble)
    k_member_name = f'({num_conversation + 1}){q_mysettings_hr.owner.profile.name_korean}'
    dict_request_for_my_issued_wkt_trouble[k_member_name] = response_contents_str
    #--------------------------------------------------------------------------------------------------------------------------
    data = {
        'dict_request_for_my_issued_wkt_trouble': dict_request_for_my_issued_wkt_trouble,
        'status_workingtime_issued_requested_to_hr': 'ACCEPTED', # STATUS_MY_WORKINGTIME_ISSUED_REQUEST_TO_HR[4][0], ('ACCEPTED', '정정 내용 사용자 동의 및 완료'),  # 4
        'check_hr_wkt_issued_request_to_hr_activated': False,
    }
    Workingtime_Issued.objects.filter(id=q_workingtime_issued.id).update(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    messages.success(request, f'선택한 {q_workingtime_issued.owner.profile.name_korean}님의 출퇴근 기록 Trouble에 대한 인사팀 요청 내용의 수정을 마감하였습니다.')
    #--------------------------------------------------------------------------------------------------------------------------
    # News 등록
    data = {
        'owner': q_workingtime_issued.owner,
        'workingtime_issued': q_workingtime_issued,
        'news_content': LIST_MY_SYSTEM_ALERT_CONTENTS[31][0],  # ('MY_WORKINGTIME_ISSUED_TROUBLE_SOLVED_BY_HR', '나의 출퇴근 문제 해결 완료'),  # 31
    }
    News_My_System_Alert.objects.create(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    return True


