# 발행한 퇴근 수정내용 바로저장하기 (주어진 출퇴근 정보로) Ver.2023-04-04
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_control_save_workingtime_issued_modification_by_hr_directly(request, q_mysettings_hr):
    q_workingtime_issued_id_str = request.POST.get('button-hr-workingtime-control-workingtime-issued-modify-autoupdate')
    if q_workingtime_issued_id_str is None or q_workingtime_issued_id_str == '':
        messages.warning(request, f'선택한 멤버의 출퇴근 정보가 없습니다. 관리자에게 문의하세요.')
        return False
    q_workingtime_issued_id = int(q_workingtime_issued_id_str)
    q_workingtime_issued = Workingtime_Issued.objects.get(id=q_workingtime_issued_id)
    #--------------------------------------------------------------------------------------------------------------------------
    date_of_work = q_workingtime_issued.date_of_work
    datetime_start = q_workingtime_issued.datetime_start
    datetime_end = q_workingtime_issued.datetime_end
    status_wkt_start_key = q_workingtime_issued.status_wkt_start
    status_wkt_end_key = q_workingtime_issued.status_wkt_end
    status_wkt_location_key = q_workingtime_issued.status_working_type_location
    time_net_working = q_workingtime_issued.time_net_working
    dict_modified_draft_for_workingtime_issued_by_me = q_workingtime_issued.dict_modified_draft_for_workingtime_issued_by_me

    if dict_modified_draft_for_workingtime_issued_by_me is not None:
        if 'status_wkt_start_key' in dict_modified_draft_for_workingtime_issued_by_me:
            status_wkt_start_key = dict_modified_draft_for_workingtime_issued_by_me['status_wkt_start_key']
        if 'status_wkt_end_key' in dict_modified_draft_for_workingtime_issued_by_me:
            status_wkt_end_key = dict_modified_draft_for_workingtime_issued_by_me['status_wkt_end_key']
        if 'inputTimeStart' in dict_modified_draft_for_workingtime_issued_by_me:
            inputTimeStart_str = dict_modified_draft_for_workingtime_issued_by_me['inputTimeStart']
            inputtimestart_hour = int(inputTimeStart_str.split(':')[0])
            inputtimestart_minute = int(inputTimeStart_str.split(':')[1])
            datetime_start = datetime.datetime(date_of_work.year, date_of_work.month, date_of_work.day, inputtimestart_hour, inputtimestart_minute)
        if 'inputTimeEnd' in dict_modified_draft_for_workingtime_issued_by_me:
            inputTimeEnd_str = dict_modified_draft_for_workingtime_issued_by_me['inputTimeEnd']
            inputtimeend_hour = int(inputTimeEnd_str.split(':')[0])
            inputtimeend_minute = int(inputTimeEnd_str.split(':')[1])
            datetime_end = datetime.datetime(date_of_work.year, date_of_work.month, date_of_work.day, inputtimeend_hour, inputtimeend_minute)
        if 'status_wkt_location_key' in dict_modified_draft_for_workingtime_issued_by_me:
            status_wkt_location_key = dict_modified_draft_for_workingtime_issued_by_me['status_wkt_location_key']
    if datetime_start is not None and datetime_end is not None:
        return_value = hr_workingtime_get_net_working_time(datetime_start, datetime_end)
        time_net_working = return_value[1]
        time_total_working = return_value[3]
    else:
        time_net_working = None
        time_total_working = None
    data = {
        'datetime_start': datetime_start,
        'datetime_end': datetime_end,
        'status_wkt_start': status_wkt_start_key,
        'status_wkt_end': status_wkt_end_key,
        'time_net_working': time_net_working,
        'time_total_working': time_total_working,
        'status_working_type_location': status_wkt_location_key,
    }
    Workingtime_Issued.objects.filter(id=q_workingtime_issued.id).update(**data)
    q_workingtime_issued.refresh_from_db()
    #--------------------------------------------------------------------------------------------------------------------------
    response_contents_str = f'*** 출퇴근 정보 수정요청이 종료되었습니다. ***'
    dict_request_for_my_issued_wkt_trouble = q_workingtime_issued.dict_request_for_my_issued_wkt_trouble
    if dict_request_for_my_issued_wkt_trouble is None:
        dict_request_for_my_issued_wkt_trouble = {}
    num_conversation = len(dict_request_for_my_issued_wkt_trouble)
    k_member_name = f'({num_conversation + 1}){q_mysettings_hr.owner.profile.name_korean}'
    dict_request_for_my_issued_wkt_trouble[k_member_name] = response_contents_str
    #--------------------------------------------------------------------------------------------------------------------------
    data = {
        'dict_request_for_my_issued_wkt_trouble': dict_request_for_my_issued_wkt_trouble,
        'status_workingtime_issued_requested_to_hr': 'ACCEPTED',  # STATUS_MY_WORKINGTIME_ISSUED_REQUEST_TO_HR[4][0], ('ACCEPTED', '정정 내용 사용자 동의 및 완료'),  # 4
        'check_hr_wkt_issued_request_to_hr_activated': False,
    }
    Workingtime_Issued.objects.filter(id=q_workingtime_issued.id).update(**data)
    q_workingtime_issued.refresh_from_db()
    #--------------------------------------------------------------------------------------------------------------------------
    messages.success(request, f'선택한 {q_workingtime_issued.owner.profile.name_korean}님의 출퇴근 기록 Trouble에 대한 인사팀 요청 내용의 수정을 마감하였습니다.')
    #--------------------------------------------------------------------------------------------------------------------------
    # News 등록
    data = {
        'owner': q_workingtime_issued.owner,
        'workingtime_issued': q_workingtime_issued,
        'news_content': 'MY_WORKINGTIME_ISSUED_TROUBLE_SOLVED_BY_HR',  # LIST_MY_SYSTEM_ALERT_CONTENTS[31][0],  # ('MY_WORKINGTIME_ISSUED_TROUBLE_SOLVED_BY_HR', '나의 출퇴근 문제 해결 완료'),  # 31
    }
    News_My_System_Alert.objects.create(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    return True






