#--------------------------------------------------------------------------------------------------------------------------
# Workingtime 쿼리 multi 삭제하기 창 활성화
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_control_workingtime_delete_selected_workingtime_view(request, q_mysettings_hr):
    list_q_wkt_id_str = request.POST.getlist('checkbox-hr-workingtime-select-member')
    if list_q_wkt_id_str is None or len(list_q_wkt_id_str) == 0:
        messages.warning(request, f'멤버가 선택되지 않았습니다.')
        return False
    if 'all' in list_q_wkt_id_str:
        date_selected_workingtime = q_mysettings_hr.date_selected_workingtime
        if date_selected_workingtime is None:
            ls_today = datetime.date.today()
            date_selected_workingtime = ls_today
        qs_wkt_selected_day = Workingtime_Issued.objects.filter(Q(check_discard=False) & Q(date_of_work=date_selected_workingtime))
        if qs_wkt_selected_day is not None and len(qs_wkt_selected_day) > 0:
            list_q_wkt_id = []
            for q_wkt_selected_day in qs_wkt_selected_day:
                if q_wkt_selected_day.id not in list_q_wkt_id:
                    list_q_wkt_id.append(q_wkt_selected_day.id)
    else:
        list_q_wkt_id = list(map(int, list_q_wkt_id_str))
    check_activate_task_plan_delete_view = q_mysettings_hr.check_activate_task_plan_delete_view
    if check_activate_task_plan_delete_view == True:
        check_activate_task_plan_delete_view = False
    else:
        check_activate_task_plan_delete_view = True
    data = {
        'list_workingtime_issued_id_selected': list_q_wkt_id,
        'check_activate_task_plan_delete_view': check_activate_task_plan_delete_view,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True


#--------------------------------------------------------------------------------------------------------------------------
# Workingtime 쿼리 multi 삭제하기 확정하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_control_workingtime_delete_selected_workingtime_confirm(request, q_mysettings_hr):
    list_workingtime_issued_id_selected = q_mysettings_hr.list_workingtime_issued_id_selected
    qs_wkt_delete = Workingtime_Issued.objects.filter(id__in=list_workingtime_issued_id_selected)
    if qs_wkt_delete is not None and len(qs_wkt_delete) > 0:
        messages.success(request, f'{len(list_workingtime_issued_id_selected)}명의 출퇴근 쿼리를 삭제하였습니다.')
        for q_wkt_delete in qs_wkt_delete:
            data = {
                'check_discard': True,
            }
            Workingtime_Issued.objects.filter(id=q_wkt_delete.id).update(**data)
        # 삭제하기 창 원상복귀
        hr_workingtime_control_workingtime_delete_selected_workingtime_cancel(request, q_mysettings_hr)
    return True


#--------------------------------------------------------------------------------------------------------------------------
# Workingtime 쿼리 multi 삭제하기 취소하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_control_workingtime_delete_selected_workingtime_cancel(request, q_mysettings_hr):
    data = {
        'list_workingtime_issued_id_selected': None,
        'check_activate_task_plan_delete_view': False,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True


#--------------------------------------------------------------------------------------------------------------------------
# Workingtime Delete by multi-selection
#--------------------------------------------------------------------------------------------------------------------------
def hr_task_control_task_plan_delete_register_modal_view_by_multi_selection(request, q_mysettings_hr):
    selected_year = q_mysettings_hr.selected_year
    selected_month = q_mysettings_hr.selected_month
    list_selected_task_plan_id_str = request.POST.getlist('checkbox-hr-task-plan-owner-select')
    if list_selected_task_plan_id_str is None or len(list_selected_task_plan_id_str) == 0:
        messages.warning(request, f'선택한 멤버 업무관리 쿼리가 없습니다.')
        return False
    elif 'all' in list_selected_task_plan_id_str:
        qs_task_plan_selected_month = Task_Plan.objects.filter(Q(check_discard=False) & Q(date_deadline_task_submission__year=selected_year) & Q(date_deadline_task_submission__month=selected_month)).order_by('owner__profile__name_korean')
        if qs_task_plan_selected_month is not None and len(qs_task_plan_selected_month) > 0:
            list_selected_task_plan_id = []
            for q_task_plan_selected_month in qs_task_plan_selected_month:
                list_selected_task_plan_id.append(q_task_plan_selected_month.id)
    else:
        list_selected_task_plan_id = list(map(int, list_selected_task_plan_id_str))

    if list_selected_task_plan_id is None or len(list_selected_task_plan_id) == 0:
        messages.warning(request, f'선택된 멤버의 업무관리 쿼리가 없습니다.')
        return False
    # 선택한 멤버 업무쿼리 프로젝트별 참여비율 입력 모달 활성화하기
    qs_task_plan_selected = Task_Plan.objects.filter(id__in=list_selected_task_plan_id)
    if qs_task_plan_selected is not None and len(qs_task_plan_selected) > 0:
        for q_task_plan_selected in qs_task_plan_selected:
            data = {
                'check_discard': True,
            }
            Task_Plan.objects.filter(id=q_task_plan_selected.id).update(**data)
        messages.success(request, f'{len(qs_task_plan_selected)}명에 대하여 {selected_year}년 {selected_month}월달 프로젝트 참여비율 입력창을 비활성화 하였습니다.')
    # 선택한 멤버 업무쿼리 리스트에 저장하기
    data = {
        'list_selected_task_plan_id': None,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True








