#--------------------------------------------------------------------------------------------------------------------------
# 발행한 근무계획서 수정요청에 대한 인사팀 Talk 등록하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_plan_control_communication_register_request_talk(request):
    q_workingtime_plan_id_str = request.POST.get('button-xxx-workingtime-plan-control-communication-register-request-talk')
    if q_workingtime_plan_id_str is None or q_workingtime_plan_id_str == '':
        messages.warning(request, f'선택한 발행된 휴가 정보가 없습니다. 관리자에게 문의하세요.')
        return False
    q_workingtime_plan_id = int(q_workingtime_plan_id_str)
    q_workingtime_plan = Workingtime_Plan.objects.get(id=q_workingtime_plan_id)
    #--------------------------------------------------------------------------------------------------------------------------
    response_contents_str = request.POST.get('text-xxx-workingtime-control-workingtime-plan-talk-contents')
    if response_contents_str is None or response_contents_str == '':
        messages.warning(request, f'응답내용을 입력하지 않았습니다.')
        return False
    #--------------------------------------------------------------------------------------------------------------------------
    dict_communication_with_hr_for_my_xxx_document_plan = q_workingtime_plan.dict_communication_with_hr_for_my_xxx_document_plan
    if dict_communication_with_hr_for_my_xxx_document_plan is None:
        dict_communication_with_hr_for_my_xxx_document_plan = {}
    num_conversation = len(dict_communication_with_hr_for_my_xxx_document_plan)
    k_member_name = f'({num_conversation + 1}){request.user.profile.name_korean}'
    dict_communication_with_hr_for_my_xxx_document_plan[k_member_name] = response_contents_str
    #--------------------------------------------------------------------------------------------------------------------------
    data = {
        'dict_communication_with_hr_for_my_xxx_document_plan': dict_communication_with_hr_for_my_xxx_document_plan,
    }
    Workingtime_Plan.objects.filter(id=q_workingtime_plan.id).update(**data)
    # messages.success(request, f'발행된 근무계획서 Trouble에 대한 내용을 등록하였습니다.')
    return True


#--------------------------------------------------------------------------------------------------------------------------
# 발행한 근무계획서 인사팀에서 마지막에 등록한 Talk 지우기
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_plan_control_communication_delete_last_talk(request):
    q_workingtime_plan_id_str = request.POST.get('button-xxx-workingtime-plan-control-communication-delete-last-talk')
    if q_workingtime_plan_id_str is None or q_workingtime_plan_id_str == '':
        messages.warning(request, f'선택한 발행된 휴가 정보가 없습니다. 관리자에게 문의하세요.')
        return False
    q_workingtime_plan_id = int(q_workingtime_plan_id_str)
    q_workingtime_plan = Workingtime_Plan.objects.get(id=q_workingtime_plan_id)
    #--------------------------------------------------------------------------------------------------------------------------
    dict_communication_with_hr_for_my_xxx_document_plan = q_workingtime_plan.dict_communication_with_hr_for_my_xxx_document_plan
    dict_communication_with_hr_for_my_xxx_document_plan.popitem()
    data = {
        'dict_communication_with_hr_for_my_xxx_document_plan': dict_communication_with_hr_for_my_xxx_document_plan,
    }
    Workingtime_Plan.objects.filter(id=q_workingtime_plan.id).update(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    # 마지막 Talk 코멘트를 삭제한 경우이면서 근무계획서 작성자이면 HR 수정 요청을 비활성화 한다.
    if len(dict_communication_with_hr_for_my_xxx_document_plan) == 0 and q_workingtime_plan.owner == request.user:
        data = {
            'status_xxx_document_plan_requested_to': STATUS_MY_WORKINGTIME_ISSUED_REQUEST_TO_HR[0][0],
            'check_hr_xxx_document_plan_request_to_hr_activated': False,
        }
        Workingtime_Plan.objects.filter(id=q_workingtime_plan.id).update(**data)
    return True




#--------------------------------------------------------------------------------------------------------------------------
# 근무계획서 Reference File Workingtime Plan에 등록하기/삭제하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_plan_reference_file_upload_or_cancel(request, q_workingtime_plan):
    # Reference File
    # form_wkt_plan_file = HR_Workingtime_Plan_Reference_File_Form(instance=q_workingtime_plan)
    reference_file = request.FILES.get('reference_file')
    reference_file_clear_str = request.POST.get('reference_file-clear')
    if reference_file_clear_str == 'on':
        data = {
            'path': None,
            'filename': None,
            'reference_file': None,
        }
        Workingtime_Plan.objects.filter(id=q_workingtime_plan.id).update(**data)
    else:
        if reference_file is not None and reference_file != '':
            try:
                path_str = f'my/workingtime/plan/reference/{request.user.id}/{q_workingtime_plan.id}'
                filename_str = str(reference_file)
                data = {
                    'path': path_str,
                    'filename': filename_str,
                }
                Workingtime_Plan.objects.filter(id=q_workingtime_plan.id).update(**data)
                q_workingtime_plan.refresh_from_db()
                q_workingtime_plan.reference_file = reference_file
                q_workingtime_plan.save()
            except:
                messages.warning(request, f'첨부파일명을 영어로 작성하세요.')
                pass
        else:
            pass
    q_workingtime_plan.refresh_from_db()
    return True


