#--------------------------------------------------------------------------------------------------------------------------
# 등록된 근무계획서 수정내용 임시저장하기 (Draft 생성)
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_control_save_draft_workingtime_plan_modification_by_hr(request, q_mysettings_hr):
    ls_today = datetime.date.today()
    q_wkt_id_str = request.POST.get('button-hr-workingtime-control-workingtime-plan-modify-update')
    if q_wkt_id_str is None or q_wkt_id_str == '':
        messages.warning(request, f'선택한 멤버의 근무계획서 정보가 없습니다. 관리자에게 문의하세요.')
        return False
    q_wkt_id = int(q_wkt_id_str)
    q_workingtime_plan = Workingtime_Plan.objects.get(id=q_wkt_id)
    #--------------------------------------------------------------------------------------------------------------------------
    # 근무계획서 종류
    type_workingtime_str = request.POST.get('select-hr-workingday-control-plan-type-workingtime')
    #--------------------------------------------------------------------------------------------------------------------------
    # 시작일
    date_wkt_plan_start_str = request.POST.get('input-date-hr-workingtime-control-plan-modification-start')
    #--------------------------------------------------------------------------------------------------------------------------
    # 시작시간
    time_wkt_plan_start_str = request.POST.get('input-time-hr-workingtime-control-plan-modification-start')
    #--------------------------------------------------------------------------------------------------------------------------
    # 종료일
    date_wkt_plan_end_str = request.POST.get('input-date-hr-workingtime-control-plan-modification-end')
    #--------------------------------------------------------------------------------------------------------------------------
    # 종료시간
    time_wkt_plan_end_str = request.POST.get('input-time-hr-workingtime-control-plan-modification-end')
    #--------------------------------------------------------------------------------------------------------------------------
    print('//////////////////////////////////////////////////// time_wkt_plan_end_str', time_wkt_plan_end_str)
    datetime_start_str = f'{date_wkt_plan_start_str} {time_wkt_plan_start_str}'
    datetime_end_str = f'{date_wkt_plan_end_str} {time_wkt_plan_end_str}'
    #--------------------------------------------------------------------------------------------------------------------------
    # 출장종류
    type_workingtime_field_str = request.POST.get('select-hr-workingday-control-plan-type-type_workingtime-field')
    #--------------------------------------------------------------------------------------------------------------------------
    # 출장지
    destination_str = request.POST.get('input-text-hr-workingtime-control-plan-modification-destination')
    #--------------------------------------------------------------------------------------------------------------------------
    # 이유
    reason_str = request.POST.get('input-text-hr-workingtime-control-plan-modification-reason')
    #--------------------------------------------------------------------------------------------------------------------------

    #--------------------------------------------------------------------------------------------------------------------------
    draft_data = {
        'type_workingtime': type_workingtime_str,
        'type_workingtime_field': type_workingtime_field_str,
        'datetime_start': datetime_start_str,
        'date_wkt_plan_start': date_wkt_plan_start_str,
        'time_wkt_plan_start': time_wkt_plan_start_str,
        'datetime_end': datetime_end_str,
        'date_wkt_plan_end': date_wkt_plan_end_str,
        'time_wkt_plan_end': time_wkt_plan_end_str,
        'type_workingtime_field': type_workingtime_field_str,
        'destination': destination_str,
        'reason': reason_str,
    }
    data = {
        'status_xxx_document_plan_requested_to': 'MODIFIED_BY_HR',  # ('MODIFIED_BY_HR', '문서 담당팀이 정정/취소 요청내용 적용 완료'), # 3
        'dict_modified_draft_for_xxx_document_plan_from_hr': draft_data,
    }
    Workingtime_Plan.objects.filter(id=q_workingtime_plan.id).update(**data)
    messages.success(request, f'선택한 근무계획서 수정내용을 임시 저장하였습니다.')
    return True



#--------------------------------------------------------------------------------------------------------------------------
# 등록된 근무계획서 인사팀이 수정 완료하기 - Workingtime_Plan 내용 저장
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_plan_control_close_request_trouble_view(request, q_mysettings_hr):
    q_workingtime_plan_id_str = request.POST.get('button-hr-workingtime-plan-control-modification-confirm-case-close')
    if q_workingtime_plan_id_str is None or q_workingtime_plan_id_str == '':
        messages.warning(request, f'선택한 멤버의 근무계획서 정보가 없습니다. 관리자에게 문의하세요.')
        return False
    q_workingtime_plan_id = int(q_workingtime_plan_id_str)
    q_workingtime_plan = Workingtime_Plan.objects.get(id=q_workingtime_plan_id)
    #--------------------------------------------------------------------------------------------------------------------------
    # Draft 내용으로 정보 업데이트
    dict_draft = q_workingtime_plan.dict_modified_draft_for_xxx_document_plan_from_hr
    print('dict_draft', dict_draft)
    #--------------------------------------------------------------------------------------------------------------------------
    # 근무계획서 종류
    if dict_draft['type_workingtime'] is not None and dict_draft['type_workingtime'] != 'None':
        type_workingtime = dict_draft['type_workingtime']
    else:
        type_workingtime = q_workingtime_plan.type_workingtime
    #--------------------------------------------------------------------------------------------------------------------------
    # 시작일
    if dict_draft['date_wkt_plan_start'] is not None and dict_draft['date_wkt_plan_start'] != 'None':
        date_wkt_plan_start_str = dict_draft['date_wkt_plan_start'].split('-')
        date_year = int(date_wkt_plan_start_str[0])
        date_month = int(date_wkt_plan_start_str[1])
        date_day = int(date_wkt_plan_start_str[2])
    else:
        date_wkt_plan_start_str = None
    if dict_draft['time_wkt_plan_start'] is not None and dict_draft['time_wkt_plan_start'] != 'None':
        time_wkt_plan_start_str = dict_draft['time_wkt_plan_start'].split(':')
        time_hour = int(time_wkt_plan_start_str[0])
        time_minute = int(time_wkt_plan_start_str[1])
    else:
        time_wkt_plan_start_str = None
    if date_wkt_plan_start_str is not None and time_wkt_plan_start_str is not None:
        datetime_start = datetime.datetime(date_year, date_month, date_day, time_hour, time_minute)
    else:
        datetime_start = None
    #--------------------------------------------------------------------------------------------------------------------------
    # 종료일
    if dict_draft['date_wkt_plan_end'] is not None and dict_draft['date_wkt_plan_end'] != 'None':
        date_wkt_plan_end_str = dict_draft['date_wkt_plan_end'].split('-')
        date_year = int(date_wkt_plan_end_str[0])
        date_month = int(date_wkt_plan_end_str[1])
        date_day = int(date_wkt_plan_end_str[2])
    else:
        date_wkt_plan_end_str = None
    if dict_draft['time_wkt_plan_end'] is not None and dict_draft['time_wkt_plan_end'] != 'None':
        time_wkt_plan_end_str = dict_draft['time_wkt_plan_end'].split(':')
        time_hour = int(time_wkt_plan_end_str[0])
        time_minute = int(time_wkt_plan_end_str[1])
    else:
        time_wkt_plan_end_str = None
    if date_wkt_plan_end_str is not None and time_wkt_plan_end_str is not None:
        datetime_end = datetime.datetime(date_year, date_month, date_day, time_hour, time_minute)
    else:
        datetime_end = None
    #--------------------------------------------------------------------------------------------------------------------------
    # 출장종류
    if dict_draft['type_workingtime_field'] is not None and dict_draft['type_workingtime_field'] != 'None':
        type_workingtime_field = dict_draft['type_workingtime_field']
    else:
        type_workingtime_field = q_workingtime_plan.type_workingtime_field
    #--------------------------------------------------------------------------------------------------------------------------
    # 출장지
    if dict_draft['destination'] is not None and dict_draft['destination'] != 'None':
        destination = dict_draft['destination']
    else:
        destination = q_workingtime_plan.destination
    #--------------------------------------------------------------------------------------------------------------------------
    # 이유
    if dict_draft['reason'] is not None and dict_draft['reason'] != 'None':
        reason = dict_draft['reason']
    else:
        reason = q_workingtime_plan.reason
    #--------------------------------------------------------------------------------------------------------------------------
    # 업데이트 하기
    data = {
        'type_workingtime': type_workingtime,
        'datetime_start': datetime_start,
        'datetime_end': datetime_end,
        'type_workingtime_field': type_workingtime_field,
        'destination': destination,
        'reason': reason,
    }
    Workingtime_Plan.objects.filter(id=q_workingtime_plan.id).update(**data)
    q_workingtime_plan.refresh_from_db()
    #--------------------------------------------------------------------------------------------------------------------------
    response_contents_str = f'*** 출퇴근 정보 수정요청이 종료되었습니다. ***'
    dict_communication_with_hr_for_my_xxx_document_plan = q_workingtime_plan.dict_communication_with_hr_for_my_xxx_document_plan
    if dict_communication_with_hr_for_my_xxx_document_plan is None:
        dict_communication_with_hr_for_my_xxx_document_plan = {}
    num_conversation = len(dict_communication_with_hr_for_my_xxx_document_plan)
    k_member_name = f'({num_conversation + 1}){q_mysettings_hr.owner.profile.name_korean}'
    dict_communication_with_hr_for_my_xxx_document_plan[k_member_name] = response_contents_str
    #--------------------------------------------------------------------------------------------------------------------------
    data = {
        'dict_communication_with_hr_for_my_xxx_document_plan': dict_communication_with_hr_for_my_xxx_document_plan,
        'status_xxx_document_plan_requested_to': STATUS_MY_WORKINGTIME_ISSUED_REQUEST_TO_HR[4][0],
        'check_hr_xxx_document_plan_request_to_hr_activated': False,
    }
    Workingtime_Plan.objects.filter(id=q_workingtime_plan.id).update(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    messages.success(request, f'선택한 {q_workingtime_plan.owner.profile.name_korean}님의 근무계획서 Trouble에 대한 인사팀 내용 수정을 마감하였습니다.')
    #--------------------------------------------------------------------------------------------------------------------------
    # News 등록
    data = {
        'owner': q_workingtime_plan.owner,
        'workingtime_plan': q_workingtime_plan,
        'news_content': LIST_MY_SYSTEM_ALERT_CONTENTS[39][0],  # ('MY_WORKINGTIME_PLAN_TROUBLE_SOLVED_BY_HR', '나의 근무계획서 문제 해결 완료'),  # 39
    }
    News_My_System_Alert.objects.create(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    return True






