#--------------------------------------------------------------------------------------------------------------------------
# Workingtime Control Calendar 앞뒤 달 선택하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_get_workingtime_control_calendar_info(request, q_mysettings_hr):
    ls_today = datetime.date.today()
    date_selected_workingtime_control = q_mysettings_hr.date_selected_workingtime_control
    if date_selected_workingtime_control is None:
        selected_year = ls_today.year
        selected_month = ls_today.month
        date_selected_workingtime_control = datetime.date(selected_year, selected_month, 1)
        data = {
            'date_selected_workingtime_control': date_selected_workingtime_control
        }
        HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
        q_mysettings_hr.refresh_from_db()
    else:
        selected_year = date_selected_workingtime_control.year
        selected_month = date_selected_workingtime_control.month
    if selected_month == 12:
        selected_year_next = selected_year + 1
        selected_month_next = 1
        selected_year_prev = selected_year
        selected_month_prev = selected_month - 1
    elif selected_month == 1:
        selected_year_next = selected_year
        selected_month_next = selected_month + 1
        selected_year_prev = selected_year - 1
        selected_month_prev = 12
    else:
        selected_year_next = selected_year
        selected_month_next = selected_month + 1
        selected_year_prev = selected_year
        selected_month_prev = selected_month - 1
    date_selected_workingtime_last_month = datetime.date(selected_year_prev, selected_month_prev, 1)
    date_selected_workingtime_next_month = datetime.date(selected_year_next, selected_month_next, 1)
    #--------------------------------------------------------------------------------------------------------------------------
    return date_selected_workingtime_last_month, date_selected_workingtime_control, date_selected_workingtime_next_month



