#--------------------------------------------------------------------------------------------------------------------------
# 개인맞춤형 출퇴근 시간 설정 모달창 닫기
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_issued_personalized_member_list_modal_view_close(request, q_mysettings_hr):
    print('# 개인맞춤형 출퇴근 시간 설정 모달창 닫기')
    # 등록된 멤버의 profile id 리스트와
    q_hr_dms = HR_Document_Minor_Settings.objects.last()
    if q_hr_dms is not None:
        list_profile_id_wkt_issued_check_personalized = []
        list_dict_wkt_issued_check_personalized = q_hr_dms.list_dict_wkt_issued_check_personalized
        if list_dict_wkt_issued_check_personalized is not None and len(list_dict_wkt_issued_check_personalized) > 0:
            for dict_wkt_issued_check_personalized in list_dict_wkt_issued_check_personalized:
                list_profile_id_wkt_issued_check_personalized.append(dict_wkt_issued_check_personalized['profile_id'])
        data = {
            'list_profile_id_wkt_issued_check_personalized': list_profile_id_wkt_issued_check_personalized
        }
        HR_Document_Minor_Settings.objects.filter(id=q_hr_dms.id).update(**data)
    data = {
        'check_activate_wkt_personalized_member_list_modal_view': False,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True


#--------------------------------------------------------------------------------------------------------------------------
# 개인맞춤형 출퇴근자 선택된 멤버 리스트에서 멤버 선택
#--------------------------------------------------------------------------------------------------------------------------
def hr_workingtime_issued_personalized_member_list_selected_member_select_member(request, q_mysettings_hr):
    print('request', request.POST)
    # 모달창에서 선택한 멤버 제외자 리스트에 삭제하기
    selectedMemberEmail = request.POST.get('button-hr-workingtime-issued-today-personalized-member-select')
    print('selectedMemberEmail', selectedMemberEmail)
    q_profile = Profile.objects.filter(Q(check_discard=False) & Q(email=selectedMemberEmail)).last()
    q_user = q_profile.user
    q_workingtime_issued = Workingtime_Issued.objects.filter(Q(check_discard=False) & Q(owner=q_user)).order_by('date_of_work').last()
    data = {
        'workingtime_control_type': 'WORKINGTIME_TODAY', # Submenu 멤버 출퇴근 현황으로 라우팅
        'date_selected_workingtime': q_workingtime_issued.date_of_work,
        'workingtime_issued': q_workingtime_issued, # 선택멤버 최근 출퇴근 이슈 선택
        'check_activate_wkt_personalized_member_list_modal_view': False, #개인맞춤형 모달창 닫기
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    q_mysettings_hr.refresh_from_db()
    # # return JsonResponse('update successfully', safe=False)
    hr_workingtime_issued_personalized_member_list_modal_view_close(request, q_mysettings_hr)
    return True



