def hr_workingtime_control_function(request):
    ls_now = datetime.datetime.now()
    ls_today = datetime.date.today()
    ls_year = ls_today.year
    ls_month = ls_today.month
    day_1 = datetime.timedelta(days=1)
    ls_tomorrow = ls_today + day_1
    ls_yesterday = ls_today - day_1
    where_am_i = 'hr'
    q_authority = Authority.objects.filter(check_discard=False).last()
    q_mysettings_home = get_mysettings_home(request)
    q_mysettings_hr = get_xxx_my_settings(request, q_mysettings_home, where_am_i)
    qs_hrlayout_all = HR_Layout.objects.filter(Q(check_discard=False))
    qs_profile_all = Profile.objects.filter(Q(check_discard=False) & Q(check_resign=False))
    q_user = request.user
    q_profile = q_user.profile
    #--------------------------------------------------------------------------------------------------------------------------
    # 나의 hrlayout 리스트 업 및 Active hrlayout 하나 지정하여 home_mysettings 업데이트
    if q_mysettings_home.hrlayout is None or q_mysettings_hr.hrlayout is None:
        q_hrlayout = update_active_hrlayout_to_home_mysettings_and_list_up_my_hrlayout_to_member(request)
        data = {
            'hrlayout': q_hrlayout,
        }
        MY_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
        q_mysettings_hr.refresh_from_db()
    else:
        # Mysettings에 선택된 나의 HR Layout이 없으면 자동으로 하나 선택해주기
        q_hrlayout = q_mysettings_home.hrlayout

    # Mysettings Reset하기

    if q_mysettings_hr.date_reset != ls_today:
        data = {
            'list_member_hr_id_searched': None,
            'list_input_keyword': None,
            'list_member_id_discard': None,
            'list_member_id_searched': None,
            'list_member_id_all_part': None,
            'list_profile_id_searched': None,
            'list_resign_profile_id_searched': None,
            'check_subsearch': False,

            'page_number_auth_panel': 1,
            'selected_field_ordering': MEMBER_REGISTER_FIELD[1][0],

            'document_control_type': LIST_HR_DOCUMENT_CONTROL_TYPE[0][0],
            'list_document_issued_id_searched': None,
            'list_document_issued_id_selected': None,
            'workingtime_control_type': LIST_HR_WORKINGTIME_CONTROL_TYPE[0][0],
            'list_wkt_control_id_searched': None,
            'list_wkt_control_id_selected': None,
            'list_workingtime_issued_id_searched': None,
            'list_workingtime_issued_id_selected': None,
            'list_workingtime_issued_id_activated_modification': None,
            'list_dict_excepter_searched': None,

            'status_working_day_workingtime': None,
            'status_wkt_start_workingtime': None,
            'status_wkt_end_workingtime': None,
            'selected_field_name_for_wkt_today_sorting': None,
            'check_selected_field_name_for_wkt_analytics_sorting_descend': False,
            'selected_company_name_for_wkt': None,
            'selected_division_name_for_wkt': None,
            'selected_team_name_for_wkt': None,

            'type_workingtime': None,
            'type_workingtime_field': None,
            'selected_field_name_for_wkt_plan_sorting': LIST_WORKING_TIME_TABLE_COLUMN_INDEX_FOR_PLAN[0][0],
            'list_workingtime_plan_id_searched': None,
            'list_workingtime_plan_id_selected': None,

            'selected_field_name_for_wkt_analytics_sorting': LIST_WORKING_TIME_TABLE_COLUMN_INDEX_FOR_ANALYTICS[0][0],

            'date_reset': ls_today,
        }
        HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
        q_mysettings_hr.refresh_from_db()

    #--------------------------------------------------------------------------------------------------------------------------
    # HR Settings
    #--------------------------------------------------------------------------------------------------------------------------
    q_hr_dms = HR_Document_Minor_Settings.objects.last()
    if q_hr_dms is not None:
        # 출퇴근체크 제외자 프로필 id 리스트 확보
        list_profile_id_wkt_issued_check_excepter = q_hr_dms.list_profile_id_wkt_issued_check_excepter
    else:
        list_profile_id_wkt_issued_check_excepter = None
    # print('list_profile_id_wkt_issued_check_excepter', list_profile_id_wkt_issued_check_excepter)

    #--------------------------------------------------------------------------------------------------------------------------
    # 멤버 출퇴근 현황
    #--------------------------------------------------------------------------------------------------------------------------

