    # elif q_mysettings_hr.workingtime_control_type == LIST_HR_WORKINGTIME_CONTROL_TYPE[2][0]:
    # print('----------------------- LIST_HR_WORKINGTIME_CONTROL_TYPE[2][0]')
    ls_year
    ls_last_year = ls_year - 1
