def generateWorkingTimeExcel(request):
    status_wkt_start_dict = {
        'WKD_TIME_EARLY': '조기출근',
        'WKD_TIME_NORMAL': '정상출근',
        'WKD_TIME_LATE': '지각',
        'WKD_TIME_UNKNOWN': '출근미상',
        'WKD_TIME_EXTRA': '근무일 외 출근',  # 4
        'WKD_TIME_VACATION_AND_WORK': '반차/반반차 후 출근',  # 5
        'WKD_TIME_ON_VACATION': '휴가중',  # 6
        'WKD_TIME_OFF_SITE_AND_ON_SITE': '외근 후 출근',  # 7
        'WKD_TIME_OFF_SITE': '외부근무',  # 7
        'WKD_TIME_HOME': '자택근무'  # 8
    }

    status_wkt_end_dict = {
        'WKD_TIME_EARLY': '조기퇴근',  # 0
        'WKD_TIME_NORMAL': '정상퇴근',  # 1
        'WKD_TIME_LATE': '연장근로',  # 2
        'WKD_TIME_UNKNOWN': '퇴근미상',  # 3
        'WKD_TIME_EXTRA': '근무일 외 퇴근',  # 4
        'WKD_TIME_VACATION_AND_WORK': '반차/반반차 퇴근',  # 5
        'WKD_TIME_ON_VACATION': '휴가중',  # 6
        'WKD_TIME_OFF_SITE_AND_ON_SITE': '외근 후 퇴근',  # 7
        'WKD_TIME_OFF_SITE': '외부근무',  # 7
        'WKD_TIME_HOME': '자택근무'  # 8
    }

    q_hr_dms = HR_Document_Minor_Settings.objects.last()
    if q_hr_dms is not None:
        list_profile_id_wkt_issued_check_excepter = q_hr_dms.list_profile_id_wkt_issued_check_excepter
    else:
        list_profile_id_wkt_issued_check_excepter = []

    first_date = request.POST.get('input-hr-workingtime-control-calendar-select-date-workingtime-control') if request.GET.get('first_date') == None or request.GET.get('first_date') == '' else request.GET.get('first_date')
    second_date = request.POST.get('input-hr-workingtime-control-calendar-select-date-workingtime-control2') if request.GET.get('second_date') == None or request.GET.get('second_date') == '' else request.GET.get('second_date')

    if first_date == '' or first_date == None:
        first_date = str(datetime.datetime.today().strftime('%Y-%m-%d'))
    if second_date == '' or second_date == None:
        second_date = str(datetime.datetime.today().strftime('%Y-%m-%d'))

    if first_date > second_date:
        first_date = str(datetime.datetime.today().strftime('%Y-%m-%d'))
        second_date = str(datetime.datetime.today().strftime('%Y-%m-%d'))

    start_date = datetime.datetime.strptime(first_date, '%Y-%m-%d')
    end_date = datetime.datetime.strptime(second_date, '%Y-%m-%d')

    dateQueryStr1 = ''
    dateQeuryStr2 = ''
    index = 0
    for single_date in range((end_date - start_date).days + 1):
        current_date = (start_date + datetime.timedelta(days=single_date)).strftime('%Y-%m-%d')
        dateQueryStr1 += f""" 'border' as border, '{current_date}' as date_of_work, date{index}.datetime_start, date{index}.status_wkt_start, date{index}.datetime_end, date{index}.status_wkt_end, date{index}.working_hours{'' if str(current_date) == second_date else ','} """
        dateQeuryStr2 += f"""
            LEFT JOIN (
                SELECT wk.owner_id, to_char(datetime_start, 'HH24:MI') as datetime_start, status_wkt_start, to_char(datetime_end, 'HH24:MI') as datetime_end, status_wkt_end,
                    to_char((EXTRACT(EPOCH FROM (datetime_end - datetime_start)) * interval '1 second'), 'HH24시간 MI분') as working_hours
                FROM hr_workingtime_issued wk
                WHERE date_of_work = '{str(current_date)}'
            ) date{index} ON date{index}.owner_id=mem.user_id
        """
        index += 1
    dateQeuryStr2 += " ORDER BY member_name "
    cur = connection.cursor()

    cur.execute(f"""
        SELECT mem.member_name, mem.division, mem.team_name, {dateQueryStr1}
        FROM (
            SELECT mem.user_id, member_name, vw.division, vw.team_name FROM member_member mem
            LEFT JOIN vw_member_info vw ON vw.owner_id=mem.user_id
            LEFT JOIN member_profile profile ON mem.user_id=profile.user_id
            WHERE mem.check_discard=false AND mem.member_name IS NOT NULL AND profile.check_discard=false AND profile.id NOT IN ({str(list_profile_id_wkt_issued_check_excepter).replace('[','').replace(']','')})
        ) mem
        {dateQeuryStr2}
    """)

    rowsByPersons = cur.fetchall()

    columns = []
    columns2 = ['', '', '']
    rows = [columns2]
    for person in rowsByPersons:
        member_name = person[0]
        division = person[1]
        team_name = person[2]
        row = [member_name, division, team_name]
        for i, elem in enumerate(person):
            if person[i] == 'border':
                date_of_work = str(person[i + 1])
                datetime_start = person[i + 2]
                status_wkt_start = None if person[i + 3] == None or person[i + 3] == 'None' else status_wkt_start_dict[person[i + 3]]
                datetime_end = person[i + 4]
                status_wkt_end = None if person[i + 5] == None or person[i + 5] == 'None' else status_wkt_end_dict[person[i + 5]]
                working_hours = person[i + 6]

                if not date_of_work in columns:
                    columns.append(date_of_work)
                    columns.append(date_of_work)
                    columns.append(date_of_work)
                    columns.append(date_of_work)
                    columns.append(date_of_work)

                    rows[0].append('출근시간')
                    rows[0].append('출근상태')
                    rows[0].append('퇴근시간')
                    rows[0].append('퇴근상태')
                    rows[0].append('근무시간')

                row.append('' if datetime_start == None else str(datetime_start))
                row.append('' if status_wkt_start == None else str(status_wkt_start))
                row.append('' if datetime_end == None else str(datetime_end))
                row.append('' if status_wkt_end == None else str(status_wkt_end))
                row.append('' if working_hours == None else str(working_hours))

        rows.append(row)
    columns.sort()
    columns.insert(0, '팀')
    columns.insert(0, '소속')
    columns.insert(0, '이름')

    def get_excel_column_name(n):
        string = ""
        while n > 0:
            n, remainder = divmod(n - 1, 26)
            string = chr(65 + remainder) + string
        return string

    df = pd.DataFrame(rows, columns=columns)

    #--------------------------------------------------------------------------------------------------------------------------
    # Web Download File
    with BytesIO() as b:
        # Use the StringIO object as the filehandle.
        writer = pd.ExcelWriter(b, engine='xlsxwriter')  # pip install xlsxwriter

        workbook = writer.book
        merge_format = workbook.add_format({
            'border': 1,
            'align': 'center',
            'valign': 'vcenter'
        })
        worksheet = workbook.add_worksheet('Sheet1')
        writer.sheets['Sheet1'] = worksheet

        columns.append('')
        prevColumn = ''
        activated = False
        firstColumnToMerge = ''
        secondColumnToMerge = ''
        for i, column in enumerate(columns):
            if activated == False and prevColumn == column:
                activated = True
                firstColumnToMerge = get_excel_column_name(i)

            if activated == True and prevColumn != column:
                activated = False
                secondColumnToMerge = get_excel_column_name(i)

                worksheet.conditional_format(firstColumnToMerge + "3:" + firstColumnToMerge + str(len(rows)), {'type': 'formula', 'criteria': 'True', 'format': workbook.add_format({'left': 1})})
                worksheet.conditional_format(secondColumnToMerge + "3:" + secondColumnToMerge + str(len(rows)), {'type': 'formula', 'criteria': 'True', 'format': workbook.add_format({'right': 1})})

                worksheet.merge_range(firstColumnToMerge + "1:" + secondColumnToMerge + "1", "Merged Range", merge_format)
            prevColumn = column
        columns.pop()

        df.to_excel(writer, sheet_name='Sheet1', index=False)

        writer.save()
        # Set up the Http response.
        filename = f'hr_workingtime_control_(년 월 출퇴근현황).xlsx'
        response = HttpResponse(
            b.getvalue(),
            content_type='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
        )
        response['Content-Disposition'] = 'attachment; filename=%s' % filename
        # views.py에서 return 값을 redirect 하면 안된다. response값을 그대로 return 해야 파일이 다운로드 된다.
        return response





























