#--------------------------------------------------------------------------------------------------------------------------
def activate_request_vacation_control_promotion_plan_upload(request, q_vacation_control):
    # print('////////////////////////////////////////')
    status_vacation_control = q_vacation_control.status_vacation_control
    # print('status_vacation_control', status_vacation_control)
    if status_vacation_control in ['NORMAL', 'USED', 'EXPIRED']:
        # print('1')
        return False
    # print('q_vacation_control.promotion_plan_file', q_vacation_control.promotion_plan_file)
    if q_vacation_control.check_uploaded_promotion_plan == True:
        # print('2')
        return False
    data = {
        'check_need_to_upload_promotion_plan': True,
    }
    # print('계획서 업로드 활성화 됨', request.user.profile.name_korean)
    Vacation_Control.objects.filter(id=q_vacation_control.id).update(**data)
    return True


