#--------------------------------------------------------------------------------------------------------------------------
# 휴가 날짜 개시일 / 종료일로부터 총 사용하는 크레딧 계산하기
#
# 휴가 사용일자에 Calendar 이벤트 획득정보가 없으면(해당년도가 없으면) API로 값을 받아서 DB 업데이트 해아 함.
#--------------------------------------------------------------------------------------------------------------------------

#--------------------------------------------------------------------------------------------------------------------------
# 지정된 기간 내 공휴일/토요일/일요일 리스트로 받기 (휴가시작일 - 휴가종료일 사이에 있는)
#--------------------------------------------------------------------------------------------------------------------------
def calculate_list_holidays_between_vacation_start_date_and_end_date(vacation_type_str, date_vacation_start, date_vacation_end):
    # 휴가 시작일과 종료일을 입력받으면 법정공휴일 및 회사공휴일을 고려하여 자동으로 시작일/종료일을 재조정해주는 역할
    # 공휴일, 회사지정휴일이 휴가 시작일과 끝일 사이에 존재하는지 여부 확인
    qs_event_holiday = HR_Calendar_Event.objects.filter(Q(check_discard=False) & Q(check_holiday=True))
    list_holiday_date = []
    if vacation_type_str != LIST_VACATION_TYPES[2][0] and vacation_type_str != LIST_VACATION_TYPES[3][0]:
        # 공휴일, 회사지정휴일 모으기
        if qs_event_holiday is not None and len(qs_event_holiday) > 0:
            for q_event_holiday in qs_event_holiday:
                if date_vacation_start <= q_event_holiday.date_event <= date_vacation_end:
                        if q_event_holiday not in list_holiday_date:
                            list_holiday_date.append(q_event_holiday.date_event)
        # 주말(토,일) 모으기
        i = 0
        date_vacation_today = date_vacation_start
        while date_vacation_end > date_vacation_today:
            if i > 0:
                day_i = datetime.timedelta(days=i)
                date_vacation_today = date_vacation_start + day_i
            check_weekend = hr_check_date_weekend(date_vacation_today)
            if check_weekend == True:
                if date_vacation_today not in list_holiday_date:
                    list_holiday_date.append(date_vacation_today)
            # print('date_vacation_today', i, date_vacation_today)
            i = i + 1
    print('//////////////  list_holiday_date', list_holiday_date)
    return list_holiday_date


#--------------------------------------------------------------------------------------------------------------------------
# 공휴일에 따른 휴가 시작일/종료일 자동 재조정
#--------------------------------------------------------------------------------------------------------------------------
def auto_adjust_proper_vacation_start_date_and_end_date(vacation_type_str, date_vacation_start, date_vacation_end):
    time_delta_1day = datetime.timedelta(days=1)
    # print('입력받은 휴가개시일 :', date_vacation_start)
    # print('입력받은 휴가종료일 :', date_vacation_end)
    #--------------------------------------------------------------------------------------------------------------------------
    list_holiday_date = calculate_list_holidays_between_vacation_start_date_and_end_date(vacation_type_str, date_vacation_start, date_vacation_end)
    # print('기한 내 공휴일 및 주말 리스트  list_holiday_date', list_holiday_date )
    #--------------------------------------------------------------------------------------------------------------------------
    # 휴가개시일이 공휴일에 포함되어 있으면 개시을을 뒤로 미룸(최대 공휴일 10일 연결된 경우까지 커버)
    if date_vacation_start in list_holiday_date:
        date_vacation_start = date_vacation_start + time_delta_1day
        if date_vacation_start in list_holiday_date:
            date_vacation_start = date_vacation_start + time_delta_1day
            if date_vacation_start in list_holiday_date:
                date_vacation_start = date_vacation_start + time_delta_1day
                if date_vacation_start in list_holiday_date:
                    date_vacation_start = date_vacation_start + time_delta_1day
                    if date_vacation_start in list_holiday_date:
                        date_vacation_start = date_vacation_start + time_delta_1day
                        if date_vacation_start in list_holiday_date:
                            date_vacation_start = date_vacation_start + time_delta_1day
                            if date_vacation_start in list_holiday_date:
                                date_vacation_start = date_vacation_start + time_delta_1day
                                if date_vacation_start in list_holiday_date:
                                    date_vacation_start = date_vacation_start + time_delta_1day
                                    if date_vacation_start in list_holiday_date:
                                        date_vacation_start = date_vacation_start + time_delta_1day
                                        if date_vacation_start in list_holiday_date:
                                            date_vacation_start = date_vacation_start + time_delta_1day
    # 휴가종료일이 공휴일에 포함되어 있으면 종료일을 앞으로 당김(최대 공휴일 10일 연결된 경우까지 커버)
    if date_vacation_end in list_holiday_date:
        date_vacation_end = date_vacation_end - time_delta_1day
        if date_vacation_end in list_holiday_date:
            date_vacation_end = date_vacation_end - time_delta_1day
            if date_vacation_end in list_holiday_date:
                date_vacation_end = date_vacation_end - time_delta_1day
                if date_vacation_end in list_holiday_date:
                    date_vacation_end = date_vacation_end - time_delta_1day
                    if date_vacation_end in list_holiday_date:
                        date_vacation_end = date_vacation_end - time_delta_1day
                        if date_vacation_end in list_holiday_date:
                            date_vacation_end = date_vacation_end - time_delta_1day
                            if date_vacation_end in list_holiday_date:
                                date_vacation_end = date_vacation_end - time_delta_1day
                                if date_vacation_end in list_holiday_date:
                                    date_vacation_end = date_vacation_end - time_delta_1day
                                    if date_vacation_end in list_holiday_date:
                                        date_vacation_end = date_vacation_end - time_delta_1day
                                        if date_vacation_end in list_holiday_date:
                                            date_vacation_end = date_vacation_end - time_delta_1day
    return date_vacation_start, date_vacation_end



#--------------------------------------------------------------------------------------------------------------------------
# 공휴일에 따른 휴가 시작일 자동 재조정
#--------------------------------------------------------------------------------------------------------------------------
def auto_adjust_proper_vacation_start_date(vacation_type_str, date_vacation_start):
    time_delta_1day = datetime.timedelta(days=1)
    day_10 = datetime.timedelta(days=10)
    date_vacation_end = date_vacation_start + day_10
    #--------------------------------------------------------------------------------------------------------------------------
    list_holiday_date = calculate_list_holidays_between_vacation_start_date_and_end_date(vacation_type_str, date_vacation_start, date_vacation_end)
    # print('기한 내 공휴일 및 주말 리스트  list_holiday_date', list_holiday_date )
    #--------------------------------------------------------------------------------------------------------------------------
    # 휴가개시일이 공휴일에 포함되어 있으면 개시을을 뒤로 미룸(최대 공휴일 10일 연결된 경우까지 커버)
    if date_vacation_start in list_holiday_date:
        date_vacation_start = date_vacation_start + time_delta_1day
        if date_vacation_start in list_holiday_date:
            date_vacation_start = date_vacation_start + time_delta_1day
            if date_vacation_start in list_holiday_date:
                date_vacation_start = date_vacation_start + time_delta_1day
                if date_vacation_start in list_holiday_date:
                    date_vacation_start = date_vacation_start + time_delta_1day
                    if date_vacation_start in list_holiday_date:
                        date_vacation_start = date_vacation_start + time_delta_1day
                        if date_vacation_start in list_holiday_date:
                            date_vacation_start = date_vacation_start + time_delta_1day
                            if date_vacation_start in list_holiday_date:
                                date_vacation_start = date_vacation_start + time_delta_1day
                                if date_vacation_start in list_holiday_date:
                                    date_vacation_start = date_vacation_start + time_delta_1day
                                    if date_vacation_start in list_holiday_date:
                                        date_vacation_start = date_vacation_start + time_delta_1day
                                        if date_vacation_start in list_holiday_date:
                                            date_vacation_start = date_vacation_start + time_delta_1day
    return date_vacation_start


#--------------------------------------------------------------------------------------------------------------------------
# 공휴일에 따른 휴가 종료일 자동 재조정
#--------------------------------------------------------------------------------------------------------------------------
def auto_adjust_proper_vacation_end_date(vacation_type_str, date_vacation_end):
    time_delta_1day = datetime.timedelta(days=1)
    day_10 = datetime.timedelta(days=10)
    date_vacation_start = date_vacation_end - day_10
    #--------------------------------------------------------------------------------------------------------------------------
    list_holiday_date = calculate_list_holidays_between_vacation_start_date_and_end_date(vacation_type_str, date_vacation_start, date_vacation_end)
    # print('기한 내 공휴일 및 주말 리스트  list_holiday_date', list_holiday_date )
    #--------------------------------------------------------------------------------------------------------------------------
    # 휴가종료일이 공휴일에 포함되어 있으면 종료일을 앞으로 당김(최대 공휴일 10일 연결된 경우까지 커버)
    if date_vacation_end in list_holiday_date:
        date_vacation_end = date_vacation_end - time_delta_1day
        if date_vacation_end in list_holiday_date:
            date_vacation_end = date_vacation_end - time_delta_1day
            if date_vacation_end in list_holiday_date:
                date_vacation_end = date_vacation_end - time_delta_1day
                if date_vacation_end in list_holiday_date:
                    date_vacation_end = date_vacation_end - time_delta_1day
                    if date_vacation_end in list_holiday_date:
                        date_vacation_end = date_vacation_end - time_delta_1day
                        if date_vacation_end in list_holiday_date:
                            date_vacation_end = date_vacation_end - time_delta_1day
                            if date_vacation_end in list_holiday_date:
                                date_vacation_end = date_vacation_end - time_delta_1day
                                if date_vacation_end in list_holiday_date:
                                    date_vacation_end = date_vacation_end - time_delta_1day
                                    if date_vacation_end in list_holiday_date:
                                        date_vacation_end = date_vacation_end - time_delta_1day
                                        if date_vacation_end in list_holiday_date:
                                            date_vacation_end = date_vacation_end - time_delta_1day
    return date_vacation_end


#--------------------------------------------------------------------------------------------------------------------------
# 국공휴일에 따른 휴가개시일/휴가종료일 자동조정 및 사용될 휴가 크레딧 계산
#--------------------------------------------------------------------------------------------------------------------------
def calculate_needed_vacation_credit_using_two_date_info(vacation_type_str, date_vacation_start, date_vacation_end, credit_used_unit):
    ls_today = datetime.date.today()
    time_delta_1day = datetime.timedelta(days=1)
    #--------------------------------------------------------------------------------------------------------------------------
    return_value = auto_adjust_proper_vacation_start_date_and_end_date(vacation_type_str, date_vacation_start, date_vacation_end)
    date_vacation_start_adjusted = return_value[0]
    date_vacation_end_adjusted = return_value[1]
    # print('조정 계산된 휴가개시일 :', date_vacation_start_adjusted)
    # print('조정 계산된 휴가종료일 :', date_vacation_end_adjusted)
    list_holiday_date_adjusted = calculate_list_holidays_between_vacation_start_date_and_end_date(vacation_type_str, date_vacation_start_adjusted, date_vacation_end_adjusted)
    #--------------------------------------------------------------------------------------------------------------------------
    # 휴가 쓰는 날짜
    delta_vacation = date_vacation_end_adjusted - date_vacation_start_adjusted
    delta_vacation_day = delta_vacation.days + 1
    #--------------------------------------------------------------------------------------------------------------------------
    # 사용하는 휴가 크레딧 계산하기
    if delta_vacation_day >= 1: # 하루 이상의 휴가 사용시
        if credit_used_unit == 1:
            num_holiday_total = len(list_holiday_date_adjusted)
            num_actual_day_off = delta_vacation_day - num_holiday_total
            credit_used_total = num_actual_day_off * credit_used_unit
        else:
            credit_used_total = credit_used_unit
    else:  # 하루 미만 휴가 (반차, 반반차)
        credit_used_total = 1 * credit_used_unit
    # print('사용하려는 크레딧 합 credit_used_total', credit_used_total)
    #--------------------------------------------------------------------------------------------------------------------------
    list_vacation_date_adjusted = []
    date_i = date_vacation_start_adjusted
    while date_i <= date_vacation_end_adjusted:
        if date_i not in list_holiday_date_adjusted:
            if date_i not in list_vacation_date_adjusted:
                list_vacation_date_adjusted.append(date_i)
        date_i = date_i + time_delta_1day
    #--------------------------------------------------------------------------------------------------------------------------
    return credit_used_total, date_vacation_start_adjusted, date_vacation_end_adjusted, list_holiday_date_adjusted, list_vacation_date_adjusted








#==========================================================================================================================
# 휴가에 사용될 발행된 휴가 / Credit 지정하기 Ver. 2023-04-19
#
# 모든 타입의 휴가
# 사용할 연차 : Credit이 남아있는 모든 연차 사용
# 사용될 휴가종류, 연차사용시간 및 계획서상 사용될 Credit에 따른 발행된휴가 ID:사용될 credit 지정하기 함수
# 연차가 아닌 경우 휴가 작성시 동시에 휴가발행(선발행, 신청자가 작성한 날짜에 맞춰 갯수파악 뒤 자동발행)
#==========================================================================================================================
def calculate_dict_vacation_issued_and_used_credit(request, q_profile, credit_used_total, vacation_type_str, qs_vacation_issued):
    # 연차인 경우 qs_vacation_issued 필요없음(None 값 제공), 연차가 아닌 경우 미리 생성된 qs_vacation_issued 정보 필요
    # print('휴가에 사용될 발행된 휴가 / Credit 지정하기 함수 시작,  credit_used_total: ', credit_used_total)
    q_owner = q_profile.user
    list_used_vacation_issued_id = [] # 휴가계획에 사용할 발행된 휴가 ID 리스트
    dict_used_vacation_issued_id_credit = {} # {}  # format = {사용될 발행휴가 ID : 사용될 Credit 수}
    list_credit_collected = []
    #--------------------------------------------------------------------------------------------------------------------------
    if vacation_type_str == 'VC_REGULAR':  # 연차인 경우
        #--------------------------------------------------------------------------------------------------------------------------
        i = 1
        while i <= q_profile.status_working_year:
            q_vacation_control = Vacation_Control.objects.filter(Q(check_discard=False) & Q(owner=q_owner) & Q(status_working_year=i)).last()
            # print('년차별 확인하기', i, '년차 VC Control', q_vacation_control)
            #--------------------------------------------------------------------------------------------------------------------------
            # 현재년차 사용가능 발행휴가 찾기
            qs_vacation_issued = Vacation_Issued.objects.filter(Q(check_discard=False) & Q(vacation_control=q_vacation_control) & Q(credit__gt=0) & Q(vacation_type=vacation_type_str)).order_by('date_created')
            # print('현재 선택한', i, '년차에서 사용가능한 발행휴가 ', qs_vacation_issued)
            if qs_vacation_issued is not None and len(qs_vacation_issued) > 0:
                for q_vacation_issued in qs_vacation_issued:
                    list_used_vacation_issued_id.append(q_vacation_issued.id)
                    list_credit_collected.append(q_vacation_issued.credit)

                    # print('이번 발행 휴가에서 수집한 Credit', q_vacation_issued.credit,  '총 수집한 Credit', sum(list_credit_collected), '수집한 발행휴가ID', q_vacation_issued.id)
                    if sum(list_credit_collected) >= credit_used_total:
                        over_credit = sum(list_credit_collected) - credit_used_total
                        dict_used_vacation_issued_id_credit[q_vacation_issued.id] = q_vacation_issued.credit - over_credit
                        break
                    else:
                        dict_used_vacation_issued_id_credit[q_vacation_issued.id] = q_vacation_issued.credit
                        pass
            if sum(list_credit_collected) >= credit_used_total:
                break
            i = i + 1
        # print('sum(list_credit_collected)', sum(list_credit_collected))
        if sum(list_credit_collected) >= credit_used_total:
            # 발행휴가(Vacation Issued) 쿼리 상태 업데이트
            for k_vacation_issued_id, v_used_credit in dict_used_vacation_issued_id_credit.items():
                data = {
                    'credit_scheduled_to_use': v_used_credit,
                    'status': 'UNDERAPPROVAL',
                }
                Vacation_Issued.objects.filter(id=k_vacation_issued_id).update(**data)
            return list_used_vacation_issued_id, dict_used_vacation_issued_id_credit
        else:
            return False
    #--------------------------------------------------------------------------------------------------------------------------
    else:  # 연차가 아닌경우
        #--------------------------------------------------------------------------------------------------------------------------
        if qs_vacation_issued is not None and len(qs_vacation_issued) > 0:
            for q_vacation_issued in qs_vacation_issued:
                list_used_vacation_issued_id.append(q_vacation_issued.id)
                list_credit_collected.append(q_vacation_issued.credit)
                # print('이번 발행 휴가에서 수집한 Credit', q_vacation_issued.credit,  '총 수집한 Credit', sum(list_credit_collected), '수집한 발행휴가ID', q_vacation_issued.id)
                if sum(list_credit_collected) >= credit_used_total:
                    over_credit = sum(list_credit_collected) - credit_used_total
                    dict_used_vacation_issued_id_credit[q_vacation_issued.id] = q_vacation_issued.credit - over_credit
                    break
                else:
                    dict_used_vacation_issued_id_credit[q_vacation_issued.id] = q_vacation_issued.credit
                    pass
            return list_used_vacation_issued_id, dict_used_vacation_issued_id_credit
        else:
            return False



