#--------------------------------------------------------------------------------------------------------------------------
# 휴가관리 멤버 검색하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_vacation_control_search_vacation_control_member(request, q_mysettings_hr):
    year_vc_issued_selected = q_mysettings_hr.year_vc_issued_selected
    keyword_str = request.POST.get('text-hr-vacation-control-member-search-keyword')
    print('keyword_str', keyword_str)
    if keyword_str is None or keyword_str == '':
        data = {
            'list_vacation_control_id_searched': None,
        }
        HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
        messages.warning(request, f'검색을 리셋하였습니다.')
        return True
    qs_profile = Profile.objects.filter(Q(check_discard=False) & Q(check_resign=False) & Q(name_korean__icontains=keyword_str)).order_by('name_korean')
    print('qs_profile', qs_profile)
    if qs_profile is None or len(qs_profile) == 0:
        data = {
            'list_vacation_control_id_searched': None,
        }
        HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
        messages.warning(request, f'검색어와 일치하는 멤버가 없습니다.')
    else:
        list_vacation_control_id_searched = []
        for q_profile in qs_profile:
            q_vacation_control = Vacation_Control.objects.filter(Q(check_discard=False) & Q(owner=q_profile.user) & Q(check_last=True)).last()
            if q_vacation_control is not None:
                if q_vacation_control.id not in list_vacation_control_id_searched:
                    list_vacation_control_id_searched.append(q_vacation_control.id)
        data = {
            'list_vacation_control_id_searched': list_vacation_control_id_searched,
        }
        HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
        messages.success(request, f'{len(list_vacation_control_id_searched)}명이 검색어와 일치합니다.')
    return True


#--------------------------------------------------------------------------------------------------------------------------
# 휴가관리 멤버 Checkbox로 선택하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_vacation_control_select_member_vacation_control(request, q_mysettings_hr):
    list_vacation_control_id_str = request.POST.getlist('checkbox-hr-vacation-control-select-vacation-control')
    if list_vacation_control_id_str is None or list_vacation_control_id_str == '' or len(list_vacation_control_id_str) == 0:
        data = {
            'list_vacation_control_id_selected': None,
            'vacation_control': None,
        }
        messages.warning(request, f'선택된 멤버가 없습니다.')
    else:
        if 'all' in list_vacation_control_id_str:
            list_vacation_control_id = []
            qs_vacation_control = Vacation_Control.objects.filter(Q(check_discard=False) & Q(check_last=True)).order_by('owner__profile__name_korean')
            if qs_vacation_control is not None and len(qs_vacation_control) > 0:
                for q_vacation_control in qs_vacation_control:
                    if q_vacation_control.id not in list_vacation_control_id:
                        list_vacation_control_id.append(q_vacation_control.id)
                list_vacation_control_id.append('all')
                data = {
                    'list_vacation_control_id_selected': list_vacation_control_id,
                }
                messages.success(request, f'{len(list_vacation_control_id)}명이 선택되었습니다.')
            else:
                data = {
                    'list_vacation_control_id_selected': None,
                }
                messages.warning(request, f'선택된 멤버가 없습니다.')
        else:
            list_vacation_control_id = list(map(int, list_vacation_control_id_str))
            data = {
                'list_vacation_control_id_selected': list_vacation_control_id,
            }
            messages.success(request, f'{len(list_vacation_control_id)}명이 선택되었습니다.')
            if q_mysettings_hr.vacation_control is not None and q_mysettings_hr.vacation_control.id not in list_vacation_control_id:
                data['vacation_control'] = None
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True


#--------------------------------------------------------------------------------------------------------------------------
# 휴가관리 선택멤버 리셋하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_vacation_control_select_member_vacation_control_reset(request, q_mysettings_hr):
    qs_vacation_control_all = Vacation_Control.objects.filter(Q(check_discard=False))
    if qs_vacation_control_all is not None and len(qs_vacation_control_all) > 0:
        for q_vacation_control_all in qs_vacation_control_all:
            if q_vacation_control_all.owner.profile.status_working_year == q_vacation_control_all.status_working_year:
                data = {
                    'check_selected': True,
                }
            else:
                data = {
                    'check_selected': False,
                }
            Vacation_Control.objects.filter(id=q_vacation_control_all.id).update(**data)
    data = {
        'list_vacation_control_id_selected': None,
        'list_vacation_control_id_searched': None,
        'vacation_control': None,
    }
    messages.success(request, f'선택/검색 멤버를 리셋하였습니다.')
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True


#--------------------------------------------------------------------------------------------------------------------------
# 휴가관리 선택멤버 Refresh 하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_vacation_control_select_member_vacation_control_refresh(request, q_mysettings_hr):
    # 프로필 근무년수 관련 종합 업데이트 하기
    from member.functions import update_member_working_year_and_working_month
    qs_profile = Profile.objects.filter(Q(check_discard=False) & Q(check_resign=False))
    if qs_profile is not None and len(qs_profile) > 0:
        for q_profile in qs_profile:
            q_profile = update_member_working_year_and_working_month(q_profile)
            q_owner = q_profile.user
            status_working_year = q_profile.status_working_year
            create_new_vacation_control_query(q_profile, status_working_year)
    return True

#--------------------------------------------------------------------------------------------------------------------------
# 멤버 이름으로 (VC Control) 선택하기: 디테일 휴가관리창 활성화
#--------------------------------------------------------------------------------------------------------------------------
def hr_vacation_control_activate_detail_vacation_control_view(request, q_mysettings_hr):
    q_vacation_control_id_str = request.POST.get('button-hr-vacation-control-select-vacation-control')
    if q_vacation_control_id_str is None or q_vacation_control_id_str == '':
        messages.warning(request, f'선택한 멤버의 휴가관리 정보가 없습니다. 관리자에게 문의하세요.')
        return False
    q_vacation_control_id = int(q_vacation_control_id_str)
    # 선택된 멤버의 Vacation Control ID를 선택된 VC 리스트에 추가/제거하기
    list_vacation_control_id_selected = q_mysettings_hr.list_vacation_control_id_selected
    if list_vacation_control_id_selected is None:
        list_vacation_control_id_selected = []
    if q_vacation_control_id in list_vacation_control_id_selected:
        # ID가 리스트에 포함되어 있는 경우
        if q_mysettings_hr.vacation_control is not None and q_mysettings_hr.vacation_control.id == q_vacation_control_id:
            # 선택된 Vacation Control과 이번에 선택한 Vacation Control이 같은 경우
            list_vacation_control_id_selected.remove(q_vacation_control_id)
        else:
            # 선택된 Vacation Control과 이번에 선택한 Vacation Control이 다른 경우
            # list_vacation_control_id_selected.append(q_vacation_control_id)
            pass
    else:
        # ID가 리스트에 포함 안된 경우
        list_vacation_control_id_selected.append(q_vacation_control_id)
    # Vacation Control 쿼리 찾기
    q_vacation_control = Vacation_Control.objects.get(id=q_vacation_control_id)
    if q_vacation_control == q_mysettings_hr.vacation_control and q_mysettings_hr.check_activate_detail_vacation_control_view == True:
        data = {
            'vacation_control': None,
            'check_activate_detail_vacation_control_view': False,
            'list_vacation_control_id_selected': list_vacation_control_id_selected,
        }
        HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
        messages.warning(request, f'선택한 {q_vacation_control.owner.profile.name_korean}님의 디테일 휴가관리창을 비활성화 하였습니다.')
        return True
    data = {
        'vacation_control': q_vacation_control,
        'check_activate_detail_vacation_control_view': True,
        'list_vacation_control_id_selected': list_vacation_control_id_selected,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    messages.success(request, f'선택한 {q_vacation_control.owner.profile.name_korean}님의 디테일 휴가관리창이 활성화 되었습니다.')
    return True






