#--------------------------------------------------------------------------------------------------------------------------
# 선택년차의 근무시작일 및 근무종료일 찾기
#--------------------------------------------------------------------------------------------------------------------------
def find_date_workingyear_start_and_date_workingyear_end(date_joined, status_working_year):
    # 선택년차의 근무시작일 찾기
    year_joined = date_joined.year
    month_joined = date_joined.month
    day_joined = date_joined.day

    i = status_working_year - 1  # 만 근무년차 (1년차(근무한지 365일 안된 경우) == 0)
    j = i + 1
    # 선택근무년차 근무시작하는 날 찾기
    day_issued_this_time = day_joined
    # 선택근무년차 근무시작하는 달 찾기
    month_issued_this_time = month_joined
    # 선택근무년차 근무시작하는 년 찾기
    year_issued_this_time = year_joined + i
    # 발행하는 Date 생성
    date_workingyear_start = datetime.date(year_issued_this_time, month_issued_this_time, day_issued_this_time)
    # print('date_workingyear_start', date_workingyear_start)
    #--------------------------------------------------------------------------------------------------------------------------
    # 선택년차의 근무종료일 찾기
    time_delta_1day = datetime.timedelta(days=1)
    # 입사일 -1일
    date_joined_a_day_ago = date_joined - time_delta_1day
    # 입사일 -1일한 날짜에서 일/월/년 확보
    day_expired_this_time = date_joined_a_day_ago.day
    month_expired_this_time = date_joined_a_day_ago.month
    if month_expired_this_time == 1 and day_expired_this_time == 1:   # 1월 2일 입사자 (1월 1일은 공휴일), 종료일은 12월 31일이 된다.
        year_expired_this_time = year_joined + j - 1
        month_expired_this_time = 12
        day_expired_this_time = 31
    else:
        year_expired_this_time = year_joined + j
    date_workingyear_end = datetime.date(year_expired_this_time, month_expired_this_time, day_expired_this_time)
    return date_workingyear_start, date_workingyear_end


#--------------------------------------------------------------------------------------------------------------------------
# 선택한 멤버 근무년수에 대한 휴가 컨트롤 쿼리 생성/업데이트  Ver. 2022-11-22
#
# 사용자 근무년수/달수/입사일기준 만 근무년수/만 근무달수 획득함수는 Memebers app에 있음
# def calculate_status_working_year_ver_1(request)
    # status_working_month_first_year : 첫 해의 근무달수, 첫해가 넘어가면 11
    # status_working_year : 근무년수 (1년(365일) 못채웠으면 1년차, 1년이 지나면 2년차)
    # delta_year_joined : 입사일 기준 만 근무 년수
    # delta_month_joined : 입사일 기준 만 근무 달수
#
#--------------------------------------------------------------------------------------------------------------------------
def create_new_vacation_control_query(q_profile, status_working_year):
    q_user = q_profile.user
    # 프로필 근무년수 관련 종합 업데이트 하기
    from member.functions import update_member_working_year_and_working_month
    q_profile = update_member_working_year_and_working_month(q_profile)
    ls_now = datetime.datetime.now()
    ls_today = datetime.date.today()
    ls_year = ls_today.year
    ls_month = ls_today.month
    ls_day = ls_today.day
    #--------------------------------------------------------------------------------------------------------------------------
    if q_profile is None:
        print('프로필 정보 정보 누락')
        return False
    else:
        date_joined = q_profile.date_joined
    #--------------------------------------------------------------------------------------------------------------------------
    # 프로필 관련 계산작업 하기
    # Status working month first year 구하기
    if q_profile.status_working_year > 1: # 2년차 이상이면 이미 1년차의 근무년월은 만 11개월 모두 채웠다.
        # 프로필상 현재 2년차 이상인 경우
        status_working_month_first_year = 11
    else:
        # 프로필상 현재 1년차인 경우
        status_working_month_first_year = q_profile.status_working_month_first_year
    #--------------------------------------------------------------------------------------------------------------------------
    # 선택년차의 근무시작일 및 근무종료일 찾기
    if date_joined is not None:
        return_value = find_date_workingyear_start_and_date_workingyear_end(date_joined, status_working_year)
        date_workingyear_start = return_value[0]
        date_workingyear_end = return_value[1]
    else:
        print('프로필 입사일 정보 누락')
        return False
    # print('date_workingyear_end', date_workingyear_end)
    #--------------------------------------------------------------------------------------------------------------------------
    # 휴가컨트롤 상태 정의
    if date_workingyear_end < ls_today:
        status_vacation_control = STATUS_MY_VACATION_CONTROL[2][0]  # ('EXPIRED', '해당년차 기한 만료'),  # 2
    else:
        status_vacation_control = STATUS_MY_VACATION_CONTROL[0][0]  # ('NORMAL', '정상 상태'), # 0
    #--------------------------------------------------------------------------------------------------------------------------
    q_vacation_control_selected = Vacation_Control.objects.filter(Q(check_discard=False) & Q(owner=q_user) & Q(status_working_year=status_working_year)).last()
    # print('q_vacation_control_selected', q_vacation_control_selected)
    # 프로필에는 현재 근무년차의 근무시작일/종료일만 있다.
    # 과거의 휴가컨트롤 쿼리를 생성할 경우 과거 근무년차에 해당하는 근무시작일/종료일을 계산해야 한다.
    #--------------------------------------------------------------------------------------------------------------------------
    if q_vacation_control_selected is None:
        print('# 휴가 컨트롤 쿼리가 없는 경우, 신규생성')
        if date_workingyear_start <= ls_today: #  근무시작일이 오늘 / 오늘보다 과거인 경우
            print('status_working_year 년차 카운트', status_working_year, '년차 생성 시작')
            data = {
                'owner': q_user,
                'status_vacation_control': status_vacation_control,
                'status_working_month_first_year': status_working_month_first_year,
                'status_working_year': status_working_year,
                'date_workingyear_start': date_workingyear_start,
                'date_workingyear_end': date_workingyear_end,
                'check_last': True,  # 마지막 근무년차
                'check_selected': True,  # 활성화된(선택된) 근무년차
            }
            q_vacation_control_selected = Vacation_Control.objects.create(**data)
            issue_member_regular_vacation_by_working_year(q_vacation_control_selected)
            # 옛날 Vacation control 업데이트
            qs_vacation_control_old_working_year = Vacation_Control.objects.filter(Q(check_discard=False) & Q(owner=q_profile.user))
            if qs_vacation_control_old_working_year is not None and len(qs_vacation_control_old_working_year) > 0:
                # Vacation_Control.objects.filter(Q(check_discard=False) & Q(status_working_year__isnull=False)).aggregate(Max('status_working_year'))
                for q_vacation_control_old_working_year in qs_vacation_control_old_working_year:
                    if q_profile.status_working_year == q_vacation_control_old_working_year.status_working_year:
                        data = {
                            'check_last': True,
                            'check_selected': True,
                        }
                    else:
                        data = {
                            'check_last': False,
                            'check_selected': False,
                        }
                    Vacation_Control.objects.filter(id=q_vacation_control_old_working_year.id).update(**data)
        else:
            print('근무시작일이 오늘 / 오늘보다 미래인 경우')
            pass
    #--------------------------------------------------------------------------------------------------------------------------
    else:
        print('# 휴가 컨트롤 쿼리가 있는 경우, 업데이트')
        data = {
            'status_vacation_control': status_vacation_control,
            'status_working_month_first_year': status_working_month_first_year,
            'status_working_year': status_working_year,
            'date_workingyear_start': date_workingyear_start,
            'date_workingyear_end': date_workingyear_end,
            'check_selected': True,
        }
        Vacation_Control.objects.filter(id=q_vacation_control_selected.id).update(**data)
        if status_working_year == 1:
            # 1년차이면 추가발행할 연차 있는지 확인하고 발행
            issue_member_regular_vacation_by_working_year(q_vacation_control_selected)

        # 해당 근무년차 Vacation Control Check Last / Check Selected 리셋 및 미래년차 삭제
        qs_vacation_control = Vacation_Control.objects.filter(Q(check_discard=False) & Q(owner=q_user))
        if qs_vacation_control is not None:
            for q_vacation_control in qs_vacation_control:
                # print('q_vacation_control.status_working_year', q_vacation_control.status_working_year)
                if q_vacation_control.status_working_year == status_working_year:
                    data = {
                        'check_last': True,
                        'check_selected': True,
                    }
                else:
                    data = {
                        'check_last': False,
                        'check_selected': False,
                    }
                Vacation_Control.objects.filter(id=q_vacation_control.id).update(**data)
                if q_vacation_control.status_working_year > q_profile.status_working_year:
                    data = {
                        'check_discard': True,
                    }
                    Vacation_Control.objects.filter(id=q_vacation_control.id).update(**data)
                    # print('discard!!!!!!!!!!', q_vacation_control)
    #--------------------------------------------------------------------------------------------------------------------------
    if q_vacation_control_selected is not None:
        q_vacation_control_selected.refresh_from_db()
    return q_vacation_control_selected



#--------------------------------------------------------------------------------------------------------------------------
# 멤버 휴가 컨트롤 근무년수별 선택하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_vacation_control_switch_member_status_working_year(request, q_mysettings_hr):
    print("# 멤버 휴가 컨트롤 근무년수별 선택하기 ///////////////////////")
    q_vacation_control = q_mysettings_hr.vacation_control
    print('q_vacation_control', q_vacation_control)
    q_user = q_vacation_control.owner
    q_profile = q_user.profile
    #--------------------------------------------------------------------------------------------------------------------------
    # Status working year 구하기
    status_working_year_str = request.POST.get('select-hr-vacation-control-working-year')
    if status_working_year_str is None or status_working_year_str == '':
        return False
    status_working_year =  int(status_working_year_str)
    print('선택한 근무년차', status_working_year)
    #--------------------------------------------------------------------------------------------------------------------------
    # 현재 근무년차 해당하는 휴가관리 쿼리 찾기
    q_vacation_control_selected = create_new_vacation_control_query(q_profile, status_working_year)
    q_vacation_control_selected.refresh_from_db()
    #--------------------------------------------------------------------------------------------------------------------------
    # 휴가 관리 쿼리 상태 업데이트 (Vacation Control Update)
    update_hr_vacation_control_overall(q_vacation_control_selected)
    #--------------------------------------------------------------------------------------------------------------------------
    # 나머지 선택안된 Vacation Control은 check_selected == False로 상태 업데이트
    qs_vacation_control_unselected = Vacation_Control.objects.filter(Q(check_discard=False) & Q(owner=q_user))
    if qs_vacation_control_unselected is not None and len(qs_vacation_control_unselected) > 0:
        for q_vacation_control_unselected in qs_vacation_control_unselected:
            print('q_vacation_control_unselected', q_vacation_control_unselected.id)
            if q_vacation_control_unselected != q_vacation_control_selected:
                data = {
                    'check_selected': False,
                }
                Vacation_Control.objects.filter(id=q_vacation_control_unselected.id).update(**data)
            else:
                data = {
                    'check_selected': True,
                }
                Vacation_Control.objects.filter(id=q_vacation_control_unselected.id).update(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    # 해당 근무년차 Vacation Control 을 Mysettings에 업데이트하기
    # print('q_vacation_control_selected', q_vacation_control_selected.check_selected, q_vacation_control_selected)
    data = {
        'vacation_control': q_vacation_control_selected,
        'check_activate_detail_vacation_control_view': True,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    q_vacation_control_selected.refresh_from_db()
    # print('q_vacation_control_selected check_selected :', q_vacation_control_selected.check_selected)
    return True



#--------------------------------------------------------------------------------------------------------------------------
# HR Vacation 자동 발행
#
# Queryset date field lookup:
# today = datetime.date.today() or today = datetime.date(2009,8,22)
# today에 생성된 쿼리 찾을 경우(1) : Model.objects.filter(date_created__year=today.year, date_created__month=today.month, date_created__day=today.day)
# today에 생성된 쿼리 찾을 경우(2) : Model.objects.filter(date_created__startswith=today)
# today에 생성된 쿼리 찾을 경우(3) : Model.objects.filter(date_created__contains=today)
# today 포함 이후에 생성된 쿼리 찾을 경우: Model.objects.filter(date_created__gte=today)
# today 포함 이전에 생성된 쿼리 찾을 경우: Model.objects.filter(date_created__lte=today)
#
# 연차 발행 규칙
# 입사일 기준 근무 만 1년이 지나면 기 발행 연차는 못쓰게 되며, 새로운 연차가 발행된다. (인사팀에서 사용가능하도록 변경할 수 있게, 기한지난 연차 따로 관리)
# 근무년수 만 2년까지 총 26개 (1년차 11개, 2년차 15개)가 발행된다.
# 3년차 15개, 4~5년차 16개, 6~7년차 17개 7~8년차 18개씩 2년마다 1개씩 늘어난다.
# 21년차부터 최대 25개로 제한
# 1년차에는 만 1달이 지나면 1개가 발행되어 최대 1년간 11개가 발행된다.
# 만 1년이 지난 1년 + 1일이 되면 (2년차 첫째날이 되면) 15개가 2년차 몫으로 새로 발행된다. (1년차 11개는 기한만료가 된다. -> 미사용된 휴가 따로 관리)
#--------------------------------------------------------------------------------------------------------------------------

#--------------------------------------------------------------------------------------------------------------------------
# 휴가 발행하기 Ver. 2022-10-05
#--------------------------------------------------------------------------------------------------------------------------

#--------------------------------------------------------------------------------------------------------------------------
# 선택된 근속년차별 발행해야 하는 연차 개수 업데이트
#--------------------------------------------------------------------------------------------------------------------------
def calculate_vacation_issued_total_for_this_working_year(q_vacation_control_this_working_year):
    status_working_year = q_vacation_control_this_working_year.status_working_year
    status_working_year_profile = q_vacation_control_this_working_year.owner.profile.status_working_year
    # print('status_working_year', status_working_year)
    # print('status_working_year_profile', status_working_year_profile)

    if q_vacation_control_this_working_year.status_working_year == 1:
        if status_working_year == status_working_year_profile:
            # print('# 현재 기준 1년차이면 월차수 만큼')
            issue_number_vc_this_working_year_total = q_vacation_control_this_working_year.owner.profile.status_working_month_first_year
        else:
            # print('# 현재 기준 2년차 이상이나 과거의 1년차를 발행하는 것이면 최대치 11개 만큼')
            issue_number_vc_this_working_year_total = 11
    else:
        # 2년차 이상이면 15개 부터 시작해서 매 2년마다 1개씩 추가, 최대 25개까지 발행
        issue_number_vc_this_working_year_total = 14 + (status_working_year // 2)
        if issue_number_vc_this_working_year_total > 25:
            issue_number_vc_this_working_year_total = 25
    # print('********************* issue_number_vc_this_working_year_total', issue_number_vc_this_working_year_total)
    return issue_number_vc_this_working_year_total


#--------------------------------------------------------------------------------------------------------------------------
# 기 발행된 연차 중 신청중인 연차 계산
#--------------------------------------------------------------------------------------------------------------------------
def calculate_vacation_issued_underapproval_this_working_year(q_vacation_control_this_working_year):
    qs_vacation_issued_total = Vacation_Issued.objects.filter(Q(check_discard=False) & Q(vacation_control=q_vacation_control_this_working_year) & Q(vacation_type='VC_REGULAR') & Q(status='UNDERAPPROVAL'))
    list_credit_vacation_issued_underapproval = []
    if qs_vacation_issued_total is not None and len(qs_vacation_issued_total) > 0:
        for q_vacation_issued_total in qs_vacation_issued_total:
            list_credit_vacation_issued_underapproval.append(q_vacation_issued_total.credit_scheduled_to_use)
    vc_count_underapproval_total = sum(list_credit_vacation_issued_underapproval)
    # print('********************* vc_count_underapproval_total', vc_count_underapproval_total)
    return vc_count_underapproval_total


#--------------------------------------------------------------------------------------------------------------------------
# 기 발행된 연차 중 사용된 연차 계산
#--------------------------------------------------------------------------------------------------------------------------
def calculate_vacation_issued_used_this_working_year(q_vacation_control_this_working_year):
    qs_vacation_issued_total = Vacation_Issued.objects.filter(Q(check_discard=False) & Q(vacation_control=q_vacation_control_this_working_year) & Q(vacation_type='VC_REGULAR'))
    list_credit_vacation_issued_used = []
    if qs_vacation_issued_total is not None and len(qs_vacation_issued_total) > 0:
        for q_vacation_issued_total in qs_vacation_issued_total:
            if q_vacation_issued_total.status == 'VALID' or q_vacation_issued_total.status == 'REVIVED':
                # 사용가능연차에서 사용된 Credit 모으기
                list_credit_vacation_issued_used.append(1 - q_vacation_issued_total.credit)
            else:
                # 사용불가능한 연차에서 사용된 Credit 모으기
                if q_vacation_issued_total.status == 'USED' :
                    list_credit_vacation_issued_used.append(1)
    vc_count_used_total = sum(list_credit_vacation_issued_used)
    # print(' ********************* vc_count_used_total', vc_count_used_total)
    return vc_count_used_total


#--------------------------------------------------------------------------------------------------------------------------
# 기 발행된 연차 중 미사용 만기된, 이월되지 않은 연차개수
#--------------------------------------------------------------------------------------------------------------------------
def calculate_vacation_issued_unused_this_working_year(q_vacation_control_this_working_year):
    ls_today = datetime.date.today()
    list_vacation_issued_unsuese_expired_this_working_year = []
    qs_vacation_issued_total = Vacation_Issued.objects.filter(Q(check_discard=False) & Q(vacation_control=q_vacation_control_this_working_year) & Q(vacation_type='VC_REGULAR'))
    if qs_vacation_issued_total is not None and len(qs_vacation_issued_total) > 0:
        for q_vacation_issued_total in qs_vacation_issued_total:
            if q_vacation_issued_total.date_expired < ls_today and q_vacation_issued_total.credit > 0:  # 사용가능 크레딧이 남았으나 기한 만료된 경우.
                if q_vacation_issued_total.status != 'REVIVED' :
                    data = {
                        'status': 'EXPIRED',
                    }
                    Vacation_Issued.objects.filter(id=q_vacation_issued_total.id).update(**data)
                if q_vacation_issued_total not in list_vacation_issued_unsuese_expired_this_working_year:
                    list_vacation_issued_unsuese_expired_this_working_year.append(q_vacation_issued_total.credit)
    if len(list_vacation_issued_unsuese_expired_this_working_year) > 0:
        vc_count_unused_expired_total = sum(list_vacation_issued_unsuese_expired_this_working_year)
    else:
        vc_count_unused_expired_total = 0
    # print('********************* vc_count_unused_expired_total', vc_count_unused_expired_total)
    return vc_count_unused_expired_total



#--------------------------------------------------------------------------------------------------------------------------
# 이번년도로 이월된 과거의 연차개수 (2년차부터)
#--------------------------------------------------------------------------------------------------------------------------
def calculate_vacation_issued_unused_revived_previous_working_year(q_vacation_control_this_working_year):
    list_vacation_issued_prev_working_year_expired_unused_revived_credit = []
    if q_vacation_control_this_working_year is not None:
        qs_vacation_issued_total_revived = Vacation_Issued.objects.filter(Q(check_discard=False) & Q(vacation_control=q_vacation_control_this_working_year) & Q(status='REVIVED') & Q(vacation_type='VC_REGULAR'))
        if qs_vacation_issued_total_revived is not None and len(qs_vacation_issued_total_revived) > 0:
            for q_vacation_issued_total_revived in qs_vacation_issued_total_revived:
                list_vacation_issued_prev_working_year_expired_unused_revived_credit.append(q_vacation_issued_total_revived.credit)
    vc_count_revived_prev_unused_expired_total = sum(list_vacation_issued_prev_working_year_expired_unused_revived_credit)
    # print('********************* vc_count_revived_prev_unused_expired_total', vc_count_revived_prev_unused_expired_total)
    return vc_count_revived_prev_unused_expired_total



#--------------------------------------------------------------------------------------------------------------------------
# 다음 년도로 이월된 이번년도의 연차개수
#--------------------------------------------------------------------------------------------------------------------------
def calculate_vacation_issued_unused_revived_this_working_year(q_vacation_control):
    list_vacation_issued_next_working_year_expired_unused_revived_credit = []
    status_working_year = q_vacation_control.status_working_year
    # 다음년차 휴가관리 쿼리 찾기
    status_working_year_next = status_working_year + 1
    q_vacation_control_next_working_year = Vacation_Control.objects.filter(Q(check_discard=False) & Q(owner=q_vacation_control.owner) & Q(status_working_year=status_working_year_next)).last()
    if q_vacation_control_next_working_year is not None:
        qs_vacation_issued_total_next_working_year = Vacation_Issued.objects.filter(Q(check_discard=False) & Q(vacation_control=q_vacation_control_next_working_year) & Q(status='REVIVED') & Q(vacation_type='VC_REGULAR'))
        if qs_vacation_issued_total_next_working_year is not None and len(qs_vacation_issued_total_next_working_year) > 0:
            for q_vacation_issued_total_next_working_year in qs_vacation_issued_total_next_working_year:
                list_vacation_issued_next_working_year_expired_unused_revived_credit.append(q_vacation_issued_total_next_working_year.credit)
    vc_count_revived_unused_expired_total = sum(list_vacation_issued_next_working_year_expired_unused_revived_credit)
    # print('********************* vc_count_revived_unused_expired_total', vc_count_revived_unused_expired_total)
    return vc_count_revived_unused_expired_total


#--------------------------------------------------------------------------------------------------------------------------
# 기 발행된 연차 중 사용 가능한 연차 계산
#--------------------------------------------------------------------------------------------------------------------------
def calculate_vacation_issued_available_this_working_year(q_vacation_control_this_working_year):
    vc_count_revived_prev_unused_expired_total = q_vacation_control_this_working_year.vc_count_revived_prev_unused_expired_total
    if vc_count_revived_prev_unused_expired_total is None:
        vc_count_revived_prev_unused_expired_total = 0
    vc_count_issued_total = q_vacation_control_this_working_year.vc_count_issued_total
    if vc_count_issued_total is None:
        vc_count_issued_total = 0
    vc_count_underapproval_total = q_vacation_control_this_working_year.vc_count_underapproval_total
    if vc_count_underapproval_total is None:
        vc_count_underapproval_total = 0
    vc_count_used_total = q_vacation_control_this_working_year.vc_count_used_total
    if vc_count_used_total is None:
        vc_count_used_total = 0
    vc_count_unused_expired_total = q_vacation_control_this_working_year.vc_count_unused_expired_total
    if vc_count_unused_expired_total is None:
        vc_count_unused_expired_total = 0
    vc_count_revived_unused_expired_total = q_vacation_control_this_working_year.vc_count_revived_unused_expired_total
    if vc_count_revived_unused_expired_total is None:
        vc_count_revived_unused_expired_total = 0
    # Equation
    vc_count_available_total = vc_count_issued_total + vc_count_revived_prev_unused_expired_total - vc_count_underapproval_total - vc_count_used_total - vc_count_unused_expired_total - vc_count_revived_unused_expired_total
    # print('********************* vc_count_available_total', vc_count_available_total)
    return vc_count_available_total




#--------------------------------------------------------------------------------------------------------------------------
# 연차 외 발행된 휴가 ID 리스트 계산
#--------------------------------------------------------------------------------------------------------------------------
def calculate_vacation_issued_irregular_this_working_year(q_vacation_control):
    list_vc_issued_additionally = []
    qs_vacation_issued_irregular = Vacation_Issued.objects.filter(Q(check_discard=False) & ~Q(vacation_type='VC_REGULAR') & Q(vacation_control=q_vacation_control))
    if qs_vacation_issued_irregular is not None and len(qs_vacation_issued_irregular) > 0:
        for q_vacation_issued_irregular in qs_vacation_issued_irregular:
            if q_vacation_issued_irregular.id not in list_vc_issued_additionally:
                list_vc_issued_additionally.append(q_vacation_issued_irregular.id)
    # print('********************* list_vc_issued_additionally', list_vc_issued_additionally)
    return list_vc_issued_additionally


#--------------------------------------------------------------------------------------------------------------------------
# 휴가 관리 쿼리 상태 업데이트 (Vacation Control Update)
#--------------------------------------------------------------------------------------------------------------------------
def update_hr_vacation_control_overall(q_vacation_control):
    #--------------------------------------------------------------------------------------------------------------------------
    # 직전년차 발행된 미사용 만기된 휴가 중 이번년차 사용가능하도록 이월된 연차개수 (2년차부터) (미사용 만료 이월된 직전년차 연차개수)
    vc_count_revived_prev_unused_expired_total = calculate_vacation_issued_unused_revived_previous_working_year(q_vacation_control)
    data = {
        'vc_count_revived_prev_unused_expired_total': vc_count_revived_prev_unused_expired_total,
    }
    Vacation_Control.objects.filter(id=q_vacation_control.id).update(**data)
    q_vacation_control.refresh_from_db()
    #--------------------------------------------------------------------------------------------------------------------------
    # 선택된 근속년차별 발행해야 하는 연차 개수 업데이트 (이번년차 받은 연차개수)
    vc_count_issued_total = calculate_vacation_issued_total_for_this_working_year(q_vacation_control)
    data = {
        'vc_count_issued_total': vc_count_issued_total
    }
    Vacation_Control.objects.filter(id=q_vacation_control.id).update(**data)
    q_vacation_control.refresh_from_db()
    #--------------------------------------------------------------------------------------------------------------------------
    # 기 발행된 휴가 중 미사용 만기된 휴가 개수 (미사용 만료된 연차개수)
    vc_count_unused_expired_total = calculate_vacation_issued_unused_this_working_year(q_vacation_control)
    data = {
        'vc_count_unused_expired_total': vc_count_unused_expired_total,
    }
    Vacation_Control.objects.filter(id=q_vacation_control.id).update(**data)
    q_vacation_control.refresh_from_db()
    #--------------------------------------------------------------------------------------------------------------------------
    # 기 발행된 연차 중 신청중인 연차 개수 (신청중인 연차개수)
    vc_count_underapproval_total = calculate_vacation_issued_underapproval_this_working_year(q_vacation_control)
    data = {
        'vc_count_underapproval_total': vc_count_underapproval_total,
    }
    Vacation_Control.objects.filter(id=q_vacation_control.id).update(**data)
    q_vacation_control.refresh_from_db()
    #--------------------------------------------------------------------------------------------------------------------------
    # 기 발행된 연차 중 사용된 연차 계산
    vc_count_used_total = calculate_vacation_issued_used_this_working_year(q_vacation_control)
    data = {
        'vc_count_used_total': vc_count_used_total,
    }
    Vacation_Control.objects.filter(id=q_vacation_control.id).update(**data)
    q_vacation_control.refresh_from_db()

    #--------------------------------------------------------------------------------------------------------------------------
    # 기 발행된 미사용 만기된사용 연차 중 다음년차 사용가능하도록 이월된 이번년도 연차개수 (미사용 만료 이월된 이번년차 연차개수)
    vc_count_revived_unused_expired_total = calculate_vacation_issued_unused_revived_this_working_year(q_vacation_control)
    data = {
        'vc_count_revived_unused_expired_total': vc_count_revived_unused_expired_total,
    }
    Vacation_Control.objects.filter(id=q_vacation_control.id).update(**data)
    q_vacation_control.refresh_from_db()

    #--------------------------------------------------------------------------------------------------------------------------
    # 기 발행된 연차 중 사용 가능한 연차 계산(사용가능한 연차개수)
    vc_count_available_total = calculate_vacation_issued_available_this_working_year(q_vacation_control)
    data = {
        'vc_count_available_total': vc_count_available_total,  # 사용가능 연차 업데이트
    }
    Vacation_Control.objects.filter(id=q_vacation_control.id).update(**data)
    q_vacation_control.refresh_from_db()
    #--------------------------------------------------------------------------------------------------------------------------
    # 연차 외 발행된 휴가 ID 리스트 계산
    list_vc_issued_additionally = calculate_vacation_issued_irregular_this_working_year(q_vacation_control)
    data = {
        'list_vc_issued_additionally': list_vc_issued_additionally,
    }
    Vacation_Control.objects.filter(id=q_vacation_control.id).update(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    return vc_count_issued_total, vc_count_unused_expired_total, vc_count_underapproval_total, vc_count_used_total, vc_count_revived_prev_unused_expired_total, vc_count_available_total








