#--------------------------------------------------------------------------------------------------------------------------
# 휴가 수동 등록 함수
#--------------------------------------------------------------------------------------------------------------------------
def hr_vacation_control_register_vacation_manual(request, q_mysettings_hr):
    ls_today = datetime.date.today()
    time_delta_1day = datetime.timedelta(days=1)
    q_vacation_control = q_mysettings_hr.vacation_control
    #--------------------------------------------------------------------------------------------------------------------------
    # 휴가 발행 일자 정보 획득
    date_issued_str = request.POST.get('date_issued')
    if date_issued_str is None or date_issued_str == '':
        messages.warning(request, f'휴가 발행일 정보가 없어 오늘자로 자동기입되었습니다.')
        date_issued= ls_today
    else:
        date_issued = datetime.datetime.strptime(date_issued_str, '%Y-%m-%d').date()  # 숫자-숫자-숫자 를 datetime 오브젝트 값으로 변환
    #--------------------------------------------------------------------------------------------------------------------------
    # 옮길 휴가 마감일 지정
    extention_days_vacation_issued_str = request.POST.get('select_hr_vacation_control_issued_vacation_manual_extension_days')
    if extention_days_vacation_issued_str is None or extention_days_vacation_issued_str == '':
        messages.warning(request, f'휴가 연장 마감일 날짜지정 정보가 없습니다. 관리자에게 문의하세요.')
        return False
    if extention_days_vacation_issued_str != VACATION_ISSUED_REVIVAL_EXTENDED_DAYS[4][0]:
        date_expired_year = date_issued.year
        date_expired_month = date_issued.month + int(extention_days_vacation_issued_str)
        date_expired_day_plus_one = date_issued.day
        year_count_factor = date_expired_month // 13

        if year_count_factor > 0:
            date_expired_month = date_expired_month - 12
            date_expired_year = date_expired_year + 1
        else:
            date_expired_month = date_expired_month
            date_expired_year = date_expired_year
        date_expired_plus_one = datetime.date(date_expired_year, date_expired_month, date_expired_day_plus_one)
        date_expired = date_expired_plus_one - time_delta_1day
    else:
        # 마감일 단축키 선택하지 않은 경우(마감일 직접 지정하기 선택한 경우)
        date_expired_str = request.POST.get('date_expired')
        if date_expired_str is None or date_expired_str == '':
            messages.warning(request, f'휴가 연장 마감일 날짜지정 선택시 직접 날짜 지정하지 않았습니다.')
            return False
        else:
            date_expired = datetime.datetime.strptime(date_expired_str, '%Y-%m-%d').date()  # 숫자-숫자-숫자 를 datetime 오브젝트 값으로 변환
    #--------------------------------------------------------------------------------------------------------------------------
    # check_update_status = 'create'  # create, update
    vacation_type_str = request.POST.get('hr-vacation-control-form-vacation-type')
    if vacation_type_str == 'VC_REGULAR': # ('VC_REGULAR', '연차'),  # 0
        messages.warning(request, f'연차는 수동으로 발행할 수 없습니다. 관리자에게 문의하세요.')
        return False
    vacation_credit_str = request.POST.get('hr-vacation-control-form-vacation-credit')
    if vacation_credit_str is None or vacation_credit_str == '':
        messages.warning(request, f'휴가 발행 개수를 잘못 기입하였습니다.')
        return False
    vacation_credit = int(vacation_credit_str)
    if vacation_credit < 0:
        messages.warning(request, f'휴가 발행 개수는 0 보다 큰 값을 가져야 합니다.')
        return False
    #--------------------------------------------------------------------------------------------------------------------------
    # 연차 외 휴가 발행하기
    i = 0
    while i < vacation_credit:
        data = {
            'owner': q_vacation_control.owner,
            'vacation_control': q_vacation_control,
            'vacation_type': vacation_type_str,
            'check_issued_regularly': False,
            'date_issued': date_issued,
            'date_expired': date_expired,
        }
        q_vacation_issued = Vacation_Issued.objects.create(**data)
        # Vacation Control 사용가능휴가개수 Update
        q_vacation_control.refresh_from_db()
        i = i + 1
    #--------------------------------------------------------------------------------------------------------------------------
    # 휴가 관리 쿼리 상태 업데이트 (Vacation Control Update)
    update_hr_vacation_control_overall(q_vacation_control)
    #--------------------------------------------------------------------------------------------------------------------------
    return True


