#--------------------------------------------------------------------------------------------------------------------------
def hr_vacation_control_update_issued_vacation_revival_view(request, q_mysettings_hr):
    ls_today = datetime.date.today()
    time_delta_1day = datetime.timedelta(days=1)
    #--------------------------------------------------------------------------------------------------------------------------
    q_vacation_control = q_mysettings_hr.vacation_control
    q_vacation_issued_id_str = request.POST.get('button-hr-vacation-control-vacation-issued-revive-update')
    if q_vacation_issued_id_str is None or q_vacation_issued_id_str == '':
        messages.warning(request, f'선택한 발행한 휴가정보가 없습니다. 관리자에게 문의하세요.')
    q_vacation_issued_id = int(q_vacation_issued_id_str)
    q_vacation_issued = Vacation_Issued.objects.get(id=q_vacation_issued_id)
    print('q_vacation_issued', q_vacation_issued, q_vacation_issued.vacation_control.status_working_year)
    # 옮길 휴가 남은 크레딧 확인
    if q_vacation_issued.credit == 0:
        messages.warning(request, f'선택한 옮길 휴가에 남은 Credit이 없습니다. 다른 발행된 휴가를 선택하세요.')
        return False
    #--------------------------------------------------------------------------------------------------------------------------
    # 옮길 휴가관리 쿼리 찾기
    status_working_year_for_revive_str = request.POST.get('select-hr-vacation-control-working-year-for-revive-unused-vc')
    if status_working_year_for_revive_str is None or status_working_year_for_revive_str == '':
        messages.warning(request, f'선택한 옮길 근무년차 정보가 없습니다. 관리자에게 문의하세요.')
        return False
    status_working_year_for_revive = int(status_working_year_for_revive_str)
    if status_working_year_for_revive <= q_mysettings_hr.vacation_control.status_working_year:
        messages.warning(request, f'선택한 옮길 근무년차는 선택한 휴가관리 근무년차보다 높은 근무년차만 가능합니다. (예: 4년차 휴가는 5년차 휴가로 옮길 수 있음')
        return False
    q_vacation_control_selected = Vacation_Control.objects.filter(Q(check_discard=False) & Q(owner=q_vacation_control.owner) & Q(status_working_year=status_working_year_for_revive)).last()
    print('q_vacation_control_selected', q_vacation_control_selected)
    if q_vacation_control_selected is None:
        messages.warning(request, f'선택한 옮길 근무년차에 해당하는 휴가관리 쿼리가 없습니다. 관라지에게 문의하세요.')
        return False
    #--------------------------------------------------------------------------------------------------------------------------
    # 옮길 휴가 마감일 지정
    extention_days_vacation_issued_str = request.POST.get('select_hr_vacation_control_issued_vacation_revive_extension_days')
    if extention_days_vacation_issued_str is None or extention_days_vacation_issued_str == '':
        messages.warning(request, f'휴가 연장 마감일 날짜지정 정보가 없습니다. 관리자에게 문의하세요.')
        return False
    if extention_days_vacation_issued_str != VACATION_ISSUED_REVIVAL_EXTENDED_DAYS[4][0]:
        # 마감일 단축키 지정한 경우
        # 휴가 마감 일자 정보 획득
        date_expired_year = ls_today.year
        date_expired_month = ls_today.month + int(extention_days_vacation_issued_str)
        date_expired_day_plus_one = ls_today.day
        year_count_factor = date_expired_month // 13

        if year_count_factor > 0:
            date_expired_month = date_expired_month - 12
            date_expired_year = date_expired_year + 1
        else:
            date_expired_month = date_expired_month
            date_expired_year = date_expired_year
        date_expired_plus_one = datetime.date(date_expired_year, date_expired_month, date_expired_day_plus_one)
        date_expired = date_expired_plus_one - time_delta_1day
    else:
        # 마감일 단축키 선택하지 않은 경우(마감일 직접 지정하기 선택한 경우)
        date_expired_str = request.POST.get('date_expired')
        if date_expired_str is None or date_expired_str == '':
            messages.warning(request, f'휴가 연장 마감일 날짜지정 선택시 직접 날짜 지정하지 않았습니다.')
            return False
        else:
            date_expired = datetime.datetime.strptime(date_expired_str, '%Y-%m-%d').date()  # 숫자-숫자-숫자 를 datetime 오브젝트 값으로 변환
    #--------------------------------------------------------------------------------------------------------------------------
    # 옮길휴가 변경내용 업데이트
    data = {
        'vacation_control': q_vacation_control_selected,
        'date_expired': date_expired,
        'status': 'REVIVED',
    }
    Vacation_Issued.objects.filter(id=q_vacation_issued.id).update(**data)
    messages.success(request, f'선택한 미사용 만료된 휴가의 만료날짜를 {status_working_year_for_revive}년차 {date_expired} 일까지 연장하였습니다.')
    # Mysettings 변경내용 업데이트
    data = {
        'check_activate_detail_vacation_issued_revival_view': False,
        'check_activate_detail_vacation_issued_modification_view': False,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True


