#--------------------------------------------------------------------------------------------------------------------------
def hr_vacation_control_delete_issued_vacation(request, q_mysettings_hr):
    q_vacation_control = q_mysettings_hr.vacation_control
    check_update_status = 'update'
    q_vacation_issued_id_str = request.POST.get('button-hr-vacation-control-vacation-issued-delete')
    if q_vacation_issued_id_str is None or q_vacation_issued_id_str == '':
        messages.warning(request, f'선택한 발행된 휴가 정보가 없습니다. 관리자에게 문의하세요.')
        return False
    q_vacation_issued_id = int(q_vacation_issued_id_str)
    q_vacation_issued = Vacation_Issued.objects.get(id=q_vacation_issued_id)
    data = {
        'check_discard': True,
    }
    Vacation_Issued.objects.filter(id=q_vacation_issued.id).update(**data)
    # Vacation Control 업데이트

    list_vc_issued_additionally = q_vacation_control.list_vc_issued_additionally
    if q_vacation_issued.id in list_vc_issued_additionally:
        # 연차 외 휴가
        list_vc_issued_additionally.remove(q_vacation_issued.id)
        data = {
            'list_vc_issued_additionally': list_vc_issued_additionally,
        }
        Vacation_Control.objects.filter(id=q_vacation_control.id).update(**data)
    else:
        # 연차
        update_hr_vacation_control_overall(q_vacation_control)

    messages.warning(request, f'선택한 발행된 휴가를 삭제하였습니다.')
    return True






