#--------------------------------------------------------------------------------------------------------------------------
# 휴가계획서 멤버 선택하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_vacation_control_select_vc_plan_owner_name(request, q_mysettings_hr, where_am_i):
    if where_am_i == 'my':
        # my 에서는 멤버 선택이 필요없음.
        return True
    q_vacation_plan_id_str = request.POST.get('button-vc-control-plan-registered-owner-name-select')
    if q_vacation_plan_id_str is None or q_vacation_plan_id_str == '':
        messages.warning(request, f'선택한 휴가계획서 정보가 없습니다. 관리자에게 문의하세요.')
        return False
    q_vacation_plan_id = int(q_vacation_plan_id_str)
    q_vacation_plan = Vacation_Plan.objects.get(id=q_vacation_plan_id)
    radio_last_workingyear_str = request.POST.get('radio-hr-vacation-control-search-vacation-plan-lastworkingyear')
    if radio_last_workingyear_str == 'true':
        # 현재년차(최근년차)만
        check_search_only_last_workingyear = True
    else:
        check_search_only_last_workingyear = False
    #--------------------------------------------------------------------------------------------------------------------------
    q_owner = q_vacation_plan.owner
    if check_search_only_last_workingyear == True:
        q_vacation_control_last = Vacation_Control.objects.filter(Q(owner=q_owner) & Q(check_last=True)).last()
        qs_vacation_plan_owner = Vacation_Plan.objects.filter(Q(check_discard=False) & Q(owner=q_owner) & Q(vacation_control=q_vacation_control_last))
    else:
        qs_vacation_plan_owner = Vacation_Plan.objects.filter(Q(check_discard=False) & Q(owner=q_owner))
    list_vacation_plan_id_membername = []
    if qs_vacation_plan_owner is not None and len(qs_vacation_plan_owner) > 0:
        for q_vacation_plan_owner in qs_vacation_plan_owner:
            if q_vacation_plan_owner.id not in list_vacation_plan_id_membername:
                list_vacation_plan_id_membername.append(q_vacation_plan_owner.id)
    if len(list_vacation_plan_id_membername) > 1:
        data = {
            'vacation_control_plan_display_type': LIST_HR_VACATION_CONTROL_PLAN_DISPLY_TYPE[5][0],
            'list_vacation_plan_id_membername': list_vacation_plan_id_membername,
            'check_search_only_last_workingyear': check_search_only_last_workingyear,
        }
        HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
        q_mysettings_hr.refresh_from_db()
        messages.success(request, f'선택한 {q_owner.profile.name_korean} 멤버의 {len(list_vacation_plan_id_membername)}개의 휴가계획서만 모았습니다.')
    else:
        messages.warning(request, f'선택한 멤버의 추가적으로 등록된 휴가계획서가 없습니다.')
    return True


