#--------------------------------------------------------------------------------------------------------------------------
# Step 1 to Step 2  (작성자 정보 저장)
#--------------------------------------------------------------------------------------------------------------------------
def hr_vacation_plan_save_step1_to_step2(request, q_mysettings_hr):
    q_hrlayout_applicant = q_mysettings_hr.hrlayout_applicant
    q_vacation_plan_register = q_mysettings_hr.vacation_plan_register
    # 작성자의 근무년차 선택정보 획득
    #--------------------------------------------------------------------------------------------------------------------------
    # 작성일 정보 획득
    datetime_submission_str = request.POST.get('datetime_submission')
    if datetime_submission_str is None or datetime_submission_str == '':
        if q_vacation_plan_register is not None:
            if q_vacation_plan_register.datetime_submission is not None:
                datetime_submission = q_vacation_plan_register.datetime_submission
            else:
                datetime_submission = None
                messages.warning(request, f'휴가 제출일자 정보를 지정하지 않았습니다.')
        else:
            datetime_submission = None
            messages.warning(request, f'휴가 제출일자 정보를 지정하지 않았습니다.')
    else:
        datetime_submission = datetime.datetime.strptime(datetime_submission_str, '%Y-%m-%d')  # 숫자-숫자-숫자 를 datetime 오브젝트 값으로 변환
    #--------------------------------------------------------------------------------------------------------------------------
    # 근무년차 정보 획득
    status_working_year_str = request.POST.get('select-hr-vacation-control-working-year-for-plan-register')
    if status_working_year_str is None or status_working_year_str == '' or status_working_year_str == 'none' :
        status_working_year = None
    else:
        status_working_year = int(status_working_year_str)
    print('status_working_year_str', status_working_year_str)
    #--------------------------------------------------------------------------------------------------------------------------
    # 근무년차 획득 확정하기
    if datetime_submission is not None:
        # 근무년차 정보 있는 경우, 작성일 정보와 일치하지 않으면 작성일 기준으로 근무년차 획득
        time_delta_365days = datetime.timedelta(days=365)
        date_joined = q_hrlayout_applicant.member.user.profile.date_joined
        date_submission = datetime_submission.date()
        delta_workingtime = date_submission - date_joined
        status_working_year = (delta_workingtime//time_delta_365days) + 1
    else:
        # 근무년차 정보 없는경우 작성일 정보를 이용하여 근무년차 계산하기
        if status_working_year is None:
            if datetime_submission is None:
                messages.warning(request, f'휴가 제출일자 정보 혹은 근무년차 정보 둘 중 하나를 제공해야 합니다.')
                return False
    print('status_working_year', status_working_year)
    #--------------------------------------------------------------------------------------------------------------------------
    # 근무년차정보 이용하여 Vacation Control 쿼리 찾기
    q_vacation_control_register = Vacation_Control.objects.filter(Q(check_discard=False) & Q(owner=q_hrlayout_applicant.member.user) & Q(status_working_year=status_working_year)).last()
    if q_vacation_control_register is None:
        messages.warning(request, f'해당 멤버의 {status_working_year} 년차 휴가관리 쿼리가 없습니다. 관리자에게 문의하세요.')
        return False
    print('q_vacation_control_register', q_vacation_control_register)
    #--------------------------------------------------------------------------------------------------------------------------
    # 휴가계획서 임시생성
    data = {
        'owner': q_hrlayout_applicant.member.user,
        'vacation_control': q_vacation_control_register,
        'hrlayout_applicant': q_hrlayout_applicant,
        'datetime_submission': datetime_submission,
        # 'status_vacation_plan': STATUS_MY_VACATION_PLAN[4][0],  # ('APPROVED', '승인완료'),  # 4 success
    }
    if q_vacation_plan_register is None:
        q_vacation_plan_register = Vacation_Plan.objects.create(**data)
        messages.success(request, f'휴가계획서 업로드 1단계 - 작성자 정보를 등록하였습니다. {q_hrlayout_applicant.member.member_name}님의 임시휴가계획서가 생성되었습니다.')
    else:
        Vacation_Plan.objects.filter(id=q_vacation_plan_register.id).update(**data)
        messages.success(request, f'휴가계획서 업로드 1단계 - 작성자 정보를 업데이트 하였습니다. 2단계로 넘어갑니다.')
        q_vacation_plan_register.refresh_from_db()
    # 생성한 임시휴가계획서를 Mysettings에 업데이트
    data = {
        'vacation_control_register': q_vacation_control_register,
        'vacation_plan_register': q_vacation_plan_register,
        'status_hr_vacation_plan_register_manually': STATUS_HR_VACATION_PLAN_REGISTER_MANUALLY[1][0],
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    print('q_mysettings_hr.vacation_plan_register', q_mysettings_hr.vacation_plan_register)
    return True

