#--------------------------------------------------------------------------------------------------------------------------
# Step 2 to Step 3 (결재자 정보 저장)
#--------------------------------------------------------------------------------------------------------------------------
def hr_vacation_plan_save_step2_to_step3(request, q_mysettings_hr):
    q_vacation_plan_register = q_mysettings_hr.vacation_plan_register
    q_hrlayout_approver_1 = q_mysettings_hr.hrlayout_approver_1
    q_hrlayout_approver_2 = q_mysettings_hr.hrlayout_approver_2
    q_hrlayout_approver_3 = q_mysettings_hr.hrlayout_approver_3
    if q_hrlayout_approver_1 is not None:
        if q_hrlayout_approver_1.check_company_leader == True:
            data = {
                'hrlayout_approver_companyleader': q_hrlayout_approver_1,
            }
        if q_hrlayout_approver_1.check_company_leader == False and q_hrlayout_approver_1.check_division_leader == True:
            data = {
                'hrlayout_approver_divisionleader': q_hrlayout_approver_1,
            }
        if q_hrlayout_approver_1.check_company_leader == False and q_hrlayout_approver_1.check_division_leader == False and q_hrlayout_approver_1.check_team_leader == True:
            data = {
                'hrlayout_approver_teamleader': q_hrlayout_approver_1,
            }
        Vacation_Plan.objects.filter(id=q_vacation_plan_register.id).update(**data)
        if q_hrlayout_approver_2 is not None:
            if q_hrlayout_approver_2.check_company_leader == True:
                data = {
                    'hrlayout_approver_companyleader': q_hrlayout_approver_2,
                }
            if q_hrlayout_approver_2.check_company_leader == False and q_hrlayout_approver_2.check_division_leader == True:
                data = {
                    'hrlayout_approver_divisionleader': q_hrlayout_approver_2,
                }
            Vacation_Plan.objects.filter(id=q_vacation_plan_register.id).update(**data)
        if q_hrlayout_approver_3 is not None:
            if q_hrlayout_approver_3.check_company_leader == True:
                data = {
                    'hrlayout_approver_companyleader': q_hrlayout_approver_3,
                }
                Vacation_Plan.objects.filter(id=q_vacation_plan_register.id).update(**data)

    else:
        messages.warning(request, f'결재자 1 정보가 없습니다. 결재자는 순차적으로 채워야 합니다.')
        return False
    data = {
        'status_hr_vacation_plan_register_manually': STATUS_HR_VACATION_PLAN_REGISTER_MANUALLY[2][0],
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    messages.success(request, f'휴가계획서 업로드 2단계 - 결재자 정보를 업데이트 하였습니다. 3단계로 넘어갑니다.')
    return True

