#--------------------------------------------------------------------------------------------------------------------------
# Step 3 to Step 4 (휴가계획서 정보 저장)
#--------------------------------------------------------------------------------------------------------------------------
def hr_vacation_plan_save_step3_to_step4(request, q_mysettings_hr):
    ls_today = datetime.date.today()
    time_delta_7days = datetime.timedelta(days=7)
    print('*************************************  # Step 3 to Step 4 (휴가계획서 정보 저장)')
    q_vacation_plan_register = q_mysettings_hr.vacation_plan_register
    if q_vacation_plan_register is None:
        messages.warning(request, f'등록중인 휴가계획서가 쿼리가 없습니다.')
        return False
    q_vacation_control_register = q_vacation_plan_register.vacation_control
    if q_vacation_control_register is None:
        messages.warning(request, f'등록중인 휴가컨트롤 쿼리가 없습니다.')
        return False
    print('q_vacation_control_register', q_vacation_control_register)
    q_profile = q_vacation_plan_register.owner.profile
    #--------------------------------------------------------------------------------------------------------------------------
    # 휴가 사유
    vacation_reason_str = request.POST.get('text-hr-vacation-plan-register-vacation-reason')
    # 휴가 타입
    vacation_type_str = request.POST.get('select-hr-vacation-plan-register-vacation-type')
    print('vacation_type_str', vacation_type_str)
    # 사용하는 연차 종류
    vacation_regular_type_str = request.POST.get('select-hr-vacation-plan-register-vacation-regular-type')
    if vacation_regular_type_str == LIST_VACATION_REGULAR_TYPES[0][0]:
        credit_used_unit = 1
    elif vacation_regular_type_str == LIST_VACATION_REGULAR_TYPES[1][0]:
        credit_used_unit = 0.5
    elif vacation_regular_type_str == LIST_VACATION_REGULAR_TYPES[2][0]:
        credit_used_unit = 0.25
    else:
        credit_used_unit = 1
    #--------------------------------------------------------------------------------------------------------------------------
    # 휴가 날짜 개시일 / 종료일로부터 총 사용하는 크레딧 계산하기
    #--------------------------------------------------------------------------------------------------------------------------
    # 사용자 입력 휴가 개시일/종료일 받기
    # 휴가 개시일
    date_vacation_start_str = request.POST.get('date_vacation_start')
    if date_vacation_start_str is None or date_vacation_start_str == '':
        messages.warning(request, f'휴가 개시일 정보가 없습니다.')
        return False
    date_vacation_start = datetime.datetime.strptime(date_vacation_start_str, '%Y-%m-%d').date()
    # 휴가 종료일
    date_vacation_end_str = request.POST.get('date_vacation_end')
    if date_vacation_end_str is None or date_vacation_end_str == '':
        date_vacation_end = date_vacation_start
    else:
        date_vacation_end = datetime.datetime.strptime(date_vacation_end_str, '%Y-%m-%d').date()
    # 개시일 < 종료일 확인
    if date_vacation_start > date_vacation_end:
        messages.warning(request, f'휴가 개시일이 휴가 종료일 보다 과거일 수 없습니다. 날짜를 다시 지정하세요..')
        return False
    #--------------------------------------------------------------------------------------------------------------------------
    # 국공휴일에 따른 휴가개시일/휴가종료일 자동조정 및 사용될 휴가 크레딧 계산
    return_value = calculate_needed_vacation_credit_using_two_date_info(vacation_type_str, date_vacation_start, date_vacation_end, credit_used_unit)
    credit_used_total = return_value[0]
    date_vacation_start = return_value[1]
    date_vacation_end = return_value[2]
    list_holiday_date_adjusted = return_value[3]
    list_vacation_date_adjusted = return_value[4]
    print('이번 휴가계획서에서 사용할 Credit 개수', credit_used_total)
    print('이번 휴가계획서 휴가개시일 :', date_vacation_start)
    print('이번 휴가계획서 휴가종료일 :', date_vacation_end)
    #--------------------------------------------------------------------------------------------------------------------------
    # 휴가 개시일 / 종료일 calendar event 등록 여부 확인. 누락시 생성
    list_year_check_calendar_event = []
    year_calendar_start = date_vacation_start.year
    year_calendar_end = date_vacation_end.year
    if year_calendar_start == year_calendar_end:
        list_year_check_calendar_event.append(year_calendar_start)
    else:
        list_year_check_calendar_event.append(year_calendar_start)
        list_year_check_calendar_event.append(year_calendar_end)
    for year_check_calendar_event in list_year_check_calendar_event:
        q_calendar_control = HR_Calendar_Control.objects.filter(Q(check_discard=False) & Q(year_calendar=year_check_calendar_event)).last()
        if q_calendar_control is None:
            data = {
                'year_calendar': year_check_calendar_event,
            }
            q_calendar_control = HR_Calendar_Control.objects.create(**data)
            # 해당 년도 Calendar Control 쿼리 이용하여 National Event 생성하기
            messages.warning(request, f'휴가계획서 등록년도({year_check_calendar_event})에 해당하는 국가공휴일 정보가 없습니다. 국가공휴일 정보를 내려받는데 10분정도 소요됩니다.')
            register_national_holiday_using_api_by_year(request, q_calendar_control)
        else:
            print('해당 근무년차에 대응하는 Calendar Event 정보가 있습니다.')
            pass
    #--------------------------------------------------------------------------------------------------------------------------
    # 해당 휴가 타입으로 이용가능한 발행휴가 크레딧 확인하기 및 사용될 발행휴가 ID 리스트 확보
    qs_vacation_issued = Vacation_Issued.objects.filter(Q(check_discard=False) & Q(vacation_control=q_vacation_control_register) & Q(vacation_type=vacation_type_str) & Q(credit__gt=0))
    print('qs_vacation_issued', len(qs_vacation_issued))
    if qs_vacation_issued is not None and len(qs_vacation_issued) > 0:
        return_value = calculate_dict_vacation_issued_and_used_credit(request, q_profile, credit_used_total, vacation_type_str, None)
        list_used_vacation_issued_id = return_value[0] # 사용될 credit은 credit_schedule_to_use에 저장되어 있음.
        dict_used_vacation_issued_id_credit = return_value[1]
    else:
        messages.warning(request, f'휴가계획서 등록 가능한 발행된 휴가가 없습니다.')
        return False
    print('list_used_vacation_issued_id', list_used_vacation_issued_id)
    #--------------------------------------------------------------------------------------------------------------------------
    # 발행휴가 상태 업데이트
    qs_vacation_issued_register = Vacation_Issued.objects.filter(id__in=list_used_vacation_issued_id)
    if qs_vacation_issued_register is not None and len(qs_vacation_issued_register) > 0:
        for q_vacation_issued_register in qs_vacation_issued_register:
            list_linked_vacation_plan = q_vacation_issued_register.list_linked_vacation_plan
            if list_linked_vacation_plan is None:
                list_linked_vacation_plan = []
            if q_vacation_plan_register.id not in list_linked_vacation_plan:
                list_linked_vacation_plan.append(q_vacation_plan_register.id)
            credit_scheduled_to_use = q_vacation_issued_register.credit_scheduled_to_use
            credit = q_vacation_issued_register.credit
            credit_after = credit - credit_scheduled_to_use
            data = {
                'credit': credit_after,
                # 'credit_scheduled_to_use': 0, ## 최종 등록할 때 0으로 저장. 그 전에 취소시 발행휴가 원상복귀를 위해 정보를 남겨둬야 함.
                'list_linked_vacation_plan': list_linked_vacation_plan,
            }
            Vacation_Issued.objects.filter(id=q_vacation_issued_register.id).update(**data)

    #--------------------------------------------------------------------------------------------------------------------------
    # 휴가계획서 작성시점 기준 휴가 상황 파악
    if q_vacation_control_register.check_last == True:
        print('# 현재 년차 휴가관리쿼리에 등록 == 사용가능휴가를 이용하여 등록')
        # 이월된것 / 받은것 / 사용하려고 계획중인 것 == 사용전(사용가능)
        vc_count_revived_prev_unused_expired_total = q_vacation_control_register.vc_count_revived_prev_unused_expired_total
        if vc_count_revived_prev_unused_expired_total is None:
            vc_count_revived_prev_unused_expired_total = 0
        vc_count_issued_total = q_vacation_control_register.vc_count_issued_total
        if vc_count_issued_total is None:
            vc_count_issued_total = 0
        vc_count_underapproval_total = q_vacation_control_register.vc_count_underapproval_total
        if vc_count_underapproval_total is None:
            vc_count_underapproval_total = 0
        vc_count_issued_and_revied = vc_count_revived_prev_unused_expired_total + vc_count_issued_total + vc_count_underapproval_total
        # 사용한것 / 만료된것 / 만료된것중다음차수로이월한 것 == 사용후/만료후(사용불가)
        vc_count_used_total = q_vacation_control_register.vc_count_used_total
        if vc_count_used_total is None:
            vc_count_used_total = 0
        vc_count_unused_expired_total = q_vacation_control_register.vc_count_unused_expired_total
        if vc_count_unused_expired_total is None:
            vc_count_unused_expired_total = 0
        vc_count_revived_unused_expired_total = q_vacation_control_register.vc_count_revived_unused_expired_total
        if vc_count_revived_unused_expired_total is None:
            vc_count_revived_unused_expired_total = 0
        vc_count_used = vc_count_used_total + vc_count_unused_expired_total + vc_count_revived_unused_expired_total
        # 이번 휴가에 사용하려는 것
        vc_count_plan = credit_used_total
        # 사용가능한 것
        vc_count_available_total = q_vacation_control_register.vc_count_available_total
        vc_count_remained = vc_count_available_total - credit_used_total
    else:
        print('# 지난 휴가관리쿼리 이용하여 휴가 등록 == 사용가능휴가 없으나 강제등록')
        # 미사용 만료된 연차에서 사용하는 것으로 저장
        vc_count_revived_prev_unused_expired_total = q_vacation_control_register.vc_count_revived_prev_unused_expired_total
        if vc_count_revived_prev_unused_expired_total is None:
            vc_count_revived_prev_unused_expired_total = 0
        vc_count_issued_total = q_vacation_control_register.vc_count_issued_total
        if vc_count_issued_total is None:
            vc_count_issued_total = 0
        vc_count_underapproval_total = q_vacation_control_register.vc_count_underapproval_total
        if vc_count_underapproval_total is None:
            vc_count_underapproval_total = 0
        vc_count_issued_and_revied = vc_count_revived_prev_unused_expired_total + vc_count_issued_total + vc_count_underapproval_total
        # 사용한것 / 만료된것 / 만료된것중다음차수로이월한 것 == 사용후/만료후(사용불가)
        vc_count_used_total = q_vacation_control_register.vc_count_used_total
        if vc_count_used_total is None:
            vc_count_used_total = 0
        vc_count_revived_unused_expired_total = q_vacation_control_register.vc_count_revived_unused_expired_total
        if vc_count_revived_unused_expired_total is None:
            vc_count_revived_unused_expired_total = 0
        vc_count_used = vc_count_used_total + vc_count_revived_unused_expired_total
        # 이번 휴가에 사용하려는 것
        vc_count_plan = credit_used_total
        # 사용가능한 것
        vc_count_unused_expired_total = q_vacation_control_register.vc_count_unused_expired_total
        if vc_count_unused_expired_total is None:
            vc_count_unused_expired_total = 0
        vc_count_available_total = q_vacation_control_register.vc_count_available_total
        vc_count_remained = vc_count_available_total + vc_count_unused_expired_total - credit_used_total
    #--------------------------------------------------------------------------------------------------------------------------
    # 휴가 사용되는 날짜 리스트 업데이트
    list_date_vacation = []
    if list_vacation_date_adjusted is not None and len(list_vacation_date_adjusted) > 0:
        for vacation_date_adjusted in list_vacation_date_adjusted:
            if vacation_date_adjusted not in list_date_vacation:
                vacation_date_adjusted_str = str(vacation_date_adjusted)
                list_date_vacation.append(vacation_date_adjusted_str)
    else:
        list_date_vacation = None
    #--------------------------------------------------------------------------------------------------------------------------
    # 휴가계획서 업데이트
    q_vacation_plan_register.refresh_from_db()
    if q_vacation_plan_register.datetime_submission is None:
        # 신청일 정보가 없는 경우, 휴가개시일과 동일 시간으로 자동 기입
        datetime_submission = date_vacation_start
    else:
        datetime_submission = ls_today
    data = {
        'datetime_start': date_vacation_start,
        'datetime_end': date_vacation_end,
        'list_date_vacation': list_date_vacation,
        'reason': vacation_reason_str,
        'vacation_type': vacation_type_str,
        # 'status_vacation_plan': STATUS_MY_VACATION_PLAN[4][0],
        'list_used_vacation_issued_id': list_used_vacation_issued_id,
        'credit_used_total': credit_used_total,

        'vc_count_issued_and_revied': vc_count_issued_and_revied,
        'vc_count_used': vc_count_used,
        'vc_count_plan': vc_count_plan,
        'vc_count_remained': vc_count_remained,
        'datetime_submission': datetime_submission,
        'datetime_approval': datetime_submission,
    }
    Vacation_Plan.objects.filter(id=q_vacation_plan_register.id).update(**data)
    q_vacation_plan_register.refresh_from_db()
    #--------------------------------------------------------------------------------------------------------------------------
    # 휴가 관리 쿼리 상태 업데이트 (Vacation Control Update)
    update_hr_vacation_control_overall(q_vacation_control_register)
    data = {
        'vc_count_underapproval_total': 0,
    }
    Vacation_Control.objects.filter(id=q_vacation_control_register.id).update(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    data = {
        'status_hr_vacation_plan_register_manually': STATUS_HR_VACATION_PLAN_REGISTER_MANUALLY[3][0],
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    messages.success(request, f'휴가계획서 업로드 3단계 - 결재자 정보를 업데이트 하였습니다. 4단계로 넘어갑니다.')
    return True

