#--------------------------------------------------------------------------------------------------------------------------
# Step 4 to Complete (휴가계획서 정보 저장)
#--------------------------------------------------------------------------------------------------------------------------
def hr_vacation_plan_save_step4_to_complete(request, q_mysettings_hr):
    q_vacation_plan_register = q_mysettings_hr.vacation_plan_register
    messages.success(request, f'성공적으로 {q_vacation_plan_register.owner.profile.name_korean}님의 휴가계획서가 등록되었습니다.')
    list_used_vacation_issued_id = q_vacation_plan_register.list_used_vacation_issued_id
    #--------------------------------------------------------------------------------------------------------------------------
    # 발행휴가 상태 업데이트
    qs_vacation_issued_register = Vacation_Issued.objects.filter(id__in=list_used_vacation_issued_id)
    if qs_vacation_issued_register is not None and len(qs_vacation_issued_register) > 0:
        for q_vacation_issued_register in qs_vacation_issued_register:
            data = {
                'credit_scheduled_to_use': 0,
                'check_underapproval': False,
            }
            Vacation_Issued.objects.filter(id=q_vacation_issued_register.id).update(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    # 휴가계획서에 코멘트 달기
    comment_str = request.POST.get('text-hr-vacation-plan-register-commment')
    if comment_str is not None or comment_str != '':
        dict_comment = q_vacation_plan_register.dict_comment
        if dict_comment is None:
            dict_comment = {}
        k_member_id = str(request.user.member.id)
        dict_comment[k_member_id] = comment_str
        data = {
            'dict_comment': dict_comment,
        }
        Vacation_Plan.objects.filter(id=q_vacation_plan_register.id).update(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    # 최종승인이면 칼렌다 휴가 리스트 추가
    list_date_vacation = q_vacation_plan_register.list_date_vacation
    if list_date_vacation is not None and len(list_date_vacation) > 0:
        for date_vacation_str in list_date_vacation:
            date_vacation = datetime.datetime.strptime(date_vacation_str, '%Y-%m-%d').date()
            q_calendar_vacation = HR_Calendar_Vacation.objects.filter(date_vacation=date_vacation).last()
            if q_calendar_vacation is None:
                data = {
                    'date_vacation': date_vacation,
                    'list_attendee': [q_vacation_plan_register.id]
                }
                q_calendar_vacation = HR_Calendar_Vacation.objects.create(**data)
            else:
                list_attendee = q_calendar_vacation.list_attendee
                if list_attendee is None:
                    list_attendee = []
                if q_vacation_plan_register.id not in list_attendee:
                    list_attendee.append(q_vacation_plan_register.id)
                data = {
                    'date_vacation': date_vacation,
                    'list_attendee': list_attendee,
                }
                HR_Calendar_Vacation.objects.filter(id=q_calendar_vacation.id).update(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    # Mysettings 업데이트
    data = {
        'vacation_control_register': None,
        'vacation_plan_register': None,
        'status_hr_vacation_plan_register_manually': STATUS_HR_VACATION_PLAN_REGISTER_MANUALLY[0][0],
        'hrlayout_applicant': None,
        'hrlayout_approver_1': None,
        'hrlayout_approver_2': None,
        'hrlayout_approver_3': None,
        'check_hrlayout_takeover': False,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True

#--------------------------------------------------------------------------------------------------------------------------
# 휴가계획서 수동등록 취소하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_vacation_plan_cancel_register_remove_temp_vacation_plan(request, q_mysettings_hr):
    q_vacation_plan_register = q_mysettings_hr.vacation_plan_register
    list_used_vacation_issued_id = q_vacation_plan_register.list_used_vacation_issued_id
    # 휴가계획서에 사용된 발행휴가 원상복귀
    qs_vacation_issued_register = Vacation_Issued.objects.filter(id__in=list_used_vacation_issued_id)
    if qs_vacation_issued_register is not None and len(qs_vacation_issued_register) > 0:
        for q_vacation_issued_register in qs_vacation_issued_register:
            list_linked_vacation_plan = q_vacation_issued_register.list_linked_vacation_plan
            if list_linked_vacation_plan is None:
                list_linked_vacation_plan = []
            if q_vacation_plan_register.id in list_linked_vacation_plan:
                list_linked_vacation_plan.remove(q_vacation_plan_register.id)
            credit_scheduled_to_use = q_vacation_issued_register.credit_scheduled_to_use
            credit = q_vacation_issued_register.credit
            credit_after = credit + credit_scheduled_to_use
            data = {
                'credit': credit_after,
                'credit_scheduled_to_use': 0,
                'list_linked_vacation_plan': list_linked_vacation_plan,
            }
            Vacation_Issued.objects.filter(id=q_vacation_issued_register.id).update(**data)
    # 휴가계획서 파기
    if q_vacation_plan_register is not None:
        data = {
            'check_discard': True,
        }
        Vacation_Plan.objects.filter(id=q_vacation_plan_register.id).update(**data)
    # Mysettings 상태 업데이트 (원상복귀)
    data = {
        'vacation_control_register': None,
        'vacation_plan_register': None,
        'status_hr_vacation_plan_register_manually': STATUS_HR_VACATION_PLAN_REGISTER_MANUALLY[0][0],
        'hrlayout_applicant': None,
        'hrlayout_approver_1': None,
        'hrlayout_approver_2': None,
        'hrlayout_approver_3': None,
        'check_hrlayout_takeover': False,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    messages.success(request, f'휴가계획서 작성을 취소하였습니다. 임시 생성된 휴가계획서 정보가 파기되었습니다.')
    return True












