#--------------------------------------------------------------------------------------------------------------------------
# 멤버 휴가계획서 자동등록을 위한 파일 업로드 (관리자) V.2 (2023-04-20), HR_Document_Issued 도입
#--------------------------------------------------------------------------------------------------------------------------
def hr_vacation_plan_upload_automatically(request, q_mysettings_hr):
    file_upload_type = request.POST.get('file-upload-type')
    if file_upload_type == 'remove':
        print('remove!!!!!!!!!')
        HR_Document_Approval_Management.objects.all().delete()
        HR_Document_Issued.objects.all().delete()
        Vacation_Control.objects.all().delete()
        Vacation_Issued.objects.all().delete()
        Vacation_Plan.objects.all().delete()

    ls_today = datetime.date.today()


    from member.functions import calculate_status_working_year_ver_2
    from my.functions import my_xxx_document_issued_create_title, my_xxx_document_issued_create_code
    import math
    dict_error_type_and_name = {}
    uploaded_file = request.FILES['file_vc_plan_autoupload']
    # File Convert to DF ##########################
    file_type_str = request.POST.get('file-type')
    if file_type_str == 'xlsx':
        if not uploaded_file.name.endswith('.xlsx'):
            messages.warning(request, 'This is not a xlsx file')
            return False
        else:
            df = pd.read_excel(uploaded_file, sheet_name=0, header=0, index_col=False, keep_default_na=True)
    elif file_type_str == 'csv':
        if not uploaded_file.name.endswith('.csv'):
            messages.warning(request, 'This is not a csv file')
            return False
        else:
            df = pd.read_csv(uploaded_file, header=0, index_col=False, keep_default_na=True)
    # df = pd.read_excel(uploaded_file, sheet_name=0, header=0, index_col=False, keep_default_na=True)
    df = df.where(pd.notnull(df), None)
    df = df.astype(object).replace(np.nan, None)
    df = df.replace(np.nan, '', regex=True)
    # print('df', df)

    dict_error_type_and_name= {'no_vc_remained':[], 'no_date_joined':[], 'vc_credit_shortage':[], 'no_vc_type':[], 'exist_vc_plan':[], 'wrong_date_joined':[], 'joined_future':[], 'no_date_vc_start':[], 'no_profile':[], 'credit_not_matched':[]}

    for index, column in df.iterrows():
        print('/', column[0])
        #--------------------------------------------------------------------------------------------------------------------------

        # 입력값 찾기
        num_count = column[0]
        name_korean = column[1]
        email = column[2]
        year_working_str = column[3]
        vacation_type_str_raw = column[4]
        date_vc_start_str = column[5]
        date_vc_end_str = column[6]
        credit_used_str = column[7]
        # print('year_working_str', year_working_str)
        # print('date_vc_start_str', date_vc_start_str)
        # print('date_vc_end_str', date_vc_end_str)
        # print('credit_used_str', credit_used_str)
        if credit_used_str == 0:
            if date_vc_start_str == date_vc_end_str:
                credit_used_str = 1
        #--------------------------------------------------------------------------------------------------------------------------
        # 멤버 이름
        q_profile = Profile.objects.filter(Q(check_discard=False) & Q(email=email)).last()
        if q_profile is None:
            q_profile = Profile.objects.filter(Q(check_discard=False) & Q(name_korean=name_korean)).last()
        if q_profile is not None:
            q_owner = q_profile.user
            #--------------------------------------------------------------------------------------------------------------------------
            # 해당 멤버 년차별 미발행 휴가 발행하기
            status_working_year = calculate_status_working_year_ver_2(q_profile, ls_today)
            data = {
                'status_working_year': status_working_year,
            }
            Profile.objects.filter(id=q_profile.id).update(**data)
            q_profile.refresh_from_db()

            i = 1
            while i <= status_working_year:
                q_vacation_control = Vacation_Control.objects.filter(Q(check_discard=False) & Q(owner=q_owner) & Q(status_working_year=i)).last()
                if q_vacation_control is None:
                    print(i, '년차 VC Control 신규 발행')
                    create_new_vacation_control_query(q_profile, i)
                i = i + 1
            #--------------------------------------------------------------------------------------------------------------------------
            name_korean = q_profile.name_korean
            #--------------------------------------------------------------------------------------------------------------------------
            # 사용 크레딧
            if credit_used_str is not None and credit_used_str != '':
                credit_used = float(credit_used_str)
                credit_used_type = credit_used
            else:
                credit_used = None
                credit_used_type = 1
            #--------------------------------------------------------------------------------------------------------------------------
            # 입사일 정보
            q_hrlayout_highest = get_my_highest_q_hrlayout_among_many(q_profile)
            # 문서포맷
            q_document_format = HR_Document_Format.objects.filter(Q(check_discard=False) & Q(type_format='vacation_plan')).last()
            # 승인프로세스
            data = {
                'owner': q_owner,
                'hrlayout_applicant': q_hrlayout_highest,
                'status_document_approval_process': 'APPROVED', #('APPROVED', '승인완료'),  # 4 success
                'check_process_completed': True,
                'document_format': q_document_format,
            }
            q_hrapproval = HR_Document_Approval_Management.objects.create(**data)

            # 프로필에 근무년수 업데이트 하기
