def hr_vacation_control_activate_issued_vacation_modification_view(request, q_mysettings_hr):
    q_vacation_issued_id_str = request.POST.get('button-hr-vacation-control-vacation-issued-modify-activate')
    if q_vacation_issued_id_str is None or q_vacation_issued_id_str == '':
        messages.warning(request, f'선택한 발행된 휴가 정보가 없습니다. 관리자에게 문의하세요.')
        return False
    q_vacation_issued_id = int(q_vacation_issued_id_str)
    q_vacation_issued = Vacation_Issued.objects.get(id=q_vacation_issued_id)
    #--------------------------------------------------------------------------------------------------------------------------
    if q_mysettings_hr.vacation_issued is not None:
        if q_vacation_issued == q_mysettings_hr.vacation_issued:
            if q_mysettings_hr.check_activate_detail_vacation_issued_modification_view == True:
                check_activate_detail_vacation_issued_modification_view = False
                q_vacation_issued = None
            else:
                check_activate_detail_vacation_issued_modification_view = True
        else:
            check_activate_detail_vacation_issued_modification_view = True
    else:
        check_activate_detail_vacation_issued_modification_view = True
    data = {
        'vacation_issued': q_vacation_issued,
        'check_activate_detail_vacation_issued_modification_view': check_activate_detail_vacation_issued_modification_view,
        'check_activate_detail_vacation_issued_revival_view': False,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True


#--------------------------------------------------------------------------------------------------------------------------
# 발행한 멤버 휴가 수정하기 업데이트
# 사용불가시 credit => 0
#--------------------------------------------------------------------------------------------------------------------------
def hr_vacation_control_update_issued_vacation_modification(request, q_mysettings_hr, status):
    check_update_status = 'update' # create or update
    q_vacation_control = q_mysettings_hr.vacation_control
    # 선택한 Vacation Issue Query 찾기
    q_vacation_issued_id_str = request.POST.get('button-hr-vacation-control-vacation-issued-modify-update')
    if q_vacation_issued_id_str is None or q_vacation_issued_id_str == '':
        messages.warning(request, f'선택한 발행된 휴가 정보가 없습니다. 관리자에게 문의하세요.')
        return False
    q_vacation_issued_id = int(q_vacation_issued_id_str)
    q_vacation_issued = Vacation_Issued.objects.get(id=q_vacation_issued_id)
    #--------------------------------------------------------------------------------------------------------------------------
    # Vacation Type
    vacation_type_str = q_vacation_issued.vacation_type
    # Check Valid 획득
    check_valid_after_str = request.POST.get('text_vacation_control_issued_vacation_availability_modification')
    check_valid_before = q_vacation_issued.check_valid
    #--------------------------------------------------------------------------------------------------------------------------
    # Vacation Credit
    credit_str = request.POST.get('text_vacation_control_issued_vacation_credit_modification')
    vacation_credit_before = q_vacation_issued.credit
    if vacation_type_str == 'VC_REGULAR':
        vacation_credit_after = float(credit_str)
    else:
        if check_valid_after_str == 'true':
            vacation_credit_after = 1
        else:
            vacation_credit_after = 0
    #--------------------------------------------------------------------------------------------------------------------------
    # Check Valid 계산
    if check_valid_after_str == 'true':
        check_valid_after = True
        if vacation_credit_after == 0:
            messages.warning(request, f'선택한 발행된 휴가의 Credit이 0인 상태로는 사용가능 상태로 변경 불가능합니다.')
            return False
        check_valid = True
    else:
        check_valid_after = False
        if vacation_credit_before == 0 and vacation_credit_after > 0:  # 사용불가상태에서 Credit만 0 에서 다른 숫자로 변경시 자동으로 상태를 사용가능으로 변경
            if vacation_credit_after == 1:
                messages.success(request, f'선택한 발행된 휴가의 Credit을 {vacation_credit_after} 만큼 부여하여 사용가능 상태로 변경되었습니다.')
            else:
                messages.success(request, f'선택한 발행된 휴가의 Credit을 {vacation_credit_after} 만큼 부여하여 일부사용가능 상태로 변경되었습니다.')
            check_valid = True
        else:
            # check_valid == False로 세팅, Credit == 0 으로 변경
            check_valid = False
            vacation_credit_after = 0
            messages.success(request, f'선택한 발행된 휴가의 Credit이 0인 사용불가능 상태로 변경되었습니다.')
    if vacation_credit_after == 0:  # Credit을 0으로 업데이트시 무조건 상태를 사용불가로 변경
        check_valid = False
    #--------------------------------------------------------------------------------------------------------------------------
    # Check Underapproval 정보획득
    check_underapproval_str = request.POST.get('text_vacation_control_issued_vacation_underapproval_modification')
    if check_underapproval_str == 'true':
        status = 'UNDERAPPROVAL'
    else:
        status = 'VALID'
    #--------------------------------------------------------------------------------------------------------------------------
    # 휴가계획서 연결여부 확인
    list_linked_vacation_plan = q_vacation_issued.list_linked_vacation_plan
    print('list_linked_vacation_plan', list_linked_vacation_plan)
    if list_linked_vacation_plan is not None:
        if len(list_linked_vacation_plan) == 0:
            list_linked_vacation_plan = None
        else:
            # 등록된 휴가계획서가 파기된거면 삭제
            for vacation_plan_linked_id in list_linked_vacation_plan:
                q_vacation_plan_linked = Vacation_Plan.objects.get(id=vacation_plan_linked_id)
                if q_vacation_plan_linked.check_discard == True or q_vacation_plan_linked.hrapproval.status_document_approval_process == 'CANCEL':
                    list_linked_vacation_plan.remove(vacation_plan_linked_id)
            if len(list_linked_vacation_plan) == 0:
                list_linked_vacation_plan = None
    #--------------------------------------------------------------------------------------------------------------------------
    # Vacation_Issued 업데이트
    data = {
        'credit': vacation_credit_after,
        'status': status,
        'check_modified_manually': True,
        'list_linked_vacation_plan': list_linked_vacation_plan,
    }
    if status == 'with_request':
        data['status_vacation_issued_requested_to_hr'] = STATUS_MY_VACATION_ISSUED_REQUEST_TO_HR[3][0]
    if status == 'without_request':
        data['status_vacation_issued_requested_to_hr'] = STATUS_MY_VACATION_ISSUED_REQUEST_TO_HR[0][0]
        data['check_hr_vc_issued_request_to_hr_activated'] = False
    Vacation_Issued.objects.filter(id=q_vacation_issued.id).update(**data)
    q_vacation_issued.refresh_from_db()
    #--------------------------------------------------------------------------------------------------------------------------
    # Vacation_Control 업데이트
    if status == 'with_request':
        data = {
            'check_hr_vc_issued_request_to_hr_responsed': True,
        }
        Vacation_Control.objects.filter(id=q_vacation_control.id).update(**data)
        messages.success(request, f'발행된 휴가 Trouble에 대한 대응조치를 완료하였습니다.')
    if status == 'without_request':
        data = {
            'check_hr_vc_issued_request_to_hr_activated': False,
            'check_hr_vc_issued_request_to_hr_responsed': False,
        }
        Vacation_Control.objects.filter(id=q_vacation_control.id).update(**data)
        messages.success(request, f'발행된 휴가 내용을 수정하였습니다.')
    q_vacation_control.refresh_from_db()
    #--------------------------------------------------------------------------------------------------------------------------
    # Vacation Control 사용가능휴가개수 Update
    update_hr_vacation_control_overall(q_vacation_control)

    # hr_vacation_control_calculate_vacation_numbers(check_update_status, q_vacation_control, q_vacation_issued, vacation_type_str, vacation_credit_before, vacation_credit_after, check_valid_before, check_valid_after)
    data = {
        'check_activate_detail_vacation_issued_modification_view': False,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True


