def hr_vacation_issued_control_confirm_response_trouble_view(request, q_mysettings_hr):
    q_vacation_issued_id_str = request.POST.get('button-hr-vacation-control-vacation-issued-response-confirm')
    if q_vacation_issued_id_str is None or q_vacation_issued_id_str == '':
        messages.warning(request, f'선택한 발행된 휴가 정보가 없습니다. 관리자에게 문의하세요.')
        return False
    q_vacation_issued_id = int(q_vacation_issued_id_str)
    q_vacation_issued = Vacation_Issued.objects.get(id=q_vacation_issued_id)
    #--------------------------------------------------------------------------------------------------------------------------
    response_contents_str = request.POST.get('text-hr-vacation-control-vacation-issued-response-contents')
    if response_contents_str is None or response_contents_str == '':
        messages.warning(request, f'응답내용을 입력하지 않았습니다.')
        return False
    print('response_contents_str', response_contents_str)
    dict_request_for_my_issued_vc_trouble = q_vacation_issued.dict_request_for_my_issued_vc_trouble
    print('dict_request_for_my_issued_vc_trouble', dict_request_for_my_issued_vc_trouble)
    if dict_request_for_my_issued_vc_trouble is None:
        dict_request_for_my_issued_vc_trouble = {}
    num_conversation = len(dict_request_for_my_issued_vc_trouble)
    k_member_name = f'({num_conversation + 1}){q_mysettings_hr.owner.profile.name_korean}'
    print('k_member_name', k_member_name)
    dict_request_for_my_issued_vc_trouble[k_member_name] = response_contents_str
    print('dict_request_for_my_issued_vc_trouble', dict_request_for_my_issued_vc_trouble)
    data = {
        'dict_request_for_my_issued_vc_trouble': dict_request_for_my_issued_vc_trouble,
    }
    Vacation_Issued.objects.filter(id=q_vacation_issued.id).update(**data)
    messages.success(request, f'발행된 휴가 Trouble에 대한 답변을 등록하였습니다. Update를 눌러 문제해결 요청에 대한 대응조치를 완료하세요')
    return True


#--------------------------------------------------------------------------------------------------------------------------
# 발행한 휴가 인사팀에서 마지막에 등록한 응답내용 지우기
#--------------------------------------------------------------------------------------------------------------------------
def hr_vacation_issued_control_confirm_response_trouble_delete_comment(request, q_mysettings_hr):
    q_vacation_issued_id_str = request.POST.get('button-hr-vacation-control-vacation-issued-response-delete-last-comment')
    if q_vacation_issued_id_str is None or q_vacation_issued_id_str == '':
        messages.warning(request, f'선택한 발행된 휴가 정보가 없습니다. 관리자에게 문의하세요.')
        return False
    q_vacation_issued_id = int(q_vacation_issued_id_str)
    q_vacation_issued = Vacation_Issued.objects.get(id=q_vacation_issued_id)
    #--------------------------------------------------------------------------------------------------------------------------
    dict_request_for_my_issued_vc_trouble = q_vacation_issued.dict_request_for_my_issued_vc_trouble
    print('dict_request_for_my_issued_vc_trouble', dict_request_for_my_issued_vc_trouble)
    dict_request_for_my_issued_vc_trouble.popitem()
    print('dict_request_for_my_issued_vc_trouble', dict_request_for_my_issued_vc_trouble)
    data = {
        'dict_request_for_my_issued_vc_trouble': dict_request_for_my_issued_vc_trouble,
    }
    if len(dict_request_for_my_issued_vc_trouble) == 0:
        data['check_report_trouble_submitted'] = False
    Vacation_Issued.objects.filter(id=q_vacation_issued.id).update(**data)
    if len(dict_request_for_my_issued_vc_trouble) == 0:
        data = {
            'check_report_trouble_submitted': False,
        }
        Vacation_Control.objects.filter(id=q_vacation_issued.vacation_control.id).update(**data)
    return True






