#--------------------------------------------------------------------------------------------------------------------------
# 발행한 휴가 인사팀 응답 내용 등록하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_vacation_plan_coummunication_register_talk_for_reference(request, q_mysettings_xxx, where_am_i):
    q_vacation_plan_id_str = request.POST.get('button-hr-vacation-control-vacation-plan-response-confirm')
    if q_vacation_plan_id_str is None or q_vacation_plan_id_str == '':
        messages.warning(request, f'선택한 휴가계획서 정보가 없습니다. 관리자에게 문의하세요.')
        return False
    q_vacation_plan_id = int(q_vacation_plan_id_str)
    q_vacation_plan = Vacation_Plan.objects.get(id=q_vacation_plan_id)
    #--------------------------------------------------------------------------------------------------------------------------
    response_contents_str = request.POST.get('text-hr-vacation-control-vacation-plan-response-contents')
    if response_contents_str is None or response_contents_str == '':
        messages.warning(request, f'응답내용을 입력하지 않았습니다.')
        return False
    # print('response_contents_str', response_contents_str)
    dict_request_talk_for_reference = q_vacation_plan.dict_request_talk_for_reference
    # print('dict_request_talk_for_reference', dict_request_talk_for_reference)
    if dict_request_talk_for_reference is None:
        dict_request_talk_for_reference = {}
    num_conversation = len(dict_request_talk_for_reference)
    k_member_name = f'({num_conversation + 1}){q_mysettings_xxx.owner.profile.name_korean}'
    dict_request_talk_for_reference[k_member_name] = response_contents_str
    #--------------------------------------------------------------------------------------------------------------------------
    data = {
        'dict_request_talk_for_reference': dict_request_talk_for_reference,
    }
    Vacation_Plan.objects.filter(id=q_vacation_plan.id).update(**data)
    data = {
        'vacation_plan': q_vacation_plan
    }
    if where_am_i == 'hr':
        HR_My_Settings.objects.filter(id=q_mysettings_xxx.id).update(**data)
    elif where_am_i == 'my':
        MY_My_Settings.objects.filter(id=q_mysettings_xxx.id).update(**data)
    return True


#--------------------------------------------------------------------------------------------------------------------------
# 발행한 휴가 인사팀 응답 내용 삭제하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_vacation_plan_communication_delete_talk_for_reference(request, q_mysettings_xxx, where_am_i):
    q_vacation_plan_id_str = request.POST.get('button-hr-vacation-control-vacation-plan-response-delete-last-comment')
    if q_vacation_plan_id_str is None or q_vacation_plan_id_str == '':
        messages.warning(request, f'선택한 휴가계획서 정보가 없습니다. 관리자에게 문의하세요.')
        return False
    q_vacation_plan_id = int(q_vacation_plan_id_str)
    q_vacation_plan = Vacation_Plan.objects.get(id=q_vacation_plan_id)
    #--------------------------------------------------------------------------------------------------------------------------
    dict_request_talk_for_reference = q_vacation_plan.dict_request_talk_for_reference
    dict_request_talk_for_reference.popitem()
    data = {
        'dict_request_talk_for_reference': dict_request_talk_for_reference,
    }
    if len(dict_request_talk_for_reference) == 0:
        data['check_hr_vc_plan_request_from_hr_activated'] = False
        messages.warning(request, f'모든 대화내용이 삭제되어 해당 휴가계획서에 대한 요청을 비활성화합니다.')
    Vacation_Plan.objects.filter(id=q_vacation_plan.id).update(**data)
    if len(dict_request_talk_for_reference) == 0:
        data = {
            'check_hr_vc_plan_request_from_hr_activated': False,
        }
        Vacation_Control.objects.filter(id=q_vacation_plan.vacation_control.id).update(**data)
        data = {
            'vacation_plan': None
        }
        if where_am_i == 'hr':
            HR_My_Settings.objects.filter(id=q_mysettings_xxx.id).update(**data)
        elif where_am_i == 'my':
            MY_My_Settings.objects.filter(id=q_mysettings_xxx.id).update(**data)
        #--------------------------------------------------------------------------------------------------------------------------
        # News 등록
        data = {
            'owner': q_vacation_plan.owner,
            'vacation_plan': q_vacation_plan,
            'news_content': LIST_MY_SYSTEM_ALERT_CONTENTS[14][0],  # ('MY_VACATION_PLAN_HR_REQUEST_CANCEL', '인사팀이 나의 휴가계획서 내용업데이트 요청 취소'),  # 14
        }
        News_My_System_Alert.objects.create(**data)
        #--------------------------------------------------------------------------------------------------------------------------
    messages.success(request, f'선택한 대화내용을 삭제하였습니다.')
    return True


