#--------------------------------------------------------------------------------------------------------------------------
# 연차 사용 진도표 표시용 Dict 데이터로 변환  dict = {q_vacation_control_id_str: percent_consumption_vacation, ...}
#--------------------------------------------------------------------------------------------------------------------------
def get_dict_usedprogress_bar_for_hr_vc_promotion_control(request, q_mysettings_hr):
    dict_vc_procress_promotion = {}
    qs_vacation_control_last = Vacation_Control.objects.filter(Q(check_discard=False) & Q(check_last=True)).order_by('owner__profile__name_korean')
    if qs_vacation_control_last is not None and len(qs_vacation_control_last) > 0:
        for q_vacation_control_last in qs_vacation_control_last:
            vc_count_revived_prev_unused_expired_total = q_vacation_control_last.vc_count_revived_prev_unused_expired_total
            vc_count_issued_total = q_vacation_control_last.vc_count_issued_total
            vc_count_used_total = q_vacation_control_last.vc_count_used_total
            if vc_count_used_total == None or vc_count_used_total == 0:
                percent_consumption = 0
            else:
                if vc_count_revived_prev_unused_expired_total is None:
                    percent_consumption = (vc_count_used_total / vc_count_issued_total) * 100
                else:
                    percent_consumption = (vc_count_used_total / (vc_count_issued_total + vc_count_revived_prev_unused_expired_total)) * 100
            dict_vc_procress_promotion[str(q_vacation_control_last.id)] = percent_consumption
            data = {
                'percent_consumption': percent_consumption,
            }
            Vacation_Control.objects.filter(id=q_vacation_control_last.id).update(**data)
    return dict_vc_procress_promotion


#--------------------------------------------------------------------------------------------------------------------------
# 연차 만료 시간표 표시용 Dict 데이터로 변환  dict = {q_vacation_control_id_str: remained_time, ...}
#--------------------------------------------------------------------------------------------------------------------------
def get_dict_deadline_bar_for_hr_vc_promotion_control(request, q_mysettings_hr):
    ls_today = datetime.date.today()
    dict_vc_deadline_promotion = {}
    qs_vacation_control_last = Vacation_Control.objects.filter(Q(check_discard=False) & Q(check_last=True)).order_by('owner__profile__name_korean')
    if qs_vacation_control_last is not None and len(qs_vacation_control_last) > 0:
        for q_vacation_control_last in qs_vacation_control_last:
            date_workingyear_end = q_vacation_control_last.date_workingyear_end
            if date_workingyear_end is None:
                # print('no dte_workingyear_end', q_vacation_control_last.owner.profile.name_korean)
                pass
            else:
                print('date_workingyear_end', type(date_workingyear_end), date_workingyear_end)
                print('ls_today', type(ls_today), ls_today)
                if date_workingyear_end < ls_today:
                    print('no date_workingyear_end < ls_today', q_vacation_control_last.owner.profile.name_korean)
                    pass
                elif date_workingyear_end == ls_today:
                    percent_deadline = 100
                    dict_vc_deadline_promotion[str(q_vacation_control_last.id)] = 100
                    data = {
                        'percent_deadline': percent_deadline,
                        'days_remained': 0,
                    }
                    Vacation_Control.objects.filter(id=q_vacation_control_last.id).update(**data)
                else:
                    # print('date_workingyear_end', date_workingyear_end)
                    delta_days_vc_remained = date_workingyear_end - ls_today
                    # print('delta_days_vc_remained', delta_days_vc_remained)
                    delta_days_vc_remained = str(delta_days_vc_remained)
                    # print('delta_days_vc_remained', delta_days_vc_remained)
                    delta_days_vc_remained = delta_days_vc_remained.split(' ')[0]
                    # print('delta_days_vc_remained', delta_days_vc_remained)
                    days_vc_remained_int = int(delta_days_vc_remained)
                    # days_vc_remained_int = int(str(delta_days_vc_remained).strip().split('day')[0]) # 'day'로 split 해야 함. days로 하면 하루 남았을 때 오류남
                    percent_deadline = (1 - (days_vc_remained_int / 365)) * 100
                    # print('percent_deadline', percent_deadline)
                    dict_vc_deadline_promotion[str(q_vacation_control_last.id)] = percent_deadline
                    # print(f'percent_deadline {q_vacation_control_last.owner.profile.name_korean}', percent_deadline)
                    data = {
                        'percent_deadline': percent_deadline,
                        'days_remained': days_vc_remained_int,
                    }
                    Vacation_Control.objects.filter(id=q_vacation_control_last.id).update(**data)
    return dict_vc_deadline_promotion



#--------------------------------------------------------------------------------------------------------------------------
# 연차사용현황판 테이블 필터링/정렬하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_vacation_control_promotion_table_filtering_or_sorting(request, q_mysettings_hr):
    status_vc_promotion_ordering_type_str = request.POST.get('select-hr-vacation-control-promotion-sort')
    if status_vc_promotion_ordering_type_str is None or status_vc_promotion_ordering_type_str == '' or status_vc_promotion_ordering_type_str == 'none':
        status_vc_promotion_ordering_type_str = None

    status_vacation_control_str = request.POST.get('select-hr-vacation-control-promotion-filter')
    if status_vacation_control_str is None or status_vacation_control_str == '' or status_vacation_control_str == 'none':
        status_vacation_control_str = None

    keyword_filtering_vc_promotion_str = request.POST.get('text-hr-vacation-control-promotion-search-keyword')
    if keyword_filtering_vc_promotion_str is None or keyword_filtering_vc_promotion_str == '' or keyword_filtering_vc_promotion_str == 'none':
        list_searched_vc_control_id_for_promotion = None
    else:
        list_searched_vc_control_id_for_promotion = []
        qs_vacation_control_last_searched = Vacation_Control.objects.filter(Q(check_discard=False) & Q(check_last=True) & Q(owner__profile__name_korean__icontains=keyword_filtering_vc_promotion_str)).order_by('owner__profile__name_korean')
        if qs_vacation_control_last_searched is None or len(qs_vacation_control_last_searched) == 0 :
            list_searched_vc_control_id_for_promotion = None
        else:
            for q_vacation_control_last_searched in qs_vacation_control_last_searched:
                if q_vacation_control_last_searched.id not in list_searched_vc_control_id_for_promotion:
                    list_searched_vc_control_id_for_promotion.append(q_vacation_control_last_searched.id)
    data = {
        'status_vacation_control': status_vacation_control_str,
        'status_vc_promotion_ordering_type': status_vc_promotion_ordering_type_str,
        'list_searched_vc_control_id_for_promotion': list_searched_vc_control_id_for_promotion,
    }
    print('data', data)
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)


