#--------------------------------------------------------------------------------------------------------------------------
 # 연차촉진 관리자 세팅값 업데이트하기
 #--------------------------------------------------------------------------------------------------------------------------
def hr_vacation_control_promotion_settings_update_by_form(request, q_mysettings_hr):
    q_hr_vacation_promotion_settings = HR_Vacation_Promotion_Settings.objects.filter(Q(check_discard=False)).last()
    form_vacation_promotion = Hr_Vacation_Promotion_Settings_Update_Form(request.POST, request.FILES, instance=q_hr_vacation_promotion_settings)
    if form_vacation_promotion.is_valid:
        form_vacation_promotion.save()
        qs_vacation_control_last = Vacation_Control.objects.filter(Q(check_discard=False) & Q(check_last=True)).order_by('owner__profile__name_korean')
        if qs_vacation_control_last is not None and len(qs_vacation_control_last) > 0:
            for q_vacation_control_last in qs_vacation_control_last:
                update_member_vacation_and_inform_to_promote_comsuming_vc(request, q_vacation_control_last.owner.profile)
        messages.success(request, f'연차 촉진 관리자 세팅값을 업데이트하였습니다.')

    return True


#--------------------------------------------------------------------------------------------------------------------------
# 연차촉진 멤버 선택하기
#--------------------------------------------------------------------------------------------------------------------------
def hr_vacation_control_promotion_select_member_vc_control(request, q_mysettings_hr):
    list_vc_control_selected_id_str = request.POST.getlist('checkbox-vc-control-promotion-select-member-vc-control-id')
    # print('list_vc_control_selected_id_str', list_vc_control_selected_id_str)
    list_vc_control_selected_id = q_mysettings_hr.list_selected_vc_control_id_for_promotion
    if list_vc_control_selected_id is None:
        list_vc_control_selected_id = []

    if 'all' in list_vc_control_selected_id_str:
        print('# 최신근무년차 멤버 휴가 컨트롤 전체 선택')
        qs_vacation_control_last = Vacation_Control.objects.filter(Q(check_discard=False) & Q(check_last=True))
        messages.success(request, f'모든 멤버를 선택하였습니다.')
    else:
        #--------------------------------------------------------------------------------------------------------------------------
        # 남은 기한 정보 확인
        remained_days_from_str = request.POST.get('button-vc-control-promotion-select-member-vc-control-days-from')
        remained_days_to_str = request.POST.get('button-vc-control-promotion-select-member-vc-control-days-to')
        # print('remained_days_from_str', remained_days_from_str)
        # print('remained_days_to_str', remained_days_to_str)

        if remained_days_from_str is not None and remained_days_from_str != '':
            remained_days_from = int(remained_days_from_str)
        else:
            remained_days_from = None
        if remained_days_to_str is not None and remained_days_to_str != '':
            remained_days_to = int(remained_days_to_str)
        else:
            remained_days_to = None
        # print('remained_days_from', remained_days_from)
        # print('remained_days_to', remained_days_to)

        if remained_days_from is not None or remained_days_to is not None:
            # print('# 둘 중 하나라도 정보가 있는 경우')
            if remained_days_from is None and remained_days_to is not None:
                # print('# ~To 정보만 있는 경우')
                qs_vacation_control_last = Vacation_Control.objects.filter(Q(check_discard=False) & Q(check_last=True) & Q(days_remained__lte=remained_days_to))
            elif remained_days_from is not None and remained_days_to is None:
                # print('# from ~ 정보만 있는 경우')
                qs_vacation_control_last = Vacation_Control.objects.filter(Q(check_discard=False) & Q(check_last=True) & Q(days_remained__gte=remained_days_from))
            else:
                # print('# from ~ to 정보 모두 있는 경우')
                qs_vacation_control_last = Vacation_Control.objects.filter(Q(check_discard=False) & Q(check_last=True) & Q(days_remained__gte=remained_days_from) & Q(days_remained__lte=remained_days_to))
        else:
            # print('# 둘 다 정보가 없는 경우')
            #--------------------------------------------------------------------------------------------------------------------------
            # print('# 선택된 멤버의 휴가 컨트롤만 선택')
            if len(list_vc_control_selected_id_str) > 0:
                list_vc_control_selected_id = list(map(int, list_vc_control_selected_id_str))
                qs_vacation_control_last = Vacation_Control.objects.filter(id__in=list_vc_control_selected_id)
                messages.success(request, f'{len(list_vc_control_selected_id)}명의 멤버를 선택하였습니다.')
            else:
                list_vc_control_selected_id = None
                messages.warning(request, f'선택된 멤버가 없습니다.')
                return False
    if qs_vacation_control_last is not None and len(qs_vacation_control_last) > 0:
        for q_vacation_control_last in qs_vacation_control_last:
            if q_vacation_control_last.id not in list_vc_control_selected_id:
                list_vc_control_selected_id.append(q_vacation_control_last.id)
    if len(list_vc_control_selected_id) == 0:
        list_vc_control_selected_id = None
    data = {
        'list_selected_vc_control_id_for_promotion': list_vc_control_selected_id,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)


