        dict_vc_usedprogress_promotion = get_dict_usedprogress_bar_for_hr_vc_promotion_control(request, q_mysettings_hr)
        dict_vc_deadline_promotion = get_dict_deadline_bar_for_hr_vc_promotion_control(request, q_mysettings_hr)

