# HR Task Project 입력
#--------------------------------------------------------------------------------------------------------------------------
def hr_task_project_register_project_by_form(request, q_mysettings_hr):
    project_name_str = request.POST.get('text-hr-task-control-project-name')
    project_name_str = project_name_str.strip()
    project_name_str = project_name_str.upper()
    status_project_str = request.POST.get('select-hr-task-control-project-status')
    date_project_start_str = request.POST.get('date_project_start')
    if date_project_start_str is not None and date_project_start_str != '':
        date_project_start = datetime.datetime.strptime(date_project_start_str, '%Y-%m-%d').date()
    else:
        date_project_start = None
    data = {
        'project_name': project_name_str,
        'status_project': status_project_str,
        'date_project_start': date_project_start,
    }
    q_project_simple = Project_Simple.objects.create(**data)
    messages.success(request, f'프로젝트를 신규등록하였습니다.')
    data = {
        'project_simple': q_project_simple,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True


#--------------------------------------------------------------------------------------------------------------------------
# HR Task Project 업데이트
# 프로젝트명 변경시 Task_Plan에 등록된 프로젝트명도 모두 변경해야 됨.
# list_dict_project_id_project_percent 안의 내용
# Check On Progress :  True : 프로젝트 개발 진행중, False: 진행중이지 않음.(개발완료, 개발중단 두 경우는 무조건 False,  그 이외의 경우에도 현재 진행중이지 않으면 False)
#--------------------------------------------------------------------------------------------------------------------------
def hr_task_project_update_project_by_form(request, q_mysettings_hr):
    q_project_simple = q_mysettings_hr.project_simple
    status_project_str = request.POST.get('status_project')
    date_project_start_str = request.POST.get('date_project_start')
    date_project_end_str = request.POST.get('date_project_end')
    # 프로젝트 종료일 지정
    if status_project_str == LIST_PROJECT_SIMPLE_STATUS[4][0] or status_project_str == LIST_PROJECT_SIMPLE_STATUS[5][0]:
        if date_project_end_str is not None and date_project_end_str != '':
            date_project_end = datetime.datetime.strptime(date_project_end_str, '%Y-%m-%d').date()
        else:
            date_project_end = q_project_simple.date_project_end
            if date_project_end is None:
                messages.warning(request, f'프로젝트 종료일을 지정하지 않았습니다.')
                return False
    else:
        if date_project_end_str is not None and date_project_end_str != '':
            date_project_end = datetime.datetime.strptime(date_project_end_str, '%Y-%m-%d').date()
        else:
            date_project_end = q_project_simple.date_project_end
    # 프로젝트 시작일 지정
    if date_project_start_str is not None and date_project_start_str != '':
        date_project_start = datetime.datetime.strptime(date_project_start_str, '%Y-%m-%d').date()
    else:
        date_project_start = q_project_simple.date_project_start
    # 프로젝트 이름 및 상태 저장
    form_hr_task_project_update = HR_Task_Project_Update_Form(request.POST, instance=q_mysettings_hr.project_simple)
    if form_hr_task_project_update.is_valid():
        form_hr_task_project_update.save()
        q_project_simple.refresh_from_db()
    # Project simple 정보 저장
    data = {
        'date_project_start': date_project_start,
        'date_project_end': date_project_end,
    }
    Project_Simple.objects.filter(id=q_project_simple.id).update(**data)
    # 기작성한 Task Plan의 Project 이름 업데이트
    q_project_simple_selected = q_mysettings_hr.project_simple
    project_name_original = q_project_simple_selected.project_name
    project_name_str = request.POST.get('project_name')
    qs_task_plan_all = Task_Plan.objects.filter(check_discard=False)
    if qs_task_plan_all is not None and len(qs_task_plan_all) > 0:
        for q_task_plan_all in qs_task_plan_all:
            list_dict_project_id_project_percent = q_task_plan_all.list_dict_project_id_project_percent
            if list_dict_project_id_project_percent is not None and len(list_dict_project_id_project_percent) > 0:
                for dict_project_id_project_percent in list_dict_project_id_project_percent:
                    if dict_project_id_project_percent['project_name'] == project_name_original:
                        dict_project_id_project_percent['project_name'] = project_name_str
                data = {
                    'list_dict_project_id_project_percent': list_dict_project_id_project_percent,
                }
                Task_Plan.objects.filter(id=q_task_plan_all.id).update(**data)
    # Mysettings 업데이트
    data = {
        'project_simple': q_project_simple,
        'status_task_project_control_submenu': LIST_TASK_PROJECT_CONTROL_SUBMENU[1][0],
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True


