#--------------------------------------------------------------------------------------------------------------------------
def hr_task_control_task_plan_search_by_keyword(request, q_mysettings_hr):
    search_keyword_str = request.POST.get('text-hr-task-control-task-plan-search-keyword')
    if search_keyword_str is None or search_keyword_str == '':
        list_searched_task_plan_id = None
        messages.success(request, f'검색을 리셋하였습니다.')
    else:
        list_searched_task_plan_id = []
        qs_task_plan = Task_Plan.objects.filter(Q(check_discard=False) & Q(owner__profile__name_korean__icontains=search_keyword_str))
        if qs_task_plan is not None and len(qs_task_plan) > 0:
            for q_task_plan in qs_task_plan:
                if q_task_plan.id not in list_searched_task_plan_id:
                    list_searched_task_plan_id.append(q_task_plan.id)
            messages.success(request, f'{len(list_searched_task_plan_id)}개 검색결과가 매칭되었습니다.')
        else:
            list_searched_task_plan_id = None
    print('list_searched_task_plan_id', list_searched_task_plan_id)
    data = {
        'list_searched_task_plan_id': list_searched_task_plan_id,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)


