#--------------------------------------------------------------------------------------------------------------------------
# Task Plan Modal Activate by multi-selected member
#--------------------------------------------------------------------------------------------------------------------------
def hr_task_control_task_plan_activate_register_modal_view_by_multi_selection(request, q_mysettings_hr):
    selected_year = q_mysettings_hr.selected_year
    selected_month = q_mysettings_hr.selected_month
    list_selected_task_plan_id_str = request.POST.getlist('checkbox-hr-task-plan-owner-select')
    if list_selected_task_plan_id_str is None or len(list_selected_task_plan_id_str) == 0:
        messages.warning(request, f'선택한 멤버 업무관리 쿼리가 없습니다.')
        return False
    elif 'all' in list_selected_task_plan_id_str:
        qs_task_plan_selected_month = Task_Plan.objects.filter(Q(check_discard=False) & Q(date_deadline_task_submission__year=selected_year) & Q(date_deadline_task_submission__month=selected_month)).order_by('owner__profile__name_korean')
        if qs_task_plan_selected_month is not None and len(qs_task_plan_selected_month) > 0:
            list_selected_task_plan_id = []
            for q_task_plan_selected_month in qs_task_plan_selected_month:
                list_selected_task_plan_id.append(q_task_plan_selected_month.id)
    else:
        list_selected_task_plan_id = list(map(int, list_selected_task_plan_id_str))

    if list_selected_task_plan_id is None or len(list_selected_task_plan_id) == 0:
        messages.warning(request, f'선택된 멤버의 업무관리 쿼리가 없습니다.')
        return False
    # 선택한 멤버 업무쿼리 프로젝트별 참여비율 입력 모달 활성화하기
    qs_task_plan_selected = Task_Plan.objects.filter(id__in=list_selected_task_plan_id)
    if qs_task_plan_selected is not None and len(qs_task_plan_selected) > 0:
        for q_task_plan_selected in qs_task_plan_selected:
            data = {
                'check_activate_submission_form': True,
                'check_activate_submission_form_enforced': True,
            }
            Task_Plan.objects.filter(id=q_task_plan_selected.id).update(**data)
            #--------------------------------------------------------------------------------------------------------------------------
            # News 등록
            data = {
                'owner': q_task_plan_selected.owner,
                'task_plan': q_task_plan_selected,
                'news_content': LIST_MY_SYSTEM_ALERT_CONTENTS[47][0],  # ('MY_TASK_PLAN_MONTHLY_ACTIVATED_BY_HR', '월간 프로젝트별 참여비율 입력 요청됨'),  # 47
            }
            News_My_System_Alert.objects.create(**data)
            #--------------------------------------------------------------------------------------------------------------------------
        messages.success(request, f'{len(qs_task_plan_selected)}명에 대하여 {selected_year}년 {selected_month}월달 프로젝트 참여비율 입력창을 활성화 하였습니다.')
    # 선택한 멤버 업무쿼리 리스트에 저장하기
    data = {
        'list_selected_task_plan_id': None,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True


