#--------------------------------------------------------------------------------------------------------------------------
# Taks Plan HR Modify by 개별 Confirm
#--------------------------------------------------------------------------------------------------------------------------
def hr_task_control_task_plan_modification_confirm(request, q_mysettings_hr):
    list_dict_project_id_project_percent = q_mysettings_hr.task_plan.list_dict_project_id_project_percent
    list_modified_task_project_percent_str = request.POST.getlist('input-hr-task-plan-project-percent-modified')
    list_modified_task_project_name_str = request.POST.getlist('input-hr-task-plan-project-name-modified')
    # print('list_dict_project_id_project_percent', list_dict_project_id_project_percent)
    # print('list_modified_task_project_percent_str', list_modified_task_project_percent_str)
    # print('list_modified_task_project_name_str', list_modified_task_project_name_str)
    for i in range(len(list_modified_task_project_percent_str)):
        if list_modified_task_project_percent_str[i] == '':
            list_modified_task_project_percent_str[i] = 0
    if list_modified_task_project_percent_str is None or '' in list_modified_task_project_percent_str:
        messages.warning(request, f'입력값이 정확하지 않습니다.')
        return False
    list_modified_task_project_percent = list(map(int, list_modified_task_project_percent_str))
    if sum(list_modified_task_project_percent) != 100:
        messages.warning(request, f'입력한 프로젝트별 참여율 합이 100이 아닙니다. 다시 작성하세요.')
        return False
    list_dict_project_id_project_percent_new = []
    i = 0
    for task_project_name_str in list_modified_task_project_name_str:
        data = {
            'id': i,
            'project_name': task_project_name_str,
            'participant_percent': list_modified_task_project_percent[i],
        }
        list_dict_project_id_project_percent_new.append(data)
        i = i + 1
    # print('list_dict_project_id_project_percent_new', list_dict_project_id_project_percent_new)
    data = {
        'list_dict_project_id_project_percent': list_dict_project_id_project_percent_new,
    }
    Task_Plan.objects.filter(id=q_mysettings_hr.task_plan.id).update(**data)
    messages.success(request, f'성공적으로 {q_mysettings_hr.task_plan.owner.profile.name_korean}님의 프로젝트 참여율을 수정하였습니다.')
    data = {
        'check_activate_task_plan_modify_view': False,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True


