#--------------------------------------------------------------------------------------------------------------------------
# 선택한 년도/달에 해당하는 선택된 프로필 멤버의 업무관리쿼리 찾기/생성하기
#--------------------------------------------------------------------------------------------------------------------------
def get_my_task_plan_of_this_month_using_profile(request, q_profile, selected_year, selected_month):
    ls_today = datetime.date.today()
    q_hrlayout = get_my_highest_q_hrlayout_among_many(q_profile)
    qs_hrlayout = HR_Layout.objects.filter(Q(check_discard=False) & Q(member__user=q_profile.user))
    #--------------------------------------------------------------------------------------------------------------------------
    # 선택한 날짜에 해당하는 프로필 유저의 업무관리 쿼리 찾기
    q_task_plan_user = Task_Plan.objects.filter(Q(check_discard=False) & Q(owner=q_profile.user) & Q(date_deadline_task_submission__year=selected_year) & Q(date_deadline_task_submission__month=selected_month)).last()
    # print('///////////////////////////////////////////// q_task_plan_user 1', q_task_plan_user)
    #--------------------------------------------------------------------------------------------------------------------------
    # 선택한 날짜에 해당하는 업무관리 쿼리가 없는 경우, 업무관리쿼리 생성
    if q_task_plan_user is None:
        print('q_task_plan_user is None!!!!!')
        if selected_month in [1,3,5,7,8,10,12]:
            ls_day_end = 31
        elif selected_month in [4, 6, 9, 11]:
            ls_day_end = 30
        else:
            ls_day_end = 28
        #--------------------------------------------------------------------------------------------------------------------------
        # # 입력받기 마감일 찾기
        date_monthly_end = datetime.date(selected_year, selected_month, ls_day_end)
        date_deadline_task_submission = date_monthly_end
        #--------------------------------------------------------------------------------------------------------------------------
        # 입력받기 시작일 찾기
        date_start_task_submission = date_monthly_end
        i = 0
        j = 0
        while i < 3:
            # print('i, j', i, j)
            if j > 0:
                day_j = datetime.timedelta(days=j)
                date_start_task_submission = date_monthly_end - day_j
            # print('date_start_task_submission', date_start_task_submission)
            list_holiday_date = calculate_list_holidays_between_vacation_start_date_and_end_date('VC_REGULAR', date_start_task_submission, date_monthly_end)
            # print('list_holiday_date', list_holiday_date)
            if date_start_task_submission not in list_holiday_date:
                # print('no holiday, add date')
                i = i + 1
            j = j + 1

        dict_project_id_project_percent = {}
        dict_project_id_project_percent['id'] = 0
        dict_project_id_project_percent['project_name'] = 'none'
        dict_project_id_project_percent['participant_percent'] = 0
        data = {
            'owner': q_profile.user,
            'hrlayout': q_hrlayout,
            'list_dict_project_id_project_percent': [dict_project_id_project_percent],
            'num_of_involved_project': 1,
            'date_deadline_task_submission': date_deadline_task_submission,
            'date_start_task_submission': date_start_task_submission,
        }
        if qs_hrlayout is not None and len(qs_hrlayout) == 1:
            # 포지션 1개인 경우
            pass
        elif qs_hrlayout is not None and len(qs_hrlayout) > 1:
            # 포지션 2개 이상인 경우
            list_hrlayout_id = []
            for q_hrlayout in qs_hrlayout:
                list_hrlayout_id.append(q_hrlayout.id)
            data['list_hrlayout_id'] = list_hrlayout_id
        q_task_plan_user = Task_Plan.objects.create(**data)
    #--------------------------------------------------------------------------------------------------------------------------
    # print('///////////////////////////////////////////// q_task_plan_user 2', q_task_plan_user)
    return q_task_plan_user



