def get_project_simple_on_progress_selected_month(request, selected_year, selected_month):
    if selected_month in [1, 3, 5, 7, 8, 10, 12]:
        selected_day_start = 31
    elif selected_month in [4, 6, 9, 11]:
        selected_day_start = 30
    else:
        selected_day_start = 28
    selected_date_start = datetime.date(selected_year, selected_month, selected_day_start)
    selected_date_end = datetime.date(selected_year, selected_month, 1)
    # print('selected_date_start', selected_date_start)
    # print('selected_date_end', selected_date_end)
    # qs_project_simple_onprogress = Project_Simple.objects.filter(Q(check_discard=False) & Q(date_project_start__lte=selected_date_start) & (Q(date_project_end__isnull=True) | Q(date_project_end__gte=selected_date_end))).order_by('project_name')
