#--------------------------------------------------------------------------------------------------------------------------
# # 선택한 팀 기준으로 프로젝트별 참여율 리스트 구하기
#--------------------------------------------------------------------------------------------------------------------------
def get_list_project_analysis_pie_chart_selected_team_selected_period(request, q_mysettings_hr):
    ls_today = datetime.date.today()
    ls_year = ls_today.year
    ls_month = ls_today.month
    q_project_simple = q_mysettings_hr.project_simple
    q_team = q_mysettings_hr.team
    date_project_analysis_start = q_mysettings_hr.date_project_analysis_start
    date_project_analysis_end = q_mysettings_hr.date_project_analysis_end
    #--------------------------------------------------------------------------------------------------------------------------
    # 시작일/종료일 기준 Task Plan 쿼리셋 구하기
    qs_task_plan_selected_month = Task_Plan.objects.filter(Q(check_discard=False) & Q(check_submitted=True) & Q(date_deadline_task_submission__gte=date_project_analysis_start) & Q(date_deadline_task_submission__lte=date_project_analysis_end))
    print('length qs_task_plan_selected_month', len(qs_task_plan_selected_month))
    if qs_task_plan_selected_month is None and len(qs_task_plan_selected_month) == 0:
        return False
    #--------------------------------------------------------------------------------------------------------------------------
    dict_project_name_participant_percent = {}
    list_project_name = []

    dict_team_participant = {} # 선택한 팀이 관여한 프로젝트:참여율 정보 수집
    list_dict_involved_team_id_name = [] # 선택한 기간 내에 참여한 모든 팀 ID : 팀 Name
    list_team_name = []

    for q_task_plan_selected_month in qs_task_plan_selected_month:
        list_dict_project_id_project_percent = q_task_plan_selected_month.list_dict_project_id_project_percent
        if q_task_plan_selected_month.hrlayout is not None:
            if q_task_plan_selected_month.hrlayout.team is not None:
                list_team_name.append(q_task_plan_selected_month.hrlayout.team.team_name)
                if {'id':q_task_plan_selected_month.hrlayout.team.id, 'team_name':q_task_plan_selected_month.hrlayout.team.team_name} not in list_dict_involved_team_id_name:
                    list_dict_involved_team_id_name.append({'id':q_task_plan_selected_month.hrlayout.team.id, 'team_name':q_task_plan_selected_month.hrlayout.team.team_name})
            if list_dict_project_id_project_percent is not None and len(list_dict_project_id_project_percent) > 0:
                    for dict_project_id_project_percent in list_dict_project_id_project_percent:
                        project_name_str = dict_project_id_project_percent['project_name']
                        if project_name_str not in list_project_name:
                            list_project_name.append(project_name_str)
    # print('list_dict_involved_team_id_name', list_dict_involved_team_id_name)

    if list_team_name is None or len(list_team_name) == 0:
        return False
    for team_name in list_team_name:
        dict_team_participant.setdefault(team_name, [])
    for project_name_str in list_project_name:
        dict_project_name_participant_percent.setdefault(project_name_str, [])

    for q_task_plan_selected_month in qs_task_plan_selected_month:
        if q_task_plan_selected_month.hrlayout is not None:
            if q_task_plan_selected_month.hrlayout.team == q_team:
                list_dict_project_id_project_percent = q_task_plan_selected_month.list_dict_project_id_project_percent
                for dict_project_id_project_percent in list_dict_project_id_project_percent:
                    project_name_str = dict_project_id_project_percent['project_name']
                    if project_name_str not in list_project_name:
                        list_project_name.append(project_name_str)
                    participant_percent_int = dict_project_id_project_percent['participant_percent']
                    # print('project_name_str', project_name_str)
                    # print('participant_percent_int', participant_percent_int)
                    dict_project_name_participant_percent[project_name_str].append(participant_percent_int)
    # print('dict_project_name_participant_percent', dict_project_name_participant_percent)
    #--------------------------------------------------------------------------------------------------------------------------
    dict_project_collection_sum = {}
    list_project_sum = []
    for k, v_list in dict_project_name_participant_percent.items():
        sum_v_list = sum(v_list)
        list_project_sum.append(sum_v_list)
        dict_project_collection_sum[k]=sum_v_list

    dict_project_collection_radio = {}
    project_total = sum(list_project_sum)
    for k, v_sum in dict_project_collection_sum.items():
        if v_sum != 0:
            v_ratio = v_sum/project_total
            v_ratio = round(v_ratio, 3)
        else:
            v_ratio = 0
        dict_project_collection_radio[k]=v_ratio

    list_project_analysis_pie_chart_selected_team_data = []
    for k, v_ratio in dict_project_collection_radio.items():
        # print('k : ', k, 'v_ratio : ', v_ratio)
        list_project_analysis_pie_chart_selected_team_data.append({'name': k, 'y': v_ratio})
    #--------------------------------------------------------------------------------------------------------------------------
    data = {
        'list_dict_involved_team_id_name': list_dict_involved_team_id_name,
        'list_project_analysis_pie_chart_selected_team_data': list_project_analysis_pie_chart_selected_team_data,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    q_mysettings_hr.refresh_from_db()
    return True


#--------------------------------------------------------------------------------------------------------------------------
# Task Plan 분석 by Team 선택
#--------------------------------------------------------------------------------------------------------------------------
def hr_task_control_project_participant_analysis_by_team_name(request, q_mysettings_hr):
    selected_year = q_mysettings_hr.selected_year
    selected_month = q_mysettings_hr.selected_month
    if selected_month in [1, 3, 5, 7, 8, 10, 12]:
        day_project_analysis_end = 31
    elif selected_month in [4, 6, 9, 11]:
        day_project_analysis_end = 30
    else:
        day_project_analysis_end = 28
    date_project_analysis_start = datetime.date(selected_year, selected_month, 1)
    date_project_analysis_end = datetime.date(selected_year, selected_month, day_project_analysis_end)
    #--------------------------------------------------------------------------------------------------------------------------
    # 팀 찾기
    q_team_id_str = request.POST.get('button-hr-task-control-select-team-analysis')
    if q_team_id_str is None or q_team_id_str == '':
        return False
    q_team_id_int = int(q_team_id_str)
    q_team = Team.objects.get(id=q_team_id_int)
    print('선택한 팀', q_team)
    #--------------------------------------------------------------------------------------------------------------------------
    # 팀원 찾기
    qs_hrlayout_team = HR_Layout.objects.filter(Q(check_discard=False) & Q(team=q_team))
    if qs_hrlayout_team is None or len(qs_hrlayout_team) == 0:
        return False
    list_selected_team_member_id = []
    for q_hrlayout_team in qs_hrlayout_team:
        if q_hrlayout_team.member.id not in list_selected_team_member_id:
            list_selected_team_member_id.append(q_hrlayout_team.member.id)

    #--------------------------------------------------------------------------------------------------------------------------
    # Mysettings 업데이트
    data = {
        'team': q_team,
        'date_project_analysis_start': date_project_analysis_start,
        'date_project_analysis_end': date_project_analysis_end,
        'list_selected_team_member_id': list_selected_team_member_id,
        'task_plan': None,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    q_mysettings_hr.refresh_from_db()
    #--------------------------------------------------------------------------------------------------------------------------
    # 선택한 팀/날짜 기준으로 선택기간동안의 프로젝트별 참여율 리스트 dict 구하기
    get_list_project_analysis_pie_chart_selected_team_selected_period(request, q_mysettings_hr)
