###########################################################################################################################
#
#                                          Chart Data 구하기 - Member 기준
#
###########################################################################################################################

def get_list_project_analysis_pie_chart_selected_project_selected_period_member(request, q_mysettings_xxx, where_am_i, q_user):
    ls_today = datetime.date.today()
    ls_year = ls_today.year
    ls_month = ls_today.month
    if ls_month in [1, 3, 5, 7, 8, 10, 12]:
        ls_day_last = 31
    elif ls_month in [4, 6, 9, 11]:
        ls_day_last = 30
    else:
        ls_day_last = 28
    time_delta_365days = datetime.timedelta(days=365)
    time_delta_7330days = datetime.timedelta(days=730)
    ls_today_1y_ago = ls_today - time_delta_365days
    ls_today_2y_ago = ls_today - time_delta_7330days
    selected_year = q_mysettings_xxx.selected_year
    selected_month = q_mysettings_xxx.selected_month
    if selected_month in [1, 3, 5, 7, 8, 10, 12]:
        selected_day_last = 31
    elif selected_month in [4, 6, 9, 11]:
        selected_day_last = 30
    else:
        selected_day_last = 28

    #--------------------------------------------------------------------------------------------------------------------------
    if where_am_i == 'hr':
        date_project_analysis_end = datetime.date(selected_year, selected_month, selected_day_last)
        date_project_analysis_start = date_project_analysis_end - time_delta_365days

    elif where_am_i == 'my':
        date_project_analysis_end = datetime.date(ls_year, ls_month, ls_day_last)
        date_project_analysis_start = date_project_analysis_end - time_delta_365days

    print('date_project_analysis_start', date_project_analysis_start)
    print('date_project_analysis_end', date_project_analysis_end)
    #--------------------------------------------------------------------------------------------------------------------------
    # 시작일/종료일 기준 Task Plan 쿼리셋 구하기
    qs_task_plan_selected_month = Task_Plan.objects.filter(Q(check_discard=False) & Q(owner=q_user) & Q(check_submitted=True) & Q(date_deadline_task_submission__gte=date_project_analysis_start) & Q(date_deadline_task_submission__lte=date_project_analysis_end)).order_by('date_deadline_task_submission')
    print('///////////////////// length qs_task_plan_selected_month', len(qs_task_plan_selected_month))
    if qs_task_plan_selected_month is None and len(qs_task_plan_selected_month) == 0:
        return False
    #--------------------------------------------------------------------------------------------------------------------------
    dict_project_name_participant_percent = {}
    list_project_name = []

    for q_task_plan_selected_month in qs_task_plan_selected_month:
        list_dict_project_id_project_percent = q_task_plan_selected_month.list_dict_project_id_project_percent
        if list_dict_project_id_project_percent is not None and len(list_dict_project_id_project_percent) > 0:
            for dict_project_id_project_percent in list_dict_project_id_project_percent:
                project_name_str = dict_project_id_project_percent['project_name']
                if project_name_str not in list_project_name:
                    list_project_name.append(project_name_str)

    for project_name_str in list_project_name:
        dict_project_name_participant_percent.setdefault(project_name_str, [])
    # print('dict_project_name_participant_percent', dict_project_name_participant_percent)
    print('list_project_name', list_project_name)

    import copy
    i = 0
    for q_task_plan_selected_month in qs_task_plan_selected_month:
        list_project_name_temp = copy.deepcopy(list_project_name)  # 그냥 list_project_name_temp = list_project_name 한다고 복사되지 않는다. 같다는 의미이다. 복사하려면 copy 함수를 사용해야 한다.
        print('list_project_name_temp start ////////////////////////', i, list_project_name_temp)

        list_dict_project_id_project_percent = q_task_plan_selected_month.list_dict_project_id_project_percent
        if list_dict_project_id_project_percent is not None and len(list_dict_project_id_project_percent) > 0:
            for dict_project_id_project_percent in list_dict_project_id_project_percent:
                project_name_str = dict_project_id_project_percent['project_name']
                participant_percent_int = dict_project_id_project_percent['participant_percent']
                print('project_name_str', project_name_str)
                print('participant_percent_int', participant_percent_int)

                dict_project_name_participant_percent[project_name_str].append(participant_percent_int)

                if project_name_str in list_project_name_temp:
                    list_project_name_temp.remove(project_name_str)
                    print('list_project_name_temp remove: ', list_project_name_temp)

            if len(list_project_name_temp) > 0:
                for project_name_temp in list_project_name_temp:
                    dict_project_name_participant_percent[project_name_temp].append(0)
        i = i + 1

    print('dict_project_name_participant_percent', dict_project_name_participant_percent)

    list_project_analysis_pie_chart_selected_member_data = []
    for k, v_list in dict_project_name_participant_percent.items():
        print('k', k)
        print('v_list', v_list)
        list_project_analysis_pie_chart_selected_member_data.append({'name':k, 'data': v_list})
    # print('list_project_analysis_pie_chart_selected_member_data', list_project_analysis_pie_chart_selected_member_data)
    data = {
        'list_project_analysis_pie_chart_selected_member_data': list_project_analysis_pie_chart_selected_member_data,
        'date_project_analysis_end': date_project_analysis_end,
        'date_project_analysis_start': date_project_analysis_start,
    }
    if where_am_i == 'hr':
        HR_My_Settings.objects.filter(id=q_mysettings_xxx.id).update(**data)

    elif where_am_i == 'my':
        MY_My_Settings.objects.filter(id=q_mysettings_xxx.id).update(**data)
    q_mysettings_xxx.refresh_from_db()
    return list_project_analysis_pie_chart_selected_member_data





#--------------------------------------------------------------------------------------------------------------------------
# 참여율 Random Generation , 선택된 달에 대해.
#--------------------------------------------------------------------------------------------------------------------------
def hr_task_control_task_plan_generate_randomly(request, q_mysettings_hr):
    import random
    ls_today = datetime.date.today()
    ls_month = ls_today.month
    selected_year = q_mysettings_hr.selected_year
    selected_month = q_mysettings_hr.selected_month
    qs_task_plan_month = Task_Plan.objects.filter(Q(check_discard=False) & Q(date_deadline_task_submission__year=selected_year) & Q(date_deadline_task_submission__month=selected_month))
    # print('num qs_task_plan_month ', len(qs_task_plan_month))
    # qs_project_simple_month = Project_Simple.objects.filter(Q(check_discard=False) & ~Q(status_project=LIST_PROJECT_SIMPLE_STATUS[4][0]) & ~Q(status_project=LIST_PROJECT_SIMPLE_STATUS[5][0]) & Q(date_project_start__lte=date_analysis_start) & (Q(date_project_end__gte=date_analysis_end) | Q(date_project_end__isnull=True)))
    qs_project_simple_onprogress = get_project_simple_on_progress_selected_month(request, selected_year, selected_month)
    # print('qs_project_simple_onprogress', qs_project_simple_onprogress)

    list_project_name_onprogress = []
    num_total_project_onprogress = len(qs_project_simple_onprogress)
    for q_project_simple_onprogress in qs_project_simple_onprogress:
        if q_project_simple_onprogress.project_name not in list_project_name_onprogress:
            list_project_name_onprogress.append(q_project_simple_onprogress.project_name)

    list_q_project = []
    for q_project_simple_onprogress in qs_project_simple_onprogress:
        list_q_project.append(q_project_simple_onprogress)

    if qs_task_plan_month is not None and len(qs_task_plan_month) > 0:
        for q_task_plan_month in qs_task_plan_month:
            list_dict_project_id_project_percent = []
            num_involved_project = random.randint(0, num_total_project_onprogress) # 멤버가 참여중인 프로젝트 랜덤 개수
            if num_involved_project == 0:
                # 하나도 포함 안됨.
                pass
            else:
                # 일부 또는 전부 포함

                if num_involved_project == num_total_project_onprogress:
                    # 모든 프로젝트 포함
                    list_q_project_selected = list_q_project
                else:
                    # 일부 프로젝트 포함
                    # list_q_project_selected = random.choices(list_q_project, k=num_involved_project) # 중복 선택 가능
                    list_q_project_selected = random.sample(list_q_project, k=num_involved_project) # 중복 선택 불가
                # print('list_q_project_selected', list_q_project_selected)

                i = 0
                set_number = 100
                while i < num_involved_project:
                    if i + 1 == num_involved_project:
                        num_picked_percent = set_number
                    else:
                        starting_number = set_number - num_involved_project + i
                        num_picked_percent = random.randint(1, starting_number)
                        set_number = set_number - num_picked_percent

                    q_project_selected = list_q_project_selected[i]
                    project_id = q_project_selected.id
                    project_name = q_project_selected.project_name

                    list_dict_project_id_project_percent.append({'id':project_id, 'project_name':project_name, 'participant_percent':num_picked_percent})
                    i = i + 1

            data = {
                'list_dict_project_id_project_percent': list_dict_project_id_project_percent,
                'check_submitted': True,
            }
            Task_Plan.objects.filter(id=q_task_plan_month.id).update(**data)
    messages.success(request, f'{selected_year}년 {selected_month}월의 월간 멤버 프로젝트 참여율을 임의로 할당하였습니다.')
    return True





