def hr_task_control_function(request):
    ls_now = datetime.datetime.now()
    ls_today = datetime.date.today()
    ls_year = datetime.datetime.now().year
    ls_month = datetime.datetime.now().month
    ls_next_year = int(ls_year) + 1
    ls_next_next_year = int(ls_year) + 2
    ls_last_year = int(ls_year) - 1

    #--------------------------------------------------------------------------------------------------------------------------
    where_am_i = 'hr'
    q_authority = Authority.objects.filter(check_discard=False).last()
    q_mysettings_home = get_mysettings_home(request)
    q_mysettings_hr = get_xxx_my_settings(request, q_mysettings_home, where_am_i)
    #--------------------------------------------------------------------------------------------------------------------------
    # Full Calendar
    return_value = get_full_weeks_calendar(request, q_mysettings_hr, where_am_i)
    cm_prev = return_value[0] # 칼랜다 한달 전
    cm = return_value[1] # 칼랜다 이번 달
    cm_next = return_value[2] # 칼랜다 한달 후
    cmweeks = return_value[3] # 이 달의 몇 번째 주인가?
    weekday = return_value[4] # 0: Monday, 1: Tuesday , ... , 6: Sunday
    dy_prev = return_value[5] # 오늘이 포함된 달의 이전 달이 포함된 해
    dy = return_value[6] # 오늘이 포함된 달이 포함된 해
    dy_next = return_value[7] # 오늘이 포함된 달의 다음 달이 포함된 해
    dm_prev = return_value[8] # 오늘이 포함된 달의 이전 달
    dm = return_value[9] # 오늘이 포함된 달
    dm_next = return_value[10] # 오늘이 포함된 달의 다음 달
    dd = return_value[11] # 오늘
    #--------------------------------------------------------------------------------------------------------------------------
    qs_hrlayout_all = HR_Layout.objects.filter(Q(check_discard=False))
    #--------------------------------------------------------------------------------------------------------------------------
    # 나의 hrlayout 리스트 업 및 Active hrlayout 하나 지정하여 home_mysettings 업데이트
    if q_mysettings_home.hrlayout is None or q_mysettings_hr.hrlayout is None:
        q_hrlayout = update_active_hrlayout_to_home_mysettings_and_list_up_my_hrlayout_to_member(request)
        data = {
            'hrlayout': q_hrlayout,
        }
        MY_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
        q_mysettings_hr.refresh_from_db()
    else:
        # Mysettings에 선택된 나의 HR Layout이 없으면 자동으로 하나 선택해주기
        q_hrlayout = q_mysettings_home.hrlayout

    # if q_hrlayout is not None:
    #     if q_hrlayout.team is not None:
    #         if q_mysettings_hr.team is None:
    #             data = {
    #                 'team': q_hrlayout.team,
    #             }
    #             MY_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    #             q_mysettings_hr.refresh_from_db()
    #--------------------------------------------------------------------------------------------------------------------------
    # Project Queryset
    #--------------------------------------------------------------------------------------------------------------------------
    # if q_mysettings_hr.task_control_type == LIST_HR_TASK_CONTROL_TYPE[0][0]:

    qs_project_simple = Project_Simple.objects.filter(check_discard=False)
    selected_year = q_mysettings_hr.selected_year
    selected_month = q_mysettings_hr.selected_month
    qs_project_simple_onprogress = get_project_simple_on_progress_selected_month(request, selected_year, selected_month)
    # Active Project Queryset
    # qs_project_simple_active = Project_Simple.objects.filter(Q(check_discard=False) & ~Q(status_project=LIST_PROJECT_SIMPLE_STATUS[4][0]))
    qs_project_simple_active = Project_Simple.objects.filter(Q(check_discard=False) & ~Q(status_project='COMPLETED') & ~Q(status_project='TERMINATED'))
    print("qs_project_simple_active.query:", qs_project_simple_active.query)

    # print('qs_project_simple_onprogress', qs_project_simple_onprogress)
    # 테이블 width % 설정하기
    if qs_project_simple_onprogress is not None and len(qs_project_simple_onprogress) > 0:
        if q_mysettings_hr.check_display_size_task_table_fullwidth == True:
            rest_width = 100 - (5 + 10 + 6 + 13)
            percent_table_width_project_participants = int(rest_width/len(qs_project_simple_onprogress))
            num_colspan_table_for_yearly_project_participant = 3 + len(qs_project_simple_onprogress)
        else:
            rest_width = 100 - (7 + 10 + 10)
            percent_table_width_project_participants = int(rest_width/len(qs_project_simple_onprogress))
            num_colspan_table_for_yearly_project_participant = 2 + len(qs_project_simple_onprogress)
    else:
        percent_table_width_project_participants = 0
        num_colspan_table_for_yearly_project_participant = 0
    # print('percent_table_width_project_participants', percent_table_width_project_participants)

    #--------------------------------------------------------------------------------------------------------------------------
    # Task Queryset 갱신 및 찾기
    qs_profile = Profile.objects.filter(Q(check_discard=False) & Q(check_resign=False))
    # print('qs_profile', len(qs_profile))
    selected_year = q_mysettings_hr.selected_year
    selected_month = q_mysettings_hr.selected_month
    if qs_profile is not None and len(qs_profile) > 0:
        for q_profile in qs_profile:
            get_my_task_plan_of_this_month_using_profile(request, q_profile, selected_year, selected_month)
    # print('selected_year, selected_month :', selected_year, selected_month)
    # 선택한 달의 모든 멤버 task plan 쿼리셋
    selected_field_name_for_task_plan_sorting = q_mysettings_hr.selected_field_name_for_task_plan_sorting
    list_searched_task_plan_id = q_mysettings_hr.list_searched_task_plan_id
    if list_searched_task_plan_id is not None and len(list_searched_task_plan_id) > 0:
        if selected_field_name_for_task_plan_sorting is not None:
            if q_mysettings_hr.check_selected_field_name_for_task_plan_sorting_inverse == True:
                selected_field_name_for_task_plan_sorting = f'-{selected_field_name_for_task_plan_sorting}'
            qs_task_plan_selected_month = Task_Plan.objects.filter(Q(check_discard=False) & Q(date_deadline_task_submission__year=selected_year) & Q(date_deadline_task_submission__month=selected_month) & Q(id__in=list_searched_task_plan_id)).order_by(selected_field_name_for_task_plan_sorting)
        else:
            qs_task_plan_selected_month = Task_Plan.objects.filter(Q(check_discard=False) & Q(date_deadline_task_submission__year=selected_year) & Q(date_deadline_task_submission__month=selected_month) & Q(id__in=list_searched_task_plan_id)).order_by('owner__profile__name_korean')
    else:
        if selected_field_name_for_task_plan_sorting is not None:
            if q_mysettings_hr.check_selected_field_name_for_task_plan_sorting_inverse == True:
                selected_field_name_for_task_plan_sorting = f'-{selected_field_name_for_task_plan_sorting}'
            qs_task_plan_selected_month = Task_Plan.objects.filter(Q(check_discard=False) & Q(date_deadline_task_submission__year=selected_year) & Q(date_deadline_task_submission__month=selected_month)).order_by(selected_field_name_for_task_plan_sorting)
        else:
            qs_task_plan_selected_month = Task_Plan.objects.filter(Q(check_discard=False) & Q(date_deadline_task_submission__year=selected_year) & Q(date_deadline_task_submission__month=selected_month)).order_by('owner__profile__name_korean')
    # print('qs_task_plan_selected_month', len(qs_task_plan_selected_month))
    # 선택한 멤버의 1년치 task plan 쿼리셋
    if q_mysettings_hr.task_plan is not None:
        q_owner_selected = q_mysettings_hr.task_plan.owner
        time_delta_365days = datetime.timedelta(days=365)
        date_year_ago = ls_today - time_delta_365days
        qs_task_plan_selected_member = Task_Plan.objects.filter(Q(check_discard=False) & Q(owner=q_owner_selected) & Q(date_deadline_task_submission__gte=date_year_ago)).order_by('-date_deadline_task_submission')
    else:
        qs_task_plan_selected_member = None
    # print('qs_task_plan_selected_month lenth', len(qs_task_plan_selected_month))


    #--------------------------------------------------------------------------------------------------------------------------
    # Form
    form_hr_task_project_register = HR_Task_Project_Register_Form()
    form_hr_task_project_update = HR_Task_Project_Update_Form(instance=q_mysettings_hr.project_simple)

    def registered_task_project_date_start():
        q_project_simple = q_mysettings_hr.project_simple
        if q_project_simple is not None:
            date_project_start = q_project_simple.date_project_start
            return date_project_start
        else:
            return None
    def registered_task_project_date_end():
        q_project_simple = q_mysettings_hr.project_simple
        if q_project_simple is not None:
            date_project_end = q_project_simple.date_project_end
            return date_project_end
        else:
            return None

    form_hr_task_project_date_start_register = HR_Task_Project_Register_Date_Start_Form(initial={'date_project_start':registered_task_project_date_start})
    form_hr_task_project_date_end_register = HR_Task_Project_Register_Date_End_Form(initial={'date_project_end':registered_task_project_date_end})
    # form_hr_task_project_date_start_register = HR_Task_Project_Register_Date_Start_Form()
    # form_hr_task_project_date_end_register = HR_Task_Project_Register_Date_End_Form()

    #################################################
    if request.method == 'GET':
        context = {
            'LIST_HR_TASK_CONTROL_TYPE': LIST_HR_TASK_CONTROL_TYPE,
            'LIST_PROJECT_SIMPLE_STATUS': LIST_PROJECT_SIMPLE_STATUS,
            'LIST_TASK_PROJECT_CONTROL_SUBMENU': LIST_TASK_PROJECT_CONTROL_SUBMENU,
            'LIST_TASK_PROJECT_PARTICIPANT_SUBMENU': LIST_TASK_PROJECT_PARTICIPANT_SUBMENU,
            'LIST_TASK_PLAN_TABLE_COLUMN_INDEX': LIST_TASK_PLAN_TABLE_COLUMN_INDEX,

            'ls_today': ls_today,
            'ls_year': ls_year,
            'ls_next_year': ls_next_year,
            # Full Calendar
            'cm_prev': cm_prev,
            'cm': cm,
            'cm_next': cm_next,
            'cmweeks': cmweeks,
            'weekday': weekday,
            'dy_prev': dy_prev,
            'dy': dy,
            'dy_next': dy_next,
            'dm_prev': dm_prev,
            'dm': dm,
            'dm_next': dm_next,
            'dd': dd,
            # Queryset
            'q_mysettings_hr': q_mysettings_hr,
            'qs_project_simple': qs_project_simple,
            'qs_project_simple_onprogress': qs_project_simple_onprogress,
            'qs_task_plan_selected_month': qs_task_plan_selected_month,
            'qs_task_plan_selected_member': qs_task_plan_selected_member,
            'qs_project_simple_active': qs_project_simple_active,
            'percent_table_width_project_participants': percent_table_width_project_participants,
            'num_colspan_table_for_yearly_project_participant': num_colspan_table_for_yearly_project_participant,
            # form
            'form_hr_task_project_register': form_hr_task_project_register,
            'form_hr_task_project_update': form_hr_task_project_update,
            'form_hr_task_project_date_start_register': form_hr_task_project_date_start_register,
            'form_hr_task_project_date_end_register': form_hr_task_project_date_end_register,
        }
        return context

    #################################################
    if request.method == 'POST':
        print('request.POST', request.POST)

        #--------------------------------------------------------------------------------------------------------------------------
        # HR Task Control 메뉴 변경
        #--------------------------------------------------------------------------------------------------------------------------
        if request.POST.get('button-hr-task-control-type-switch') is not None:
            switch_hr_task_control_type(request, q_mysettings_hr)


        #--------------------------------------------------------------------------------------------------------------------------
        # Project 관리
