#-------------------------------------------------------------------------------------------------------------------
# HR Full Calendar Month 변경
#-------------------------------------------------------------------------------------------------------------------
def switch_hr_full_calendar_month_forward_backward(request, q_mysettings_hr):
    ls_today = datetime.date.today()
    ls_year = ls_today.year
    ls_month = ls_today.month
    ls_day = ls_today.day
    selected_year = q_mysettings_hr.selected_year
    selected_month = q_mysettings_hr.selected_month
    selected_day = q_mysettings_hr.selected_day
    if selected_month is None:
        data = {
            'selected_year': int(ls_year),
            'selected_month': int(ls_month),
            'selected_day': int(ls_day),
        }
        HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)

    delta_month_str = request.POST.get('button-hr-calendar-control-full-calendar-delta-month')
    if delta_month_str == 'backward':
        if selected_month == 1:
            selected_month = 12
            selected_year = selected_year - 1
        else:
            selected_month = selected_month - 1
    elif delta_month_str == 'current':
        pass
    elif delta_month_str == 'forward':
        if selected_month == 12:
            selected_month = 1
            selected_year = selected_year + 1
        else:
            selected_month = selected_month + 1
    elif delta_month_str == 'reset':
        selected_year = int(ls_year)
        selected_month = int(ls_month)
        selected_day = int(ls_day)
    else:
        messages.warning(request, f'선택된 해당 날짜가 없습니다.')
        return False
    data = {
        'selected_year': selected_year,
        'selected_month': selected_month,
        'selected_day': selected_day,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True



#--------------------------------------------------------------------------------------------------------------------------
# 칼렌다 국공휴일 업데이트
#
# 국경일 : 국가의 경사를 기념하기 위한 날 (모두 쉬는건 아님) // # 3.1절(3월 1일), 제헌절(7월 17일, 쉬는날이 아님), 광복절(8월 15일), 개천절(10월 3일), 한글날(10월 9일)
# 법정기념일 : 법에 정한 기념일(대부분 쉬는 날 아님)
# 법정공휴일 : 법에 정한 쉬는 날  //
#               일요일,
#               새해 첫날 (1월 1일, 명절),
#               설날 연휴 (음력 12월 31일, 음력 1월 1일, 음력 1월 2일, 명절),
#               3.1절 (3월 1일, 국경일),
#               부처님오신날 (음력 4월 8일, 종교기념일),
#               어린이날 (5월 5일, 법정기념일),
#               현충일 (6월 6일, 법정기념일),
#               광복절 (8월 15일, 국경일),
#               추석 연휴 (음력 8월 14일, 음력 8월 15일, 음력 8월 16일, 명절),
#               개천절 (10월 3일, 국경일),
#               한글날 (10월 9일, 국경일),
#               성탄절 (12월 25일, 종교기념일),
# 기타 법정공휴일:
#               대한민국 대통령 선거일
#               대한민국 국회의원 선거일
#               대한민국 전국동시지방선거일
#               대체공휴일 (설/춯석연후, 어린이날이 일요일 및 다른 공휴일과 겹칠 경우, 그 공휴일의 다음의 첫 번째 비공휴일)
#               임시공휴일 (정부에서 임의 지정하는 공휴일)
#               지방공휴일 (지방자치단체가 특정지역에 한해 공휴일 지정)
#--------------------------------------------------------------------------------------------------------------------------

def register_national_holiday_using_api_by_year(request, q_calendar_control):
    year_holiday = q_calendar_control.year_calendar

    ### Prerequisites ###
    # 한국천문연구원 특일정보 API
    # https://www.data.go.kr/data/15012690/openapi.do
    # 인증키를 넣어야 함
    # 현재 인증키 만료일은 2024-09-01
    key_holiday = 'Fg9BrcPFFpsv0Twj1Z8ODbLQM%2FaWK2HbJHCB0nJVGsOGi0mosbuR6eY5QDpBoISaYBSn0ELm5jOwoPXAiy1ToA%3D%3D'
    list_month_holiday = ['01', '02', '03', '04', '05', '06', '07', '08', '09', '10', '11', '12']
    list_operation_word = ['getHoliDeInfo', 'getRestDeInfo', 'getAnniversaryInfo', 'get24DivisionsInfo', 'getSundryDayInfo']


    for month_holiday in list_month_holiday:
        for operation_word in list_operation_word:
            table_url_holiday = f"http://apis.data.go.kr/B090041/openapi/service/SpcdeInfoService/{operation_word}?solYear={year_holiday}&solMonth={month_holiday}&ServiceKey={key_holiday}&_type=json"
            response_table_url_holiday = requests.get(table_url_holiday)
            if response_table_url_holiday.status_code == 200:
                print(f'****************************** {year_holiday} / {month_holiday}')
                ### Json Data Processing ###
                soup = bs4(response_table_url_holiday.content, "lxml", from_encoding="utf-8")
                soup_str_text = str(soup.text)
                json_data = json.loads(soup_str_text)
                # print(json_data)
                # print(json_data['response']['body']['items']['item'])
                try:
                    json_data_n = pd.json_normalize(json_data['response']['body']['items']['item'])
                    df = pd.DataFrame(json_data_n)
                    # print(df)
                    for index, row in df.iterrows():
                        # dateKind, dateName, isHoliday, locdate
                        # print(row['dateKind'])
                        # print(row['dateName'])
                        # print(row['isHoliday'])
                        # print(row['locdate'])
                        event_type_str = row['dateKind']
                        event_name_str = row['dateName']
                        check_holiday_str = row['isHoliday']
                        date_event_str = str(row['locdate'])
                        # Event 종류 (01: 국경일, 02: 기념일, 03: 24절기, 04: 잡절)
                        if event_type_str == '01':
                            event_type = NATIONAL_EVENT_TYPES[0][0]
                        elif event_type_str == '02':
                            event_type = NATIONAL_EVENT_TYPES[1][0]
                        elif event_type_str == '03':
                            event_type = NATIONAL_EVENT_TYPES[2][0]
                        elif event_type_str == '04':
                            event_type = NATIONAL_EVENT_TYPES[3][0]
                        # print('event_type', event_type)
                        # Event의 법정공휴일 여부
                        if check_holiday_str == 'Y':
                            check_holiday = True
                        else:
                            check_holiday = False
                        # print('check_holiday', check_holiday)
                        # Event 날짜
                        date_event = date_event_str[0:4] + '-' + date_event_str[4:6] + '-' + date_event_str[6:]
                        # print('date_event', date_event)
                        data = {
                            'calendar_control': q_calendar_control,
                            'date_event': date_event,
                            'name_event': event_name_str,
                            'type_event_national': event_type,
                            'check_holiday': check_holiday,
                        }
                        q_calendar = HR_Calendar_Event.objects.filter(Q(date_event=date_event) & Q(name_event=event_name_str)).last()
                        if q_calendar is None :
                            HR_Calendar_Event.objects.create(**data)
                            print(f'{event_name_str} Created!')
                        else:
                            HR_Calendar_Event.objects.filter(id=q_calendar.id).update(**data)
                            print(f'{event_name_str} Updated!')
                        time.sleep(3)
                except:
                    print('Nothing')
                    time.sleep(3)


def register_event_national_by_API(request, q_mysettings_hr):
    ls_year = datetime.datetime.now().year
    selected_year_calendar_str = request.POST.get('select-hr-calendar-control-national-event-register')
    if selected_year_calendar_str is None or selected_year_calendar_str == '':
        messages.warning(request, f'등록할 년도 정보가 정확하지 않습니다. 관리자에게 문의하세요.')
        return False
    selected_year_calendar = int(selected_year_calendar_str)
    # Calendar Control 쿼리 찾기
    q_calendar_control = HR_Calendar_Control.objects.filter(Q(check_discard=False) & Q(year_calendar=selected_year_calendar)).last()
    if q_calendar_control is None:
        data = {
            'year_calendar': selected_year_calendar,
        }
        q_calendar_control = HR_Calendar_Control.objects.create(**data)
    # 해당 년도 Calendar Control 쿼리 이용하여 National Event 생성하기
    register_national_holiday_using_api_by_year(request, q_calendar_control)
    data = {
        'selected_year_register_event': selected_year_calendar,
        'calendar_control': q_calendar_control,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)



#--------------------------------------------------------------------------------------------------------------------------
# 수동 National Event 등록
#--------------------------------------------------------------------------------------------------------------------------
def register_event_national_manually(request, q_mysettings_hr):
    date_event_str = request.POST.get('date_event')
    if date_event_str is None or date_event_str == '':
        messages.warning(request, f'날짜를 입력하지 않았습니다.')
        return False
    date_event = datetime.datetime.strptime(date_event_str, '%Y-%m-%d').date()  # 숫자-숫자-숫자 를 datetime 오브젝트 값으로 변환
    year_calendar = date_event.year
    q_calendar_control = HR_Calendar_Control.objects.filter(Q(check_discard=False) & Q(year_calendar=year_calendar)).last()
    if q_calendar_control is None:
        data = {
            'year_calendar': year_calendar,
        }
        q_calendar_control = HR_Calendar_Control.objects.create(**data)

    check_holiday_str = request.POST.get('radio-event-national-holiday')
    if check_holiday_str == 'true':
        check_holiday = True
    else:
        check_holiday = False
    data = {
        'calendar_control': q_calendar_control,
        'date_event': date_event,
        'check_holiday': check_holiday,
        'list_applied_company': ['all'],
    }
    q_calendar_event = HR_Calendar_Event.objects.create(**data)
    form_hr_national_event_register = HR_Calendar_National_Event_Register_From(request.POST, instance=q_calendar_event)
    if form_hr_national_event_register.is_valid:
        form_hr_national_event_register.save()
    return True


