def register_event_voronoi_manually(request, q_mysettings_hr):
    date_event_str = request.POST.get('date_event')
    if date_event_str is None or date_event_str == '':
        messages.warning(request, f'날짜를 입력하지 않았습니다.')
        return False
    date_event = datetime.datetime.strptime(date_event_str, '%Y-%m-%d').date()  # 숫자-숫자-숫자 를 datetime 오브젝트 값으로 변환
    year_calendar = date_event.year
    q_calendar_control = HR_Calendar_Control.objects.filter(Q(check_discard=False) & Q(year_calendar=year_calendar)).last()
    if q_calendar_control is None:
        data = {
            'year_calendar': year_calendar,
        }
        q_calendar_control = HR_Calendar_Control.objects.create(**data)

    check_holiday_str = request.POST.get('radio-event-voronoi-holiday')
    if check_holiday_str == 'true':
        check_holiday = True
    else:
        check_holiday = False

    list_applied_company = request.POST.getlist('checkbox-event-voronoi-apply')
    if list_applied_company is None or len(list_applied_company) == 0:
        messages.warning(request, f'적용 회사 범위를 선택하지 않았습니다.')
        return False

    data = {
        'calendar_control': q_calendar_control,
        'date_event': date_event,
        'check_voronoi_event': True,
        'check_holiday': check_holiday,
        'list_applied_company': list_applied_company,
    }
    q_calendar_event = HR_Calendar_Event.objects.create(**data)
    form_hr_voronoi_event_register = HR_Calendar_Voronoi_Event_Register_From(request.POST, instance=q_calendar_event)
    if form_hr_voronoi_event_register.is_valid:
        form_hr_voronoi_event_register.save()
    return True



