    q_calendar_control = HR_Calendar_Control.objects.get(id=q_calendar_control_id)
    print('q_calendar_control **********', q_calendar_control)
    data = {
        'calendar_control': q_calendar_control,
    }
    HR_My_Settings.objects.filter(id=q_mysettings_hr.id).update(**data)
    return True




