###################################################################################################################################################
#
#                                                     HR Calendar Control Main Function
#
###################################################################################################################################################
###################################################################################################################################################

def hr_calendar_control_function(request):
    ls_today = datetime.date.today()
    ls_year = datetime.datetime.now().year
    ls_next_year = int(ls_year) + 1
    where_am_i = 'hr'
    q_authority = Authority.objects.filter(check_discard=False).last()
    q_mysettings_home = get_mysettings_home(request)
    q_mysettings_hr = get_xxx_my_settings(request, q_mysettings_home, where_am_i)

    #--------------------------------------------------------------------------------------------------------------------------
    # Queryset
    #--------------------------------------------------------------------------------------------------------------------------
    # 칼렌다 컨트롤 쿼리
    qs_calendar_control = HR_Calendar_Control.objects.filter(Q(check_discard=False)).order_by('year_calendar')
    print('qs_calendar_control', qs_calendar_control)
    if q_mysettings_hr.calendar_control is None:
        selected_year_calendar = ls_year
    else :
        selected_year_calendar = q_mysettings_hr.calendar_control.year_calendar
    #--------------------------------------------------------------------------------------------------------------------------
    # 칼렌다 이벤트 쿼리
    qs_event_national = HR_Calendar_Event.objects.filter(Q(check_discard=False) & Q(check_voronoi_event=False) & Q(date_event__year=selected_year_calendar)).order_by('date_event')
    qs_event_voronoi = HR_Calendar_Event.objects.filter(Q(check_discard=False) & Q(check_voronoi_event=True) & (Q(date_event__year=ls_year) | Q(date_event__year=ls_next_year))).order_by('date_event')
    qs_event_all = HR_Calendar_Event.objects.filter(Q(check_discard=False) & (Q(date_event__year=ls_year) | Q(date_event__year=ls_next_year))).order_by('date_event')

    # Full Calendar
    return_value = get_full_weeks_calendar(request, q_mysettings_hr, where_am_i)
    cm_prev = return_value[0] # 칼랜다 한달 전
    cm = return_value[1] # 칼랜다 이번 달
    cm_next = return_value[2] # 칼랜다 한달 후
    cmweeks = return_value[3] # 이 달의 몇 번째 주인가?
    weekday = return_value[4] # 0: Monday, 1: Tuesday , ... , 6: Sunday
    dy_prev = return_value[5] # 오늘이 포함된 달의 이전 달이 포함된 해
    dy = return_value[6] # 오늘이 포함된 달이 포함된 해
    dy_next = return_value[7] # 오늘이 포함된 달의 다음 달이 포함된 해
    dm_prev = return_value[8] # 오늘이 포함된 달의 이전 달
    dm = return_value[9] # 오늘이 포함된 달
    dm_next = return_value[10] # 오늘이 포함된 달의 다음 달
    dd = return_value[11] # 오늘

    # 선택한 칼랜다 연차 기준으로 앞뒤 년도 획득
    q_calendar_control = q_mysettings_hr.calendar_control
    if q_calendar_control is None:
        year_calendar = ls_year
    else:
        year_calendar = q_calendar_control.year_calendar
    list_year_calendar_national_event_register = []
    i = -5
    while i < 2:
        list_year_calendar_national_event_register.append(year_calendar + i)
        i = i + 1
    print('list_year_calendar_national_event_register', list_year_calendar_national_event_register)

    # form
    form_date_holiday = HR_Holiday_Register_Date_Form()
    form_hr_national_event_register = HR_Calendar_National_Event_Register_From()
    form_hr_voronoi_event_register = HR_Calendar_Voronoi_Event_Register_From()

    #################################################
    if request.method == 'GET':
        context = {
            'NATIONAL_EVENT_TYPES': NATIONAL_EVENT_TYPES,
            'VORONOI_EVENT_TYPES': VORONOI_EVENT_TYPES,
            'LIST_HR_CALENDAR_CONTROL_TYPE': LIST_HR_CALENDAR_CONTROL_TYPE,

            'ls_today': ls_today,
            'ls_year': ls_year,
            'ls_next_year': ls_next_year,
            'q_mysettings_hr': q_mysettings_hr,
            'qs_event_all': qs_event_all,
            'qs_event_national': qs_event_national,
            'qs_event_voronoi': qs_event_voronoi,
            'qs_calendar_control': qs_calendar_control,
            # Full Calendar
            'cm_prev': cm_prev,
            'cm': cm,
            'cm_next': cm_next,
            'cmweeks': cmweeks,
            'weekday': weekday,
            'dy_prev': dy_prev,
            'dy': dy,
            'dy_next': dy_next,
            'dm_prev': dm_prev,
            'dm': dm,
            'dm_next': dm_next,
            'dd': dd,
            # list
            'list_year_calendar_national_event_register': list_year_calendar_national_event_register,
            # Form
            'form_date_holiday': form_date_holiday,
            'form_hr_national_event_register': form_hr_national_event_register,
            'form_hr_voronoi_event_register': form_hr_voronoi_event_register,
        }
        return context
    #################################################
    if request.method == 'POST':
        print('request.POST', request.POST)

        # HR Calendar Control Type 변경하기
        if request.POST.get('button-hr-calendar-control-type-switch') is not None:
            switch_hr_calendar_control_type(request, q_mysettings_hr)

        # Calendar 앞뒤로 한달씩 움직이기
        if request.POST.get('button-hr-calendar-control-full-calendar-delta-month') is not None:
            return switch_hr_full_calendar_month_forward_backward(request, q_mysettings_hr)


        # 국공휴일 Holiday 변경하기
        if request.POST.get('button-hr-calendar-control-update-holiday-activate-or-inactivate') is not None:
            q_event_national_id_str = request.POST.get('button-hr-calendar-control-update-holiday-activate-or-inactivate')
            if q_event_national_id_str is None or q_event_national_id_str == '':
                return False
            q_event_national_id = int(q_event_national_id_str)
            q_event_national = HR_Calendar_Event.objects.get(id=q_event_national_id)
            check_holiday = q_event_national.check_holiday
            if check_holiday == True:
                check_holiday = False
                messages.warning(request, f'선택한 {q_event_national.name_event}을 근무하는 날로 변경하였습니다.')
            else:
                check_holiday = True
                messages.success(request, f'선택한 {q_event_national.name_event}을 쉬는 날로 변경하였습니다.')
            data = {
                'check_holiday': check_holiday,
            }
            HR_Calendar_Event.objects.filter(id=q_event_national_id).update(**data)
            return True


        # 국공휴일 Holiday 삭제하기
        if request.POST.get('button-hr-calendar-control-delete-national-holiday') is not None:
            q_event_national_id_str = request.POST.get('button-hr-calendar-control-delete-national-holiday')
            if q_event_national_id_str is None or q_event_national_id_str == '':
                return False
            q_event_national_id = int(q_event_national_id_str)
            q_event_national = HR_Calendar_Event.objects.get(id=q_event_national_id)
            messages.warning(request, f'선택한 {q_event_national.name_event}을 삭제하였습니다.')

            data = {
                'check_discard': True,
            }
            HR_Calendar_Event.objects.filter(id=q_event_national_id).update(**data)
            return True


        # 보로노이 Holiday 삭제하기
        if request.POST.get('button-hr-calendar-control-delete-voronoi-holiday') is not None:
            q_event_voronoi_id_str = request.POST.get('button-hr-calendar-control-delete-voronoi-holiday')
            if q_event_voronoi_id_str is None or q_event_voronoi_id_str == '':
                return False
            q_event_voronoi_id = int(q_event_voronoi_id_str)
            q_event_voronoi = HR_Calendar_Event.objects.get(id=q_event_voronoi_id)
            messages.warning(request, f'선택한 {q_event_voronoi.name_event}을 삭제하였습니다.')

            data = {
                'check_discard': True,
            }
            HR_Calendar_Event.objects.filter(id=q_event_voronoi_id).update(**data)
            return True


        #--------------------------------------------------------------------------------------------------------------------------
        # Calendar Event Register
        #--------------------------------------------------------------------------------------------------------------------------
        # Calendar National Event 등록된 년도 선택하기
        if request.POST.get('button-calendar-control-select-calendar-year-for-national-event') is not None:
            hr_calendar_control_select_calendar_year_for_national_event(request, q_mysettings_hr)

        # 자동(API) National Event 등록하기
        if request.POST.get('button-hr-calendar-control-register-api') == 'true':
            register_event_national_by_API(request, q_mysettings_hr)

        # 수동 National Event 등록
        if request.POST.get('button-register-event-national') == 'true':
            register_event_national_manually(request, q_mysettings_hr)

        # 수동 Voronoi Event 등록
        if request.POST.get('button-register-event-voronoi') == 'true':
            register_event_voronoi_manually(request, q_mysettings_hr)

        return False




