def get_list_authority_team_and_team_leader_and_team_member(qs_m2t__authority):
    list_q_team__authority = []
    list_q_member__authority_team_leader = []
    list_q_member__authority_team_member = []
    for q_m2t__authority_division in qs_m2t__authority:
        q_team__authority = q_m2t__authority_division.team
        q_member__authority = q_m2t__authority_division.member
        if q_team__authority not in list_q_team__authority:
            list_q_team__authority.append(q_team__authority)
        if q_m2t__authority_division.check_team_leader == True:
            if q_member__authority not in list_q_member__authority_team_leader:
                list_q_member__authority_team_leader.append(q_member__authority)
        elif q_m2t__authority_division.check_team_leader != True:
            if q_member__authority not in list_q_member__authority_team_member:
                list_q_member__authority_team_member.append(q_member__authority)
    return list_q_team__authority, list_q_member__authority_team_leader, list_q_member__authority_team_member

def get_list_authority_division_leader_and_division_member(qs_m2d__authority):
    list_q_division__authority = []
    list_q_member__authority_division_leader = []
    list_q_member__authority_division_member = []
    for q_m2d__authority in qs_m2d__authority:
        q_division__authority = q_m2d__authority.division
        q_member__authority = q_m2d__authority.member
        if q_division__authority not in list_q_division__authority:
            list_q_division__authority.append(q_division__authority)
        if q_m2d__authority.check_division_leader == True:
            if q_member__authority not in list_q_member__authority_division_leader:
                list_q_member__authority_division_leader.append(q_member__authority)
        elif q_m2d__authority.check_division_leader != True:
            if q_member__authority not in list_q_member__authority_division_member:
                list_q_member__authority_division_member.append(q_member__authority)
    return list_q_division__authority, list_q_member__authority_division_leader, list_q_member__authority_division_member

def get_list_authority_company_and_company_leader_and_company_member(qs_m2c__authority):
    list_q_company__authoirity = []
    list_q_member__authority_company_leader = []
    list_q_member__authority_company_member = []
    for q_m2c__authority in qs_m2c__authority:
        q_company__authority = q_m2c__authority.company
        q_member__authority = q_m2c__authority.member
        if q_company__authority is not None:
            if q_company__authority not in list_q_company__authoirity:
                list_q_company__authoirity.append(q_company__authority)
            if q_m2c__authority.check_company_leader == True:
                if q_member__authority not in list_q_member__authority_company_leader:
                    list_q_member__authority_company_leader.append(q_member__authority)
            elif q_m2c__authority.check_company_leader != True:
                if q_member__authority not in list_q_member__authority_company_member:
                    list_q_member__authority_company_member.append(q_member__authority)
        else:
            # q_m2c.company 필드값이 없는 더미 쿼리 삭제
            q_m2c__authority.delete()
    return list_q_company__authoirity, list_q_member__authority_company_leader, list_q_member__authority_company_member

def get_list_authority_divission_and_division_leader_and_division_member_and_team_and_team_leader_team_member(qs_d2c__authority):
    list_q_division__authority = []
    list_q_member__authority_division_leader = []
    list_q_member__authority_division_member = []
    list_q_team__authority = []
    list_q_member__authority_team_leader = []
    list_q_member__authority_team_member = []

    for q_d2c__authority in qs_d2c__authority:
        if q_d2c__authority.team2division is not None:
            q_company__authority = q_d2c__authority.company
            q_t2d__authority = q_d2c__authority.team2division
            q_division__authority = q_t2d__authority.division
            qs_m2d__authority_division = Member2Division.objects.filter(division=q_division__authority)
            qs_m2t__authority_division = Member2Team.objects.filter(division=q_division__authority)
            # 부서 직접 소속된 부서리더/부서멤버 찾기
            return_value = get_list_authority_division_leader_and_division_member(qs_m2d__authority_division)
            for item in return_value[0] :
                if item not in list_q_division__authority:
                    list_q_division__authority.append(item)
            for item in return_value[1] :
                if item not in list_q_member__authority_division_leader:
                    list_q_member__authority_division_leader.append(item)
            for item in return_value[2] :
                if item not in list_q_member__authority_division_member:
                    list_q_member__authority_division_member.append(item)

            # 부서 소속된 팀/팀리더/팀멤버 찾기
            return_value = get_list_authority_team_and_team_leader_and_team_member(qs_m2t__authority_division)
            for item in return_value[0] :
                if item not in list_q_team__authority:
                    list_q_team__authority.append(item)
            for item in return_value[1] :
                if item not in list_q_member__authority_team_leader:
                    list_q_member__authority_team_leader.append(item)
            for item in return_value[2] :
                if item not in list_q_member__authority_team_member:
                    list_q_member__authority_team_member.append(item)

        elif q_d2c__authority.member2division is not None:
            q_company__authority = q_d2c__authority.company
            q_m2d__authority = q_d2c__authority.member2division
            q_division__authority = q_m2d__authority.division
            qs_m2d__authority_division = Member2Division.objects.filter(division=q_division__authority)
            # 부서 직접 소속된 부서리더/부서멤버 찾기
            return_value = get_list_authority_division_leader_and_division_member(qs_m2d__authority_division)
            for item in return_value[0] :
                if item not in list_q_division__authority:
                    list_q_division__authority.append(item)
            for item in return_value[1] :
                if item not in list_q_member__authority_division_leader:
                    list_q_member__authority_division_leader.append(item)
            for item in return_value[2] :
                if item not in list_q_member__authority_division_member:
                    list_q_member__authority_division_member.append(item)

    return list_q_division__authority, list_q_member__authority_division_leader, list_q_member__authority_division_member, list_q_team__authority, list_q_member__authority_team_leader, list_q_member__authority_team_member


def get_list_authority_all(request):
    # remove dummy queries #######################################################
    delete_dummy_query_hr_layout()

    # Start collecting selected queries #############################################
    list_q_company__authoirity = []
    list_q_member__authority_company_leader = []
    list_q_member__authority_company_member = []
    list_q_division__authority = []
    list_q_member__authority_division_leader = []
    list_q_member__authority_division_member = []
    list_q_team__authority = []
    list_q_member__authority_team_leader = []
    list_q_member__authority_team_member = []

    # list_authority-selected-company == q_company.id
    list_authority_selected_company_id = request.POST.getlist('authority-selected-company')
    if list_authority_selected_company_id is not None:
        qs_company__authority = Company.objects.filter(Q(check_discard=False) & Q(id__in=list_authority_selected_company_id))

        for q_company__authority in qs_company__authority:
            qs_d2c__authority = Division2Company.objects.filter(Q(check_discard=False) & Q(company=q_company__authority))
            return_value = get_list_authority_divission_and_division_leader_and_division_member_and_team_and_team_leader_team_member(qs_d2c__authority)
            for item in return_value[0]:
                if item not in list_q_division__authority:
                    list_q_division__authority.append(item)
